def _private_route_registry():
    """Return the route registry captured by the real route mint gateway."""
    cells = dict(zip(
        bind._realize_projected_routes_from_claim_inventory.__code__.co_freevars,
        bind._realize_projected_routes_from_claim_inventory.__closure__,
    ))
    return cells["mint"].cell_contents.__kwdefaults__["_registry"]


def _slice_c0_unregistered_publication(kind):
    """Build one real deferred occurrence and its ordinary validation gateway."""
    accepted = bind.realize_projected_routes(
        **_c_complete_kwargs(_compiler_redirect_goto_case)
    )
    assert type(accepted) is model.ProjectedRouteRealizationAccepted
    phase = accepted.realization.site_phase_result
    batch = bind._AtomicPublicationBatch()
    projected_cells = dict(zip(
        bind._realize_projected_routes_from_claim_inventory.__code__.co_freevars,
        bind._realize_projected_routes_from_claim_inventory.__closure__,
    ))

    if kind == "site":
        template = phase.effect_results[0].source_site
        value = bind._site_mint(
            type(template),
            {name: getattr(template, name) for name in type(template).__dataclass_fields__},
            _batch=batch,
        )
        registry = bind._SITE_REGISTRY
        ordinary = lambda target, identity: bind._register_site(target, identity)
        canonical_identity = batch._entries[0][3]
        validator = lambda: bind._validate_registered_site(value)
        drift = ("instruction_ordinal", value.instruction_ordinal + 1)
    elif kind == "binding":
        template = phase.effect_results[0]
        value = bind._site_binding_mint(
            type(template),
            {
                name: getattr(template, name)
                for name in type(template).__dataclass_fields__
                if name != "result_id"
            },
            "result_id", _batch=batch,
        )
        registry = bind._SITE_BINDING_REGISTRY
        ordinary = lambda target, identity: bind._register_site_binding(target, identity)
        canonical_identity = value.result_id
        validator = lambda: bind.validate_projected_effect_site_result(value)
        drift = ("authority_id", authority_id("slice-c0-binding-drift"))
    else:
        if kind == "relation":
            template = accepted.realization.rows[0].relation
            identity_name = "relation_id"
            constructor = projected_cells["mint"].cell_contents
        elif kind == "route":
            template = accepted.realization.rows[0]
            identity_name = "row_id"
            constructor = projected_cells["mint"].cell_contents
        else:
            template = accepted
            identity_name = None
            constructor = projected_cells["result"].cell_contents
        value = constructor(
            type(template),
            {name: getattr(template, name) for name in type(template).__dataclass_fields__},
            identity_name, _batch=batch,
        )
        registry = _private_route_registry()
        register_route = constructor.__defaults__[-1]
        ordinary = lambda target, identity: register_route(target, identity)
        if kind == "relation":
            canonical_identity = value.relation_id
            validator = lambda: projected_cells["validate_route"].cell_contents(
                value, "relation_id",
            )
            drift = ("new_target", value.old_target)
        elif kind == "route":
            canonical_identity = value.row_id
            validator = lambda: projected_cells["validate_route"].cell_contents(
                value, "row_id",
            )
            drift = ("plan_step_index", value.plan_step_index + 1)
        else:
            canonical_identity = authority_id((
                type(value).__qualname__,
                tuple(
                    (name, getattr(value, name))
                    for name in type(value).__dataclass_fields__
                ),
            ))
            validator = lambda: projected_cells["validate_result"].cell_contents(
                value, model.ProjectedRouteRealizationAccepted,
            )
            alternate = bind.realize_projected_routes(
                **_c_complete_kwargs(_compiler_direct_branch_case)
            )
            assert type(alternate) is model.ProjectedRouteRealizationAccepted
            drift = ("realization", alternate.realization)

    assert len(batch._entries) == 1
    assert registry.get(id(value)) is None
    return (
        batch, value, registry, ordinary, canonical_identity, validator, drift,
    )


def _slice_c0_unregistered_scalar_site():
    """Build a real deferred scalar coordinate from canonical local inputs."""
    values = _c_local_alias_fixture()
    draft = bind._draft_local_alias_binding(
        claim=values["claim"], patch_step_fact=values["patch_step_fact"],
        source_inventory=values["source_inventory"],
        projected_inventory=values["projected_inventory"],
    )
    observation = draft.projected_observation
    batch = bind._AtomicPublicationBatch()
    value = bind._site_mint(model.ScalarizedInstructionCoordinate, {
        "owner": model.AnchoredBlockRef(
            draft.projected_block.block_ref, draft.projected_block.anchor_ea,
        ),
        "instruction_ordinal": observation.ordinal,
        "instruction_ea": observation.instruction_ea,
        "instruction_kind": InsnKind.MOV,
        "opcode": observation.opcode,
        "raw_opcode": observation.raw_opcode,
        "width": observation.width,
        "display_text_digest": authority_id((
            "scalarized-display-text", observation.display_text,
        )),
    }, _batch=batch)
    return batch, value, batch._entries[0][3]


def test_slice_c0_scalar_site_gateway_recomputes_canonical_live_content() -> None:
    """The scalar branch is a closed site type, not an unchecked fallback."""
    _batch, foreign_value, _identity = _slice_c0_unregistered_scalar_site()
    with pytest.raises((TypeError, ValueError)):
        bind._register_site(foreign_value, "foreign-scalar-identity")
    assert bind._SITE_REGISTRY.get(id(foreign_value)) is None

    batch, value, identity = _slice_c0_unregistered_scalar_site()
    batch.commit()
    bind._validate_registered_site(value)
    row = bind._SITE_REGISTRY[id(value)]
    original = value.instruction_ordinal
    object.__setattr__(value, "instruction_ordinal", original + 1)
    try:
        with pytest.raises((TypeError, ValueError)):
            bind._register_site(value, identity)
        assert bind._SITE_REGISTRY[id(value)] is row
    finally:
        object.__setattr__(value, "instruction_ordinal", original)
    bind._validate_registered_site(value)


@pytest.mark.parametrize("kind", ("site", "binding", "relation", "route", "result"))
def test_slice_c0_real_registration_gateway_rejects_foreign_identity(
    kind,
) -> None:
    """An empty key never licenses a caller-supplied noncanonical identity."""
    _batch, value, registry, ordinary, canonical_identity, validator, _drift = (
        _slice_c0_unregistered_publication(kind)
    )
    with pytest.raises(ValueError):
        ordinary(value, f"foreign-{kind}-identity")
    assert registry.get(id(value)) is None
    assert ordinary(value, canonical_identity) is value
    validator()


@pytest.mark.parametrize("kind", ("site", "binding", "relation", "route", "result"))
def test_slice_c0_real_registration_gateway_rejects_stale_live_content(
    kind,
) -> None:
    """Exact-object reissue must recompute content, not trust its stored seal."""
    batch, value, registry, ordinary, canonical_identity, validator, drift = (
        _slice_c0_unregistered_publication(kind)
    )
    batch.commit()
    validator()
    row = registry[id(value)]
    field, changed = drift
    original = getattr(value, field)
    object.__setattr__(value, field, changed)
    try:
        with pytest.raises((TypeError, ValueError)):
            ordinary(value, canonical_identity)
        assert registry[id(value)] is row
    finally:
        object.__setattr__(value, field, original)
    validator()


@pytest.mark.parametrize("kind", ("site", "binding", "relation", "route", "result"))
def test_slice_c0_batch_rejects_foreign_seal_and_stale_live_content(kind) -> None:
    """Batch precheck uses the same live canonical evidence as ordinary insert."""
    foreign_batch, foreign_value, foreign_registry, *_rest = (
        _slice_c0_unregistered_publication(kind)
    )
    registry, key, reference, _seal = foreign_batch._entries[0]
    foreign_batch._entries[0] = (
        registry, key, reference, f"foreign-{kind}-seal",
    )
    with pytest.raises((TypeError, ValueError)):
        foreign_batch.commit()
    assert foreign_registry.get(id(foreign_value)) is None

    batch, value, value_registry, _ordinary, _identity, _validator, drift = (
        _slice_c0_unregistered_publication(kind)
    )
    field, changed = drift
    original = getattr(value, field)
    object.__setattr__(value, field, changed)
    try:
        with pytest.raises((TypeError, ValueError)):
            batch.commit()
        assert value_registry.get(id(value)) is None
    finally:
        object.__setattr__(value, field, original)


@pytest.mark.parametrize("registry_kind, foreign_kind", (
    ("site", "relation"),
    ("binding", "site"),
    ("route", "site"),
))
def test_slice_c0_ordinary_and_batch_reject_wrong_registry_record_type(
    registry_kind, foreign_kind,
) -> None:
    """Each closed registry rejects a live record owned by another registry."""
    _target_batch, target, target_registry, target_gateway, *_target_rest = (
        _slice_c0_unregistered_publication(registry_kind)
    )
    _foreign_batch, foreign, _foreign_registry, *_foreign_rest = (
        _slice_c0_unregistered_publication(foreign_kind)
    )
    with pytest.raises((TypeError, ValueError)):
        target_gateway(foreign, "sha256:" + "a" * 64)
    assert target_registry.get(id(foreign)) is None

    batch = bind._AtomicPublicationBatch()
    batch.defer(
        value=foreign, registry=target_registry,
        seal="sha256:" + "b" * 64,
    )
    with pytest.raises((TypeError, ValueError)):
        batch.commit()
    assert target_registry.get(id(foreign)) is None
    assert target_registry.get(id(target)) is None


@pytest.mark.parametrize("kind", ("site", "binding", "relation", "route", "result"))
def test_slice_c0_invalid_gateway_contender_loses_to_canonical_batch(kind) -> None:
    """An invalid contender cannot claim the key before a canonical writer."""
    batch, value, registry, ordinary, _identity, validator, _drift = (
        _slice_c0_unregistered_publication(kind)
    )
    barrier = threading.Barrier(2, timeout=10)
    contender_done = threading.Event()
    outcomes = {}

    def commit_batch():
        try:
            barrier.wait()
            contender_done.wait(timeout=10)
            batch.commit()
        except BaseException as exc:
            outcomes["batch"] = exc
        else:
            outcomes["batch"] = None

    def publish_invalid_contender():
        try:
            barrier.wait()
            ordinary(value, f"foreign-{kind}-contender")
        except BaseException as exc:
            outcomes["contender"] = exc
        else:
            outcomes["contender"] = None
        finally:
            contender_done.set()

    threads = (
        threading.Thread(target=commit_batch, daemon=True),
        threading.Thread(target=publish_invalid_contender, daemon=True),
    )
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join(timeout=15)

    assert not any(thread.is_alive() for thread in threads)
    assert type(outcomes["contender"]) is ValueError
    assert outcomes["batch"] is None
    row = registry.get(id(value))
    assert row is not None and row[0]() is value
    validator()


@pytest.mark.parametrize("kind", ("site", "binding", "relation", "route", "result"))
def test_slice_c0_registration_gateways_idempotently_reissue_exact_occurrence(
    kind,
) -> None:
    """Only the identical live occurrence with its exact seal is idempotent."""
    batch, value, registry, ordinary, identity, validator, _drift = (
        _slice_c0_unregistered_publication(kind)
    )
    batch.commit()
    row = registry[id(value)]
    assert ordinary(value, identity) is value
    assert registry[id(value)] is row
    validator()


def _slice_c0_unregistered_conditional_relation(factory_name):
    draft, _index, _build, _kwargs = _draft_probe(globals()[factory_name])
    template = draft.relation
    assert type(template) in {
        model.LoweredConditionalRouteRealization,
        model.ClonedConditionalRouteRealization,
    }
    cells = dict(zip(
        bind._realize_projected_routes_from_claim_inventory.__code__.co_freevars,
        bind._realize_projected_routes_from_claim_inventory.__closure__,
    ))
    mint = cells["mint"].cell_contents
    batch = bind._AtomicPublicationBatch()
    value = mint(
        type(template),
        {name: getattr(template, name) for name in type(template).__dataclass_fields__},
        "relation_id", _batch=batch,
    )
    return (
        batch, value, _private_route_registry(), mint.__defaults__[-1],
        cells["validate_route"].cell_contents,
    )


@pytest.mark.parametrize("factory_name", (
    "_lower_conditional_case",
    "_conditional_redirect_case_for_inventory_mutation",
))
@pytest.mark.parametrize("gateway", ("ordinary", "batch"))
def test_slice_c0_conditional_arm_drift_rejects_without_normalizing_candidate(
    factory_name, gateway,
) -> None:
    """Classification observes reversed arms; it never repairs the candidate."""
    batch, relation, registry, register, validate = (
        _slice_c0_unregistered_conditional_relation(factory_name)
    )
    canonical_arms = relation.arms
    reversed_arms = tuple(reversed(canonical_arms))
    assert reversed_arms != canonical_arms
    object.__setattr__(relation, "arms", reversed_arms)
    with pytest.raises((TypeError, ValueError)):
        if gateway == "batch":
            batch.commit()
        else:
            register(relation, relation.relation_id)
    assert relation.arms is reversed_arms
    assert registry.get(id(relation)) is None

    object.__setattr__(relation, "arms", canonical_arms)
    if gateway == "batch":
        batch.commit()
    else:
        register(relation, relation.relation_id)
    assert relation.arms is canonical_arms
    validate(relation, "relation_id")
    assert relation.arms is canonical_arms


@pytest.mark.parametrize("gateway", ("ordinary", "batch"))
def test_slice_c0_nested_failure_anchor_drift_rejects_without_normalizing(
    gateway,
) -> None:
    """A rejected result cannot launder reordered nested failure anchors."""
    accepted = bind.realize_projected_routes(
        **_c_complete_kwargs(_compiler_redirect_goto_case)
    )
    relation = accepted.realization.rows[0].relation
    canonical_anchors = tuple(sorted(
        (relation.feeder, relation.old_target), key=canonical_bytes,
    ))
    assert canonical_anchors != tuple(reversed(canonical_anchors))
    cells = dict(zip(
        bind._realize_projected_routes_from_claim_inventory.__code__.co_freevars,
        bind._realize_projected_routes_from_claim_inventory.__closure__,
    ))
    failure_gateway = cells["failure"].cell_contents
    result_gateway = cells["result"].cell_contents
    validate_result = cells["validate_result"].cell_contents
    failure = failure_gateway(
        claim_id=None, proof_id=None, route_subject_id=None,
        scope=model.RouteRealizationFailureScope.EVIDENCE,
        proposal_id=None, evidence_id=None,
        stage=model.RouteRealizationFailureStage.EFFECT_TERMINAL_PRESERVATION,
        anchored_refs=canonical_anchors,
    )
    batch = bind._AtomicPublicationBatch()
    rejected = result_gateway(
        model.ProjectedRouteRealizationRejected,
        {"failures": (failure,)}, None, _batch=batch,
    )
    result_identity = authority_id((
        type(rejected).__qualname__, (("failures", rejected.failures),),
    ))
    reversed_anchors = tuple(reversed(canonical_anchors))
    object.__setattr__(failure, "anchored_refs", reversed_anchors)
    with pytest.raises((TypeError, ValueError)):
        if gateway == "batch":
            batch.commit()
        else:
            result_gateway.__defaults__[-1](rejected, result_identity)
    assert failure.anchored_refs is reversed_anchors
    assert _private_route_registry().get(id(rejected)) is None

    object.__setattr__(failure, "anchored_refs", canonical_anchors)
    failures_tuple = rejected.failures
    if gateway == "batch":
        batch.commit()
    else:
        result_gateway.__defaults__[-1](rejected, result_identity)
    assert rejected.failures is failures_tuple
    assert failure.anchored_refs is canonical_anchors
    validate_result(rejected, model.ProjectedRouteRealizationRejected)
    assert rejected.failures is failures_tuple
    assert failure.anchored_refs is canonical_anchors


def test_slice_c0_unsorted_route_failure_uses_normalized_canonical_identity() -> None:
    """Failure construction normalizes first, then seals the resulting record."""
    accepted = bind.realize_projected_routes(
        **_c_complete_kwargs(_compiler_redirect_goto_case)
    )
    relation = accepted.realization.rows[0].relation
    canonical_anchors = tuple(sorted(
        (relation.feeder, relation.old_target), key=canonical_bytes,
    ))
    unsorted_anchors = tuple(reversed(canonical_anchors))
    assert unsorted_anchors != canonical_anchors
    cells = dict(zip(
        bind._realize_projected_routes_from_claim_inventory.__code__.co_freevars,
        bind._realize_projected_routes_from_claim_inventory.__closure__,
    ))
    failure = cells["failure"].cell_contents(
        claim_id=None, proof_id=None, route_subject_id=None,
        scope=model.RouteRealizationFailureScope.EVIDENCE,
        proposal_id=None, evidence_id=None,
        stage=model.RouteRealizationFailureStage.EFFECT_TERMINAL_PRESERVATION,
        anchored_refs=unsorted_anchors,
    )
    assert failure.anchored_refs == canonical_anchors
    canonical_tuple = failure.anchored_refs
    registry = _private_route_registry()
    row = registry.get(id(failure))
    assert row is not None and row[0]() is failure
    assert row[1] == bind._canonical_registry_seal(failure, registry)
    assert failure.anchored_refs is canonical_tuple

    rejected = cells["result"].cell_contents(
        model.ProjectedRouteRealizationRejected,
        {"failures": (failure,)},
    )
    canonical_tuple = failure.anchored_refs
    cells["validate_result"].cell_contents(
        rejected, model.ProjectedRouteRealizationRejected,
    )
    assert failure.anchored_refs is canonical_tuple


class _SliceC0EqualAnchorTuple(tuple):
    pass


class _SliceC0MutatingEqualAnchorTuple(tuple):
    def __new__(cls, values, mutation):
        value = tuple.__new__(cls, values)
        value.mutation = mutation
        return value

    def __eq__(self, other):
        self.mutation()
        return tuple.__eq__(self, other)


@dataclass(frozen=True, slots=True)
class _SliceC0AnchoredBlockRefSubclass(model.AnchoredBlockRef):
    pass


def _slice_c0_deferred_rejected_result():
    accepted = bind.realize_projected_routes(
        **_c_complete_kwargs(_compiler_redirect_goto_case)
    )
    relation = accepted.realization.rows[0].relation
    canonical_anchors = tuple(sorted(
        (relation.feeder, relation.old_target), key=canonical_bytes,
    ))
    cells = dict(zip(
        bind._realize_projected_routes_from_claim_inventory.__code__.co_freevars,
        bind._realize_projected_routes_from_claim_inventory.__closure__,
    ))
    failure = cells["failure"].cell_contents(
        claim_id=None, proof_id=None, route_subject_id=None,
        scope=model.RouteRealizationFailureScope.EVIDENCE,
        proposal_id=None, evidence_id=None,
        stage=model.RouteRealizationFailureStage.EFFECT_TERMINAL_PRESERVATION,
        anchored_refs=canonical_anchors,
    )
    batch = bind._AtomicPublicationBatch()
    rejected = cells["result"].cell_contents(
        model.ProjectedRouteRealizationRejected,
        {"failures": (failure,)}, None, _batch=batch,
    )
    result_identity = authority_id((
        type(rejected).__qualname__, (("failures", rejected.failures),),
    ))
    return (
        batch, rejected, failure, canonical_anchors, result_identity,
        cells["result"].cell_contents.__defaults__[-1],
        cells["validate_result"].cell_contents,
    )


def _slice_c0_attempt_rejected_result_publication(gateway, batch, rejected,
                                                   result_identity, register):
    try:
        if gateway == "batch":
            batch.commit()
        else:
            register(rejected, result_identity)
    except BaseException as exc:
        return exc
    return None


@pytest.mark.parametrize("gateway", ("ordinary", "batch"))
def test_slice_c0_equal_tuple_subclass_rejects_without_publication(gateway) -> None:
    """An equal tuple subclass cannot cross the closed registry boundary."""
    batch, rejected, failure, anchors, identity, register, _validate = (
        _slice_c0_deferred_rejected_result()
    )
    wrong_anchors = _SliceC0EqualAnchorTuple(anchors)
    object.__setattr__(failure, "anchored_refs", wrong_anchors)

    outcome = _slice_c0_attempt_rejected_result_publication(
        gateway, batch, rejected, identity, register,
    )

    assert type(outcome) in {TypeError, ValueError}
    assert failure.anchored_refs is wrong_anchors
    assert _private_route_registry().get(id(rejected)) is None


@pytest.mark.parametrize("gateway", ("ordinary", "batch"))
def test_slice_c0_candidate_equality_callback_never_runs(gateway) -> None:
    """Classification rejects the subclass before its equality callback."""
    batch, rejected, failure, anchors, identity, register, _validate = (
        _slice_c0_deferred_rejected_result()
    )
    callbacks = []

    def mutate_candidate():
        callbacks.append("called")
        object.__setattr__(failure, "step_index", 7)

    wrong_anchors = _SliceC0MutatingEqualAnchorTuple(anchors, mutate_candidate)
    object.__setattr__(failure, "anchored_refs", wrong_anchors)

    outcome = _slice_c0_attempt_rejected_result_publication(
        gateway, batch, rejected, identity, register,
    )

    assert type(outcome) in {TypeError, ValueError}
    assert callbacks == []
    assert failure.step_index is None
    assert failure.anchored_refs is wrong_anchors
    assert _private_route_registry().get(id(rejected)) is None


@pytest.mark.parametrize("gateway", ("ordinary", "batch"))
@pytest.mark.parametrize("container_kind", ("list", "mapping"))
def test_slice_c0_cyclic_mutable_container_has_typed_closed_rejection(
    gateway, container_kind,
) -> None:
    """Unsupported exact mutable cycles reject without recursion or writes."""
    batch, rejected, failure, _anchors, identity, register, _validate = (
        _slice_c0_deferred_rejected_result()
    )
    if container_kind == "list":
        cycle = []
        cycle.append(cycle)
        unchanged = lambda: cycle[0] is cycle
    else:
        cycle = {}
        cycle["cycle"] = cycle
        unchanged = lambda: cycle["cycle"] is cycle
    object.__setattr__(failure, "anchored_refs", cycle)

    outcome = _slice_c0_attempt_rejected_result_publication(
        gateway, batch, rejected, identity, register,
    )

    assert type(outcome) in {TypeError, ValueError}
    assert failure.anchored_refs is cycle
    assert unchanged()
    assert _private_route_registry().get(id(rejected)) is None


@pytest.mark.parametrize("gateway", ("ordinary", "batch"))
def test_slice_c0_nested_dataclass_subclass_rejects_without_publication(gateway) -> None:
    """A nested dataclass subclass is not an admitted concrete record type."""
    batch, rejected, failure, anchors, identity, register, _validate = (
        _slice_c0_deferred_rejected_result()
    )
    nested_subclass = _SliceC0AnchoredBlockRefSubclass(
        anchors[0].ref, anchors[0].anchor_ea,
    )
    wrong_anchors = (nested_subclass, anchors[1])
    object.__setattr__(failure, "anchored_refs", wrong_anchors)

    outcome = _slice_c0_attempt_rejected_result_publication(
        gateway, batch, rejected, identity, register,
    )

    assert type(outcome) in {TypeError, ValueError}
    assert failure.anchored_refs is wrong_anchors
    assert _private_route_registry().get(id(rejected)) is None


@pytest.mark.parametrize("attack", ("tuple_subclass", "equality", "list", "mapping", "dataclass_subclass"))
def test_slice_c0_registered_result_validator_uses_closed_pure_snapshot(attack) -> None:
    """The real validator rejects unsafe nested state without callbacks."""
    batch, rejected, failure, anchors, _identity, _register, validate = (
        _slice_c0_deferred_rejected_result()
    )
    batch.commit()
    published_row = _private_route_registry()[id(rejected)]
    callbacks = []
    if attack == "tuple_subclass":
        nested = _SliceC0EqualAnchorTuple(anchors)
    elif attack == "equality":
        def mutate_candidate():
            callbacks.append("called")
            object.__setattr__(failure, "step_index", 7)
        nested = _SliceC0MutatingEqualAnchorTuple(anchors, mutate_candidate)
    elif attack == "list":
        nested = []
        nested.append(nested)
    elif attack == "mapping":
        nested = {}
        nested["cycle"] = nested
    else:
        nested = (
            _SliceC0AnchoredBlockRefSubclass(
                anchors[0].ref, anchors[0].anchor_ea,
            ),
            anchors[1],
        )
    object.__setattr__(failure, "anchored_refs", nested)

    try:
        validate(rejected, model.ProjectedRouteRealizationRejected)
    except BaseException as exc:
        outcome = exc
    else:
        outcome = None

    assert type(outcome) in {TypeError, ValueError}
    assert callbacks == []
    assert failure.step_index is None
    assert failure.anchored_refs is nested
    assert _private_route_registry()[id(rejected)] is published_row


@pytest.mark.parametrize(
    "gateway", ("validate", "register", "batch"),
    ids=("validation", "ordinary-publication", "batch-publication"),
)
def test_slice_c0_state_transform_mappingproxy_rejects_foreign_backing_without_callbacks(
    gateway: str,
) -> None:
    """Every registry gateway rejects foreign attrs without producer callbacks."""
    callbacks: list[str] = []

    class ProducerMapping(Mapping):
        def __getitem__(self, key):
            callbacks.append(f"get:{key}")
            return 1

        def __iter__(self):
            callbacks.append("iter")
            return iter(("foreign",))

        def __len__(self):
            callbacks.append("len")
            return 1

    authority, *_ = _compiler_corridor_unsupported_case(
        proof_kind=route_model.SemanticRouteProofKind.STATE_TRANSFORM,
    )
    instruction = (
        authority.bound_evidence.evidence.route_proofs[0]
        .state_transform.program[0]
    )
    forged = MappingProxyType(ProducerMapping())
    object.__setattr__(instruction, "attrs", forged)
    projected_cells = dict(zip(
        bind._realize_projected_routes_from_claim_inventory.__code__.co_freevars,
        bind._realize_projected_routes_from_claim_inventory.__closure__,
    ))
    route_mint = projected_cells["mint"].cell_contents
    register_route = route_mint.__defaults__[0]
    route_registry = route_mint.__kwdefaults__["_registry"]
    route_seal = route_mint.__kwdefaults__["_seal"]

    with pytest.raises((TypeError, ValueError)):
        if gateway == "validate":
            bind.validate_source_route_authority(authority)
        elif gateway == "register":
            register_route(authority, authority.source_authority_id)
        else:
            batch = bind._AtomicPublicationBatch()
            seal = route_seal(
                authority, authority.source_authority_id,
            )
            batch.defer(
                value=authority, registry=route_registry, seal=seal,
            )
            batch.commit()

    assert instruction.attrs is forged
    assert callbacks == []


