def test_slice_c0_validator_rejects_draft_before_any_site_mint(monkeypatch) -> None:
    """C0: one draft mutation is rejected before the first site mint."""
    kwargs = _slice_c_route_kwargs(_compiler_redirect_goto_case)
    real_drafter = bind._draft_projected_site_closure

    def omit_one_source_effect(**values):
        draft = real_drafter(**values)
        return replace(draft, effect_dispositions=draft.effect_dispositions[1:])

    monkeypatch.setattr(bind, "_draft_projected_site_closure", omit_one_source_effect)
    real_site_mint = bind._site_mint
    real_validator = bind._validate_projected_site_closure_draft
    call_relations = []

    def observe_validator(*args, **values):
        call_relations.extend(
            value for value, _identity in values["route_publications"]
        )
        return real_validator(*args, **values)

    def reject_site_mint_before_validation(*args, **values):
        if args and args[0] is model.RawEffectGatePhaseFact:
            return real_site_mint(*args, **values)
        pytest.fail("site mint before validation")

    monkeypatch.setattr(bind, "_site_mint", reject_site_mint_before_validation)
    monkeypatch.setattr(bind, "_site_binding_mint", lambda *args, **values: pytest.fail("binding mint before validation"))
    monkeypatch.setattr(
        bind, "_validate_projected_site_closure_draft", observe_validator,
    )
    route_cell = next(
        cell for name, cell in zip(
            bind._realize_projected_routes_from_claim_inventory.__code__.co_freevars,
            bind._realize_projected_routes_from_claim_inventory.__closure__,
        ) if name == "mint"
    )
    real_route_mint = route_cell.cell_contents
    route_calls = []
    route_cell.cell_contents = lambda *args, **values: route_calls.append(args[0]) or real_route_mint(*args, **values)
    try:
        result = realize_projected_routes_for_test(**kwargs)
    finally:
        route_cell.cell_contents = real_route_mint
    assert type(result) is model.ProjectedRouteRealizationRejected
    failure = result.failures[0]
    assert failure.stage is model.RouteRealizationFailureStage.EFFECT_TERMINAL_PRESERVATION
    assert route_calls == []
    registry = _private_route_registry()
    assert all(registry.get(id(value)) is None for value in call_relations)


def test_slice_c0_first_closure_mint_follows_independent_validator(monkeypatch) -> None:
    """The closure validator is the last fallible step before closure minting."""
    kwargs = _slice_c_route_kwargs(_compiler_redirect_goto_case)
    events = []
    real_drafter = bind._draft_projected_site_closure
    real_validator = bind._validate_projected_site_closure_draft
    real_site_mint = bind._site_mint
    real_binding_mint = bind._site_binding_mint
    phase = {"name": "outside"}

    def observe_draft(**values):
        phase["name"] = "draft"
        draft = real_drafter(**values)
        phase["name"] = "between"
        return draft

    def observe_validator(*args, **values):
        events.append("validator")
        result = real_validator(*args, **values)
        phase["name"] = "validated"
        return result

    def observe_site_mint(*args, **values):
        if phase["name"] == "draft":
            pytest.fail("site mint during draft discovery")
        if phase["name"] == "validated":
            events.append("site-mint")
        return real_site_mint(*args, **values)

    def observe_binding_mint(*args, **values):
        if phase["name"] in {"draft", "between"}:
            pytest.fail("binding mint before independent validation")
        if phase["name"] == "validated":
            events.append("binding-mint")
        return real_binding_mint(*args, **values)

    def observe_route_mint(*args, **values):
        if phase["name"] == "draft":
            pytest.fail("route mint during draft discovery")
        if phase["name"] == "validated":
            events.append("route-mint")
        return real_route_mint(*args, **values)

    monkeypatch.setattr(bind, "_draft_projected_site_closure", observe_draft)
    monkeypatch.setattr(bind, "_validate_projected_site_closure_draft", observe_validator)
    monkeypatch.setattr(bind, "_site_mint", observe_site_mint)
    monkeypatch.setattr(bind, "_site_binding_mint", observe_binding_mint)
    route_cell = next(
        cell for name, cell in zip(
            bind._realize_projected_routes_from_claim_inventory.__code__.co_freevars,
            bind._realize_projected_routes_from_claim_inventory.__closure__,
        ) if name == "mint"
    )
    real_route_mint = route_cell.cell_contents
    route_cell.cell_contents = observe_route_mint
    try:
        result = realize_projected_routes_for_test(**kwargs)
    finally:
        route_cell.cell_contents = real_route_mint
    assert type(result) is model.ProjectedRouteRealizationAccepted
    assert events and events[0] == "validator"
    assert "site-mint" in events
    assert "binding-mint" in events


@pytest.mark.parametrize("gateway, failing_type, failing_position", (
    pytest.param("site", model.EffectSiteCoordinate, 0, id="source-effect-coordinate"),
    pytest.param("site", model.EffectSiteCoordinate, 1, id="projected-effect-coordinate"),
    pytest.param("site", model.TerminalSiteCoordinate, 0, id="source-terminal-coordinate"),
    pytest.param("site", model.TerminalSiteCoordinate, 1, id="projected-terminal-coordinate"),
    pytest.param("binding", model.ProjectedEffectSiteResult, 0, id="effect-result"),
    pytest.param("binding", model.ProjectedTerminalSiteResult, 0, id="terminal-result"),
    pytest.param("binding", model.ProjectedSemanticSitePhaseResult, 0, id="phase-result"),
    pytest.param("binding", model.ProjectedRouteSitePreservation, 0, id="preservation"),
    pytest.param("route", model.ProjectedRouteRealizationRow, 0, id="route-row"),
    pytest.param("route", model.ProjectedRouteRealization, 0, id="realization"),
    pytest.param("result", model.ProjectedRouteRealizationAccepted, 0, id="accepted-result"),
    pytest.param("commit", object, 0, id="commit-entry"),
))
def test_slice_c0_any_post_validation_build_failure_publishes_no_closure_object(
    monkeypatch, gateway, failing_type, failing_position,
) -> None:
    """Every fallible closure build precedes one all-object registry commit."""
    values = _c_complete_kwargs(_compiler_redirect_goto_case)
    projected_cells = dict(zip(
        bind._realize_projected_routes_from_claim_inventory.__code__.co_freevars,
        bind._realize_projected_routes_from_claim_inventory.__closure__,
    ))
    route_mint_cell = projected_cells["mint"]
    result_cell = projected_cells["result"]
    route_registry = _private_route_registry()
    real_validator = bind._validate_projected_site_closure_draft
    real_site_mint = bind._site_mint
    real_binding_mint = bind._site_binding_mint
    real_route_mint = route_mint_cell.cell_contents
    real_result = result_cell.cell_contents
    call_owned = []
    positions = {}

    def should_fail(current_gateway, cls):
        key = (current_gateway, cls)
        position = positions.get(key, 0)
        positions[key] = position + 1
        return (
            gateway == current_gateway
            and cls is failing_type
            and position == failing_position
        )

    def observe_validator(*args, **kwargs):
        call_owned.extend(
            ("route", value) for value, _identity in kwargs["route_publications"]
        )
        return real_validator(*args, **kwargs)

    def build_site(cls, fields, **kwargs):
        if should_fail("site", cls):
            raise ValueError(f"forced {cls.__name__} build failure")
        value = real_site_mint(cls, fields, **kwargs)
        call_owned.append(("site", value))
        return value

    def build_binding(cls, fields, identity_name, **kwargs):
        if should_fail("binding", cls):
            raise ValueError(f"forced {cls.__name__} build failure")
        value = real_binding_mint(cls, fields, identity_name, **kwargs)
        call_owned.append(("binding", value))
        return value

    def build_route(cls, fields, identity_name, **kwargs):
        if should_fail("route", cls):
            raise ValueError(f"forced {cls.__name__} build failure")
        value = real_route_mint(cls, fields, identity_name, **kwargs)
        call_owned.append(("route", value))
        return value

    def build_result(cls, fields, identity_name=None, **kwargs):
        if should_fail("result", cls):
            raise ValueError(f"forced {cls.__name__} build failure")
        value = real_result(cls, fields, identity_name, **kwargs)
        if cls is model.ProjectedRouteRealizationAccepted:
            call_owned.append(("route", value))
        return value

    monkeypatch.setattr(
        bind, "_validate_projected_site_closure_draft", observe_validator,
    )
    monkeypatch.setattr(bind, "_site_mint", build_site)
    monkeypatch.setattr(bind, "_site_binding_mint", build_binding)
    if gateway == "commit":
        monkeypatch.setattr(
            bind._AtomicPublicationBatch, "commit",
            lambda self: (_ for _ in ()).throw(ValueError("forced commit failure")),
        )
    route_mint_cell.cell_contents = build_route
    result_cell.cell_contents = build_result
    try:
        outcome = bind.realize_projected_routes(**values)
    finally:
        route_mint_cell.cell_contents = real_route_mint
        result_cell.cell_contents = real_result

    assert type(outcome) is model.ProjectedRouteRealizationRejected
    assert call_owned
    registries = {
        "route": route_registry,
        "site": bind._SITE_REGISTRY,
        "binding": bind._SITE_BINDING_REGISTRY,
    }
    for kind, value in call_owned:
        row = registries[kind].get(id(value))
        assert row is None or row[0]() is not value, (
            type(value).__name__, getattr(value, "relation_id", None),
            getattr(value, "result_id", None),
        )


def test_slice_c0_late_complete_batch_precheck_failure_publishes_nothing(
    monkeypatch,
) -> None:
    """A last accepted-result seal failure leaves every earlier entry absent."""
    real_commit = bind._AtomicPublicationBatch.commit
    captured = []

    def reject_last_entry(batch):
        entries = tuple(batch._entries)
        assert entries
        captured.extend((*entry, entry[2]()) for entry in entries)
        registry, key, reference, _seal = entries[-1]
        accepted = reference()
        assert type(accepted) is model.ProjectedRouteRealizationAccepted
        batch._entries[-1] = (
            registry, key, reference, "sha256:" + "f" * 64,
        )
        return real_commit(batch)

    monkeypatch.setattr(bind._AtomicPublicationBatch, "commit", reject_last_entry)
    outcome = bind.realize_projected_routes(
        **_c_complete_kwargs(_compiler_redirect_goto_case)
    )

    assert type(outcome) is model.ProjectedRouteRealizationRejected
    assert type(captured[-1][4]) is model.ProjectedRouteRealizationAccepted
    assert {
        type(value).__name__
        for _registry, _key, _reference, _seal, value in captured
    } >= {
        "DirectRouteRealization",
        "EffectSiteCoordinate",
        "TerminalSiteCoordinate",
        "ProjectedEffectSiteResult",
        "ProjectedTerminalSiteResult",
        "ProjectedSemanticSitePhaseResult",
        "ProjectedRouteSitePreservation",
        "ProjectedRouteRealizationRow",
        "ProjectedRouteRealization",
        "ProjectedRouteRealizationAccepted",
    }
    for registry, key, _reference, _seal, value in captured:
        row = registry.get(key)
        assert row is None or row[0]() is not value


def test_slice_c0_nested_valid_calls_keep_call_local_route_publications(monkeypatch) -> None:
    """A nested valid closure cannot clear its caller's structural relations."""
    outer_expected = bind.realize_projected_routes(
        **_c_complete_kwargs(_compiler_redirect_goto_case)
    )
    inner_expected = bind.realize_projected_routes(
        **_c_complete_kwargs(_compiler_direct_branch_case)
    )
    assert type(outer_expected) is model.ProjectedRouteRealizationAccepted
    assert type(inner_expected) is model.ProjectedRouteRealizationAccepted

    outer_values = _c_complete_kwargs(_compiler_redirect_goto_case)
    inner_values = _c_complete_kwargs(_compiler_direct_branch_case)
    real_validator = bind._validate_projected_site_closure_draft
    nested_results = []
    inside_nested_call = False

    def validate_with_nested_call(*args, **values):
        nonlocal inside_nested_call
        if not inside_nested_call:
            inside_nested_call = True
            try:
                nested_results.append(bind.realize_projected_routes(**inner_values))
            finally:
                inside_nested_call = False
        return real_validator(*args, **values)

    projected_cells = dict(zip(
        bind._realize_projected_routes_from_claim_inventory.__code__.co_freevars,
        bind._realize_projected_routes_from_claim_inventory.__closure__,
    ))
    route_mint_cell = projected_cells["mint"]
    real_route_mint = route_mint_cell.cell_contents
    route_mints = []

    def observe_route_mint(cls, values, identity_name, **kwargs):
        route_mints.append(cls)
        return real_route_mint(cls, values, identity_name, **kwargs)

    monkeypatch.setattr(
        bind, "_validate_projected_site_closure_draft", validate_with_nested_call,
    )
    route_mint_cell.cell_contents = observe_route_mint
    try:
        outer_result = bind.realize_projected_routes(**outer_values)
    finally:
        route_mint_cell.cell_contents = real_route_mint

    assert len(nested_results) == 1
    inner_result = nested_results[0]
    assert type(inner_result) is model.ProjectedRouteRealizationAccepted
    assert type(outer_result) is model.ProjectedRouteRealizationAccepted
    assert inner_result == inner_expected
    assert outer_result == outer_expected
    assert inner_result.realization == inner_expected.realization
    assert outer_result.realization == outer_expected.realization
    assert inner_result.realization.realization_id == inner_expected.realization.realization_id
    assert outer_result.realization.realization_id == outer_expected.realization.realization_id
    route_registry = _private_route_registry()
    for row in (*inner_result.realization.rows, *outer_result.realization.rows):
        registered = route_registry.get(id(row.relation))
        assert registered is not None and registered[0]() is row.relation
    assert route_mints.count(model.ProjectedRouteRealizationRow) == 2
    assert route_mints.count(model.ProjectedRouteRealization) == 2


def test_slice_c0_barrier_overlapping_calls_match_isolated_content_and_ids(
    monkeypatch,
) -> None:
    """Two real validator overlaps retain complete call-local publications."""
    first_expected = bind.realize_projected_routes(
        **_c_complete_kwargs(_compiler_redirect_goto_case)
    )
    second_expected = bind.realize_projected_routes(
        **_c_complete_kwargs(_compiler_direct_branch_case)
    )
    assert type(first_expected) is model.ProjectedRouteRealizationAccepted
    assert type(second_expected) is model.ProjectedRouteRealizationAccepted
    inputs = (
        _c_complete_kwargs(_compiler_redirect_goto_case),
        _c_complete_kwargs(_compiler_direct_branch_case),
    )
    barrier = threading.Barrier(2, timeout=10)
    real_validator = bind._validate_projected_site_closure_draft
    outcomes = [None, None]
    errors = []

    def overlap_validator(*args, **kwargs):
        barrier.wait()
        return real_validator(*args, **kwargs)

    def worker(index):
        try:
            outcomes[index] = bind.realize_projected_routes(**inputs[index])
        except BaseException as exc:
            errors.append(exc)

    monkeypatch.setattr(
        bind, "_validate_projected_site_closure_draft", overlap_validator,
    )
    threads = tuple(
        threading.Thread(target=worker, args=(index,), daemon=True)
        for index in range(2)
    )
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join(timeout=15)

    assert not any(thread.is_alive() for thread in threads)
    assert errors == []
    first, second = outcomes
    assert first == first_expected
    assert second == second_expected
    assert first.realization == first_expected.realization
    assert second.realization == second_expected.realization
    assert first.realization.realization_id == first_expected.realization.realization_id
    assert second.realization.realization_id == second_expected.realization.realization_id
    bind.validate_projected_route_realization_result(first)
    bind.validate_projected_route_realization_result(second)
    first_relations = tuple(row.relation for row in first.realization.rows)
    second_relations = tuple(row.relation for row in second.realization.rows)
    route_registry = _private_route_registry()
    assert all(
        route_registry.get(id(relation)) is not None
        and route_registry[id(relation)][0]() is relation
        for relation in (*first_relations, *second_relations)
    )
    assert not any(
        first_relation is second_relation
        for first_relation in first_relations
        for second_relation in second_relations
    )


def test_slice_c0_private_structural_batches_have_no_leftover_pending_relation() -> None:
    """Private structural discovery returns one immutable call-owned batch."""
    cells, draft_kernel, _build = _private_projected_kernel_cells()

    def inputs(factory):
        authority, plan, source, projected, facts, attempt, *_ = factory()
        return dict(
            source_authority=authority,
            plan=plan,
            source_inventory=source,
            projected_inventory=projected,
            patch_step_facts=facts,
            attempt_id=attempt,
            _mint=cells["_route_mint"].cell_contents,
            _failure=cells["_route_failure"].cell_contents,
            _result=cells["_route_result"].cell_contents,
            _validate=cells["validate_route"].cell_contents,
        )

    first = draft_kernel(**inputs(_compiler_redirect_goto_case))
    second = draft_kernel(**inputs(_compiler_direct_branch_case))
    assert len(first) == len(second) == 4
    first_structural, first_drafts, first_index, first_publications = first
    second_structural, second_drafts, second_index, second_publications = second
    assert first_structural is second_structural is None
    assert first_index is not second_index
    assert type(first_publications) is type(second_publications) is tuple
    assert first_publications is not second_publications
    assert tuple(value for value, _identity in first_publications) == tuple(
        draft.relation for draft in first_drafts
    )
    assert tuple(value for value, _identity in second_publications) == tuple(
        draft.relation for draft in second_drafts
    )
    for relation in (
        *(draft.relation for draft in first_drafts),
        *(draft.relation for draft in second_drafts),
    ):
        with pytest.raises(ValueError, match="not minted by its kernel"):
            cells["validate_route"].cell_contents(relation, "relation_id")


@pytest.mark.parametrize("mutation", ("raw", "subset", "source_subject", "projected_subject"))
def test_slice_c0_red_validator_rejects_named_draft_mutations_before_mint(monkeypatch, mutation) -> None:
    """C0 REDs for the review's incomplete independent-validator cases."""
    kwargs = _slice_c_route_kwargs(_compiler_redirect_goto_case)
    real_drafter = bind._draft_projected_site_closure

    def mutate(**values):
        draft = real_drafter(**values)
        if mutation == "raw":
            return replace(draft, raw_retained_source_owners=(), raw_lost_source_owners=())
        if mutation == "subset":
            return replace(draft, route_subsets=())
        if mutation == "source_subject":
            rows = tuple(replace(item, source_subject=object()) for item in draft.effect_dispositions)
            return replace(draft, effect_dispositions=rows)
        rows = tuple(replace(item, projected_subject=object()) for item in draft.effect_dispositions)
        return replace(draft, effect_dispositions=rows)

    monkeypatch.setattr(bind, "_draft_projected_site_closure", mutate)
    result = realize_projected_routes_for_test(**kwargs)
    assert type(result) is model.ProjectedRouteRealizationRejected
    failure = result.failures[0]
    assert failure.stage is model.RouteRealizationFailureStage.EFFECT_TERMINAL_PRESERVATION
    if mutation in {"source_subject", "projected_subject"}:
        assert failure.scope is model.RouteRealizationFailureScope.STEP
        assert failure.claim_id is not None
        assert failure.proof_id is not None
        assert failure.route_subject_id is not None
        assert failure.step_index == 0
        assert failure.step_digest is not None
        assert failure.anchored_refs
    else:
        assert failure.scope is model.RouteRealizationFailureScope.EVIDENCE


