@pytest.mark.parametrize("kind", ("exact", "local"))
def test_slice_c0_public_leaf_translation_keeps_claim_and_mints_nothing(monkeypatch, kind) -> None:
    """Public translation preserves closed leaf claims before any closure mint."""
    values = _c_complete_kwargs(_compiler_redirect_goto_case)
    if kind == "exact":
        claim = next(
            item for item in exact_fixture()[1].claims
            if type(item) is model.ExactInfeasibleEffectClaim
        )
        fact = values["patch_step_facts"][0]
        source_row = values["source_inventory"].effects[0]
        violation = bind._ProjectedSiteDraftViolation(
            "exact leaf failure", scope=model.RouteRealizationFailureScope.STEP,
            claim=claim, proof=exact_fixture()[1].route_evidence.route_proofs[0],
            patch_step_fact=fact, source_row=source_row,
        )
    else:
        local = _c_local_alias_fixture()
        claim = local["claim"]
        fact = local["patch_step_fact"]
        source_row = local["source_inventory"].effects[0]
        violation = bind._ProjectedSiteDraftViolation(
            "local leaf failure", scope=model.RouteRealizationFailureScope.STEP,
            claim=claim, patch_step_fact=fact, source_row=source_row,
        )

    def fail_draft(**_kwargs):
        raise violation

    events = []
    monkeypatch.setattr(bind, "_draft_projected_site_closure", fail_draft)
    monkeypatch.setattr(bind, "_site_mint", lambda *a, **k: events.append("site") or pytest.fail("site mint"))
    monkeypatch.setattr(bind, "_site_binding_mint", lambda *a, **k: events.append("binding") or pytest.fail("binding mint"))
    route_cell = next(
        cell for name, cell in zip(
            bind._realize_projected_routes_from_claim_inventory.__code__.co_freevars,
            bind._realize_projected_routes_from_claim_inventory.__closure__,
        ) if name == "mint"
    )
    real_route_mint = route_cell.cell_contents
    route_cell.cell_contents = lambda *a, **k: events.append("route") or pytest.fail("route mint")
    try:
        result = bind.realize_projected_routes(**values)
    finally:
        route_cell.cell_contents = real_route_mint
    assert type(result) is model.ProjectedRouteRealizationRejected
    assert len(result.failures) == 1
    failure = result.failures[0]
    assert failure.claim_id == claim.claim_id
    assert failure.scope is model.RouteRealizationFailureScope.STEP
    assert failure.step_index == fact.step_index
    assert failure.step_digest == fact.step_digest
    if kind == "exact":
        expected_refs = tuple(sorted({
            model.AnchoredBlockRef(
                locator.block_ref if hasattr(locator, "block_ref") else locator.owner_ref,
                locator.anchor_ea if hasattr(locator, "anchor_ea") else locator.owner_anchor_ea,
            )
            for subject in (
                claim.effect_subject, claim.source_subject, claim.predicate_subject,
                claim.selected_target_subject, claim.discarded_effect_subject,
            )
            for locator in (subject.locator,)
        }, key=canonical_bytes))
        assert failure.anchored_refs == expected_refs
    else:
        assert failure.anchored_refs == (model.AnchoredBlockRef(
            claim.owner_subject.locator.block_ref,
            claim.owner_subject.locator.anchor_ea,
        ),)
    assert events == []


def test_slice_c0_real_exact_leaf_wrapper_keeps_complete_diagnostic_coordinates(
    monkeypatch,
) -> None:
    """A real proposal-owned exact leaf failure keeps every closed coordinate."""
    values = _c_exact_leaf_transaction_inputs()
    claim = next(
        item for item in values["claims"]
        if type(item) is model.ExactInfeasibleEffectClaim
    )
    proof = next(
        item for item in values["source_authority"].proposal.route_evidence.route_proofs
        if item.proof_id == claim.route_proof_ids[0]
    )
    relation_draft = next(
        item for item in values["drafts"]
        if item.proof is proof
        and item.selected_target_ref == claim.selected_target_subject.block_ref
    )
    source_row = next(
        row for row in values["source_inventory"].effects
        if row.owner_ref == claim.effect_subject.locator.owner_ref
        and row.instruction_ea == claim.effect_subject.locator.instruction_ea
        and row.effect_kind is claim.effect_subject.locator.effect_kind
    )
    route_mint_cell = next(
        cell for name, cell in zip(
            bind._realize_projected_routes_from_claim_inventory.__code__.co_freevars,
            bind._realize_projected_routes_from_claim_inventory.__closure__,
        ) if name == "mint"
    )
    real_route_mint = route_mint_cell.cell_contents
    events = []
    route_mint_cell.cell_contents = lambda *args, **kwargs: events.append("route") or real_route_mint(*args, **kwargs)
    monkeypatch.setattr(bind, "_site_mint", lambda *args, **kwargs: events.append("site") or pytest.fail("site mint"))
    monkeypatch.setattr(bind, "_site_binding_mint", lambda *args, **kwargs: events.append("binding") or pytest.fail("binding mint"))
    original_width = claim.width
    object.__setattr__(claim, "width", original_width + 1)
    try:
        with pytest.raises(bind._ProjectedSiteDraftViolation) as raised:
            bind._draft_projected_site_closure(**{
                key: value for key, value in values.items()
                if key not in {"route_publications"}
            })
    finally:
        object.__setattr__(claim, "width", original_width)
        route_mint_cell.cell_contents = real_route_mint

    violation = raised.value
    assert violation.reason_code == "exact-effect source site drifts from claim"
    assert violation.claim is claim
    assert violation.proof is proof
    assert violation.relation_draft is relation_draft
    assert violation.source_row is source_row
    coordinates = bind._route_failure_coordinates(
        values["source_authority"].proposal,
        **bind._translate_projected_site_draft_violation(violation),
    )
    expected_anchors = tuple(sorted({
        model.AnchoredBlockRef(
            locator.block_ref if hasattr(locator, "block_ref") else locator.owner_ref,
            locator.anchor_ea if hasattr(locator, "anchor_ea") else locator.owner_anchor_ea,
        )
        for subject in (
            claim.effect_subject, claim.source_subject, claim.predicate_subject,
            claim.selected_target_subject, claim.discarded_effect_subject,
        )
        for locator in (subject.locator,)
    }, key=canonical_bytes))
    assert len(expected_anchors) == 4
    assert coordinates == {
        "claim_id": claim.claim_id,
        "proof_id": proof.proof_id,
        "route_subject_id": None,
        "scope": model.RouteRealizationFailureScope.STEP,
        "proposal_id": authority_id(values["source_authority"].proposal),
        "evidence_id": values["source_authority"].proposal.route_evidence.atomic_group_id,
        "stage": model.RouteRealizationFailureStage.EFFECT_TERMINAL_PRESERVATION,
        "step_index": relation_draft.facts[0].step_index,
        "step_digest": relation_draft.facts[0].step_digest,
        "anchored_refs": expected_anchors,
    }
    assert events == []
    route_registry = _private_route_registry()
    assert all(
        route_registry.get(id(value)) is None
        for value, _identity in values["route_publications"]
    )


def test_slice_c0_real_transaction_local_leaf_wrapper_keeps_exact_coordinates(
    monkeypatch,
) -> None:
    """A transaction-derived local leaf failure keeps its exact claim and fact."""
    values = _c_two_local_alias_transaction_inputs()
    claim = next(
        item for item in values["claims"]
        if type(item) is model.LocalAliasEffectScalarizationClaim
    )
    fact = next(
        item for item in values["patch_step_facts"]
        if item.step_index == claim.step_index
    )
    projected_observation = next(
        item for item in values["projected_observations"]
        if item.instruction_ea == claim.host_ea
    )
    source_row = next(
        item for item in values["source_rows"]
        if item.instruction_ea == claim.host_ea
    )
    route_mint_cell = next(
        cell for name, cell in zip(
            bind._realize_projected_routes_from_claim_inventory.__code__.co_freevars,
            bind._realize_projected_routes_from_claim_inventory.__closure__,
        ) if name == "mint"
    )
    real_route_mint = route_mint_cell.cell_contents
    events = []
    route_mint_cell.cell_contents = lambda *args, **kwargs: events.append("route") or real_route_mint(*args, **kwargs)
    monkeypatch.setattr(bind, "_site_mint", lambda *args, **kwargs: events.append("site") or pytest.fail("site mint"))
    monkeypatch.setattr(bind, "_site_binding_mint", lambda *args, **kwargs: events.append("binding") or pytest.fail("binding mint"))
    mutated_observation = replace(
        projected_observation, display_text="not the scalar grammar",
    )
    mutated_blocks = tuple(
        replace(
            block,
            instruction_observations=tuple(
                mutated_observation if item is projected_observation else item
                for item in block.instruction_observations
            ),
        )
        if projected_observation in block.instruction_observations else block
        for block in values["projected_inventory"].blocks
    )
    projected_inventory = replace(
        values["projected_inventory"], blocks=mutated_blocks,
        inventory_digest=semantic_graph_inventory_digest(
            values["projected_inventory"].phase,
            values["projected_inventory"].graph_fingerprint,
            values["projected_inventory"].generation,
            mutated_blocks,
            values["projected_inventory"].subjects,
            values["projected_inventory"].bindings,
            values["projected_inventory"].effects,
            values["projected_inventory"].terminals,
            values["projected_inventory"].topology,
            values["projected_inventory"].reachable_serials,
            values["projected_inventory"].entry_serial,
            values["projected_inventory"].source_subject_ids,
            values["projected_inventory"].function_ea,
        ),
    )
    try:
        with pytest.raises(bind._ProjectedSiteDraftViolation) as raised:
            bind._draft_projected_site_closure(**{
                key: projected_inventory if key == "projected_inventory" else value
                for key, value in values.items()
                if key not in {
                    "route_publications", "source_rows", "projected_observations",
                }
            })
    finally:
        route_mint_cell.cell_contents = real_route_mint

    violation = raised.value
    assert violation.reason_code == "local-alias MOV does not match closed scalar grammar"
    assert violation.claim is claim
    assert violation.proof is None
    assert violation.patch_step_fact is fact
    assert violation.source_row is source_row
    coordinates = bind._route_failure_coordinates(
        values["source_authority"].proposal,
        **bind._translate_projected_site_draft_violation(violation),
    )
    assert coordinates == {
        "claim_id": claim.claim_id,
        "proof_id": None,
        "route_subject_id": None,
        "scope": model.RouteRealizationFailureScope.STEP,
        "proposal_id": authority_id(values["source_authority"].proposal),
        "evidence_id": values["source_authority"].proposal.route_evidence.atomic_group_id,
        "stage": model.RouteRealizationFailureStage.EFFECT_TERMINAL_PRESERVATION,
        "step_index": fact.step_index,
        "step_digest": fact.step_digest,
        "anchored_refs": (model.AnchoredBlockRef(
            claim.owner_subject.locator.block_ref,
            claim.owner_subject.locator.anchor_ea,
        ),),
    }
    assert events == []
    route_registry = _private_route_registry()
    assert all(
        route_registry.get(id(value)) is None
        for value, _identity in values["route_publications"]
    )


def test_slice_c0_transaction_derived_two_local_aliases_retain_occurrences() -> None:
    """C0 boundary: real transaction facts reach the private drafter once each."""
    values = _c_two_local_alias_transaction_inputs()
    draft = bind._draft_projected_site_closure(
        authority_id=values["authority_id"], source_authority=values["source_authority"],
        plan=values["plan"], source_inventory=values["source_inventory"],
        projected_inventory=values["projected_inventory"], claims=values["claims"],
        patch_step_facts=values["patch_step_facts"], raw_effect_gate_fact=values["raw_effect_gate_fact"],
        legacy_effective_gate_facts=None, attempt_id=values["attempt_id"],
        drafts=values["drafts"], owner_index=values["owner_index"],
    )
    local_rows = tuple(item for item in draft.effect_dispositions if item.local_binding is not None)
    assert len(draft.local_binding_drafts) == 2
    assert len(local_rows) == 2
    draft_by_ea = {
        item.claim.host_ea: item for item in draft.local_binding_drafts
    }
    row_by_ea = {
        item.local_binding.claim.host_ea: item for item in local_rows
    }
    expected_by_ea = {
        source_row.instruction_ea: (source_row, projected_observation)
        for source_row, projected_observation in zip(
            values["source_rows"], values["projected_observations"]
        )
    }
    assert set(row_by_ea) == set(expected_by_ea)
    first_ea, second_ea = tuple(sorted(expected_by_ea))
    for host_ea in (first_ea, second_ea):
        row = row_by_ea[host_ea]
        binding = draft_by_ea[host_ea]
        source_row, projected_observation = expected_by_ea[host_ea]
        derived_claim = next(
            claim for claim in values["claims"]
            if type(claim) is model.LocalAliasEffectScalarizationClaim
            and claim.host_ea == host_ea
        )
        derived_fact = next(
            fact for fact in values["patch_step_facts"]
            if fact.step_index == derived_claim.step_index
        )
        assert binding.claim is derived_claim
        assert binding.patch_step_fact is derived_fact
        assert row.local_binding is binding
        assert row.patch_step_fact is derived_fact
        assert row.source_row is source_row
        assert row.projected_row is None
        assert binding.projected_observation is projected_observation
        assert sum(item.claim is derived_claim for item in draft.local_binding_drafts) == 1
        assert sum(item.patch_step_fact is derived_fact for item in draft.local_binding_drafts) == 1
        assert sum(item.local_binding is binding for item in local_rows) == 1
        assert sum(item.patch_step_fact is derived_fact for item in local_rows) == 1


def test_slice_c0_independent_public_preimage_characterization() -> None:
    """Hand-check every direct-route preimage from canonical inputs."""
    from d810.transforms.unflatten_authority.ids import (
        derived_effect_gate_fact_id,
        projected_effect_site_result_id, projected_route_realization_id,
        projected_route_realization_row_id, projected_route_site_preservation_id,
        projected_semantic_site_phase_result_id, projected_terminal_site_result_id,
        raw_effect_gate_phase_fact_id, route_realization_id,
    )
    from d810.transforms.unflatten_authority.gates import GenericEffectfulGateFacts

    values = _c_complete_kwargs(_compiler_redirect_goto_case)
    result = bind.realize_projected_routes(**values)
    assert type(result) is model.ProjectedRouteRealizationAccepted
    realization = result.realization
    phase = realization.site_phase_result
    assert phase.exact_effect_bindings == ()
    assert phase.local_alias_bindings == ()
    source = values["source_inventory"]
    projected = values["projected_inventory"]
    source_effect = next(row for row in source.effects if row.owner_serial in source.reachable_serials)
    projected_effect = next(row for row in projected.effects if row.owner_ref == source_effect.owner_ref)
    source_terminal = next(row for row in source.terminals if row.owner_serial in source.reachable_serials)
    projected_terminal = next(row for row in projected.terminals if row.owner_ref == source_terminal.owner_ref)

    def subject_id(inventory, row, role):
        return next(
            binding.subject.subject_id for binding in inventory.bindings
            if getattr(binding.subject.locator, "owner_ref", getattr(binding.subject.locator, "block_ref", None)) == row.owner_ref
            and getattr(binding.subject.locator, "instruction_ea", None) == row.instruction_ea
            and binding.subject.role is role
        )

    source_effect_coord = model.EffectSiteCoordinate.__new__(model.EffectSiteCoordinate)
    for name, item in {
        "owner": model.AnchoredBlockRef(source_effect.owner_ref, source_effect.owner_anchor_ea),
        "instruction_ordinal": source_effect.instruction_ordinal,
        "instruction_ea": source_effect.instruction_ea,
        "effect_kind": source_effect.effect_kind,
        "opcode": source_effect.opcode,
        "width": source_effect.width,
    }.items(): object.__setattr__(source_effect_coord, name, item)
    projected_effect_coord = model.EffectSiteCoordinate.__new__(model.EffectSiteCoordinate)
    for name, item in {
        "owner": model.AnchoredBlockRef(projected_effect.owner_ref, projected_effect.owner_anchor_ea),
        "instruction_ordinal": projected_effect.instruction_ordinal,
        "instruction_ea": projected_effect.instruction_ea,
        "effect_kind": projected_effect.effect_kind,
        "opcode": projected_effect.opcode,
        "width": projected_effect.width,
    }.items(): object.__setattr__(projected_effect_coord, name, item)
    source_terminal_coord = model.TerminalSiteCoordinate.__new__(model.TerminalSiteCoordinate)
    for name, item in {
        "owner": model.AnchoredBlockRef(source_terminal.owner_ref, source_terminal.owner_anchor_ea),
        "instruction_ordinal": source_terminal.instruction_ordinal,
        "instruction_ea": source_terminal.instruction_ea,
        "terminal_kind": source_terminal.terminal_kind,
    }.items(): object.__setattr__(source_terminal_coord, name, item)
    projected_terminal_coord = model.TerminalSiteCoordinate.__new__(model.TerminalSiteCoordinate)
    for name, item in {
        "owner": model.AnchoredBlockRef(projected_terminal.owner_ref, projected_terminal.owner_anchor_ea),
        "instruction_ordinal": projected_terminal.instruction_ordinal,
        "instruction_ea": projected_terminal.instruction_ea,
        "terminal_kind": projected_terminal.terminal_kind,
    }.items(): object.__setattr__(projected_terminal_coord, name, item)

    raw_gate = GenericEffectfulGateFacts(
        True, frozenset({source_effect.owner_serial}),
        frozenset({source_effect.owner_serial}), frozenset(),
        "slice-3b4-c-red-rebound",
    )
    raw = object.__new__(model.RawEffectGatePhaseFact)
    raw_values = {
        "phase": model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        "source_inventory_digest": source.inventory_digest,
        "projected_inventory_digest": projected.inventory_digest,
        "source_fingerprint": source.graph_fingerprint,
        "projected_fingerprint": projected.graph_fingerprint,
        "source_generation": source.generation,
        "projected_generation": projected.generation,
        "pre_effectful_source_owners": (source_effect_coord.owner,),
        "raw_retained_source_owners": (source_effect_coord.owner,),
        "raw_lost_source_owners": (),
        "generic_raw_payload_digest": authority_id(("unflatten.raw-effect-gate-payload.v1", raw_gate)),
        "fact_id": "sha256:" + "0" * 64,
    }
    for name, item in raw_values.items(): object.__setattr__(raw, name, item)
    object.__setattr__(raw, "fact_id", raw_effect_gate_phase_fact_id(raw))

    expected_effect = model.ProjectedEffectSiteResult.__new__(model.ProjectedEffectSiteResult)
    for name, item in {
        "authority_id": values["authority_id"], "attempt_id": values["attempt_id"],
        "phase": model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        "source_subject_id": subject_id(source, source_effect, model.SemanticSubjectRole.EFFECT_SITE),
        "source_site": source_effect_coord,
        "outcome": model.ProjectedEffectSiteOutcome.PRESERVED,
        "projected_subject_id": subject_id(projected, projected_effect, model.SemanticSubjectRole.EFFECT_SITE),
        "projected_site": projected_effect_coord, "scalarized_site": None,
        "lineage_kind": model.ProjectedSiteLineageKind.SAME_OWNER,
        "relation_id": None, "supporting_claim_id": None,
        "supporting_binding_result_id": None, "latent_exact_binding_result_id": None,
        "patch_step_index": None, "patch_step_digest": None,
        "raw_effect_gate_fact_id": raw.fact_id, "result_id": "sha256:" + "0" * 64,
    }.items(): object.__setattr__(expected_effect, name, item)
    object.__setattr__(expected_effect, "result_id", projected_effect_site_result_id(expected_effect))
    expected_terminal = model.ProjectedTerminalSiteResult.__new__(model.ProjectedTerminalSiteResult)
    for name, item in {
        "authority_id": values["authority_id"], "attempt_id": values["attempt_id"],
        "phase": model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        "source_subject_id": subject_id(source, source_terminal, model.SemanticSubjectRole.TERMINAL_SITE),
        "source_site": source_terminal_coord,
        "outcome": model.ProjectedTerminalSiteOutcome.PRESERVED,
        "projected_subject_id": subject_id(projected, projected_terminal, model.SemanticSubjectRole.TERMINAL_SITE),
        "projected_site": projected_terminal_coord,
        "lineage_kind": model.ProjectedSiteLineageKind.SAME_OWNER,
        "relation_id": None, "result_id": "sha256:" + "0" * 64,
    }.items(): object.__setattr__(expected_terminal, name, item)
    object.__setattr__(expected_terminal, "result_id", projected_terminal_site_result_id(expected_terminal))

    route_claim = values["plan"].unflatten_proposal.claims[0]
    route_step = values["plan"].steps[0]
    feeder_serial = next(serial for ref, serial in values["plan"].source_coordinates if ref == route_step.from_serial)
    old_target_serial = next(serial for ref, serial in values["plan"].source_coordinates if ref == route_step.old_target)
    new_target_serial = next(serial for ref, serial in values["plan"].source_coordinates if ref == route_step.new_target)
    feeder_block = next(block for block in source.blocks if block.serial == feeder_serial)
    old_target_block = next(block for block in source.blocks if block.serial == old_target_serial)
    new_target_block = next(block for block in source.blocks if block.serial == new_target_serial)
    feeder = model.AnchoredBlockRef(route_step.from_serial, feeder_block.instruction_observations[0].instruction_ea)
    old_target = model.AnchoredBlockRef(route_step.old_target, old_target_block.instruction_observations[0].instruction_ea)
    new_target = model.AnchoredBlockRef(route_step.new_target, new_target_block.instruction_observations[0].instruction_ea)
    expected_relation = model.DirectRouteRealization.__new__(model.DirectRouteRealization)
    for name, item in {
        "feeder": feeder, "old_target": old_target, "new_target": new_target,
        "relation_id": route_realization_id(("direct", feeder, old_target, new_target)),
    }.items(): object.__setattr__(expected_relation, name, item)
    relation_id = expected_relation.relation_id
    expected_effect_ids = (expected_effect.result_id,)
    expected_terminal_ids = (expected_terminal.result_id,)
    expected_phase = model.ProjectedSemanticSitePhaseResult.__new__(model.ProjectedSemanticSitePhaseResult)
    for name, item in {
        "authority_id": values["authority_id"],
        "source_authority_id": values["source_authority"].source_authority_id,
        "attempt_id": values["attempt_id"],
        "phase": model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        "plan_id": values["plan"].plan_id,
        "source_inventory_digest": source.inventory_digest,
        "projected_inventory_digest": projected.inventory_digest,
        "source_fingerprint": source.graph_fingerprint,
        "projected_fingerprint": projected.graph_fingerprint,
        "source_generation": source.generation, "projected_generation": projected.generation,
        "relation_ids": (relation_id,), "raw_effect_gate_fact": raw,
        "exact_effect_bindings": (), "local_alias_bindings": (),
        "effect_results": (expected_effect,), "terminal_results": (expected_terminal,),
        "derived_effect_gate_fact_id": derived_effect_gate_fact_id(raw.fact_id, expected_effect_ids),
        "result_id": "sha256:" + "0" * 64,
    }.items(): object.__setattr__(expected_phase, name, item)
    object.__setattr__(expected_phase, "result_id", projected_semantic_site_phase_result_id(expected_phase))
    preservation = model.ProjectedRouteSitePreservation.__new__(model.ProjectedRouteSitePreservation)
    for name, item in {
        "authority_id": values["authority_id"], "attempt_id": values["attempt_id"],
        "relation_id": relation_id, "site_phase_result_id": expected_phase.result_id,
        "effect_result_ids": expected_effect_ids, "terminal_result_ids": expected_terminal_ids,
        "preservation_id": "sha256:" + "0" * 64,
    }.items(): object.__setattr__(preservation, name, item)
    object.__setattr__(preservation, "preservation_id", projected_route_site_preservation_id(preservation))
    route_fact = values["patch_step_facts"][0]
    expected_row = model.ProjectedRouteRealizationRow.__new__(model.ProjectedRouteRealizationRow)
    for name, item in {
        "claim_id": route_claim.claim_id, "proof_id": route_claim.route_proof_ids[0],
        "route_subject_id": route_claim.retired_route_subject.subject_id,
        "relation": expected_relation, "site_preservation": preservation,
        "plan_step_index": route_fact.step_index,
        "plan_step_type": model.PatchStepKind.REDIRECT_GOTO,
        "plan_step_digest": route_fact.step_digest,
        "source_fingerprint": source.graph_fingerprint,
        "projected_fingerprint": projected.graph_fingerprint,
        "source_generation": source.generation, "projected_generation": projected.generation,
        "row_id": "sha256:" + "0" * 64,
    }.items(): object.__setattr__(expected_row, name, item)
    object.__setattr__(expected_row, "row_id", projected_route_realization_row_id((
        expected_row.claim_id, expected_row.proof_id, expected_row.route_subject_id,
        expected_relation, expected_row.plan_step_index, expected_row.plan_step_type,
        expected_row.plan_step_digest, source.graph_fingerprint, projected.graph_fingerprint,
        source.generation, projected.generation, preservation,
    )))
    expected_realization = model.ProjectedRouteRealization.__new__(model.ProjectedRouteRealization)
    expected_rows = (expected_row,)
    for name, item in {
        "source_authority": values["source_authority"], "attempt_id": values["attempt_id"],
        "plan_id": values["plan"].plan_id, "rows": expected_rows,
        "site_phase_result": expected_phase,
        "projected_inventory_digest": projected.inventory_digest,
        "projected_fingerprint": projected.graph_fingerprint,
        "projected_generation": projected.generation,
        "realization_id": "sha256:" + "0" * 64,
    }.items(): object.__setattr__(expected_realization, name, item)
    object.__setattr__(expected_realization, "realization_id", projected_route_realization_id((
        values["source_authority"].source_authority_id, values["attempt_id"],
        values["plan"].plan_id, expected_rows, projected.inventory_digest,
        projected.graph_fingerprint, projected.generation, expected_phase,
    )))
    assert realization.site_phase_result == expected_phase
    assert realization.rows == expected_rows
    assert realization == expected_realization
    assert realization.site_phase_result.raw_effect_gate_fact == raw
    assert realization.site_phase_result.effect_results[0] == expected_effect
    assert realization.site_phase_result.terminal_results[0] == expected_terminal
    assert realization.rows[0].relation == expected_relation
    bind.validate_projected_route_realization(realization)


def test_slice_c0_real_invalid_shadow_has_exact_public_coordinates() -> None:
    """Specification substitute: a real semantic-invalid DTO has exact coordinates."""
    from dataclasses import replace

    values = _c_complete_kwargs(_compiler_redirect_goto_case)
