def test_slice_c0_private_drafts_have_no_public_surface_or_id_schema() -> None:
    """C0 drafts remain absent from facade exports, codecs, and ID registries."""
    from d810.transforms import unflatten_authority
    from d810.transforms.unflatten_authority import ids, legacy_codec

    private_names = {
        "_ExactEffectBindingDraft", "_LocalAliasBindingDraft",
        "_ProjectedEffectDispositionDraft", "_ProjectedTerminalDispositionDraft",
        "_RouteSiteSubsetDraft", "_ProjectedSiteClosureDraft",
        "_ProjectedSiteDraftViolation", "_draft_exact_effect_binding",
        "_draft_local_alias_binding", "_draft_projected_site_closure",
        "_validate_projected_site_closure_draft",
        "_translate_projected_site_draft_violation",
    }
    assert private_names.isdisjoint(set(bind.__all__))
    assert private_names.isdisjoint(set(unflatten_authority.__all__))
    codec_text = legacy_codec.__file__ and open(legacy_codec.__file__).read()
    ids_text = ids.__file__ and open(ids.__file__).read()
    assert all(name not in codec_text for name in private_names)
    assert all(name not in ids_text for name in private_names)
    assert all("draft" not in parameter.name.lower() for parameter in __import__("inspect").signature(bind.realize_projected_routes).parameters.values())


