def _slice_c_route_kwargs(factory):
    authority, plan, source, projected, patch_facts, attempt, *_ = factory()
    from d810.transforms.unflatten_authority.gates import GenericEffectfulGateFacts

    owners = frozenset(
        row.owner_serial for row in source.effects
        if row.owner_serial in source.reachable_serials
    )
    raw_fact = bind.bind_raw_effect_gate_phase_fact(
        source_inventory=source,
        projected_inventory=projected,
        raw_gate_facts=GenericEffectfulGateFacts(
            True, owners, owners, frozenset(), "slice-c-matrix",
        ),
    )
    return dict(
        source_authority=authority,
        plan=plan,
        source_inventory=source,
        projected_inventory=projected,
        claims=plan.unflatten_proposal.claims,
        patch_step_facts=patch_facts,
        raw_effect_gate_fact=raw_fact,
        attempt_id=attempt,
    )


