def test_slice_c_nested_records_reject_copy_pickle_and_foreign_validation() -> None:
    """13.1/13.6: every accepted nested record is registry-exact and nonportable."""
    import copy
    import pickle

    fixture = projected_site_fixture()
    result = realize_projected_routes_for_test(
        source_authority=fixture.source_authority,
        plan=fixture.plan,
        source_inventory=fixture.source_inventory,
        projected_inventory=fixture.projected_inventory,
        claims=fixture.claims,
        patch_step_facts=fixture.patch_step_facts,
        raw_effect_gate_fact=fixture.raw_fact,
        attempt_id=fixture.attempt_id,
    )
    assert type(result) is model.ProjectedRouteRealizationAccepted
    nested = result.realization.site_phase_result
    for operation in (copy.copy, copy.deepcopy, pickle.dumps):
        with pytest.raises(TypeError, match="binder-owned"):
            operation(nested)
    with pytest.raises(TypeError, match="unknown closed type"):
        bind.validate_projected_site_phase_result(object())


