def _private_projected_kernel_cells():
    cells = {
        getattr(cell.cell_contents, "__name__", None): cell
        for cell in bind._realize_projected_routes_from_claim_inventory.__closure__ or ()
    }
    draft = cells["_draft_projected_route_relations"].cell_contents
    build = next(
        cell.cell_contents
        for cell in draft.__closure__ or ()
        if getattr(cell.cell_contents, "__name__", None)
        == "_build_projected_owner_mapping_index"
    )
    return cells, draft, build


def _draft_probe(fixture_factory):
    authority, plan, source, projected, facts, attempt, *_ = fixture_factory()
    cells, draft, build = _private_projected_kernel_cells()
    kwargs = dict(
        source_authority=authority,
        plan=plan,
        source_inventory=source,
        projected_inventory=projected,
        patch_step_facts=facts,
        attempt_id=attempt,
        _mint=cells["_route_mint"].cell_contents,
        _failure=cells["_route_failure"].cell_contents,
        _result=cells["_route_result"].cell_contents,
        _validate=cells["validate_route"].cell_contents,
    )
    structural, drafts, index, route_publications = draft(**kwargs)
    assert type(structural) is type(None)
    assert len(drafts) == 1
    assert tuple(value for value, _identity in route_publications)[-1:] == (
        drafts[0].relation,
    )
    kwargs["selected_context"] = ((drafts[0].lineage_entry, drafts[0].facts),)
    return drafts[0], index, build, kwargs


def _register_private_draft(draft):
    """Register an intentionally altered draft for downstream-hook tests."""
    _cells, draft_kernel, _build = _private_projected_kernel_cells()
    return next(
        cell.cell_contents
        for cell in draft_kernel.__closure__ or ()
        if getattr(cell.cell_contents, "__name__", None) == "register_draft"
    )(draft)


def _interposed_family_relation_mint(original, target_type):
    tags = {
        model.DirectRouteRealization: "direct",
        model.LoweredConditionalRouteRealization: "lowered_conditional",
        model.ClonedConditionalRouteRealization: "cloned_conditional",
        model.TwoArmDirectBranchRouteRealization: "two_arm_direct_branch",
        model.BranchFallthroughHelperRouteRealization: "branch_fallthrough_helper",
        model.ClonedRouteCorridorRealization: "cloned_route_corridor",
    }

    def interposed(cls, values, identity_name):
        if cls is target_type:
            values = dict(values)
            if cls is model.DirectRouteRealization:
                values["old_target"] = values["feeder"]
            elif cls in {
                model.LoweredConditionalRouteRealization,
                model.ClonedConditionalRouteRealization,
            }:
                values["feeder"] = values["arms"][0].target
            elif cls is model.TwoArmDirectBranchRouteRealization:
                values["source_rewritten_arm"] = values["feeder"]
            elif cls is model.BranchFallthroughHelperRouteRealization:
                values["source_fallthrough"] = values["feeder"]
                values["untouched_conditional_arm"] = values["feeder"]
            elif cls is model.ClonedRouteCorridorRealization:
                values["terminal_continuation"] = values["predecessor"]
            fields = tuple(
                values[name]
                for name in cls.__dataclass_fields__
                if name != "relation_id"
            )
            values["relation_id"] = route_realization_id((tags[cls], *fields))
        return original(cls, values, identity_name)

    return interposed


