def test_projected_owner_mapping_has_exact_family_owner_pairs(
    fixture_name: str, relation_type: type[object],
) -> None:
    """RED: branch mappings must name only the corrected semantic domain."""
    draft, index, _build, _kwargs = _draft_probe(globals()[fixture_name])
    relation = draft.relation
    assert type(relation) is relation_type
    pairs = {
        (row.source_owner, row.projected_owner, row.lineage)
        for row in index.owner_rows
    }
    same = model.ProjectedSiteLineageKind.SAME_OWNER
    clone = model.ProjectedSiteLineageKind.RELATION_CLONE
    if type(relation) is model.TwoArmDirectBranchRouteRealization:
        assert (relation.feeder, relation.feeder, same) in pairs
        assert (relation.untouched_arm, relation.untouched_arm, same) in pairs
        assert (relation.projected_replacement_arm, relation.projected_replacement_arm, same) in pairs
        assert all(row.source_owner != relation.source_rewritten_arm for row in index.owner_rows)
    elif type(relation) is model.BranchFallthroughHelperRouteRealization:
        assert (relation.feeder, relation.feeder, same) in pairs
        assert (relation.untouched_conditional_arm, relation.untouched_conditional_arm, same) in pairs
        assert (relation.semantic_target, relation.semantic_target, same) in pairs
        assert relation.source_fallthrough == relation.untouched_conditional_arm
        assert sum(
            row.source_owner == relation.untouched_conditional_arm
            for row in index.owner_rows
        ) == 1
        assert relation.helper in index.inverse_only_projected_owners
    elif type(relation) is model.DirectRouteRealization:
        assert {
            (relation.feeder, relation.feeder, same),
            (relation.new_target, relation.new_target, same),
        } <= pairs
        assert not index.inverse_only_projected_owners
    elif type(relation) is model.LoweredConditionalRouteRealization:
        assert {
            (relation.feeder, relation.feeder, same),
            (relation.proof_source, relation.proof_source, same),
            *( (arm.target, arm.target, same) for arm in relation.arms ),
        } <= pairs
        assert not index.inverse_only_projected_owners
    elif type(relation) is model.ClonedConditionalRouteRealization:
        assert (relation.feeder, relation.feeder, same) in pairs
        assert (relation.proof_source, relation.replacement_clone, clone) in pairs
        assert {
            (arm.target, arm.target, same) for arm in relation.arms
        } <= pairs
        assert index.inverse_only_projected_owners == (relation.fallthrough_helper,)
    else:
        assert all(row.lineage is clone for row in index.owner_rows if row.lineage is clone)
        assert not index.inverse_only_projected_owners
        if type(relation) is model.ClonedRouteCorridorRealization:
            ordered = tuple(
                (row.source_owner, row.projected_owner, row.relation_id)
                for row in index.owner_rows
                if row.lineage is clone
            )
            assert ordered == tuple(
                (source_owner, projected_owner, relation.relation_id)
                for source_owner, projected_owner in zip(
                    relation.source_corridor, relation.cloned_corridor,
                )
            )


