def test_projected_owner_index_rejects_registered_same_family_role_mutation(
    fixture_name: str, role: str,
) -> None:
    """Every named relation role remains bound to its selected family output."""
    draft, _index, build, kwargs = _draft_probe(globals()[fixture_name])
    relation = draft.relation
    cells, draft_kernel, _ = _private_projected_kernel_cells()
    register_draft = next(
        cell.cell_contents
        for cell in draft_kernel.__closure__ or ()
        if getattr(cell.cell_contents, "__name__", None) == "register_draft"
    )
    mint = cells["_route_mint"].cell_contents
    values = {name: getattr(relation, name) for name in relation.__dataclass_fields__}
    if role == "old_target":
        replacement = relation.feeder
    elif role == "feeder":
        replacement = relation.arms[0].target
    elif role == "source_rewritten_arm":
        replacement = relation.feeder
    elif role == "source_fallthrough":
        replacement = relation.feeder
    else:
        replacement = relation.predecessor
    values[role] = replacement
    tag = {
        model.DirectRouteRealization: "direct",
        model.LoweredConditionalRouteRealization: "lowered_conditional",
        model.ClonedConditionalRouteRealization: "cloned_conditional",
        model.TwoArmDirectBranchRouteRealization: "two_arm_direct_branch",
        model.BranchFallthroughHelperRouteRealization: "branch_fallthrough_helper",
        model.ClonedRouteCorridorRealization: "cloned_route_corridor",
    }[type(relation)]
    fields = tuple(values[name] for name in relation.__dataclass_fields__ if name != "relation_id")
    values["relation_id"] = route_realization_id((tag, *fields))
    malformed_relation = mint(type(relation), values, "relation_id")
    malformed = register_draft(replace(draft, relation=malformed_relation))
    with pytest.raises(ValueError, match="role|relation|feeder|target|corridor"):
        build(
            drafts=(malformed,),
            source_authority=kwargs["source_authority"],
            plan=kwargs["plan"],
            patch_step_facts=kwargs["patch_step_facts"],
            selected_context=kwargs["selected_context"],
        )


