@pytest.mark.parametrize("injected_type", (TypeError, ValueError))
def test_projected_owner_index_public_boundary_preserves_exact_typed_injection(
    injected_type: type[Exception],
) -> None:
    """Round-2 RED: expected private-hook failures become typed rejection."""
    authority, plan, source, projected, facts, attempt, *_ = _compiler_direct_branch_case()
    cells, draft, _build = _private_projected_kernel_cells()
    build_cell = next(
        cell for cell in draft.__closure__ or ()
        if getattr(cell.cell_contents, "__name__", None)
        == "_build_projected_owner_mapping_index"
    )
    original = build_cell.cell_contents

    def injected(*, drafts, source_authority, plan, patch_step_facts, selected_context):
        del drafts, source_authority, plan, patch_step_facts, selected_context
        raise injected_type("injected owner mapping failure")

    build_cell.cell_contents = injected
    try:
        result = realize_projected_routes_for_test(
            source_authority=authority, plan=plan,
            source_inventory=source, projected_inventory=projected,
            patch_step_facts=facts, attempt_id=attempt,
        )
    finally:
        build_cell.cell_contents = original
    assert type(result) is model.ProjectedRouteRealizationRejected
    failure = result.failures[0]
    assert failure.stage is model.RouteRealizationFailureStage.CLAIM_SELECTION
    assert failure.scope is model.RouteRealizationFailureScope.STEP
    assert failure.claim_id == authority.proposal.claims[0].claim_id
    assert failure.proof_id == authority.proposal.claims[0].route_proof_ids[0]
    assert failure.route_subject_id == authority.proposal.claims[0].retired_route_subject.subject_id
    assert failure.step_index is not None
    assert failure.step_digest is not None


