def test_source_inventory_pair_cleanup_is_identity_safe() -> None:
    """Weak SOURCE-pair cleanup cannot remove a replacement registry row."""
    import gc
    import weakref

    authority, _plan, source, _projected, _facts, _attempt, *_ = _compiler_direct_branch_case()
    replacement_authority, _replacement_plan, replacement_source, *_ = _compiler_redirect_goto_case()
    registry_cell = next(
        cell for cell in bind._realize_projected_routes_from_claim_inventory.__closure__ or ()
        if isinstance(cell.cell_contents, dict)
        and any(
            row[1] is source
            for row in cell.cell_contents.values()
            if isinstance(row, tuple) and len(row) == 2
        )
    )
    registry = registry_cell.cell_contents
    key = id(authority)
    old_reference = registry[key][0]
    assert old_reference() is authority
    def replacement_cleanup(reference):
        row = registry.get(key)
        if row is not None and row[0] is reference:
            registry.pop(key, None)

    replacement_reference = weakref.ref(replacement_authority, replacement_cleanup)
    registry[key] = (replacement_reference, replacement_source)
    del authority
    gc.collect()
    assert key in registry
    assert registry[key][0]() is replacement_authority
    del replacement_authority
    gc.collect()
    assert key not in registry


def test_projected_path_forbidden_calls_are_zero_and_descriptor_compiles_once() -> None:
    """Projected drafting reuses accepted source evidence without replaying producers."""
    authority, plan, source, projected, facts, attempt = _two_proof_shared_target_case()
    calls = {
        "source_binder": 0,
        "inventory_builder": 0,
        "reachability": 0,
        "assessor": 0,
        "classifier": 0,
        "descriptor_compiler": 0,
        "lineage_index": 0,
        "lineage_select": 0,
        "lineage_validate": 0,
    }
    source_cells = {
        getattr(cell.cell_contents, "__name__", None): cell
        for cell in bind.bind_source_route_authority.__closure__ or ()
    }
    source_binder_cell = source_cells["_bind_source_route_authority"]
    original_source_binder = source_binder_cell.cell_contents

    def forbidden_source_binder(*args, **kwargs):
        calls["source_binder"] += 1
        raise AssertionError("projected path replayed source binder")

    source_binder_cell.cell_contents = forbidden_source_binder
    original_descriptor_compiler = bind.canonical_patch_step_descriptors

    def count_descriptor_compiler(*args, **kwargs):
        calls["descriptor_compiler"] += 1
        return original_descriptor_compiler(*args, **kwargs)

    bind.canonical_patch_step_descriptors = count_descriptor_compiler
    patched = (
        (transaction_api, "_build_semantic_graph_inventory", "inventory_builder"),
        (producer_api, "discover_reachable_effects_and_terminals", "reachability"),
        (route_model, "assess_canonical_route", "assessor"),
        (evaluate, "_classify_effect_site", "classifier"),
        (bind, "_index_lineage_fact_groups", "lineage_index"),
        (bind, "_select_lineage_fact_group", "lineage_select"),
        (bind, "_require_valid_lineage_fact_group", "lineage_validate"),
    )
    originals = []
    try:
        for owner, name, key in patched:
            original = getattr(owner, name)
            originals.append((owner, name, original))
            if key.startswith("lineage_"):
                def count_lineage(*args, _key=key, _original=original, **kwargs):
                    calls[_key] += 1
                    return _original(*args, **kwargs)
                replacement = count_lineage
            else:
                replacement = lambda *args, _key=key, **kwargs: calls.__setitem__(_key, calls[_key] + 1)
            setattr(owner, name, replacement)
        result = realize_projected_routes_for_test(
            source_authority=authority, plan=plan,
            source_inventory=source, projected_inventory=projected,
            patch_step_facts=facts, attempt_id=attempt,
        )
    finally:
        for owner, name, original in originals:
            setattr(owner, name, original)
        bind.canonical_patch_step_descriptors = original_descriptor_compiler
        source_binder_cell.cell_contents = original_source_binder
    assert type(result) is model.ProjectedRouteRealizationAccepted
    assert not hasattr(bind, "validate_exact_state_branch_effect_exclusion")
    assert calls == {
        "source_binder": 0,
        "inventory_builder": 0,
        "reachability": 0,
        "assessor": 0,
        "classifier": 0,
        "descriptor_compiler": 1,
        "lineage_index": 1,
        "lineage_select": 2,
        "lineage_validate": 2,
    }


