def _3b4a_inventory_pair(
    *, two_effects: bool = False, unreachable_effect: bool = False,
    synthesized_stop: bool = False, unreachable_terminal: bool = False,
    foreign_projected_source_subjects: bool = False,
):
    source, proposal, _exclusion, refs = exact_fixture()
    if two_effects or unreachable_effect or synthesized_stop:
        from dataclasses import replace
        from d810.ir.flowgraph import FlowGraph, InsnKind
        serial = 2 if two_effects else 4
        block = source.blocks[serial]
        if two_effects:
            instruction = replace(block.insn_snapshots[0], kind=InsnKind.CALL, is_call=True)
            block = replace(
                block, insn_snapshots=(instruction,), tail_kind=InsnKind.CALL,
                tail_opcode=instruction.opcode, raw_tail_opcode=instruction.raw_opcode,
            )
        elif unreachable_effect:
            instruction = replace(block.insn_snapshots[0], kind=InsnKind.CALL, is_call=True)
            block = replace(
                block, insn_snapshots=(instruction,), tail_kind=InsnKind.CALL,
                tail_opcode=instruction.opcode, raw_tail_opcode=instruction.raw_opcode,
            )
        elif synthesized_stop:
            block = replace(block, kind=BlockKind.STOP)
            if not unreachable_terminal:
                predecessor = source.blocks[1]
                source = FlowGraph(
                    {
                        **source.blocks,
                        1: replace(predecessor, succs=tuple((*predecessor.succs, 4))),
                        4: replace(block, preds=(1,)),
                    },
                    source.entry_serial,
                    source.func_ea,
                )
                block = source.blocks[4]
        source = FlowGraph(
            {
                **source.blocks,
                serial: block,
            },
            source.entry_serial,
            source.func_ea,
        )
    from d810.transforms.plan import PatchPlan
    plan = PatchPlan(
        plan_id=proposal.plan_id,
        snapshot_id=authority_id("3b4a-inventory"),
        source_generation=1,
        steps=(),
        source_coordinates=tuple((ref, serial) for serial, ref in refs.items()),
        unflatten_proposal=proposal,
    )
    source_inventory = transaction_api._build_semantic_graph_inventory(
        source, proposal, plan, source=True,
        phase=model.UnflattenAuthorityPhase.PRODUCER_FORECAST,
    )
    projected_inventory = transaction_api._build_semantic_graph_inventory(
        source, proposal, plan, source=False,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        source_subjects=(() if foreign_projected_source_subjects else source_inventory.subjects),
    )
    if two_effects:
        effect_owners = {row.owner_serial for row in source_inventory.effects}
        assert len(source_inventory.effects) >= 2
        assert len(effect_owners) >= 2
        assert effect_owners <= set(source_inventory.reachable_serials)
    return plan, source_inventory, projected_inventory


def test_raw_effect_gate_accepts_full_two_owner_and_rejects_partial_partitions() -> None:
    from d810.transforms.unflatten_authority.gates import GenericEffectfulGateFacts

    _plan, source_inventory, projected_inventory = _3b4a_inventory_pair(two_effects=True)
    owners = tuple(sorted(row.owner_serial for row in source_inventory.effects))
    assert len(owners) >= 2
    full = frozenset(owners)
    fact = bind.bind_raw_effect_gate_phase_fact(
        source_inventory=source_inventory,
        projected_inventory=projected_inventory,
        raw_gate_facts=GenericEffectfulGateFacts(
            False, full, frozenset({owners[0]}), frozenset(set(owners[1:])), "two-owner-full",
        ),
    )
    assert len(fact.pre_effectful_source_owners) == len(owners)
    for pre in (frozenset(), frozenset({owners[0]})):
        with pytest.raises(ValueError, match="effect-owner"):
            bind.bind_raw_effect_gate_phase_fact(
                source_inventory=source_inventory,
                projected_inventory=projected_inventory,
                raw_gate_facts=GenericEffectfulGateFacts(
                    True, pre, pre, frozenset(), "two-owner-partial",
                ),
            )


