def test_inventory_owned_synthesized_stop_coordinate_is_real_and_serial_free() -> None:
    from copy import copy, deepcopy
    import pickle
    from dataclasses import replace
    from d810.transforms.unflatten_authority.ids import canonical_decode

    _plan, source_inventory, _projected_inventory = _3b4a_inventory_pair(
        synthesized_stop=True,
    )
    row = next(row for row in source_inventory.terminals if row.terminal_kind is model.TerminalKind.STOP)
    assert row.owner_serial in source_inventory.reachable_serials
    assert row.instruction_ordinal is None
    coordinate = bind._bind_terminal_site_coordinate(source_inventory, row)
    assert coordinate.terminal_kind is model.TerminalKind.STOP
    for operation in (copy, deepcopy, pickle.dumps):
        with pytest.raises(TypeError):
            operation(coordinate)
    with pytest.raises(ValueError):
        canonical_decode(bind.canonical_bytes(coordinate))
    with pytest.raises((TypeError, ValueError)):
        replace(coordinate)


