def test_raw_effect_gate_fact_is_serial_free_closed_and_partitions_source_owners() -> None:
    from copy import copy, deepcopy
    import pickle
    from d810.transforms.unflatten_authority.gates import GenericEffectfulGateFacts
    from d810.transforms.unflatten_authority.ids import canonical_bytes, canonical_decode

    _plan, source_inventory, projected_inventory = _3b4a_inventory_pair(two_effects=True)
    serials = frozenset(row.owner_serial for row in source_inventory.effects)
    raw = GenericEffectfulGateFacts(True, serials, serials, frozenset(), "raw-ok")
    fact = bind.bind_raw_effect_gate_phase_fact(
        source_inventory=source_inventory,
        projected_inventory=projected_inventory,
        raw_gate_facts=raw,
    )
    assert fact.pre_effectful_source_owners == fact.raw_retained_source_owners
    assert fact.raw_lost_source_owners == ()
    assert fact.fact_id.startswith("sha256:")
    assert not any("serial" in field.name for field in model.RawEffectGatePhaseFact.__dataclass_fields__.values())
    encoded = canonical_bytes(fact)
    with pytest.raises(ValueError):
        canonical_decode(encoded)
    for operation in (copy, deepcopy, pickle.dumps):
        with pytest.raises(TypeError):
            operation(fact)


