def test_3b4a_coordinates_are_minted_from_exact_inventory_rows() -> None:
    _plan, source_inventory, _projected_inventory = _3b4a_inventory_pair()
    effect = source_inventory.effects[0]
    coordinate = bind._bind_effect_site_coordinate(source_inventory, effect)
    assert coordinate.owner.ref == effect.owner_ref
    assert coordinate.owner.anchor_ea == effect.owner_anchor_ea
    assert coordinate.instruction_ordinal == effect.instruction_ordinal
    from d810.transforms.unflatten_authority.ids import effect_site_coordinate_id
    assert effect_site_coordinate_id(coordinate) == effect_site_coordinate_id(
        bind._bind_effect_site_coordinate(source_inventory, source_inventory.effects[-1])
    )
    object.__setattr__(coordinate, "instruction_ea", coordinate.instruction_ea + 1)
    with pytest.raises(ValueError, match="content seal"):
        bind._validate_registered_site(coordinate)
    terminals = tuple(row for row in source_inventory.terminals if row.instruction_ordinal is not None)
    if terminals:
        terminal = bind._bind_terminal_site_coordinate(source_inventory, terminals[0])
        assert terminal.owner.ref == terminals[0].owner_ref
        assert terminal.instruction_ea == terminals[0].instruction_ea


