@pytest.mark.parametrize("reverse_facts", (False, True), ids=("canonical", "reversed"))
def test_3b3_state_choice_structural_tier_priority_is_closed(reverse_facts: bool) -> None:
    """Structural tiering is closed before proof/topology validation begins."""
    for builder in (_conditional_redirect_case_for_inventory_mutation, _lower_conditional_case):
        authority, plan, source, projected, _facts, attempt, *_ = builder()
        from d810.transforms.plan import PatchRedirectGoto
        step = plan.steps[0]
        source_ref = step.source_serial
        if type(step).__name__ == "PatchConditionalRedirect":
            old_ref, new_ref = step.conditional_target, step.fallthrough_target
        else:
            old_ref, new_ref = step.old_dispatcher_serial, step.true_target_serial
        mixed_plan = replace(plan, steps=(*plan.steps, PatchRedirectGoto(
            from_serial=source_ref, old_target=old_ref, new_target=new_ref,
        )))
        mixed_facts = transaction_api._derive_patch_lineage_facts(source, mixed_plan)
        result = realize_projected_routes_for_test(
            source_authority=authority, plan=mixed_plan, source_inventory=source,
            projected_inventory=projected,
            patch_step_facts=tuple(reversed(mixed_facts)) if reverse_facts else mixed_facts,
            attempt_id=attempt,
        )
        assert type(result) is model.ProjectedRouteRealizationAccepted
        expected_kind = (
            PatchStepKind.CONDITIONAL_REDIRECT
            if type(step).__name__ == "PatchConditionalRedirect"
            else PatchStepKind.LOWER_CONDITIONAL
        )
        assert result.realization.rows[0].plan_step_type is expected_kind

    # The conditional STATE_CHOICE authority exercises the exact 3B3-vs-GOTO
    # priority rule; the direct compiler-backed families are covered by the
    # accepted matrix below and remain direct-tier candidates by contract.
    authority, plan, source, projected, facts, attempt, claim, proof, _ = (
        _real_projected_branch_fixture()
    )
    step = plan.steps[0]
    mixed_plan = replace(plan, steps=(*plan.steps, PatchRedirectGoto(
        from_serial=step.from_serial, old_target=step.old_target, new_target=step.new_target,
    )))
    mixed_facts = transaction_api._derive_patch_lineage_facts(source, mixed_plan)
    result = realize_projected_routes_for_test(
        source_authority=authority, plan=mixed_plan, source_inventory=source,
        projected_inventory=projected,
        patch_step_facts=tuple(reversed(mixed_facts)) if reverse_facts else mixed_facts,
        attempt_id=attempt,
    )
    assert type(result) is model.ProjectedRouteRealizationRejected
    failure = result.failures[0]
    assert failure.stage is model.RouteRealizationFailureStage.UNSUPPORTED_REALIZATION_KIND
    assert failure.step_index == 0 and failure.step_digest == facts[0].step_digest
    assert failure.claim_id == claim.claim_id and failure.proof_id == proof.proof_id

    authority, plan, source, projected, _facts, attempt, *_ = _three_b3_direct_branch_case()
    ambiguous = replace(plan, steps=(*plan.steps, plan.steps[0]))
    ambiguous_facts = transaction_api._derive_patch_lineage_facts(source, ambiguous)
    result = realize_projected_routes_for_test(
        source_authority=authority, plan=ambiguous, source_inventory=source,
        projected_inventory=projected,
        patch_step_facts=tuple(reversed(ambiguous_facts)) if reverse_facts else ambiguous_facts,
        attempt_id=attempt,
    )
    assert type(result) is model.ProjectedRouteRealizationRejected
    failure = result.failures[0]
    assert failure.stage is model.RouteRealizationFailureStage.CLAIM_SELECTION
    assert failure.scope is model.RouteRealizationFailureScope.CLAIM
    assert failure.step_index is None and failure.step_digest is None
    locator = authority.proposal.claims[0].retired_route_subject.locator
    expected = {
        model.AnchoredBlockRef(locator.source_ref, locator.source_anchor_ea),
        *(model.AnchoredBlockRef(ref, ea)
          for ref, ea in zip(locator.destination_refs, locator.destination_anchor_eas)),
    }
    assert set(failure.anchored_refs) == expected


