def test_3b3_x_branch_partition_rejects_at_source_without_projected_rebind() -> None:
    """A real partition proof cannot be replayed against a two-arm F branch."""
    # The producer fixture is a genuine partition corridor.  Replaying that
    # immutable evidence against the exact F-two-way branch is the honest X
    # case: the source kernel must reject it before the projected kernel is
    # even eligible to run.
    corridor_authority, _corridor_plan, _corridor_source, _corridor_projected, _facts, _attempt, _ = (
        _compiler_split_case(corridor_length=1, corridor=True, partition=True)
    )
    source, _base, _exclusion, refs = exact_fixture()
    proposal = corridor_authority.proposal
    from d810.transforms.plan import PatchPlan, PatchRedirectBranch
    plan = PatchPlan(
        plan_id=proposal.plan_id,
        snapshot_id=authority_id("3b3-x-branch-partition-snapshot"),
        source_generation=1,
        steps=(PatchRedirectBranch(refs[1], refs[2], refs[4]),),
        source_coordinates=tuple((ref, serial) for serial, ref in refs.items()),
        unflatten_proposal=proposal,
    )
    materialization = route_model.CanonicalRouteMaterialization.capture(
        source, generation=1, phase=route_model.CanonicalRouteAssessmentPhase.SOURCE,
    )
    source_inventory = transaction_api._build_semantic_graph_inventory(
        source, proposal, plan, source=True,
        phase=model.UnflattenAuthorityPhase.PRODUCER_FORECAST,
        materialization=materialization,
    )
    with patch.object(bind, "realize_projected_routes", side_effect=AssertionError("projected X row")):
        result = bind.bind_source_route_authority(
            proposal=proposal,
            source_inventory=source_inventory,
            source_materialization=materialization,
        )
    assert type(result) is model.SourceBoundRouteAuthorityRejected
    assert result.failures
    assert result.failures[0].stage is model.RouteRealizationFailureStage.SOURCE_AUTHORITY


