def test_3b3_candidate_count_stages_are_distinct() -> None:
    from d810.transforms.plan import PatchRedirectBranch

    authority, plan, source, projected, _facts, attempt = _conditional_redirect_case_for_inventory_mutation()
    refs = source.serial_by_ref
    claim = authority.proposal.claims[0]
    locator = claim.retired_route_subject.locator
    claim_anchors = {
        model.AnchoredBlockRef(locator.source_ref, locator.source_anchor_ea),
        *(model.AnchoredBlockRef(ref, ea)
          for ref, ea in zip(locator.destination_refs, locator.destination_anchor_eas)),
    }
    # A real descriptor exists, but its source is unrelated to the claim, so
    # the structural candidate set is empty (not a malformed fact group).
    unrelated = locator.destination_refs[1]
    zero_plan = replace(plan, new_blocks=(), steps=(PatchRedirectBranch(
        from_serial=unrelated, old_target=locator.source_ref,
        new_target=locator.destination_refs[0],
    ),))
    zero_facts = transaction_api._derive_patch_lineage_facts(source, zero_plan)
    zero = realize_projected_routes_for_test(
        source_authority=authority, plan=zero_plan, source_inventory=source,
        projected_inventory=projected, patch_step_facts=zero_facts, attempt_id=attempt,
    )
    assert type(zero) is model.ProjectedRouteRealizationRejected
    zero_failure = zero.failures[0]
    assert zero_failure.stage is model.RouteRealizationFailureStage.CLAIM_COVERAGE
    assert zero_failure.scope is model.RouteRealizationFailureScope.CLAIM
    assert zero_failure.step_index is None and zero_failure.step_digest is None
    assert set(zero_failure.anchored_refs) == claim_anchors

    # Two exact descriptors are both structural candidates.  Selection fails
    # before any step group is chosen, and only claim coordinates survive.
    ambiguous = replace(plan, steps=(*plan.steps, plan.steps[0]))
    from d810.transforms.unflatten_authority.proposal import canonical_patch_step_descriptors
    duplicate_descriptor = canonical_patch_step_descriptors(ambiguous)[1]
    ambiguous_facts = (
        *_facts,
        *(replace(fact, step_index=1, step_digest=duplicate_descriptor.step_digest)
          for fact in _facts),
    )
    duplicate = realize_projected_routes_for_test(
        source_authority=authority, plan=ambiguous, source_inventory=source,
        projected_inventory=projected, patch_step_facts=ambiguous_facts,
        attempt_id=attempt,
    )
    assert type(duplicate) is model.ProjectedRouteRealizationRejected
    duplicate_failure = duplicate.failures[0]
    assert duplicate_failure.stage is model.RouteRealizationFailureStage.CLAIM_SELECTION
    assert duplicate_failure.scope is model.RouteRealizationFailureScope.CLAIM
    assert duplicate_failure.step_index is None and duplicate_failure.step_digest is None
    assert set(duplicate_failure.anchored_refs) == claim_anchors


@pytest.mark.parametrize(
    ("fixture", "owner_index", "field"),
    (
        ("_three_b3_helper_branch_case", 1, "owner_ref"),
        ("_three_b3_helper_branch_case", 1, "creation_spec_digest"),
        ("_three_b3_helper_branch_case", 1, "owner_ref"),
        ("_three_b3_helper_branch_case", 1, "creation_spec_digest"),
        ("_three_b3_two_block_corridor_case", 1, "owner_ref"),
        ("_three_b3_two_block_corridor_case", 1, "creation_spec_digest"),
        ("_three_b3_two_block_corridor_case", 1, "owner_ref"),
        ("_three_b3_two_block_corridor_case", 1, "creation_spec_digest"),
    ),
    ids=(
        "helper-step-owner", "helper-spec-owner", "helper-fact-owner", "helper-digest",
        "corridor-step-owner", "corridor-spec-owner", "corridor-fact-owner", "corridor-digest",
    ),
)
@pytest.mark.parametrize("reverse_facts", (False, True), ids=("canonical", "reversed"))
def test_3b3_owner_layer_drift_has_deterministic_stage(
    fixture: str, owner_index: int, field: str, reverse_facts: bool,
) -> None:
    """Each creation-owner layer rejects identically and retains full anchors."""
    authority, plan, source, projected, facts, attempt, *_ = globals()[fixture]()
    fact = facts[owner_index]
    mutated = replace(
        fact,
        **{
            field: (
                block_ref("foreign-owner-layer")
                if field == "owner_ref"
                else authority_id("foreign-creation-layer")
            ),
        },
    )
    malformed = tuple(mutated if index == owner_index else item for index, item in enumerate(facts))
    result = realize_projected_routes_for_test(
        source_authority=authority, plan=plan, source_inventory=source,
        projected_inventory=projected,
        patch_step_facts=tuple(reversed(malformed)) if reverse_facts else malformed,
        attempt_id=attempt,
    )
    assert type(result) is model.ProjectedRouteRealizationRejected
    failure = result.failures[0]
    if field == "owner_ref":
        # The transaction-owned inventory rejects a fact no longer belonging
        # to the selected plan before any route family reconstructs lineage.
        assert failure.stage is model.RouteRealizationFailureStage.ATTEMPT_BINDING
        assert failure.scope is model.RouteRealizationFailureScope.EVIDENCE
        assert failure.claim_id is None and failure.proof_id is None
        assert failure.step_index is None and failure.step_digest is None
    else:
        assert failure.stage is model.RouteRealizationFailureStage.HELPER_LINEAGE
        assert failure.scope is model.RouteRealizationFailureScope.STEP
        assert failure.claim_id == authority.proposal.claims[0].claim_id
        assert failure.proof_id == authority.proposal.route_evidence.route_proofs[0].proof_id
        assert failure.step_index == fact.step_index
        assert failure.step_digest == fact.step_digest
    assert len(failure.anchored_refs) == len(set(failure.anchored_refs))


