@pytest.mark.parametrize("nested", ("prefix", "origin"), ids=("prefix", "origin"))
def test_3b3_public_validator_rejects_unregistered_byte_identical_nested_route(
    nested: str,
) -> None:
    """A registered aggregate cannot hide an unregistered nested corridor value."""
    authority, plan, source, projected, facts, attempt, _ = _compiler_split_case(
        corridor_length=2, corridor=True, extra_prefix_origin=True,
    )
    accepted = realize_projected_routes_for_test(
        source_authority=authority, plan=plan, source_inventory=source,
        projected_inventory=projected, patch_step_facts=facts, attempt_id=attempt,
    )
    assert type(accepted) is model.ProjectedRouteRealizationAccepted
    aggregate = accepted.realization
    relation = aggregate.rows[0].relation
    assert type(relation) is model.ClonedRouteCorridorRealization

    def byte_identical_clone(value):
        clone = object.__new__(type(value))
        for name in value.__dataclass_fields__:
            object.__setattr__(clone, name, getattr(value, name))
        return clone

    prefix = relation.semantic_prefixes[0]
    original_origins = prefix.instruction_origins
    original_prefixes = relation.semantic_prefixes
    try:
        if nested == "prefix":
            foreign_prefix = byte_identical_clone(prefix)
            object.__setattr__(relation, "semantic_prefixes", (foreign_prefix, *original_prefixes[1:]))
        else:
            foreign_origin = byte_identical_clone(original_origins[0])
            object.__setattr__(prefix, "instruction_origins", (foreign_origin, *original_origins[1:]))
        with pytest.raises(ValueError, match="not minted by its kernel"):
            bind.validate_projected_route_realization(aggregate)
    finally:
        object.__setattr__(relation, "semantic_prefixes", original_prefixes)
        object.__setattr__(prefix, "instruction_origins", original_origins)


@pytest.mark.parametrize(
    "drift",
    (
        "q_order", "c_order", "terminal_r", "descriptor_old_target",
        "retained_projected_chain", "clone_predecessor", "clone_successor",
        "origin_ea",
        "observation_digest", "prefix_length", "prefix_order",
        "creation_row_order",
        "creation_row_digest",
    ),
)
def test_3b3_corridor_prefix_and_topology_drift_fails_closed(drift: str) -> None:
    """Each named corridor coordinate is mutated once and fails at its boundary."""
    builder = (
        _three_b3_two_block_corridor_case
        if drift in {"q_order", "c_order", "retained_projected_chain", "creation_row_order"}
        else _three_b3_one_block_corridor_case
    )
    if drift in {
        "prefix_length", "prefix_order", "origin_ea",
    }:
        builder = lambda: _compiler_split_case(
            corridor_length=1, corridor=True, extra_prefix_origin=True,
        )
    authority, plan, source, projected, facts, attempt, expected = builder()
    step = plan.steps[0]

    def projected_rows(rows):
        result = projected
        for serial, changed in rows:
            current = next(item for item in result.blocks if item.serial == serial)
            result = _replace_projected_block(result, current, observation_rows=changed)
        return result

    malformed_plan = plan
    malformed_source = source
    malformed_projected = projected
    malformed_facts = facts
    expected_stage = model.RouteRealizationFailureStage.OLD_EDGE_REMOVAL
    if drift == "q_order":
        malformed_plan = replace(plan, steps=(replace(step, corridor_serials=tuple(reversed(step.corridor_serials))),))
        malformed_facts = transaction_api._derive_patch_lineage_facts(source, malformed_plan)
        expected_stage = model.RouteRealizationFailureStage.PLAN_STEP_CORRELATION
    elif drift == "c_order":
        malformed_plan = replace(plan, steps=(replace(step, clone_block_ids=tuple(reversed(step.clone_block_ids))),))
        malformed_facts = transaction_api._derive_patch_lineage_facts(source, malformed_plan)
        expected_stage = model.RouteRealizationFailureStage.NEW_EDGE_REALIZATION
    elif drift == "descriptor_old_target":
        malformed_plan = replace(plan, steps=(replace(step, old_target=step.via_pred),))
        malformed_facts = transaction_api._derive_patch_lineage_facts(source, malformed_plan)
        expected_stage = model.RouteRealizationFailureStage.PLAN_STEP_CORRELATION
    elif drift == "terminal_r":
        serial = source.serial_by_ref[step.corridor_serials[-1]]
        row = next(item for item in projected.blocks if item.serial == serial)
        malformed_projected = projected_rows(((serial, replace(row, successor_serials=(3,))),))
    elif drift == "retained_projected_chain":
        q0, q1 = (source.serial_by_ref[ref] for ref in step.corridor_serials)
        terminal = next(item for item in projected.blocks if item.serial == q1 + 1)
        row0 = next(item for item in projected.blocks if item.serial == q0)
        row1 = next(item for item in projected.blocks if item.serial == q1)
        malformed_projected = projected_rows(((
            q0, replace(row0, successor_serials=(terminal.serial,))), (
            q1, replace(row1, predecessor_serials=())), (
            terminal.serial, replace(terminal, predecessor_serials=(q0, q1))),
        ))
    elif drift == "clone_predecessor":
        serial = projected.serial_by_ref[step.clone_block_ids[0]]
        row = next(item for item in projected.blocks if item.serial == serial)
        malformed_projected = projected_rows(((serial, replace(row, predecessor_serials=(row.predecessor_serials[0] + 1,))),))
        expected_stage = model.RouteRealizationFailureStage.NEW_EDGE_REALIZATION
    elif drift == "clone_successor":
        serial = projected.serial_by_ref[step.clone_block_ids[-1]]
        row = next(item for item in projected.blocks if item.serial == serial)
        malformed_projected = projected_rows(((serial, replace(row, successor_serials=(source.serial_by_ref[step.old_target],))),))
        expected_stage = model.RouteRealizationFailureStage.NEW_EDGE_REALIZATION
    elif drift == "prefix_length":
        serial = projected.serial_by_ref[step.clone_block_ids[0]]
        row = next(item for item in projected.blocks if item.serial == serial)
        observations = row.instruction_observations
        kept = replace(observations[-2], ordinal=0)
        tail = replace(observations[-1], ordinal=1)
        changed = replace(
            row,
            instruction_observations=(kept, tail),
            native_instruction_eas=tuple(
                item.instruction_ea for item in (kept, tail)
                if item.instruction_ea is not None
            ),
        )
        malformed_projected = projected_rows(((serial, changed),))
        expected_stage = model.RouteRealizationFailureStage.EFFECT_TERMINAL_PRESERVATION
    elif drift == "prefix_order":
        serial = projected.serial_by_ref[step.clone_block_ids[0]]
        row = next(item for item in projected.blocks if item.serial == serial)
        observations = list(row.instruction_observations)
        observations[0], observations[1] = (
            replace(observations[1], ordinal=0), replace(observations[0], ordinal=1),
        )
        malformed_projected = projected_rows(((serial, replace(row, instruction_observations=tuple(observations))),))
        expected_stage = model.RouteRealizationFailureStage.EFFECT_TERMINAL_PRESERVATION
    elif drift == "creation_row_order":
        malformed_plan = replace(plan, new_blocks=tuple(reversed(plan.new_blocks)))
        malformed_facts = transaction_api._derive_patch_lineage_facts(source, malformed_plan)
        expected_stage = model.RouteRealizationFailureStage.EFFECT_TERMINAL_PRESERVATION
    elif drift in {"origin_ea", "observation_digest"}:
        serial = projected.serial_by_ref[step.clone_block_ids[0]]
        row = next(item for item in projected.blocks if item.serial == serial)
        observations = list(row.instruction_observations)
        index = 0 if drift == "origin_ea" else (0 if len(observations) == 1 else len(observations) - 2)
        changed = observations[index]
        changed = replace(
            changed,
                    instruction_ea=changed.instruction_ea + 10
            if drift == "origin_ea" else changed.instruction_ea,
            raw_opcode=(changed.raw_opcode or 0) + 1
            if drift == "observation_digest" else changed.raw_opcode,
        )
        observations[index] = changed
        changed_row = replace(
            row,
            instruction_observations=tuple(observations),
            **(
                {
                    "native_instruction_eas": tuple(sorted(
                        item.instruction_ea for item in observations
                        if item.instruction_ea is not None
                    ))
                }
                if drift == "origin_ea" else {}
            ),
        )
        malformed_projected = projected_rows(((serial, changed_row),))
        expected_stage = model.RouteRealizationFailureStage.EFFECT_TERMINAL_PRESERVATION
    elif drift == "creation_row_digest":
        index = len(facts) - 1
        malformed_facts = tuple(
            replace(fact, creation_spec_digest=authority_id("corridor-creation-drift"))
            if position == index else fact
            for position, fact in enumerate(facts)
        )
        expected_stage = model.RouteRealizationFailureStage.HELPER_LINEAGE
    else:
        raise AssertionError(f"unhandled corridor drift {drift!r}")

    result = realize_projected_routes_for_test(
        source_authority=authority, plan=malformed_plan, source_inventory=malformed_source,
        projected_inventory=malformed_projected, patch_step_facts=malformed_facts,
        attempt_id=attempt,
    )
    assert type(result) is model.ProjectedRouteRealizationRejected
    assert result.failures[0].stage is expected_stage
    assert result.failures[0].scope is model.RouteRealizationFailureScope.STEP
    _assert_exact_canonical_step_anchors(
        result, authority, malformed_plan, source, malformed_projected,
        malformed_facts, family="corridor",
    )


def _assert_final_review_step_coordinates(result, authority, facts) -> None:
    assert type(result) is model.ProjectedRouteRealizationRejected
    failure = result.failures[0]
    claim = authority.proposal.claims[0]
    proof = authority.proposal.route_evidence.route_proofs[0]
    assert failure.scope is model.RouteRealizationFailureScope.STEP
    assert failure.claim_id == claim.claim_id
    assert failure.proof_id == proof.proof_id
    assert failure.route_subject_id == claim.retired_route_subject.subject_id
    assert failure.proposal_id == authority.proposal_id
    assert failure.evidence_id == authority.evidence_id
    assert failure.step_index == 0
    assert failure.step_digest == facts[0].step_digest
    assert failure.anchored_refs


def _assert_exact_canonical_step_anchors(result, authority, plan, source, projected, facts, *, family: str) -> None:
    """Assert the complete route-coordinate tuple selected by the binder."""
    _assert_final_review_step_coordinates(result, authority, facts)
    def anchored(ref):
        inventory = source if ref in source.serial_by_ref else projected
        return model.AnchoredBlockRef(ref, bind._inventory_block(inventory, ref).anchor_ea)

    # These are deliberately literal family role lists.  In particular, do
    # not derive them from descriptor.route_refs/owner_refs: this assertion is
    # meant to catch a descriptor-coordinate bug instead of repeating it.
    step = plan.steps[0]
    native_by_serial = {row.serial: row.block_ref for row in source.blocks}
    if family == "direct":
        feeder = step.from_serial
        old_target = step.old_target
        untouched = next(
            native_by_serial[serial]
            for serial in bind._inventory_block(source, feeder).successor_serials
            if native_by_serial[serial] != old_target
        )
        expected = [anchored(feeder), anchored(old_target), anchored(untouched), anchored(step.new_target)]
    elif family == "helper":
        helper = plan.new_blocks[0].block_id
        feeder = step.from_serial
        old_target = step.old_target
        untouched = next(
            native_by_serial[serial]
            for serial in bind._inventory_block(source, feeder).successor_serials
            if native_by_serial[serial] != old_target
        )
        expected = [anchored(feeder), anchored(untouched), anchored(old_target), anchored(helper), anchored(step.new_target)]
    elif family == "split":
        clone = plan.new_blocks[0].block_id
        split_source = plan.new_blocks[0].template_block
        expected = [anchored(step.via_pred), anchored(split_source), anchored(step.old_target), anchored(step.old_target), anchored(clone), anchored(step.new_target)]
    elif family == "corridor":
        corridor = tuple(step.corridor_serials)
        clones = tuple(step.clone_block_ids)
        last = bind._inventory_block(source, corridor[-1])
        terminal = native_by_serial[last.successor_serials[0]]
        # The literal family N is the sealed claim destination.  Unsupported
        # proof fixtures intentionally exercise cases where the compiler step
        # target and the claim destination differ; descriptor coordinates must
        # not silently replace the role anchor.
        claim_target = authority.proposal.claims[0].retired_route_subject.locator.destination_refs[-1]
        expected = [anchored(step.via_pred), *(anchored(ref) for ref in corridor), anchored(terminal), *(anchored(ref) for ref in clones), anchored(claim_target)]
    else:
        raise AssertionError(f"unknown literal anchor family {family!r}")
    assert tuple(sorted(set(expected), key=canonical_bytes)) == result.failures[0].anchored_refs


def test_3b3_projected_corridor_retained_prefix_rewire_fails_closed() -> None:
    """The projected SOURCE corridor must retain its original reciprocal edge."""
    authority, plan, source, projected, facts, attempt, _expected = (
        _three_b3_one_block_corridor_case()
    )
    retained = next(row for row in projected.blocks if row.serial == 1)
    unrelated = next(row for row in projected.blocks if row.serial == 3)
    retained = replace(retained, successor_serials=(unrelated.serial,))
    unrelated = replace(unrelated, predecessor_serials=(retained.serial,))
    old_target = next(row for row in projected.blocks if row.serial == 2)
    old_target = replace(old_target, predecessor_serials=())
    topology = tuple(projected.topology)
    predecessor_incidence = next(item for item in topology if item.kind.value == "predecessor" and item.owner_serial == 2 and item.peer_serial == 1)
    successor_incidence = next(item for item in topology if item.kind.value == "successor" and item.owner_serial == 1 and item.peer_serial == 2)
    topology = tuple(sorted(tuple(
        item for item in topology
        if item not in {predecessor_incidence, successor_incidence}
    ) + (
        replace(predecessor_incidence, owner_serial=unrelated.serial),
        replace(successor_incidence, peer_serial=unrelated.serial),
    ), key=lambda item: (item.kind.value, item.owner_serial, item.peer_serial, item.source_transfer_ea if item.source_transfer_ea is not None else -1)))
    blocks = tuple(
        retained if row.serial == retained.serial else
        old_target if row.serial == old_target.serial else
        unrelated if row.serial == unrelated.serial else row
        for row in projected.blocks
    )
    mutated = replace(
        projected, blocks=blocks, topology=topology,
        inventory_digest=semantic_graph_inventory_digest(
            projected.phase, projected.graph_fingerprint, projected.generation,
            blocks, projected.subjects, projected.bindings, projected.effects,
            projected.terminals, topology, projected.reachable_serials,
            projected.entry_serial, projected.source_subject_ids, projected.function_ea,
        ),
    )
    result = realize_projected_routes_for_test(
        source_authority=authority, plan=plan, source_inventory=source,
        projected_inventory=mutated, patch_step_facts=facts, attempt_id=attempt,
    )
    _assert_final_review_step_coordinates(result, authority, facts)
    assert result.failures[0].stage is model.RouteRealizationFailureStage.OLD_EDGE_REMOVAL


