# Task 15 Slice 3B3 Phase 0 REDs.  These intentionally name the private seam
# before it exists; each test uses the compiler-backed lower-conditional case
# below so the RED is against production behavior, not a hand-written fact.
def _literal_phase0_owner_refs(step):
    from d810.transforms.plan import (
        PatchRedirectGoto, PatchRedirectBranch,
        PatchLowerConditionalStateTransition, PatchEdgeSplitTrampoline,
        PatchEdgeSplitCorridor, PatchConditionalRedirect,
    )
    if type(step) is PatchRedirectBranch:
        return (step.from_serial, *( (step.fallthrough_helper_block_id,) if step.fallthrough_helper_block_id is not None else () ))
    if type(step) is PatchRedirectGoto:
        return (step.from_serial,)
    if type(step) is PatchLowerConditionalStateTransition:
        return (step.source_serial,)
    if type(step) is PatchEdgeSplitTrampoline:
        return (step.block_id,)
    if type(step) is PatchEdgeSplitCorridor:
        return tuple(step.clone_block_ids)
    if type(step) is PatchConditionalRedirect:
        return (step.block_id, step.fallthrough_block_id)
    raise AssertionError(f"unsupported Phase-0 step type {type(step)!r}")


def _literal_phase0_step_refs(step):
    from d810.transforms.plan import (
        PatchRedirectGoto, PatchRedirectBranch, PatchLowerConditionalStateTransition,
        PatchEdgeSplitTrampoline, PatchEdgeSplitCorridor,
        PatchConditionalRedirect,
    )
    if type(step) is PatchRedirectBranch:
        return (step.from_serial, step.old_target, step.new_target)
    if type(step) is PatchRedirectGoto:
        return (step.from_serial, step.old_target, step.new_target)
    if type(step) is PatchLowerConditionalStateTransition:
        return (step.source_serial, step.old_dispatcher_serial, step.false_target_serial, step.true_target_serial)
    if type(step) is PatchEdgeSplitTrampoline:
        return (step.source_serial, step.via_pred, step.old_target, step.apply_old_target, step.new_target, step.template_block)
    if type(step) is PatchEdgeSplitCorridor:
        return (step.source_serial, step.via_pred, step.old_target, step.new_target, step.clone_until, *step.corridor_serials, *step.clone_block_ids)
    if type(step) is PatchConditionalRedirect:
        return (step.block_id, step.source_serial, step.ref_block, step.conditional_target, step.fallthrough_target, step.old_target_serial)
    raise AssertionError(f"unsupported Phase-0 step type {type(step)!r}")


def _literal_phase0_anchor_refs(step):
    """Return the plan operands that Phase-0 diagnostics anchor literally."""
    from d810.transforms.plan import (
        PatchRedirectGoto, PatchRedirectBranch,
        PatchEdgeSplitTrampoline, PatchEdgeSplitCorridor,
        PatchConditionalRedirect,
    )
    if type(step) is PatchRedirectBranch:
        return (step.from_serial, step.old_target, step.fallthrough_helper_block_id)
    if type(step) is PatchRedirectGoto:
        return (step.from_serial,)
    if type(step) is PatchConditionalRedirect:
        return (step.block_id, step.fallthrough_block_id, step.source_serial, step.ref_block)
    if type(step) is PatchEdgeSplitTrampoline:
        return (step.block_id, step.source_serial, step.via_pred, step.old_target)
    if type(step) is PatchEdgeSplitCorridor:
        return (step.source_serial, step.via_pred, step.old_target, *step.clone_block_ids)
    return _literal_phase0_owner_refs(step)


def test_lineage_fact_group_seam_accepts_3b1_3b2a_3b2b_in_canonical_order() -> None:
    # Exercise the retained producer families through the public final sweep;
    # fact order is transport order, never semantic ownership order.
    fixtures = (
        lambda: _real_projected_branch_fixture(step_shape="goto", direct_route=True),
        _lower_conditional_case,
        _conditional_redirect_case_for_inventory_mutation,
    )
    for builder in fixtures:
        values = builder()
        authority, plan, source, projected, facts, attempt = values[:6]
        canonical = realize_projected_routes_for_test(
            source_authority=authority, plan=plan,
            source_inventory=source, projected_inventory=projected,
            patch_step_facts=facts, attempt_id=attempt,
        )
        reversed_result = realize_projected_routes_for_test(
            source_authority=authority, plan=plan,
            source_inventory=source, projected_inventory=projected,
            patch_step_facts=tuple(reversed(facts)), attempt_id=attempt,
        )
        assert type(canonical) is model.ProjectedRouteRealizationAccepted
        assert canonical == reversed_result
        assert canonical.realization.rows
        rows = canonical.realization.rows
        assert tuple(row.plan_step_index for row in rows) == tuple(sorted(row.plan_step_index for row in rows))
        assert tuple(row.plan_step_digest for row in rows) == tuple(sorted(row.plan_step_digest for row in rows))
        assert tuple(row.row_id for row in rows) == tuple(sorted(row.row_id for row in rows))
        assert tuple(row.relation.relation_id for row in rows) == tuple(sorted(row.relation.relation_id for row in rows))
        literal_owners = _literal_phase0_owner_refs(plan.steps[0])
        expected_facts = tuple(
            next(fact for fact in facts if fact.owner_ref == owner)
            for owner in literal_owners
        )
        indexed = bind._index_lineage_fact_groups(plan, facts).entries[0]
        reversed_indexed = bind._index_lineage_fact_groups(
            plan, tuple(reversed(facts)),
        ).entries[0]
        assert indexed.facts == expected_facts
        assert reversed_indexed.facts == expected_facts
        assert tuple((row.plan_step_index, row.plan_step_digest) for row in rows) == (
            tuple((facts[0].step_index, facts[0].step_digest) for _ in rows)
        )


@pytest.mark.parametrize(
    "fixture",
    (
        "_compiler_redirect_goto_case", "_lower_conditional_case",
        "_conditional_redirect_case_for_inventory_mutation", "_compiler_helper_branch_case",
        "_three_b3_direct_branch_case",
        "_three_b3_split_trampoline_case", "_three_b3_one_block_corridor_case",
        "_three_b3_two_block_corridor_case",
    ),
)
@pytest.mark.parametrize("mutation", ("duplicate", "missing", "extra", "foreign"))
@pytest.mark.parametrize("reverse_facts", (False, True), ids=("canonical", "reversed"))
def test_lineage_fact_group_seam_rejects_duplicate_and_owner_sets_for_every_family(
    fixture: str, mutation: str, reverse_facts: bool,
) -> None:
    authority, plan, source, projected, facts, attempt, *_ = globals()[fixture]()
    if mutation == "duplicate":
        supplied = (facts[0], facts[0])
    elif mutation == "missing":
        supplied = facts[:-1]
    elif mutation == "extra":
        supplied = (*facts, replace(facts[0], owner_ref=block_ref("extra-lineage-owner")))
    else:
        supplied = (*facts[:-1], replace(facts[-1], owner_ref=block_ref("foreign-lineage-owner")))
    malformed = tuple(reversed(supplied)) if reverse_facts else supplied
    results = tuple(
        realize_projected_routes_for_test(
            source_authority=authority, plan=plan,
            source_inventory=source, projected_inventory=projected,
            patch_step_facts=(malformed if not order else tuple(reversed(malformed))),
            attempt_id=attempt,
        )
        for order in (False, True)
    )
    assert all(type(result) is model.ProjectedRouteRealizationRejected for result in results)
    assert results[0] == results[1]
    failure = results[0].failures[0]
    if mutation != "missing":
        # Duplicate and foreign-owner rows violate the transaction-owned fact
        # inventory itself.  Only an absent canonical row reaches the family
        # lineage closure and can carry step-local coordinates.
        assert failure.stage is model.RouteRealizationFailureStage.ATTEMPT_BINDING
        assert failure.scope is model.RouteRealizationFailureScope.EVIDENCE
        assert failure.proposal_id == authority.proposal_id
        assert failure.evidence_id == authority.evidence_id
        assert failure.claim_id is None and failure.proof_id is None
        assert failure.route_subject_id is None
        assert failure.step_index is None and failure.step_digest is None
        assert failure.anchored_refs == ()
        return
    assert failure.stage is model.RouteRealizationFailureStage.HELPER_LINEAGE
    assert failure.scope is model.RouteRealizationFailureScope.STEP
    claim = authority.proposal.claims[0]
    proof = authority.proposal.route_evidence.route_proofs[0]
    assert failure.claim_id == claim.claim_id
    assert failure.proof_id == proof.proof_id
    assert failure.route_subject_id == claim.retired_route_subject.subject_id
    assert failure.proposal_id == authority.proposal_id
    assert failure.evidence_id == authority.evidence_id
    assert failure.step_index == 0
    assert failure.step_digest in {fact.step_digest for fact in facts}
    literal_refs = (
        *_literal_phase0_anchor_refs(plan.steps[0]),
    )
    expected = set(_claim_anchored_refs(claim))
    expected.update(
        model.AnchoredBlockRef(ref, rows[0].anchor_ea)
        for ref in literal_refs if ref is not None
        for rows in ((
            tuple(row for row in (*source.blocks, *projected.blocks) if row.block_ref == ref)
        ),)
        if rows
    )
    expected_anchors = tuple(sorted(expected, key=canonical_bytes))
    assert failure.anchored_refs == expected_anchors


@pytest.mark.parametrize(
    "field",
    ("plan_id", "step_type", "host_ea", "host_opcode", "value_size", "owner_ref", "creation_spec_digest"),
)
@pytest.mark.parametrize("reverse_facts", (False, True), ids=("canonical", "reversed"))
def test_lineage_fact_group_seam_validates_each_nonidentity_fact_field_once(
    field: str, reverse_facts: bool,
) -> None:
    authority, plan, source, projected, facts, attempt, claim, _proof, _refs = (
        _compiler_redirect_goto_case()
    )
    fact = facts[0]
    values = {
        "plan_id": authority_id("foreign-lineage-plan"),
        "step_type": "foreign-step-type",
        "host_ea": (fact.host_ea or 0) + 1,
        "host_opcode": (fact.host_opcode or 0) + 1,
        "value_size": (fact.value_size or 1) + 1,
        "owner_ref": block_ref("foreign-lineage-owner"),
        "creation_spec_digest": authority_id("foreign-lineage-spec"),
    }
    malformed = (replace(fact, **{field: values[field]}),)
    result = realize_projected_routes_for_test(
        source_authority=authority, plan=plan, source_inventory=source,
        projected_inventory=projected,
        patch_step_facts=tuple(reversed(malformed)) if reverse_facts else malformed,
        attempt_id=attempt,
    )
    assert type(result) is model.ProjectedRouteRealizationRejected
    failure = result.failures[0]
    expected_stage = (
        model.RouteRealizationFailureStage.ATTEMPT_BINDING
        if field in {"plan_id", "owner_ref"} else
        model.RouteRealizationFailureStage.HELPER_LINEAGE
        if field == "creation_spec_digest"
        else model.RouteRealizationFailureStage.PLAN_STEP_CORRELATION
    )
    assert failure.stage is expected_stage
    if field in {"plan_id", "owner_ref"}:
        assert failure.scope is model.RouteRealizationFailureScope.EVIDENCE
        assert failure.claim_id is None and failure.proof_id is None
        assert failure.route_subject_id is None and failure.anchored_refs == ()
        assert failure.step_index is None and failure.step_digest is None
    else:
        assert failure.scope is model.RouteRealizationFailureScope.STEP
        assert failure.claim_id == claim.claim_id
        assert failure.proof_id is not None and failure.route_subject_id is not None
        assert failure.step_index == fact.step_index
        assert failure.step_digest == fact.step_digest
        assert failure.anchored_refs == _claim_anchored_refs(claim)


def test_lineage_fact_group_seam_rejects_absent_or_conflicting_exact_identity_without_reconstruction() -> None:
    cases = []
    authority, plan, source, projected, facts, attempt = _conditional_redirect_case_for_inventory_mutation()
    cases.extend((
        (authority, plan, source, projected, attempt,
         replace(facts[0], step_index=1), facts[1]),
        (authority, plan, source, projected, attempt,
         replace(facts[0], step_digest=authority_id("digest-only-absent")), facts[1]),
    ))
    extra = _real_projected_branch_fixture(step_shape="goto", direct_route=True, extra_step=True)
    extra_authority, extra_plan, extra_source, extra_projected, extra_facts, extra_attempt = extra[:6]
    cases.append((
        extra_authority, extra_plan, extra_source, extra_projected, extra_attempt,
        replace(extra_facts[0], step_index=extra_facts[1].step_index), extra_facts[1],
    ))
    for authority, plan, source, projected, attempt, mutated, companion in cases:
        supplied_pair = (mutated, companion)
        for reverse_facts in (False, True):
            supplied = tuple(reversed(supplied_pair)) if reverse_facts else supplied_pair
            result = realize_projected_routes_for_test(
                source_authority=authority, plan=plan,
                source_inventory=source, projected_inventory=projected,
                patch_step_facts=supplied, attempt_id=attempt,
            )
            assert type(result) is model.ProjectedRouteRealizationRejected
            failure = result.failures[0]
            assert failure.stage is model.RouteRealizationFailureStage.PLAN_STEP_CORRELATION
            assert failure.scope is model.RouteRealizationFailureScope.EVIDENCE
            assert failure.claim_id is None
            assert failure.proof_id is None
            assert failure.route_subject_id is None
            assert failure.anchored_refs == ()
            assert failure.step_index == mutated.step_index
            assert failure.step_digest == mutated.step_digest


def test_lineage_fact_group_seam_rejects_unselected_corrupt_facts_without_claim_invention() -> None:
    # The extra compiler descriptor is valid but unrelated (step 0); the
    # direct route claim selects step 1.  A complete group is ignored, while a
    # missing unrelated group remains optional and a supplied corrupt group is
    # rejected by the final public sweep.
    authority, plan, source, projected, facts, attempt, *_ = (
        _real_projected_branch_fixture(step_shape="goto", direct_route=True, extra_step=True)
    )
    accepted = []
    for reverse_facts in (False, True):
        supplied = tuple(reversed(facts)) if reverse_facts else facts
        result = realize_projected_routes_for_test(
            source_authority=authority, plan=plan, source_inventory=source,
            projected_inventory=projected, patch_step_facts=supplied,
            attempt_id=attempt,
        )
        assert type(result) is model.ProjectedRouteRealizationAccepted
        assert result.realization.rows[0].plan_step_index == 1
        accepted.append(result)
        unrelated_only = (facts[1],)
        result = realize_projected_routes_for_test(
            source_authority=authority, plan=plan, source_inventory=source,
            projected_inventory=projected,
            patch_step_facts=tuple(reversed(unrelated_only)) if reverse_facts else unrelated_only,
            attempt_id=attempt,
        )
        assert type(result) is model.ProjectedRouteRealizationAccepted
        assert result.realization.rows[0].plan_step_index == 1
        corrupt = replace(facts[0], owner_ref=block_ref("foreign-unselected"))
        malformed = (corrupt, facts[1])
        result = realize_projected_routes_for_test(
            source_authority=authority, plan=plan, source_inventory=source,
            projected_inventory=projected,
            patch_step_facts=tuple(reversed(malformed)) if reverse_facts else malformed,
            attempt_id=attempt,
        )
        assert type(result) is model.ProjectedRouteRealizationRejected
        failure = result.failures[0]
        assert failure.stage is model.RouteRealizationFailureStage.ATTEMPT_BINDING
        assert failure.scope is model.RouteRealizationFailureScope.EVIDENCE
        assert failure.claim_id is None
        assert failure.proof_id is None
        assert failure.route_subject_id is None
        assert failure.anchored_refs == ()
        assert failure.step_index is None
        assert failure.step_digest is None
    assert accepted[0] == accepted[1]


def test_lineage_fact_group_seam_has_no_parallel_validation_paths() -> None:
    text = __import__("pathlib").Path(bind.__file__).read_text()
    projected_source = text.split("def _realize_projected_routes(", 1)[1].split(
        "\ndef _validate_registered_result", 1,
    )[0]
    assert "_index_lineage_fact_groups(" in projected_source
    assert "_select_lineage_fact_group(" in projected_source
    assert "_require_valid_lineage_fact_group(" in projected_source
    assert text.count("canonical_patch_step_descriptors(") == 1
    assert "canonical_patch_step_descriptor(" not in projected_source
    assert "_validate_step_fact_digest" not in text
    assert "_conditional_preselection" not in text
    assert __import__("re").search(r"\bid\s*\(\s*fact\s*\)", text) is None
    selector_source = text.split("def _select_lineage_fact_group(", 1)[1].split(
        "\ndef _require_valid_lineage_fact_group", 1,
    )[0]
    for kind in PatchStepKind:
        assert f"PatchStepKind.{kind.name}" in selector_source

    # After the single index call the projected binder consumes only the
    # closed descriptor/group view.  No raw-fact iteration, step-index
    # filtering, or replay of the index's owner/cardinality checks is allowed.
    post_index = projected_source.split("lineage_index = _index_lineage_fact_groups(", 1)[1]
    assert "patch_step_facts" not in post_index
    assert "for fact in facts" not in post_index
    assert "expected_owners" not in post_index
    assert "len(supplied)" not in post_index

    authority, plan, source, projected, facts, attempt, *_ = _compiler_redirect_goto_case()
    with (
        patch.object(bind, "canonical_patch_step_descriptors", wraps=bind.canonical_patch_step_descriptors) as descriptors,
        patch.object(bind, "_index_lineage_fact_groups", wraps=bind._index_lineage_fact_groups) as index,
        patch.object(bind, "_select_lineage_fact_group", wraps=bind._select_lineage_fact_group) as select,
        patch.object(bind, "_require_valid_lineage_fact_group", wraps=bind._require_valid_lineage_fact_group) as require,
    ):
        result = realize_projected_routes_for_test(
            source_authority=authority, plan=plan, source_inventory=source,
            projected_inventory=projected, patch_step_facts=facts,
            attempt_id=attempt,
        )
    assert type(result) is model.ProjectedRouteRealizationAccepted
    assert descriptors.call_count == 1
    assert index.call_count == select.call_count == require.call_count == 1


def _lower_conditional_case(
    *, projected_mutation=None, proof_mutation=None, source_mutation=None,
    include_exact_claim: bool = False, **step_overrides,
):
    from d810.analyses.control_flow import semantic_route_evidence as route_model
    from d810.transforms.edit_simulator import project_post_state
    from d810.transforms.graph_modification import SyntheticStackValueEqualsCondition
    from d810.transforms.plan import PatchLowerConditionalStateTransition, PatchPlan
    from d810.transforms.cfg_transaction import TransactionAttemptId

    source, base, _exclusion, refs = exact_fixture()
    if source_mutation is not None:
        source = source_mutation(source)
    if proof_mutation is not None:
        base = replace(base, route_evidence=proof_mutation(base.route_evidence))
    claims = producer_api.build_equivalent_route_claims(
        source=source, source_catalog=base.source_identity_catalog,
        route_evidence=base.route_evidence,
        selected_proof_ids=(base.route_evidence.route_proofs[0].proof_id,),
    )
    proposal = replace(base, claims=base.claims if include_exact_claim else claims, plan_inputs=replace(
        base.plan_inputs, shape=model.UnflattenPlanShape.PARTIAL_REWRITE,
    ))
    values = dict(
        source_serial=refs[0], old_dispatcher_serial=refs[1], rewrite_from_ea=0x1001,
        condition_operand=SyntheticStackValueEqualsCondition(4, 4, 7),
        false_target_serial=refs[3], true_target_serial=refs[2], proof_id="diagnostic-only",
        state_register=None, state_size=None, false_state=None, true_state=None,
        false_state_write_ea=None, true_state_write_ea=None,
    )
    values.update(step_overrides)
    step = PatchLowerConditionalStateTransition(**values)
    plan = PatchPlan(
        plan_id=proposal.plan_id, snapshot_id=authority_id("lower-case"),
        source_generation=1, steps=(step,),
        source_coordinates=tuple((ref, serial) for serial, ref in refs.items()),
        unflatten_proposal=proposal,
    )
    materialization = route_model.CanonicalRouteMaterialization.capture(
        source, generation=1, phase=route_model.CanonicalRouteAssessmentPhase.SOURCE,
    )
    source_inventory = transaction_api._build_semantic_graph_inventory(
        source, proposal, plan, source=True,
        phase=model.UnflattenAuthorityPhase.PRODUCER_FORECAST,
        materialization=materialization,
    )
    authority = bind.bind_source_route_authority(
        proposal=proposal, source_inventory=source_inventory,
        source_materialization=materialization,
    )
    assert type(authority) is model.SourceBoundRouteAuthorityAccepted
    projected = project_post_state(source, plan)
    if projected_mutation is not None:
        feeder = projected.blocks[0]
        tail = feeder.insn_snapshots[-1]
        if projected_mutation == "swapped_arms":
            feeder = replace(
                feeder, succs=(2, 3),
                insn_snapshots=(*feeder.insn_snapshots[:-1], replace(
                    tail, d=MopSnapshot(kind=OperandKind.BLOCK, block_ref=3),
                )),
            )
        elif projected_mutation == "wrong_explicit_target":
            feeder = replace(
                feeder, insn_snapshots=(*feeder.insn_snapshots[:-1], replace(
                    tail, d=MopSnapshot(kind=OperandKind.BLOCK, block_ref=3),
                )),
            )
        elif projected_mutation == "retained_old_edge":
            feeder = replace(
                feeder, succs=(3, 2, 1), kind=BlockKind.N_WAY,
                tail_kind=InsnKind.GOTO,
                insn_snapshots=(*feeder.insn_snapshots[:-1], replace(
                    tail, kind=InsnKind.GOTO, d=None, r=None,
                    control_transfer_kind=ControlTransferKind.GOTO,
                    branch_predicate=None, predicate_kind=None,
                    compare_width=None, is_conditional_jump=False,
                    is_unconditional_jump=True,
                )),
            )
        elif projected_mutation == "missing_predicate":
            feeder = replace(
                feeder, insn_snapshots=(*feeder.insn_snapshots[:-1], replace(
                    tail, branch_predicate=None, predicate_kind=None,
                    compare_width=None,
                )),
            )
        blocks = dict(projected.blocks)
        blocks[0] = feeder
        if projected_mutation == "missing_reciprocal":
            blocks[2] = replace(blocks[2], preds=(1,))
        elif projected_mutation == "retained_old_edge":
            blocks[1] = replace(blocks[1], preds=(0,))
        projected = type(projected)(
            blocks=blocks, entry_serial=projected.entry_serial,
            func_ea=projected.func_ea,
        )
    projected_inventory = transaction_api._build_semantic_graph_inventory(
        projected, proposal, plan, source=False,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        materialization=route_model.CanonicalRouteMaterialization.capture(
            projected, generation=1,
            phase=route_model.CanonicalRouteAssessmentPhase.PROJECTED,
        ),
        source_subjects=source_inventory.subjects,
    )
    facts = transaction_api._derive_patch_lineage_facts(source_inventory, plan)
    attempt = TransactionAttemptId(
        plan.plan_id, authority_id("lower-case-session"), 1,
        authority_id("lower-case-attempt"),
    )
    return authority.authority, plan, source_inventory, projected_inventory, facts, attempt, refs


@pytest.mark.parametrize(
    ("projected_mutation", "expected_stage"),
    (
        ("swapped_arms", model.RouteRealizationFailureStage.CONDITIONAL_ROLES),
        ("wrong_explicit_target", model.RouteRealizationFailureStage.CONDITIONAL_ROLES),
        ("missing_reciprocal", None),
        ("retained_old_edge", model.RouteRealizationFailureStage.OLD_EDGE_REMOVAL),
        ("missing_predicate", model.RouteRealizationFailureStage.CONDITIONAL_ROLES),
    ),
)
def test_projected_lower_conditional_inventory_drift_fails_closed(projected_mutation, expected_stage) -> None:
    if projected_mutation == "missing_reciprocal":
        with pytest.raises(ValueError, match="topology must be reciprocal"):
            _lower_conditional_case(projected_mutation=projected_mutation)
        return
    authority, plan, source_inventory, projected_inventory, facts, attempt, _refs = (
        _lower_conditional_case(projected_mutation=projected_mutation)
    )
    result = realize_projected_routes_for_test(
        source_authority=authority, plan=plan,
        source_inventory=source_inventory, projected_inventory=projected_inventory,
        patch_step_facts=facts, attempt_id=attempt,
    )
    assert type(result) is model.ProjectedRouteRealizationRejected
    failure = result.failures[0]
    assert failure.scope is model.RouteRealizationFailureScope.STEP
    assert failure.step_index == 0
    assert failure.stage is expected_stage
    assert failure.claim_id == authority.proposal.claims[0].claim_id
    assert failure.proof_id == authority.proposal.route_evidence.route_proofs[0].proof_id
    assert failure.proposal_id == authority.proposal_id
    assert failure.evidence_id == authority.evidence_id
    assert failure.step_digest == facts[0].step_digest
    assert failure.anchored_refs


