@pytest.mark.parametrize(
    ("mutation", "expected_count"),
    (("missing_clone", 1), ("missing_helper", 1),
     ("duplicate_clone", 3), ("duplicate_helper", 3), ("duplicate_group", 4),
     ("foreign_owner", 2)),
)
def test_conditional_owner_group_cardinality_is_atomic_in_both_orders(
    mutation: str, expected_count: int,
) -> None:
    authority, plan, source_inventory, projected_inventory, facts, attempt = (
        _conditional_redirect_case_for_inventory_mutation()
    )
    clone, helper = facts
    if mutation == "missing_clone":
        malformed = (helper,)
    elif mutation == "missing_helper":
        malformed = (clone,)
    elif mutation == "duplicate_clone":
        malformed = (clone, clone, helper)
    elif mutation == "duplicate_helper":
        malformed = (clone, helper, helper)
    elif mutation == "duplicate_group":
        malformed = (*facts, *facts)
    else:
        malformed = (replace(clone, owner_ref=block_ref("foreign-conditional-owner")), helper)
    results = tuple(
        realize_projected_routes_for_test(
            source_authority=authority,
            plan=plan,
            source_inventory=source_inventory,
            projected_inventory=projected_inventory,
            patch_step_facts=(tuple(reversed(malformed)) if reverse else malformed),
            attempt_id=attempt,
        )
        for reverse in (False, True)
    )
    assert all(type(result) is model.ProjectedRouteRealizationRejected for result in results)
    assert results[0].failures == results[1].failures
    failure = results[0].failures[0]
    assert len(malformed) == expected_count
    if mutation not in {"missing_clone", "missing_helper"}:
        assert failure.stage is model.RouteRealizationFailureStage.ATTEMPT_BINDING
        assert failure.scope is model.RouteRealizationFailureScope.EVIDENCE
        assert failure.proposal_id == authority.proposal_id
        assert failure.evidence_id == authority.evidence_id
        assert failure.claim_id is None and failure.proof_id is None
        assert failure.route_subject_id is None
        assert failure.step_index is None and failure.step_digest is None
        assert failure.anchored_refs == ()
        return
    assert failure.stage is model.RouteRealizationFailureStage.HELPER_LINEAGE
    assert failure.scope is model.RouteRealizationFailureScope.STEP
    assert failure.proposal_id == authority.proposal_id
    assert failure.evidence_id == authority.evidence_id
    assert failure.claim_id == authority.proposal.claims[0].claim_id
    assert failure.proof_id == authority.proposal.route_evidence.route_proofs[0].proof_id
    assert failure.route_subject_id == authority.proposal.claims[0].retired_route_subject.subject_id
    assert failure.step_index == 0
    assert failure.step_digest == clone.step_digest
    assert len(failure.anchored_refs) == 6
    expected_native_refs = {
        row.block_ref for row in source_inventory.blocks if row.serial in (0, 1, 2, 3)
    }
    assert {item.ref for item in failure.anchored_refs} == {
        *expected_native_refs,
        plan.steps[0].block_id,
        plan.steps[0].fallthrough_block_id,
    }


def test_conditional_exact_group_binds_unrelated_step_into_transaction_identity() -> None:
    from d810.transforms.plan import PatchRedirectGoto

    authority, plan, source_inventory, projected_inventory, facts, attempt = (
        _conditional_redirect_case_for_inventory_mutation()
    )
    baseline = realize_projected_routes_for_test(
        source_authority=authority, plan=plan, source_inventory=source_inventory,
        projected_inventory=projected_inventory, patch_step_facts=facts, attempt_id=attempt,
    )
    mixed_plan = replace(
        plan,
        steps=(*plan.steps, PatchRedirectGoto(
            from_serial=plan.steps[0].source_serial,
            old_target=plan.steps[0].ref_block,
            new_target=plan.steps[0].fallthrough_target,
        )),
    )
    mixed_facts = transaction_api._derive_patch_lineage_facts(source_inventory, mixed_plan)
    mixed = realize_projected_routes_for_test(
        source_authority=authority, plan=mixed_plan, source_inventory=source_inventory,
        projected_inventory=projected_inventory, patch_step_facts=tuple(reversed(mixed_facts)),
        attempt_id=attempt,
    )
    assert type(baseline) is model.ProjectedRouteRealizationAccepted
    assert type(mixed) is model.ProjectedRouteRealizationAccepted
    assert mixed.realization.rows[0].relation == baseline.realization.rows[0].relation
    assert mixed.realization.realization_id != baseline.realization.realization_id
    assert mixed.realization.rows[0].row_id != baseline.realization.rows[0].row_id
    assert mixed.realization.rows[0].relation.relation_id == baseline.realization.rows[0].relation.relation_id
    assert mixed.realization.rows[0].conditional_roles == baseline.realization.rows[0].conditional_roles


def test_conditional_exact_descriptor_ambiguity_is_claim_scoped() -> None:
    authority, plan, source_inventory, projected_inventory, _facts, attempt = (
        _conditional_redirect_case_for_inventory_mutation()
    )
    ambiguous_plan = replace(
        plan,
        steps=(*plan.steps, plan.steps[0]),
    )
    from d810.transforms.unflatten_authority.proposal import canonical_patch_step_descriptors
    duplicate_descriptor = canonical_patch_step_descriptors(ambiguous_plan)[1]
    ambiguous_facts = (
        *_facts,
        *(replace(
            fact,
            step_index=1,
            step_digest=duplicate_descriptor.step_digest,
        ) for fact in _facts),
    )
    results = tuple(
        realize_projected_routes_for_test(
            source_authority=authority, plan=ambiguous_plan,
            source_inventory=source_inventory, projected_inventory=projected_inventory,
            patch_step_facts=(tuple(reversed(ambiguous_facts)) if reverse else ambiguous_facts),
            attempt_id=attempt,
        )
        for reverse in (False, True)
    )
    assert all(type(result) is model.ProjectedRouteRealizationRejected for result in results)
    assert results[0].failures == results[1].failures
    failure = results[0].failures[0]
    assert failure.stage is model.RouteRealizationFailureStage.CLAIM_SELECTION
    assert failure.scope is model.RouteRealizationFailureScope.CLAIM
    assert failure.claim_id == authority.proposal.claims[0].claim_id
    assert failure.proof_id == authority.proposal.route_evidence.route_proofs[0].proof_id
    assert failure.route_subject_id == authority.proposal.claims[0].retired_route_subject.subject_id
    assert failure.proposal_id == authority.proposal_id
    assert failure.evidence_id == authority.evidence_id
    assert failure.step_index is None
    assert failure.step_digest is None
    expected_native_refs = {
        row.block_ref for row in source_inventory.blocks if row.serial in (1, 2, 3)
    }
    assert {item.ref for item in failure.anchored_refs} == expected_native_refs


def test_conditional_exact_and_fallback_candidates_share_one_union_tier() -> None:
    authority, plan, _source, _projected, facts, _attempt = (
        _conditional_redirect_case_for_inventory_mutation()
    )
    entry = bind._index_lineage_fact_groups(plan, facts).entries[0]
    descriptor = entry.descriptor
    fallback_descriptor = replace(
        descriptor,
        step_index=1,
        route_refs=(
            descriptor.route_refs[2], descriptor.route_refs[1],
            descriptor.route_refs[2], descriptor.route_refs[3],
        ),
    )
    # The source owner is exact for the first descriptor and the source block
    # is the fallback coordinate for the second; they are distinct steps.
    synthetic_index = bind._LineageFactGroupIndex((
        entry,
        replace(entry, descriptor=fallback_descriptor),
    ))
    claim = authority.proposal.claims[0]
    proof = authority.proposal.route_evidence.route_proofs[0]
    with pytest.raises(bind._LineageFactViolation) as caught:
        bind._select_lineage_fact_group(
            synthetic_index, plan=plan, claim=claim, proof=proof,
        )
    assert caught.value.stage is model.RouteRealizationFailureStage.CLAIM_SELECTION


