def test_projected_goto_rejects_conditional_proof_shape() -> None:
    """A GOTO cannot silently consume the branch-only fixture proof."""
    authority, plan, source_inventory, projected_inventory, facts, attempt, claim, *_ = (
        _real_projected_branch_fixture(step_shape="goto")
    )
    result = realize_projected_routes_for_test(
        source_authority=authority,
        plan=plan,
        source_inventory=source_inventory,
        projected_inventory=projected_inventory,
        patch_step_facts=facts,
        attempt_id=attempt,
    )
    assert type(result) is model.ProjectedRouteRealizationRejected
    failure = result.failures[0]
    assert failure.stage is model.RouteRealizationFailureStage.CLAIM_COVERAGE
    assert failure.scope is model.RouteRealizationFailureScope.CLAIM
    assert failure.step_index is None
    assert failure.step_digest is None
    assert failure.claim_id == claim.claim_id
    assert failure.proof_id == claim.route_proof_ids[0]
    descriptor = __import__(
        "d810.transforms.unflatten_authority.proposal",
        fromlist=["canonical_patch_step_descriptor"],
    ).canonical_patch_step_descriptor(plan, 0)
    inventory_by_ref = {row.block_ref: row for row in source_inventory.blocks}
    expected_anchors = set(_claim_anchored_refs(claim))
    expected_anchors.update(
        model.AnchoredBlockRef(ref, inventory_by_ref[ref].anchor_ea)
        for ref in descriptor.route_refs
        if ref in inventory_by_ref and inventory_by_ref[ref].anchor_ea is not None
    )
    assert expected_anchors <= set(failure.anchored_refs)


