def test_retirement_binding_requires_retained_members_and_seals_post_bind_mutation() -> None:
    from d810.transforms.unflatten_authority import transaction_api
    from d810.transforms.unflatten_authority.bind import validate_retired_infrastructure_binding_result

    proposal, claim, source_inventory, projected_inventory = _retirement_inventories()
    result = bind.bind_retired_dispatcher_infrastructure_claim(
        claim=claim, proposal=proposal,
        source_inventory=source_inventory,
        projected_inventory=projected_inventory,
    )
    retained = next(
        item for item in result.projected_bindings
        if item.subject.block_ref == claim.candidate_catalog.plan_members[0].block_ref
    )
    assert retained.status is model.SubjectBindingStatus.UNIQUE
    assert not hasattr(result, "candidate_reachable_serials")
    object.__setattr__(result, "generation", source_inventory.generation + 1)
    with pytest.raises(ValueError, match="content seal|generation"):
        validate_retired_infrastructure_binding_result(result)


def test_retirement_binding_accepts_physically_present_but_unreachable_retired_member() -> None:
    """Retirement is a reachability fact, even when the block remains indexed."""

    proposal, claim, source_inventory, projected_inventory = _retirement_inventories(
        physically_present_retired=True,
    )
    retired_ref = claim.candidate_catalog.plan_members[1].block_ref
    retained_ref = claim.candidate_catalog.plan_members[0].block_ref
    result = bind.bind_retired_dispatcher_infrastructure_claim(
        claim=claim, proposal=proposal,
        source_inventory=source_inventory,
        projected_inventory=projected_inventory,
    )

    retired = next(item for item in result.projected_bindings if item.subject.block_ref == retired_ref)
    retained = next(item for item in result.projected_bindings if item.subject.block_ref == retained_ref)
    assert retired.status is model.SubjectBindingStatus.UNIQUE
    assert retired.serial == 6
    assert retained.status is model.SubjectBindingStatus.UNIQUE
    assert retained.serial == 5
    assert projected_inventory.reachable_serials == (0, 1, 2, 3, 4, 5)


@pytest.mark.parametrize("binding_status", [
    model.SubjectBindingStatus.AMBIGUOUS,
    model.SubjectBindingStatus.STALE_GENERATION,
])
def test_retirement_phase_matrix_fails_closed_for_ambiguous_or_stale_member(
    binding_status: model.SubjectBindingStatus,
) -> None:
    """Identity drift never becomes a transaction-owned retirement claim."""

    proposal, claim, source_inventory, projected_inventory = _retirement_inventories()
    target = claim.candidate_catalog.plan_members[0].block_ref
    bindings = []
    for binding in projected_inventory.bindings:
        if binding.subject.block_ref == target:
            binding = replace(
                binding,
                block_ref=None,
                serial=None,
                anchor_ea=None,
                native_instruction_eas=(),
                status=binding_status,
            )
        bindings.append(binding)
    object.__setattr__(projected_inventory, "bindings", tuple(bindings))
    with pytest.raises(ValueError, match="inventory_digest does not match inventory content"):
        bind.bind_retired_dispatcher_infrastructure_claim(
            claim=claim,
            proposal=proposal,
            source_inventory=source_inventory,
            projected_inventory=projected_inventory,
            phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        )


def test_retirement_phase_matrix_marks_unsupported_unreachable_member_unaccounted() -> None:
    """A non-candidate plan member cannot authorize loss by complement."""

    proposal, claim, source_inventory, projected_inventory = _retirement_inventories(
        physically_present_retired=True,
    )
    catalog = claim.candidate_catalog
    candidates = catalog.candidates[:-1]
    reduced_catalog = model.RetirementCandidateCatalog(
        authority_id((
            "unflatten.dispatcher-retirement-candidate-catalog.v1",
            catalog.source_generation, catalog.plan_members, candidates,
        )),
        catalog.source_generation,
        catalog.plan_members,
        candidates,
    )
    reduced_claim = _claim_factory(
        model.RetiredDispatcherInfrastructureClaim,
        kind=model.UnflattenClaimKind.RETIRED_DISPATCHER_INFRASTRUCTURE,
        infrastructure_subject=claim.infrastructure_subject,
        corridor_subject=claim.corridor_subject,
        member_subjects=tuple(
            subject for subject in claim.member_subjects
            if subject.block_ref in reduced_catalog.candidate_refs
        ),
        candidate_evidence_ids=tuple(sorted({
            evidence_id
            for candidate in reduced_catalog.candidates
            for evidence_id in candidate.evidence_ids
        })),
        source_generation=claim.source_generation,
        candidate_catalog=reduced_catalog,
    )
    reduced_proposal = replace(
        proposal,
        plan_inputs=replace(
            proposal.plan_inputs,
            shape=model.UnflattenPlanShape.PARTIAL_REWRITE,
        ),
        claims=tuple(
            reduced_claim if item is claim else item
            for item in proposal.claims
        ),
        retirement_candidate_catalog=reduced_catalog,
    )
    binding_result = bind.bind_retired_dispatcher_infrastructure_claim(
        claim=reduced_claim,
        proposal=reduced_proposal,
        source_inventory=source_inventory,
        projected_inventory=projected_inventory,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
    )
    result = binding_result.phase_result
    assert result is not None
    member = next(
        item for item in result.members
        if item.block_ref == catalog.plan_members[-1].block_ref
    )
    assert member.classification is model.RetirementPhaseClassification.UNACCOUNTED
    assert member.reason == "unsupported_unreachable_member"


def test_retirement_binding_rejects_naked_caller_reachability_authority() -> None:
    """Reachability must come from a closed projected inventory, not a tuple."""

    base = model.ProposedUnflattenContract(**_valid_proposal(model))
    refs = {index: item.block_ref for index, item in enumerate(base.source_identity_catalog.blocks)}
    from d810.transforms.unflatten_authority.legacy_codec import retirement_claim_from_legacy_proof

    claim = retirement_claim_from_legacy_proof(
        {"retired_infrastructure": (
            {"role": "comparison_dispatcher", "anchor": {"serial": 0, "ea": 0x1000}, "retired": True},
            {"role": "comparison_dispatcher", "anchor": {"serial": 1, "ea": 0x1300}, "retired": False},
        )},
        proposal=base, block_refs_by_serial=refs,
    )
    proposal = replace(
        base,
        claims=(claim,),
        plan_inputs=replace(base.plan_inputs, shape=model.UnflattenPlanShape.PARTIAL_REWRITE),
        retirement_candidate_catalog=claim.candidate_catalog,
        corridor_coverage_forecast=_minimal_corridor_forecast(model, base),
    )
    with pytest.raises(TypeError):
        bind.bind_retired_dispatcher_infrastructure_claim(
            claim=claim,
            proposal=proposal,
            source_serial_by_ref={item.block_ref: index for index, item in enumerate(base.source_identity_catalog.blocks)},
            projected_serial_by_ref={claim.candidate_catalog.plan_members[1].block_ref: 0},
            candidate_reachable_serials=(0,),
            source_graph_fingerprint=authority_id("naked-reachability-source"),
            projected_graph_fingerprint=authority_id("naked-reachability-projector"),
            generation=base.source_identity_catalog.generation,
        )


def test_retirement_binding_rejects_direct_observed_mint_and_revalidates_parent() -> None:
    """Observed retirement must descend from one sealed projected occurrence."""

    proposal, claim, source_inventory, projected_inventory = _retirement_inventories()
    _, _, _, observed_inventory = _retirement_inventories(
        phase=model.UnflattenAuthorityPhase.OBSERVED_POST_APPLY,
    )
    with pytest.raises(ValueError, match="projected preflight"):
        bind.bind_retired_dispatcher_infrastructure_claim(
            claim=claim,
            proposal=proposal,
            source_inventory=source_inventory,
            projected_inventory=observed_inventory,
            phase=model.UnflattenAuthorityPhase.OBSERVED_POST_APPLY,
        )
    projected = bind.bind_retired_dispatcher_infrastructure_claim(
        claim=claim,
        proposal=proposal,
        source_inventory=source_inventory,
        projected_inventory=projected_inventory,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
    )
    assert projected.phase_result is not None
    observed = bind.revalidate_observed_retired_dispatcher_infrastructure(
        projected_result=projected.phase_result,
        claim=claim,
        proposal=proposal,
        source_inventory=source_inventory,
        observed_inventory=observed_inventory,
    )
    assert observed.phase is model.UnflattenAuthorityPhase.OBSERVED_POST_APPLY
    bind.validate_retirement_phase_result(observed)


def test_terminal_cycle_binding_rejects_direct_observed_mint_and_revalidates_parent() -> None:
    """Observed terminal-cycle authority must descend from prepared authority."""

    proposal, claim, _inputs, source_inventory, projected_inventory, _residual = (
        _terminal_cycle_inventory_fixture()
    )
    observed_inventory = _rewire_inventory(
        projected_inventory,
        {row.serial: row.successor_serials for row in projected_inventory.blocks},
        generation=projected_inventory.generation,
        phase=model.UnflattenAuthorityPhase.OBSERVED_POST_APPLY,
    )
    with pytest.raises(ValueError, match="projected preflight"):
        bind.bind_terminal_cycle_break_claim(
            claim=claim,
            proposal=proposal,
            source_inventory=source_inventory,
            candidate_inventory=observed_inventory,
            phase=model.UnflattenAuthorityPhase.OBSERVED_POST_APPLY,
        )
    projected = bind.bind_terminal_cycle_break_claim(
        claim=claim,
        proposal=proposal,
        source_inventory=source_inventory,
        candidate_inventory=projected_inventory,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
    )
    equal_but_distinct_parent = _clone_record(projected.phase_result)
    with pytest.raises(ValueError, match="not minted by the transaction binder"):
        bind.revalidate_observed_terminal_cycle_break(
            projected_result=equal_but_distinct_parent,
            claim=claim,
            proposal=proposal,
            source_inventory=source_inventory,
            observed_inventory=observed_inventory,
        )
    observed = bind.revalidate_observed_terminal_cycle_break(
        projected_result=projected.phase_result,
        claim=claim,
        proposal=proposal,
        source_inventory=source_inventory,
        observed_inventory=observed_inventory,
    )
    assert observed.phase is model.UnflattenAuthorityPhase.OBSERVED_POST_APPLY

@pytest.mark.parametrize("site_kind", (model.EffectSiteKind.STORE, model.TerminalKind.RETURN))
def test_inventory_binding_rejects_site_rows_outside_owned_native_origins(site_kind: object) -> None:
    _proposal, catalog = _fixture()
    owner = next(item for item in catalog.blocks if item.anchor_ea == 0x1300)
    serials = {item.block_ref: index for index, item in enumerate(catalog.blocks)}
    site_ea = 0x1304 if site_kind is model.EffectSiteKind.STORE else 0x1308
    if site_kind is model.EffectSiteKind.STORE:
        subject = _subject_factory(
            model.SemanticSubjectRef,
            kind=model.SemanticSubjectKind.EFFECT,
            role=model.SemanticSubjectRole.EFFECT_SITE,
            block_ref=owner.block_ref, anchor_ea=owner.anchor_ea,
            locator=model.EffectSubjectLocator(
                owner.block_ref, owner.anchor_ea, site_ea, site_kind,
            ),
        )
        effects = (model.InventoryEffectSite(
            serials[owner.block_ref], owner.block_ref, owner.anchor_ea,
            1, site_ea, site_kind, 0x90, 4,
        ),)
        terminals = ()
    else:
        subject = _subject_factory(
            model.SemanticSubjectRef,
            kind=model.SemanticSubjectKind.TERMINAL,
            role=model.SemanticSubjectRole.TERMINAL_SITE,
            block_ref=owner.block_ref, anchor_ea=owner.anchor_ea,
            locator=model.TerminalSubjectLocator(
                owner.block_ref, owner.anchor_ea, site_kind, site_ea,
            ),
        )
