def _task_15_direct_vertical_case(
    *, local_alias: bool = False, derive_transaction: bool = False,
    include_graph: bool = False, synthesized_stop: bool = False,
    generation: int = 1, unreachable_raw_opcode_delta: int = 0,
):
    """Build the ordinary/local DIRECT spine through the real plan compiler."""
    from d810.ir.expressions import ValueOpKind
    from d810.ir.flowgraph import BlockSnapshot, FlowGraph
    from d810.transforms.cfg_transaction import NativeBlockRef, TransactionAttemptId
    from d810.transforms.edit_simulator import project_post_state
    from d810.transforms.graph_modification import RedirectGoto, ScalarizeLocalAliasAccess
    from d810.transforms.plan import PatchPlan
    from tests.typed_patch_authority import compile_patch_plan

    evidence_tag = (
        ("task-15-direct-evidence", synthesized_stop)
        if generation == 1 else
        ("task-15-direct-evidence", synthesized_stop, generation)
    )
    plan_tag = (
        ("task-15-direct-plan", synthesized_stop)
        if generation == 1 else
        ("task-15-direct-plan", synthesized_stop, generation)
    )
    session_tag = (
        ("task-15-direct-session", synthesized_stop)
        if generation == 1 else
        ("task-15-direct-session", synthesized_stop, generation)
    )
    attempt_tag = (
        ("task-15-direct-attempt", local_alias, synthesized_stop)
        if generation == 1 else
        ("task-15-direct-attempt", local_alias, synthesized_stop, generation)
    )

    source_seed, seed_proposal, _exclusion, _seed_refs = exact_fixture()
    state = seed_proposal.route_evidence.route_proofs[0].state_write.state_variable
    state_write = source_seed.blocks[0].insn_snapshots[0]
    source_goto = source_seed.blocks[0].insn_snapshots[1]
    feeder_goto = InsnSnapshot(
        17, 0x2000, (),
        d=MopSnapshot(kind=OperandKind.BLOCK, block_ref=3),
        kind=InsnKind.GOTO, raw_opcode=17,
        control_transfer_kind=ControlTransferKind.GOTO,
        is_unconditional_jump=True,
    )
    local_alias_token = "%var_10"
    local_base_token = "%var_20"
    store = InsnSnapshot(
        23, 0x4000, (),
        display_text=f"{local_alias_token} = {local_base_token}",
        l=MopSnapshot(kind=OperandKind.NUMBER, size=4, value=11),
        d=MopSnapshot(kind=OperandKind.STACK, size=4, stkoff=8, stack_refs=(8,)),
        kind=InsnKind.STORE, raw_opcode=23, value_op_kind=ValueOpKind.STORE,
    )
    call = InsnSnapshot(
        29, 0x4001, (), display_text="callee()",
        kind=InsnKind.CALL, raw_opcode=29, is_call=True,
    )
    blocks = {
        0: BlockSnapshot(
            0, 0, (1,), (), 0, 0x1000, (state_write, source_goto),
            tail_opcode=source_goto.opcode, kind=BlockKind.ONE_WAY,
            tail_kind=InsnKind.GOTO, raw_tail_opcode=source_goto.raw_opcode,
        ),
        1: BlockSnapshot(
            1, 0, (3,), (0,), 0, 0x2000, (feeder_goto,),
            tail_opcode=feeder_goto.opcode, kind=BlockKind.ONE_WAY,
            tail_kind=InsnKind.GOTO, raw_tail_opcode=feeder_goto.raw_opcode,
        ),
        2: BlockSnapshot(
            2, source_seed.blocks[2].block_type, (), (),
            source_seed.blocks[2].flags, source_seed.blocks[2].start_ea,
            source_seed.blocks[2].insn_snapshots,
            tail_opcode=source_seed.blocks[2].tail_opcode,
            kind=BlockKind.ZERO_WAY,
            tail_kind=source_seed.blocks[2].tail_kind,
            raw_block_type=source_seed.blocks[2].raw_block_type,
            raw_tail_opcode=source_seed.blocks[2].raw_tail_opcode,
            native_start_ea=source_seed.blocks[2].native_start_ea,
        ),
        3: BlockSnapshot(
            3, 0, (), (1,), 0, 0x4000,
            ((store,) if synthesized_stop else (store, call)),
            tail_opcode=(store.opcode if synthesized_stop else call.opcode),
            kind=(BlockKind.STOP if synthesized_stop else BlockKind.ZERO_WAY),
            tail_kind=(InsnKind.STORE if synthesized_stop else InsnKind.CALL),
            raw_tail_opcode=(
                store.raw_opcode if synthesized_stop else call.raw_opcode
            ),
        ),
        4: source_seed.blocks[4],
    }
    if unreachable_raw_opcode_delta:
        unreachable = blocks[4]
        assert len(unreachable.insn_snapshots) == 1
        changed = replace(
            unreachable.insn_snapshots[0],
            raw_opcode=(
                unreachable.insn_snapshots[0].raw_opcode
                + unreachable_raw_opcode_delta
            ),
        )
        blocks[4] = replace(
            unreachable, insn_snapshots=(changed,),
            raw_tail_opcode=changed.raw_opcode,
        )
    source = FlowGraph(blocks, 0, source_seed.func_ea)
    native_key = seed_proposal.source_identity_catalog.native_key
    refs = {
        serial: NativeBlockRef(StableBlockIdentity.from_instruction_eas(
            tuple(instruction.ea for instruction in block.insn_snapshots),
            native_key=native_key,
        ))
        for serial, block in source.blocks.items()
    }
    production = route_model.build_canonical_semantic_evidence(
        (route_model.SemanticRouteFact(
            route_model.SemanticRouteFactKind.NATIVE_BOUND,
            0, 0, 0x1000, 7, 3, 0x1000, 0x4000, (0,), (),
            authority_id(("task-15-direct-native-bound", synthesized_stop)),
        ),),
        route_model.CanonicalSemanticEvidenceProductionContext(
            native_key, generation,
            authority_id(evidence_tag), state,
            tuple(source.blocks.values()),
            tuple((serial, ref.identity) for serial, ref in refs.items()),
            source.entry_serial,
        ),
    )
    assert production.abstention is None and production.evidence is not None
    witness = model.UseDefFragmentWitness(
        authority_id("task-15-direct-fragment"), state, (refs[0],),
        authority_id("task-15-direct-redirect"), True, True, 0, (),
    )
    proposal = producer_api.build_proposal(
        plan_id=authority_id(plan_tag), source=source,
        block_refs_by_serial=refs, source_generation=generation,
        canonical_route_evidence=production.evidence,
        selected_route_proof_ids=(production.evidence.route_proofs[0].proof_id,),
        exact_state_effect_exclusions=(), dispatcher_entry_serial=1,
        dispatcher_member_serials=(0, 1), authoritative_handler_serials=(3,),
        state_identity=state, use_def_witness=witness,
    )
    modifications = [RedirectGoto(0, 1, 3)]
    if local_alias:
        modifications.append(ScalarizeLocalAliasAccess(
            block_serial=3, host_ea=store.ea, host_opcode=store.opcode,
            alias_token=local_alias_token, base_token=local_base_token,
            value_size=4,
        ))
    compiled = compile_patch_plan(
        modifications, source, plan_id=proposal.plan_id,
        source_generation=generation,
        block_refs_by_serial=refs,
    )
    plan = PatchPlan(
        plan_id=compiled.plan_id, snapshot_id=compiled.snapshot_id,
        source_maturity=compiled.source_maturity,
        source_generation=compiled.source_generation, steps=compiled.steps,
        new_blocks=compiled.new_blocks, relocation_map=compiled.relocation_map,
        execution_policy=compiled.execution_policy, metadata=compiled.metadata,
        semantic_contract=compiled.semantic_contract,
        source_coordinates=tuple((refs[serial], serial) for serial in sorted(refs)),
        unflatten_proposal=proposal,
    )
    materialization = route_model.CanonicalRouteMaterialization.capture(
        source, generation=generation,
        phase=route_model.CanonicalRouteAssessmentPhase.SOURCE,
    )
    source_inventory = transaction_api._build_semantic_graph_inventory(
        source, proposal, plan, source=True,
        phase=model.UnflattenAuthorityPhase.PRODUCER_FORECAST,
        materialization=materialization,
    )
    projected = project_post_state(source, plan)
    if local_alias:
        projected_store = InsnSnapshot(
            store.opcode, store.ea, store.operands, display_text=store.display_text,
            l=store.l, d=store.d, kind=InsnKind.MOV, raw_opcode=store.raw_opcode,
            value_op_kind=ValueOpKind.MOVE,
        )
        projected_block = projected.blocks[3]
        projected = FlowGraph({
            **projected.blocks,
            3: BlockSnapshot(
                projected_block.serial, projected_block.block_type,
                projected_block.succs, projected_block.preds,
                projected_block.flags, projected_block.start_ea,
                (projected_store, call), tail_opcode=call.opcode,
                kind=projected_block.kind, tail_kind=InsnKind.CALL,
                raw_block_type=projected_block.raw_block_type,
                raw_tail_opcode=call.raw_opcode,
                native_start_ea=projected_block.native_start_ea,
            ),
        }, projected.entry_serial, projected.func_ea, metadata=projected.metadata)
    projected_inventory = transaction_api._build_semantic_graph_inventory(
        projected, proposal, plan, source=False,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        materialization=None, source_subjects=source_inventory.subjects,
    )
    derived = (
        transaction_api._derive_transaction_facts(source_inventory, plan)
        if derive_transaction else None
    )
    authority_result = bind.bind_source_route_authority(
        proposal=proposal, source_inventory=source_inventory,
        source_materialization=materialization,
    )
    assert type(authority_result) is model.SourceBoundRouteAuthorityAccepted
    lineage_facts = (
        derived.route_patch_step_facts
        if derived is not None else transaction_api._derive_patch_lineage_facts(
            source_inventory, plan,
        )
    )
    attempt = TransactionAttemptId(
        plan.plan_id,
        authority_id(session_tag), generation,
        authority_id(attempt_tag),
    )
    result = (
        authority_result.authority, plan, source_inventory,
        projected_inventory, lineage_facts, attempt,
    )
    if include_graph:
        return SimpleNamespace(
            source_authority=authority_result.authority,
            plan=plan, source_inventory=source_inventory,
            projected_inventory=projected_inventory,
            patch_step_facts=lineage_facts, attempt_id=attempt,
            source_graph=source, projected_graph=projected,
        )
    return (*result, derived) if derive_transaction else result


def _task_15_exact_direct_case(
    effect_kind: str, *, co_located_noreturn: bool = False,
    include_source_context: bool = False,
):
    """Build one proposal-owned exact CALL/STORE loss on a DIRECT route."""
    from d810.transforms.cfg_transaction import TransactionAttemptId
    from d810.transforms.edit_simulator import project_post_state
    from d810.transforms.graph_modification import RedirectGoto
    from d810.transforms.plan import PatchPlan
    from tests.typed_patch_authority import compile_patch_plan

    source, proposal, _exclusion, refs = exact_fixture(
        discarded_effect_kind=effect_kind,
        shared_terminal=not co_located_noreturn,
    )
    route_claims = tuple(
        claim for claim in proposal.claims
        if type(claim) is model.EquivalentSemanticRouteClaim
    )
    assert len(route_claims) == 1
    compiled = compile_patch_plan(
        [RedirectGoto(0, 1, 2)], source, plan_id=proposal.plan_id,
        source_generation=1, block_refs_by_serial=refs,
    )
    plan = PatchPlan(
        plan_id=compiled.plan_id, snapshot_id=compiled.snapshot_id,
        source_maturity=compiled.source_maturity,
        source_generation=compiled.source_generation, steps=compiled.steps,
        new_blocks=compiled.new_blocks, relocation_map=compiled.relocation_map,
        execution_policy=compiled.execution_policy, metadata=compiled.metadata,
        semantic_contract=compiled.semantic_contract,
        source_coordinates=tuple((refs[serial], serial) for serial in sorted(refs)),
        unflatten_proposal=proposal,
    )
    materialization = route_model.CanonicalRouteMaterialization.capture(
        source, generation=1,
        phase=route_model.CanonicalRouteAssessmentPhase.SOURCE,
    )
    source_inventory = transaction_api._build_semantic_graph_inventory(
        source, proposal, plan, source=True,
        phase=model.UnflattenAuthorityPhase.PRODUCER_FORECAST,
        materialization=materialization,
    )
    authority_result = bind.bind_source_route_authority(
        proposal=proposal, source_inventory=source_inventory,
        source_materialization=materialization,
    )
    assert type(authority_result) is model.SourceBoundRouteAuthorityAccepted
    projected = project_post_state(source, plan)
    projected_inventory = transaction_api._build_semantic_graph_inventory(
        projected, proposal, plan, source=False,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        materialization=None, source_subjects=source_inventory.subjects,
    )
    lineage_facts = transaction_api._derive_patch_lineage_facts(
        source_inventory, plan,
    )
    attempt = TransactionAttemptId(
        plan.plan_id, authority_id("task-15-exact-session"), 1,
        authority_id(("task-15-exact-attempt", effect_kind)),
    )
    result = (
        authority_result.authority, plan, source_inventory,
        projected_inventory, lineage_facts, attempt,
    )
    return (
        (*result, source, materialization, refs, _exclusion)
        if include_source_context else result
    )


def _task_15_lowered_conditional_vertical_case(
    *, unrelated_same_owner_site: bool = False,
    remove_projected_noreturn_terminal: bool = False,
    include_exact_claims: bool = True, include_graph: bool = False,
    synthesized_stop: bool = False, separate_terminal: bool = False,
):
    """Build RF-1 from one final graph, one producer, and one real compiler edit."""
    from d810.analyses.control_flow.effect_branch_exclusion import (
        build_exact_state_branch_effect_exclusion,
    )
    from d810.ir.expressions import ValueOpKind
    from d810.ir.flowgraph import BlockSnapshot, FlowGraph
    from d810.transforms.cfg_transaction import TransactionAttemptId
    from d810.transforms.edit_simulator import project_post_state
    from d810.transforms.graph_modification import (
        LowerConditionalStateTransition,
        SyntheticStackValueEqualsCondition,
    )
    from d810.transforms.plan import PatchLowerConditionalStateTransition, PatchPlan
    from tests.typed_patch_authority import compile_patch_plan

    source_seed, seed_evidence, seed_witness, seed_refs = exact_fixture(
        discarded_effect_kind="call_store", producer_inputs_only=True,
    )
    native_key = seed_refs[0].identity.native_key
    blocks = dict(source_seed.blocks)
    selected_nop = blocks[2].insn_snapshots[0]
    selected_target = 4 if unrelated_same_owner_site else 2
    selected_goto = InsnSnapshot(
        0, 0x3001, (),
        l=MopSnapshot(kind=OperandKind.BLOCK, block_ref=selected_target),
        kind=InsnKind.GOTO, raw_opcode=0,
        control_transfer_kind=ControlTransferKind.GOTO,
        is_unconditional_jump=True,
    )
    blocks[2] = BlockSnapshot(
        2, blocks[2].block_type, (selected_target,),
        (1, 2) if selected_target == 2 else (1,), blocks[2].flags,
        blocks[2].start_ea, (selected_nop, selected_goto),
        tail_opcode=selected_goto.opcode, kind=BlockKind.ONE_WAY,
        tail_kind=InsnKind.GOTO, raw_block_type=blocks[2].raw_block_type,
        raw_tail_opcode=selected_goto.raw_opcode,
        native_start_ea=blocks[2].native_start_ea,
    )

    seed_call, seed_store = blocks[3].insn_snapshots
    discarded_store = replace(seed_store, ea=0x4000)
    discarded_call = replace(seed_call, ea=0x4001)
    discarded_ret = InsnSnapshot(
        0, 0x4002, (), kind=InsnKind.RET, raw_opcode=0,
    )
    blocks[3] = BlockSnapshot(
        3, blocks[3].block_type, (), (1,), blocks[3].flags,
        blocks[3].start_ea,
        ((discarded_store,) if synthesized_stop else (
            (discarded_store, discarded_call, discarded_ret)
            if separate_terminal else (discarded_store, discarded_call)
        )),
        tail_opcode=(
            discarded_store.opcode if synthesized_stop else (
                discarded_ret.opcode if separate_terminal else discarded_call.opcode
            )
        ),
        kind=(BlockKind.STOP if synthesized_stop else BlockKind.ZERO_WAY),
        tail_kind=(
            InsnKind.STORE if synthesized_stop else (
                InsnKind.RET if separate_terminal else InsnKind.CALL
            )
        ), raw_block_type=blocks[3].raw_block_type,
        raw_tail_opcode=(
            discarded_store.raw_opcode
            if synthesized_stop else (
                discarded_ret.raw_opcode
                if separate_terminal else discarded_call.raw_opcode
            )
        ),
        native_start_ea=blocks[3].native_start_ea,
    )

    if unrelated_same_owner_site:
        unrelated_store = InsnSnapshot(
            31, 0x5000, (), display_text="unrelated = value",
            l=MopSnapshot(kind=OperandKind.NUMBER, size=4, value=13),
            d=MopSnapshot(kind=OperandKind.STACK, size=4, stkoff=12),
            kind=InsnKind.STORE, raw_opcode=31,
            value_op_kind=ValueOpKind.STORE,
        )
        unrelated_goto = InsnSnapshot(
            0, 0x5001, (),
            l=MopSnapshot(kind=OperandKind.BLOCK, block_ref=4),
            kind=InsnKind.GOTO, raw_opcode=0,
            control_transfer_kind=ControlTransferKind.GOTO,
            is_unconditional_jump=True,
        )
        blocks[4] = BlockSnapshot(
            4, blocks[4].block_type, (4,), (2, 4), blocks[4].flags,
            blocks[4].start_ea, (unrelated_store, unrelated_goto),
            tail_opcode=unrelated_goto.opcode, kind=BlockKind.ONE_WAY,
            tail_kind=InsnKind.GOTO, raw_block_type=blocks[4].raw_block_type,
            raw_tail_opcode=unrelated_goto.raw_opcode,
            native_start_ea=blocks[4].native_start_ea,
        )
    else:
        blocks[4] = replace(blocks[4], preds=())

    source = FlowGraph(blocks, source_seed.entry_serial, source_seed.func_ea)
    refs = {
        serial: NativeBlockRef(StableBlockIdentity.from_instruction_eas(
            tuple(instruction.ea for instruction in block.insn_snapshots),
            native_key=native_key,
        ))
        for serial, block in source.blocks.items()
    }
    seed_proof = seed_evidence.route_proofs[0]
    destinations = tuple(
        replace(destination, target_identity=refs[2].identity)
        if destination.role is SemanticEdgeRole.CONDITIONAL_TAKEN
        else replace(destination, target_identity=refs[3].identity)
        for destination in seed_proof.destinations
    )
    evidence = canonical_semantic_evidence_from_proofs(
        native_key=native_key,
        generation=1,
        proofs=(replace(seed_proof, destinations=destinations),),
    )
    proof = evidence.route_proofs[0]
    state = proof.state_write.state_variable
    exclusions = (
        tuple(
            build_exact_state_branch_effect_exclusion(
                source, source, normalized_state=7, source_serial=0,
                predicate_serial=1, selected_target_serial=2,
                discarded_effect_serial=3, state_identity=state,
                discarded_effect_ea=effect_ea,
            )
            for effect_ea in (
                (0x4000,) if synthesized_stop else (0x4000, 0x4001)
            )
        )
        if include_exact_claims else ()
    )
    assert all(exclusion is not None for exclusion in exclusions)
    proposal = producer_api.build_proposal(
        plan_id=authority_id((
            "task-15-rf1-lowered-plan", synthesized_stop, separate_terminal,
        )),
        source=source,
        block_refs_by_serial=refs, source_generation=1,
        canonical_route_evidence=evidence,
        selected_route_proof_ids=(proof.proof_id,),
        exact_state_effect_exclusions=exclusions,
        dispatcher_entry_serial=1, dispatcher_member_serials=(0, 1),
        authoritative_handler_serials=(2,), state_identity=state,
        use_def_witness=seed_witness,
    )
    compiled = compile_patch_plan(
        [LowerConditionalStateTransition(
            source_serial=0, old_dispatcher_serial=1,
            rewrite_from_ea=0x1001,
            condition_operand=SyntheticStackValueEqualsCondition(4, 4, 7),
            false_target_serial=3, true_target_serial=2,
            proof_id=proof.proof_id,
        )],
        source, plan_id=proposal.plan_id, source_generation=1,
        block_refs_by_serial=refs,
    )
    assert len(compiled.steps) == 1
    assert type(compiled.steps[0]) is PatchLowerConditionalStateTransition
    plan = PatchPlan(
        plan_id=compiled.plan_id, snapshot_id=compiled.snapshot_id,
        source_maturity=compiled.source_maturity,
        source_generation=compiled.source_generation, steps=compiled.steps,
        new_blocks=compiled.new_blocks, relocation_map=compiled.relocation_map,
        execution_policy=compiled.execution_policy, metadata=compiled.metadata,
        semantic_contract=compiled.semantic_contract,
        source_coordinates=tuple(
            (refs[serial], serial) for serial in sorted(refs)
        ),
        unflatten_proposal=proposal,
    )
    materialization = route_model.CanonicalRouteMaterialization.capture(
        source, generation=1,
        phase=route_model.CanonicalRouteAssessmentPhase.SOURCE,
    )
    source_inventory = transaction_api._build_semantic_graph_inventory(
        source, proposal, plan, source=True,
        phase=model.UnflattenAuthorityPhase.PRODUCER_FORECAST,
        materialization=materialization,
    )
    authority_result = bind.bind_source_route_authority(
        proposal=proposal, source_inventory=source_inventory,
        source_materialization=materialization,
    )
    assert type(authority_result) is model.SourceBoundRouteAuthorityAccepted
    projected = project_post_state(source, plan)
    if remove_projected_noreturn_terminal:
        discarded = projected.blocks[3]
        call = discarded.insn_snapshots[-1]
        inert_tail = InsnSnapshot(
            0, call.ea, (), kind=InsnKind.NOP, raw_opcode=0,
        )
        projected = FlowGraph(
            {
                **projected.blocks,
                3: replace(
                    discarded,
                    insn_snapshots=(*discarded.insn_snapshots, inert_tail),
                    kind=BlockKind.UNKNOWN, tail_kind=InsnKind.NOP,
                    tail_opcode=inert_tail.opcode,
                    raw_tail_opcode=inert_tail.raw_opcode,
                ),
            },
            projected.entry_serial, projected.func_ea,
            metadata=projected.metadata,
        )
    projected_inventory = transaction_api._build_semantic_graph_inventory(
        projected, proposal, plan, source=False,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        materialization=None, source_subjects=source_inventory.subjects,
    )
    facts = transaction_api._derive_patch_lineage_facts(source_inventory, plan)
    attempt = TransactionAttemptId(
        plan.plan_id, authority_id("task-15-rf1-lowered-session"), 1,
        authority_id((
            "task-15-rf1-lowered-attempt", unrelated_same_owner_site,
            remove_projected_noreturn_terminal, include_exact_claims,
            synthesized_stop, separate_terminal,
        )),
    )
    result = (
        authority_result.authority, plan, source_inventory,
        projected_inventory, facts, attempt,
    )
    if include_graph:
        return SimpleNamespace(
            source_graph=source, projected_graph=projected,
            proposal=proposal, source_authority=authority_result.authority,
            plan=plan, source_inventory=source_inventory,
            projected_inventory=projected_inventory,
            patch_step_facts=facts, attempt_id=attempt,
        )
    return result


def _task_15_cloned_conditional_vertical_case(*, synthesized_stop: bool = False):
    """Build RF-2 from one final graph, one producer, and one real clone edit."""
    from d810.ir.expressions import ValueOpKind
    from d810.ir.flowgraph import BlockSnapshot, FlowGraph
    from d810.transforms.cfg_transaction import TransactionAttemptId
    from d810.transforms.edit_simulator import project_post_state
    from d810.transforms.graph_modification import CreateConditionalRedirect
    from d810.transforms.plan import PatchConditionalRedirect, PatchPlan
    from tests.typed_patch_authority import compile_patch_plan

    source_seed, seed_evidence, seed_witness, seed_refs = exact_fixture(
        producer_inputs_only=True,
    )
    native_key = seed_refs[0].identity.native_key
    blocks = dict(source_seed.blocks)
    state_write, feeder_goto = blocks[0].insn_snapshots
    feeder_store = InsnSnapshot(
        40, 0x1001, (), display_text="feeder = value",
        l=MopSnapshot(kind=OperandKind.NUMBER, size=4, value=11),
        d=MopSnapshot(kind=OperandKind.STACK, size=4, stkoff=12),
        kind=InsnKind.STORE, raw_opcode=140,
        value_op_kind=ValueOpKind.STORE,
    )
    feeder_goto = replace(feeder_goto, ea=0x1002)
    blocks[0] = BlockSnapshot(
        0, blocks[0].block_type, blocks[0].succs, blocks[0].preds,
        blocks[0].flags, blocks[0].start_ea,
        (state_write, feeder_store, feeder_goto),
        tail_opcode=feeder_goto.opcode, kind=BlockKind.ONE_WAY,
        tail_kind=InsnKind.GOTO, raw_block_type=blocks[0].raw_block_type,
        raw_tail_opcode=feeder_goto.raw_opcode,
        native_start_ea=blocks[0].native_start_ea,
    )
    predicate_tail = blocks[1].insn_snapshots[-1]
    prefix_store = InsnSnapshot(
        41, 0x2000, (), display_text="prefix = value",
        l=MopSnapshot(kind=OperandKind.NUMBER, size=4, value=13),
        d=MopSnapshot(kind=OperandKind.STACK, size=4, stkoff=12),
        kind=InsnKind.STORE, raw_opcode=141,
        value_op_kind=ValueOpKind.STORE,
    )
    prefix_call = InsnSnapshot(
        42, 0x2001, (), display_text="ordinary_prefix_call()",
        kind=InsnKind.CALL, raw_opcode=142, is_call=True,
    )
    predicate_tail = replace(predicate_tail, ea=0x2002)
    blocks[1] = BlockSnapshot(
        1, blocks[1].block_type, blocks[1].succs, blocks[1].preds,
        blocks[1].flags, blocks[1].start_ea,
        (prefix_store, prefix_call, predicate_tail),
        tail_opcode=predicate_tail.opcode, kind=BlockKind.TWO_WAY,
        tail_kind=InsnKind.COND_JUMP,
        raw_block_type=blocks[1].raw_block_type,
        raw_tail_opcode=predicate_tail.raw_opcode,
        native_start_ea=blocks[1].native_start_ea,
    )
    selected_store = InsnSnapshot(
        44, 0x3000, (), display_text="selected = value",
        l=MopSnapshot(kind=OperandKind.NUMBER, size=4, value=17),
        d=MopSnapshot(kind=OperandKind.STACK, size=4, stkoff=16),
        kind=InsnKind.STORE, raw_opcode=144,
        value_op_kind=ValueOpKind.STORE,
    )
    blocks[2] = BlockSnapshot(
        2, blocks[2].block_type, blocks[2].succs, blocks[2].preds,
        blocks[2].flags, blocks[2].start_ea, (selected_store,),
        tail_opcode=selected_store.opcode,
        kind=(BlockKind.STOP if synthesized_stop else BlockKind.ZERO_WAY),
        tail_kind=InsnKind.STORE, raw_block_type=blocks[2].raw_block_type,
        raw_tail_opcode=selected_store.raw_opcode,
        native_start_ea=blocks[2].native_start_ea,
    )
    source = FlowGraph(blocks, source_seed.entry_serial, source_seed.func_ea)
    refs = {
        serial: NativeBlockRef(StableBlockIdentity.from_instruction_eas(
            tuple(instruction.ea for instruction in block.insn_snapshots),
            native_key=native_key,
        ))
        for serial, block in source.blocks.items()
    }
    seed_proof = seed_evidence.route_proofs[0]
    predicate_point = route_model.SemanticCorridorPoint(
        refs[1].identity, predicate_tail.ea,
    )
    source_point = route_model.SemanticCorridorPoint(
        refs[0].identity, seed_proof.state_write.instruction_ea,
    )
    proof = replace(
        seed_proof,
        source_identity=refs[1].identity,
        source_anchor_ea=blocks[1].start_ea,
        destinations=tuple(
            replace(
                destination,
                target_identity=refs[
                    2 if destination.role is SemanticEdgeRole.CONDITIONAL_TAKEN
                    else 3
                ].identity,
            )
            for destination in seed_proof.destinations
        ),
        source_owner_identity=refs[0].identity,
        state_write=replace(
            seed_proof.state_write, identity=refs[0].identity,
        ),
        predicate=replace(
            seed_proof.predicate,
            origin=predicate_point,
            consumer=predicate_point,
            corridor=(predicate_point,),
        ),
        carriers=tuple(
            replace(
                carrier,
                definition=source_point,
                consumers=(predicate_point,),
                corridor=(source_point, predicate_point),
            )
            for carrier in seed_proof.carriers
        ),
    )
    evidence = canonical_semantic_evidence_from_proofs(
        native_key=native_key, generation=1, proofs=(proof,),
    )
    proof = evidence.route_proofs[0]
    state = proof.state_write.state_variable
    proposal = producer_api.build_proposal(
        plan_id=authority_id((
            "task-15-rf2-cloned-conditional-plan", synthesized_stop,
        )),
        source=source, block_refs_by_serial=refs, source_generation=1,
        canonical_route_evidence=evidence,
        selected_route_proof_ids=(proof.proof_id,),
        exact_state_effect_exclusions=(), dispatcher_entry_serial=1,
        dispatcher_member_serials=(0, 1),
        authoritative_handler_serials=(2,), state_identity=state,
        use_def_witness=replace(
            seed_witness, redirect_owner_refs=(refs[0],),
        ),
    )
    compiled = compile_patch_plan(
        [CreateConditionalRedirect(
            source_block=0, ref_block=1, conditional_target=2,
            fallthrough_target=3,
        )],
        source, plan_id=proposal.plan_id, source_generation=1,
        block_refs_by_serial=refs,
    )
    assert len(compiled.steps) == 1
    assert type(compiled.steps[0]) is PatchConditionalRedirect
    plan = PatchPlan(
        plan_id=compiled.plan_id, snapshot_id=compiled.snapshot_id,
        source_maturity=compiled.source_maturity,
        source_generation=compiled.source_generation, steps=compiled.steps,
        new_blocks=compiled.new_blocks, relocation_map=compiled.relocation_map,
        execution_policy=compiled.execution_policy, metadata=compiled.metadata,
        semantic_contract=compiled.semantic_contract,
        source_coordinates=tuple(
            (refs[serial], serial) for serial in sorted(refs)
        ),
        unflatten_proposal=proposal,
    )
    materialization = route_model.CanonicalRouteMaterialization.capture(
        source, generation=1,
        phase=route_model.CanonicalRouteAssessmentPhase.SOURCE,
    )
    source_inventory = transaction_api._build_semantic_graph_inventory(
        source, proposal, plan, source=True,
        phase=model.UnflattenAuthorityPhase.PRODUCER_FORECAST,
        materialization=materialization,
    )
    authority_result = bind.bind_source_route_authority(
        proposal=proposal, source_inventory=source_inventory,
        source_materialization=materialization,
    )
    assert type(authority_result) is model.SourceBoundRouteAuthorityAccepted
    clean_projected_graph = project_post_state(source, plan)
    projected_graph = clean_projected_graph
    step = plan.steps[0]
    helper_serial = next(
        projected_serial
        for projected_ref, projected_serial in transaction_api._projected_serials(
            clean_projected_graph, proposal,
            blocks=clean_projected_graph.blocks, plan=plan,
        ).items()
        if projected_ref == step.fallthrough_block_id
    )
    projected_inventory = transaction_api._build_semantic_graph_inventory(
        projected_graph, proposal, plan, source=False,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        materialization=None, source_subjects=source_inventory.subjects,
    )
    facts = transaction_api._derive_patch_lineage_facts(source_inventory, plan)
    attempt = TransactionAttemptId(
        plan.plan_id,
        authority_id((
            "task-15-rf2-cloned-conditional-session", synthesized_stop,
        )), 1,
        authority_id((
            "task-15-rf2-cloned-conditional-attempt", synthesized_stop,
        )),
    )
    return SimpleNamespace(
        source_graph=source, projected_graph=projected_graph,
        clean_projected_graph=clean_projected_graph, proposal=proposal,
        source_authority=authority_result.authority, plan=plan,
        source_inventory=source_inventory,
        projected_inventory=projected_inventory,
        patch_step_facts=facts, attempt_id=attempt, refs=refs,
        helper_serial=helper_serial,
    )


def _task_15_cloned_conditional_helper_injection_case(case):
    """Rebuild RF-2 PROJECTED after adding one real helper CALL."""
    from d810.ir.flowgraph import FlowGraph
    from d810.transforms.cfg_transaction import TransactionAttemptId

    helper = case.clean_projected_graph.blocks[case.helper_serial]
    goto = helper.insn_snapshots[0]
    injected_call = InsnSnapshot(
        43, goto.ea - 1, (), display_text="helper_injected_call()",
        kind=InsnKind.CALL, raw_opcode=143, is_call=True,
    )
    mutated_graph = FlowGraph(
        {
            **case.clean_projected_graph.blocks,
            case.helper_serial: replace(
                helper, insn_snapshots=(injected_call, goto),
                tail_opcode=goto.opcode, tail_kind=goto.kind,
                raw_tail_opcode=goto.raw_opcode,
            ),
        },
        case.clean_projected_graph.entry_serial,
        case.clean_projected_graph.func_ea,
        metadata=case.clean_projected_graph.metadata,
    )
    mutated_inventory = transaction_api._build_semantic_graph_inventory(
        mutated_graph, case.proposal, case.plan, source=False,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        materialization=None,
        source_subjects=case.source_inventory.subjects,
    )
    injected_effect = next(
        row for row in mutated_inventory.effects
        if row.owner_serial == case.helper_serial
        and row.instruction_ea == injected_call.ea
        and row.effect_kind is model.EffectSiteKind.CALL
    )
    assert (
        mutated_inventory.graph_fingerprint
        != case.projected_inventory.graph_fingerprint
    )
    attempt = TransactionAttemptId(
        case.plan.plan_id,
        authority_id("task-15-rf2-cloned-conditional-negative-session"), 1,
        authority_id("task-15-rf2-cloned-conditional-negative-attempt"),
    )
    return SimpleNamespace(
        source_graph=case.source_graph, projected_graph=mutated_graph,
        clean_projected_graph=case.clean_projected_graph,
        proposal=case.proposal, source_authority=case.source_authority,
        plan=case.plan, source_inventory=case.source_inventory,
        projected_inventory=mutated_inventory,
        patch_step_facts=case.patch_step_facts, attempt_id=attempt,
        refs=case.refs, helper_serial=case.helper_serial,
        injected=injected_call, injected_effect=injected_effect,
    )


def _task_15_cloned_conditional_nonsemantic_helper_prefix_case(
    case, injected,
):
    """Rebuild RF-2 PROJECTED after one nonsemantic helper prefix."""
    from d810.ir.flowgraph import FlowGraph

    helper = case.clean_projected_graph.blocks[case.helper_serial]
    assert len(helper.insn_snapshots) == 1
    goto = helper.insn_snapshots[0]
    assert goto.kind is InsnKind.GOTO
    mutated_graph = FlowGraph(
        {
            **case.clean_projected_graph.blocks,
            case.helper_serial: replace(
                helper, insn_snapshots=(injected, goto),
                tail_opcode=goto.opcode, tail_kind=goto.kind,
                raw_tail_opcode=goto.raw_opcode,
            ),
        },
        case.clean_projected_graph.entry_serial,
        case.clean_projected_graph.func_ea,
        metadata=case.clean_projected_graph.metadata,
    )
    mutated_inventory = transaction_api._build_semantic_graph_inventory(
        mutated_graph, case.proposal, case.plan, source=False,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        materialization=None,
        source_subjects=case.source_inventory.subjects,
    )
    helper_row = next(
        row for row in mutated_inventory.blocks
        if row.serial == case.helper_serial
    )
    injected_observations = tuple(
        observation for observation in helper_row.instruction_observations
        if observation.instruction_ea == injected.ea
        and observation.instruction_kind is injected.kind
    )
    assert len(injected_observations) == 1
    assert not tuple(
        row for row in (
            *mutated_inventory.effects, *mutated_inventory.terminals,
        )
        if row.owner_serial == case.helper_serial
        and row.instruction_ea == injected.ea
    )
    assert (
        mutated_inventory.graph_fingerprint
        != case.projected_inventory.graph_fingerprint
    )
    return SimpleNamespace(
        source_graph=case.source_graph, projected_graph=mutated_graph,
        clean_projected_graph=case.clean_projected_graph,
        proposal=case.proposal, source_authority=case.source_authority,
        plan=case.plan, source_inventory=case.source_inventory,
        projected_inventory=mutated_inventory,
        patch_step_facts=case.patch_step_facts, attempt_id=case.attempt_id,
        refs=case.refs, helper_serial=case.helper_serial,
        injected=injected, injected_observation=injected_observations[0],
    )


