def _task_15_raw_opcode_graph_case(
    case, clean_projected_graph, target, *, source_owner_ref,
):
    """Rebuild one complete PROJECTED envelope after one raw-opcode drift."""
    from d810.ir.flowgraph import FlowGraph

    block = clean_projected_graph.blocks[target.owner_serial]
    assert target.instruction_ordinal < len(block.insn_snapshots)
    original = block.insn_snapshots[target.instruction_ordinal]
    assert original.ea == target.instruction_ea
    assert original.opcode == target.opcode
    assert original.raw_opcode is not None
    changed = replace(original, raw_opcode=original.raw_opcode + 0x1000)
    mutated_graph = FlowGraph(
        {
            **clean_projected_graph.blocks,
            target.owner_serial: replace(
                block,
                insn_snapshots=tuple(
                    changed if index == target.instruction_ordinal else item
                    for index, item in enumerate(block.insn_snapshots)
                ),
                raw_tail_opcode=(
                    changed.raw_opcode
                    if target.instruction_ordinal == len(block.insn_snapshots) - 1
                    else block.raw_tail_opcode
                ),
            ),
        },
        clean_projected_graph.entry_serial,
        clean_projected_graph.func_ea,
        metadata=clean_projected_graph.metadata,
    )
    proposal = case.plan.unflatten_proposal
    assert proposal is not None
    mutated_inventory = transaction_api._build_semantic_graph_inventory(
        mutated_graph, proposal, case.plan, source=False,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        materialization=None,
        source_subjects=case.source_inventory.subjects,
    )
    changed_effects = tuple(
        row for row in mutated_inventory.effects
        if row.owner_ref == target.owner_ref
        and row.owner_serial == target.owner_serial
        and row.owner_anchor_ea == target.owner_anchor_ea
        and row.instruction_ordinal == target.instruction_ordinal
        and row.instruction_ea == target.instruction_ea
        and row.effect_kind is target.effect_kind
        and row.opcode == target.opcode
        and row.width == target.width
    )
    assert len(changed_effects) == 1
    assert not hasattr(changed_effects[0], "raw_opcode")
    assert (
        mutated_inventory.graph_fingerprint
        != case.projected_inventory.graph_fingerprint
    )
    return SimpleNamespace(
        source_graph=case.source_graph,
        clean_projected_graph=clean_projected_graph,
        projected_graph=mutated_graph,
        proposal=proposal, source_authority=case.source_authority,
        plan=case.plan, source_inventory=case.source_inventory,
        projected_inventory=mutated_inventory,
        patch_step_facts=case.patch_step_facts,
        attempt_id=case.attempt_id,
        original_instruction=original, changed_instruction=changed,
        source_effect=next(
            row for row in case.source_inventory.effects
            if row.owner_ref == source_owner_ref
            and row.instruction_ea == target.instruction_ea
            and row.effect_kind is target.effect_kind
        ),
        projected_effect=changed_effects[0],
    )


