def _task_15_cloned_conditional_unoriginated_suffix_case(case):
    """Rebuild RF-2 after one clone-only CALL before the conditional tail."""
    from d810.ir.flowgraph import FlowGraph

    step = case.plan.steps[0]
    clone_ref = step.block_id
    clone_serial = case.projected_inventory.serial_by_ref[clone_ref]
    clone = case.clean_projected_graph.blocks[clone_serial]
    assert len(clone.insn_snapshots) == 3
    prefix_store, prefix_call, conditional_tail = clone.insn_snapshots
    injected = InsnSnapshot(
        145, conditional_tail.ea + 0x80, (),
        display_text="rf2_unoriginated_clone_suffix()",
        kind=InsnKind.CALL, raw_opcode=145, is_call=True,
    )
    mutated_graph = FlowGraph(
        {
            **case.clean_projected_graph.blocks,
            clone_serial: replace(
                clone,
                insn_snapshots=(
                    prefix_store, prefix_call, injected, conditional_tail,
                ),
                tail_opcode=conditional_tail.opcode,
                tail_kind=conditional_tail.kind,
                raw_tail_opcode=conditional_tail.raw_opcode,
            ),
        },
        case.clean_projected_graph.entry_serial,
        case.clean_projected_graph.func_ea,
        metadata=case.clean_projected_graph.metadata,
    )
    mutated_inventory = transaction_api._build_semantic_graph_inventory(
        mutated_graph, case.proposal, case.plan, source=False,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        materialization=None, source_subjects=case.source_inventory.subjects,
    )
    injected_effects = tuple(
        row for row in mutated_inventory.effects
        if row.owner_ref == clone_ref
        and row.instruction_ea == injected.ea
        and row.effect_kind is model.EffectSiteKind.CALL
    )
    assert len(injected_effects) == 1
    assert (
        mutated_inventory.graph_fingerprint
        != case.projected_inventory.graph_fingerprint
    )
    return SimpleNamespace(
        source_graph=case.source_graph, projected_graph=mutated_graph,
        clean_projected_graph=case.clean_projected_graph,
        proposal=case.proposal, source_authority=case.source_authority,
        plan=case.plan, source_inventory=case.source_inventory,
        projected_inventory=mutated_inventory,
        patch_step_facts=case.patch_step_facts, attempt_id=case.attempt_id,
        refs=case.refs, helper_serial=case.helper_serial,
        clone_ref=clone_ref, clone_serial=clone_serial,
        injected=injected, injected_effect=injected_effects[0],
    )


def _task_15_two_arm_vertical_case(
    *, helper: bool = False, synthesized_stop: bool = False,
):
    """Build RF-3/RF-4 from one real state-store DAG and branch redirect."""
    from d810.ir.expressions import ValueOpKind
    from d810.ir.flowgraph import BlockSnapshot, FlowGraph
    from d810.transforms.cfg_transaction import TransactionAttemptId
    from d810.transforms.edit_simulator import project_post_state
    from d810.transforms.graph_modification import RedirectBranch
    from d810.transforms.plan import PatchPlan, PatchRedirectBranch
    from tests.typed_patch_authority import compile_patch_plan

    source_seed, _seed_evidence, seed_witness, seed_refs = exact_fixture(
        producer_inputs_only=True,
    )
    native_key = seed_refs[0].identity.native_key
    blocks = dict(source_seed.blocks)
    state = _seed_evidence.route_proofs[0].state_write.state_variable
    state_number = MopSnapshot(kind=OperandKind.NUMBER, size=4, value=7)
    state_stack = MopSnapshot(
        kind=OperandKind.STACK, size=4, stkoff=4, stack_refs=(4,),
    )
    feeder_store = InsnSnapshot(
        51, 0x2000, (), display_text="state = 7",
        l=state_number, d=state_stack, kind=InsnKind.STORE,
        raw_opcode=151, value_op_kind=ValueOpKind.STORE,
    )
    feeder_branch = blocks[1].insn_snapshots[-1]
    if helper:
        feeder_branch = replace(
            feeder_branch,
            d=MopSnapshot(kind=OperandKind.BLOCK, block_ref=3),
        )
    blocks[1] = BlockSnapshot(
        1, blocks[1].block_type, ((2, 3) if helper else (3, 2)),
        blocks[1].preds,
        blocks[1].flags, blocks[1].start_ea,
        (feeder_store, feeder_branch),
        tail_opcode=feeder_branch.opcode, kind=BlockKind.TWO_WAY,
        tail_kind=InsnKind.COND_JUMP,
        raw_block_type=blocks[1].raw_block_type,
        raw_tail_opcode=feeder_branch.raw_opcode,
        native_start_ea=blocks[1].native_start_ea,
    )
    blocks[2] = _one_way_goto(blocks[2], 4, preds=(1,))
    blocks[3] = replace(blocks[3], preds=(1,))
    replacement_store = InsnSnapshot(
        52, 0x5000, (), display_text="replacement = value",
        l=MopSnapshot(kind=OperandKind.NUMBER, size=4, value=19),
        d=MopSnapshot(kind=OperandKind.STACK, size=4, stkoff=16),
        kind=InsnKind.STORE, raw_opcode=152,
        value_op_kind=ValueOpKind.STORE,
    )
    blocks[4] = BlockSnapshot(
        4, blocks[4].block_type, (), (2,), blocks[4].flags,
        blocks[4].start_ea, (replacement_store,),
        tail_opcode=replacement_store.opcode,
        kind=(BlockKind.STOP if synthesized_stop else BlockKind.ZERO_WAY),
        tail_kind=InsnKind.STORE,
        raw_block_type=blocks[4].raw_block_type,
        raw_tail_opcode=replacement_store.raw_opcode,
        native_start_ea=blocks[4].native_start_ea,
    )
    source = FlowGraph(blocks, source_seed.entry_serial, source_seed.func_ea)
    refs = {
        serial: NativeBlockRef(StableBlockIdentity.from_instruction_eas(
            tuple(instruction.ea for instruction in block.insn_snapshots),
            native_key=native_key,
        ))
        for serial, block in source.blocks.items()
    }
    dag = route_model.DecisionDagRouteWitness(
        state, 7, 2, blocks[2].start_ea, (2,),
        (blocks[2].start_ea,), (), ((2, 4),),
    )
    fact = route_model.SemanticRouteFact(
        route_model.SemanticRouteFactKind.DECISION_DAG,
        1, 1, feeder_store.ea, 7, 4,
        blocks[1].start_ea, blocks[4].start_ea, (1,), (),
        authority_id(
            "task-15-rf4-branch-helper-dag-fact"
            if helper else "task-15-rf3-two-arm-dag-fact"
        ),
        decision_dag_witness=dag,
    )
    context = route_model.CanonicalSemanticEvidenceProductionContext(
        native_key, 1, authority_id(
            "task-15-rf4-branch-helper-group"
            if helper else "task-15-rf3-two-arm-group"
        ), state,
        tuple(source.blocks.values()),
        tuple((serial, ref.identity) for serial, ref in refs.items()),
        source.entry_serial,
    )
    produced = route_model.build_canonical_semantic_evidence((fact,), context)
    assert produced.abstention is None and produced.evidence is not None
    evidence = produced.evidence
    proof = evidence.route_proofs[0]
    assert proof.proof_kind is route_model.SemanticRouteProofKind.STATE_DAG
    assert proof.shape is route_model.SemanticRouteShape.DIRECT
    proposal = producer_api.build_proposal(
        plan_id=authority_id((
            (
                "task-15-rf4-branch-helper-plan"
                if helper else "task-15-rf3-two-arm-plan"
            ),
            synthesized_stop,
        )), source=source,
        block_refs_by_serial=refs, source_generation=1,
        canonical_route_evidence=evidence,
        selected_route_proof_ids=(proof.proof_id,),
        exact_state_effect_exclusions=(), dispatcher_entry_serial=1,
        dispatcher_member_serials=(0, 1, 2),
        authoritative_handler_serials=(4,), state_identity=state,
        use_def_witness=replace(seed_witness, redirect_owner_refs=(refs[1],)),
    )
    compiled = compile_patch_plan(
        [RedirectBranch(1, 2, 4)], source, plan_id=proposal.plan_id,
        source_generation=1, block_refs_by_serial=refs,
    )
    assert len(compiled.steps) == 1
    assert type(compiled.steps[0]) is PatchRedirectBranch
    assert (
        compiled.steps[0].fallthrough_helper_block_id is not None
    ) is helper
    assert bool(compiled.new_blocks) is helper
    plan = PatchPlan(
        plan_id=compiled.plan_id, snapshot_id=compiled.snapshot_id,
        source_maturity=compiled.source_maturity,
        source_generation=compiled.source_generation, steps=compiled.steps,
        new_blocks=compiled.new_blocks, relocation_map=compiled.relocation_map,
        execution_policy=compiled.execution_policy, metadata=compiled.metadata,
        semantic_contract=compiled.semantic_contract,
        source_coordinates=tuple(
            (refs[serial], serial) for serial in sorted(refs)
        ),
        unflatten_proposal=proposal,
    )
    materialization = route_model.CanonicalRouteMaterialization.capture(
        source, generation=1,
        phase=route_model.CanonicalRouteAssessmentPhase.SOURCE,
    )
    source_inventory = transaction_api._build_semantic_graph_inventory(
        source, proposal, plan, source=True,
        phase=model.UnflattenAuthorityPhase.PRODUCER_FORECAST,
        materialization=materialization,
    )
    authority_result = bind.bind_source_route_authority(
        proposal=proposal, source_inventory=source_inventory,
        source_materialization=materialization,
    )
    assert type(authority_result) is model.SourceBoundRouteAuthorityAccepted
    projected_graph = project_post_state(source, plan)
    projected_inventory = transaction_api._build_semantic_graph_inventory(
        projected_graph, proposal, plan, source=False,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        materialization=None, source_subjects=source_inventory.subjects,
    )
    facts = transaction_api._derive_patch_lineage_facts(source_inventory, plan)
    attempt = TransactionAttemptId(
        plan.plan_id, authority_id((
            (
                "task-15-rf4-branch-helper-session"
                if helper else "task-15-rf3-two-arm-session"
            ),
            synthesized_stop,
        )), 1,
        authority_id((
            (
                "task-15-rf4-branch-helper-attempt"
                if helper else "task-15-rf3-two-arm-attempt"
            ),
            synthesized_stop,
        )),
    )
    return SimpleNamespace(
        source_graph=source, projected_graph=projected_graph,
        proposal=proposal, source_authority=authority_result.authority,
        plan=plan, source_inventory=source_inventory,
        projected_inventory=projected_inventory, patch_step_facts=facts,
        attempt_id=attempt, refs=refs,
    )


