def _task_15_corridor_unoriginated_suffix_case(case):
    """Rebuild RF-5b after one clone-only CALL before the synthetic GOTO."""
    from d810.ir.flowgraph import FlowGraph
    from d810.transforms.edit_simulator import project_post_state

    clean_projected_graph = project_post_state(case.source_graph, case.plan)
    step = case.plan.steps[0]
    clone_ref = step.clone_block_ids[-1]
    clone_serial = case.projected_inventory.serial_by_ref[clone_ref]
    clone = clean_projected_graph.blocks[clone_serial]
    assert len(clone.insn_snapshots) == 2
    source_prefix, synthetic_goto = clone.insn_snapshots
    injected = InsnSnapshot(
        908, synthetic_goto.ea + 0x80, (),
        display_text="rf5b_unoriginated_clone_suffix()",
        kind=InsnKind.CALL, raw_opcode=908, is_call=True,
    )
    mutated_graph = FlowGraph(
        {
            **clean_projected_graph.blocks,
            clone_serial: replace(
                clone,
                insn_snapshots=(source_prefix, injected, synthetic_goto),
                tail_opcode=synthetic_goto.opcode,
                tail_kind=synthetic_goto.kind,
                raw_tail_opcode=synthetic_goto.raw_opcode,
            ),
        },
        clean_projected_graph.entry_serial, clean_projected_graph.func_ea,
        metadata=clean_projected_graph.metadata,
    )
    mutated_inventory = transaction_api._build_semantic_graph_inventory(
        mutated_graph, case.proposal, case.plan, source=False,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        materialization=None, source_subjects=case.source_inventory.subjects,
    )
    injected_effects = tuple(
        row for row in mutated_inventory.effects
        if row.owner_ref == clone_ref
        and row.instruction_ea == injected.ea
        and row.effect_kind is model.EffectSiteKind.CALL
    )
    assert len(injected_effects) == 1
    assert (
        mutated_inventory.graph_fingerprint
        != case.projected_inventory.graph_fingerprint
    )
    return SimpleNamespace(
        source_graph=case.source_graph,
        clean_projected_graph=clean_projected_graph,
        projected_graph=mutated_graph,
        proposal=case.proposal, source_authority=case.source_authority,
        plan=case.plan, source_inventory=case.source_inventory,
        projected_inventory=mutated_inventory,
        patch_step_facts=case.patch_step_facts,
        attempt_id=case.attempt_id, semantic_stores=case.semantic_stores,
        semantic_return=case.semantic_return, clone_ref=clone_ref,
        clone_serial=clone_serial, injected=injected,
        injected_effect=injected_effects[0],
    )


def _task_15_branch_helper_injection_case(
    case, *, instruction_kind: InsnKind = InsnKind.CALL,
):
    """Rebuild RF-4 PROJECTED after adding one real instruction to helper H."""
    from d810.ir.flowgraph import FlowGraph

    step = case.plan.steps[0]
    assert step.fallthrough_helper_block_id is not None
    helper_serial = case.projected_inventory.serial_by_ref[
        step.fallthrough_helper_block_id
    ]
    helper = case.projected_graph.blocks[helper_serial]
    assert len(helper.insn_snapshots) == 1
    goto = helper.insn_snapshots[0]
    injected = InsnSnapshot(
        61, goto.ea - 1, (),
        display_text=f"rf4_helper_{instruction_kind.value}",
        kind=instruction_kind, raw_opcode=161,
        is_call=instruction_kind is InsnKind.CALL,
    )
    mutated_graph = FlowGraph(
        {
            **case.projected_graph.blocks,
            helper_serial: replace(
                helper, insn_snapshots=(injected, goto),
                tail_opcode=goto.opcode, tail_kind=goto.kind,
                raw_tail_opcode=goto.raw_opcode,
            ),
        },
        case.projected_graph.entry_serial, case.projected_graph.func_ea,
        metadata=case.projected_graph.metadata,
    )
    mutated_inventory = transaction_api._build_semantic_graph_inventory(
        mutated_graph, case.proposal, case.plan, source=False,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        materialization=None,
        source_subjects=case.source_inventory.subjects,
    )
    helper_effects = tuple(
        row for row in mutated_inventory.effects
        if row.owner_serial == helper_serial
        and row.owner_ref == step.fallthrough_helper_block_id
        and row.instruction_ea == injected.ea
    )
    helper_terminals = tuple(
        row for row in mutated_inventory.terminals
        if row.owner_serial == helper_serial
        and row.owner_ref == step.fallthrough_helper_block_id
        and row.instruction_ea == injected.ea
    )
    assert (
        mutated_inventory.graph_fingerprint
        != case.projected_inventory.graph_fingerprint
    )
    return SimpleNamespace(
        source_graph=case.source_graph, projected_graph=mutated_graph,
        clean_projected_graph=case.projected_graph,
        proposal=case.proposal, source_authority=case.source_authority,
        plan=case.plan, source_inventory=case.source_inventory,
        projected_inventory=mutated_inventory,
        patch_step_facts=case.patch_step_facts,
        attempt_id=case.attempt_id, refs=case.refs,
        helper_serial=helper_serial, injected=injected,
        helper_effects=helper_effects, helper_terminals=helper_terminals,
        injected_effect=helper_effects[0] if helper_effects else None,
    )


def _task_15_two_arm_replacement_store_drift_case(case):
    """Rebuild RF-3 PROJECTED after removing only N's STORE occurrence."""
    from d810.ir.flowgraph import FlowGraph

    step = case.plan.steps[0]
    replacement_serial = case.projected_inventory.serial_by_ref[step.new_target]
    replacement = case.projected_graph.blocks[replacement_serial]
    assert len(replacement.insn_snapshots) == 1
    original_store = replacement.insn_snapshots[0]
    inert_replacement = replace(
        original_store, kind=InsnKind.NOP, value_op_kind=None,
        display_text="replacement store removed",
    )
    mutated_graph = FlowGraph(
        {
            **case.projected_graph.blocks,
            replacement_serial: replace(
                replacement, insn_snapshots=(inert_replacement,),
                tail_opcode=inert_replacement.opcode,
                tail_kind=inert_replacement.kind,
                raw_tail_opcode=inert_replacement.raw_opcode,
            ),
        },
        case.projected_graph.entry_serial, case.projected_graph.func_ea,
        metadata=case.projected_graph.metadata,
    )
    mutated_inventory = transaction_api._build_semantic_graph_inventory(
        mutated_graph, case.proposal, case.plan, source=False,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        materialization=None,
        source_subjects=case.source_inventory.subjects,
    )
    assert not any(
        row.owner_ref == step.new_target
        and row.instruction_ea == original_store.ea
        and row.effect_kind is model.EffectSiteKind.STORE
        for row in mutated_inventory.effects
    )
    assert (
        mutated_inventory.graph_fingerprint
        != case.projected_inventory.graph_fingerprint
    )
    return SimpleNamespace(
        source_graph=case.source_graph, projected_graph=mutated_graph,
        proposal=case.proposal, source_authority=case.source_authority,
        plan=case.plan, source_inventory=case.source_inventory,
        projected_inventory=mutated_inventory,
        patch_step_facts=case.patch_step_facts,
        attempt_id=case.attempt_id, refs=case.refs,
        original_store=original_store,
        inert_replacement=inert_replacement,
    )


@pytest.mark.parametrize(
    ("effect_kind", "exact_count"),
    (("call", 1), ("store", 1), ("call_store", 2)),
)
def test_task_15_exact_fixture_is_one_final_graph_producer_operation(
    effect_kind: str, exact_count: int,
) -> None:
    """Route and every site-specific exact claim come from one final graph."""
    from d810.analyses.control_flow.effect_branch_exclusion import (
        validate_exact_state_branch_effect_exclusion,
    )

    real_build = producer_api.build_proposal
    with patch.object(producer_api, "build_proposal", wraps=real_build) as producer_spy:
        source, proposal, exclusions, refs = exact_fixture(
            discarded_effect_kind=effect_kind, shared_terminal=True,
        )
    assert producer_spy.call_count == 1
    exclusions = exclusions if type(exclusions) is tuple else (exclusions,)
    exact_claims = tuple(
        claim for claim in proposal.claims
        if type(claim) is model.ExactInfeasibleEffectClaim
    )
    route_claims = tuple(
        claim for claim in proposal.claims
        if type(claim) is model.EquivalentSemanticRouteClaim
    )
    assert len(exclusions) == len(exact_claims) == exact_count
    assert len(route_claims) == 1
    serial_by_ref = {ref: serial for serial, ref in refs.items()}
    for exclusion in exclusions:
        assert validate_exact_state_branch_effect_exclusion(
            source, source, exclusion,
        )
        claim = next(
            item for item in exact_claims
            if item.discarded_effect_ea == exclusion.discarded_effect_ea
        )
        producer_api.validate_exact_effect_semantics(
            proposal=proposal, exclusion=exclusion, claim=claim,
            source_catalog=proposal.source_identity_catalog,
            route_evidence=proposal.route_evidence,
            source_serial_by_ref=serial_by_ref,
        )


def _task_15_expected_same_owner_effective_partition(
    *, proposal, source_inventory, projected_inventory,
    raw_effect_gate_fact, claim_inventory=None,
):
    """Derive the RF-1/DIRECT shadow solely from closed call inputs."""
    assert proposal is not None
    assert (
        raw_effect_gate_fact.source_inventory_digest
        == source_inventory.inventory_digest
    )
    assert (
        raw_effect_gate_fact.projected_inventory_digest
        == projected_inventory.inventory_digest
    )
    claims = proposal.claims
    if claim_inventory is not None:
        derived = claim_inventory.derived
        assert derived.proposal is proposal
        assert derived.source_inventory is source_inventory
        assert claim_inventory.projected_inventory is projected_inventory
        claims = derived.claims

    source_serial_by_owner = {
        model.AnchoredBlockRef(block.block_ref, block.anchor_ea): block.serial
        for block in source_inventory.blocks
        if block.block_ref is not None and block.anchor_ea is not None
    }

    def source_serials(owners):
        serials = frozenset(source_serial_by_owner[owner] for owner in owners)
        assert len(serials) == len(owners)
        return serials

    source_owners = source_serials(
        raw_effect_gate_fact.pre_effectful_source_owners,
    )
    retained = source_serials(
        raw_effect_gate_fact.raw_retained_source_owners,
    )
    raw_lost = source_serials(raw_effect_gate_fact.raw_lost_source_owners)
    assert source_owners == retained | raw_lost
    assert not retained & raw_lost
    exact_sites = {
        (
            claim.effect_subject.locator.owner_ref,
            claim.effect_subject.locator.instruction_ea,
            claim.effect_subject.locator.effect_kind,
        )
        for claim in claims
        if type(claim) is model.ExactInfeasibleEffectClaim
    }
    local_sites = {
        (claim.owner_subject.block_ref, claim.host_ea)
        for claim in claims
        if type(claim) is model.LocalAliasEffectScalarizationClaim
    }

    def has_accepted_disposition(row):
        preserved = any(
            candidate.owner_serial in projected_inventory.reachable_serials
            and candidate.owner_ref == row.owner_ref
            and candidate.owner_anchor_ea == row.owner_anchor_ea
            and candidate.instruction_ea == row.instruction_ea
            and candidate.effect_kind is row.effect_kind
            and candidate.opcode == row.opcode
            and candidate.width == row.width
            for candidate in projected_inventory.effects
        )
        return (
            preserved
            or (row.owner_ref, row.instruction_ea, row.effect_kind)
            in exact_sites
            or (row.owner_ref, row.instruction_ea) in local_sites
        )

    authorized = frozenset(
        owner_serial
        for owner_serial in raw_lost
        if (
            owner_effects := tuple(
                row for row in source_inventory.effects
                if row.owner_serial == owner_serial
                and row.owner_serial in source_inventory.reachable_serials
            )
        )
        and all(has_accepted_disposition(row) for row in owner_effects)
    )
    return retained | authorized, raw_lost - authorized


def _task_15_expected_cloned_conditional_effective_partition(
    *, plan, source_inventory, projected_inventory, raw_effect_gate_fact,
):
    """Derive RF-2 clone preservation from the real closed compiler step."""
    from d810.transforms.plan import PatchConditionalRedirect

    assert len(plan.steps) == 1
    step = plan.steps[0]
    assert type(step) is PatchConditionalRedirect
    assert (
        raw_effect_gate_fact.source_inventory_digest
        == source_inventory.inventory_digest
    )
    assert (
        raw_effect_gate_fact.projected_inventory_digest
        == projected_inventory.inventory_digest
    )
    source_serial_by_owner = {
        model.AnchoredBlockRef(block.block_ref, block.anchor_ea): block.serial
        for block in source_inventory.blocks
        if block.block_ref is not None and block.anchor_ea is not None
    }

    def source_serials(owners):
        serials = frozenset(source_serial_by_owner[owner] for owner in owners)
        assert len(serials) == len(owners)
        return serials

    retained = source_serials(
        raw_effect_gate_fact.raw_retained_source_owners,
    )
    raw_lost = source_serials(raw_effect_gate_fact.raw_lost_source_owners)
    clone_source = step.ref_block
    clone_target = step.block_id

    def has_accepted_disposition(row):
        target = clone_target if row.owner_ref == clone_source else row.owner_ref
        candidates = tuple(
            candidate for candidate in projected_inventory.effects
            if candidate.owner_serial in projected_inventory.reachable_serials
            and candidate.owner_ref == target
            and candidate.instruction_ordinal == row.instruction_ordinal
            and candidate.instruction_ea == row.instruction_ea
            and candidate.effect_kind is row.effect_kind
            and candidate.opcode == row.opcode
            and candidate.width == row.width
        )
        if len(candidates) != 1:
            return False
        source_block = next(
            block for block in source_inventory.blocks
            if block.serial == row.owner_serial
        )
        projected_block = next(
            block for block in projected_inventory.blocks
            if block.serial == candidates[0].owner_serial
        )
        source_observation = source_block.instruction_observations[
            row.instruction_ordinal
        ]
        projected_observation = projected_block.instruction_observations[
            candidates[0].instruction_ordinal
        ]
        return (
            source_observation.instruction_ea
            == projected_observation.instruction_ea
            and source_observation.instruction_kind
            is projected_observation.instruction_kind
            and source_observation.opcode == projected_observation.opcode
            and source_observation.raw_opcode
            == projected_observation.raw_opcode
            and source_observation.width == projected_observation.width
        )

    authorized = frozenset(
        owner_serial
        for owner_serial in raw_lost
        if (
            owner_effects := tuple(
                row for row in source_inventory.effects
                if row.owner_serial == owner_serial
                and row.owner_serial in source_inventory.reachable_serials
            )
        )
        and all(has_accepted_disposition(row) for row in owner_effects)
    )
    return retained | authorized, raw_lost - authorized


def _task_15_expected_corridor_effective_partition(
    *, plan, source_inventory, projected_inventory, raw_effect_gate_fact,
):
    """Derive RF-5 clone preservation from the ordered corridor step."""
    from d810.transforms.plan import PatchEdgeSplitCorridor

    assert len(plan.steps) == 1
    step = plan.steps[0]
    assert type(step) is PatchEdgeSplitCorridor
    assert len(step.corridor_serials) == len(step.clone_block_ids) >= 1
    assert (
        raw_effect_gate_fact.source_inventory_digest
        == source_inventory.inventory_digest
    )
    assert (
        raw_effect_gate_fact.projected_inventory_digest
        == projected_inventory.inventory_digest
    )
    source_serial_by_owner = {
        model.AnchoredBlockRef(block.block_ref, block.anchor_ea): block.serial
        for block in source_inventory.blocks
        if block.block_ref is not None and block.anchor_ea is not None
    }

    def source_serials(owners):
        serials = frozenset(source_serial_by_owner[owner] for owner in owners)
        assert len(serials) == len(owners)
        return serials

    retained = source_serials(
        raw_effect_gate_fact.raw_retained_source_owners,
    )
    raw_lost = source_serials(raw_effect_gate_fact.raw_lost_source_owners)
    clone_by_source = dict(zip(step.corridor_serials, step.clone_block_ids))

    def has_accepted_disposition(row):
        projected_owner = clone_by_source.get(row.owner_ref, row.owner_ref)
        candidates = tuple(
            candidate for candidate in projected_inventory.effects
            if candidate.owner_serial in projected_inventory.reachable_serials
            and candidate.owner_ref == projected_owner
            and candidate.instruction_ordinal == row.instruction_ordinal
            and candidate.instruction_ea == row.instruction_ea
            and candidate.effect_kind is row.effect_kind
            and candidate.opcode == row.opcode
            and candidate.width == row.width
        )
        if len(candidates) != 1:
            return False
        source_block = next(
            block for block in source_inventory.blocks
            if block.serial == row.owner_serial
        )
        projected_block = next(
            block for block in projected_inventory.blocks
            if block.serial == candidates[0].owner_serial
        )
        source_observation = source_block.instruction_observations[
            row.instruction_ordinal
        ]
        projected_observation = projected_block.instruction_observations[
            candidates[0].instruction_ordinal
        ]
        return (
            source_observation.instruction_ea
            == projected_observation.instruction_ea
            and source_observation.instruction_kind
            is projected_observation.instruction_kind
            and source_observation.opcode == projected_observation.opcode
            and source_observation.raw_opcode
            == projected_observation.raw_opcode
            and source_observation.width == projected_observation.width
        )

    authorized = frozenset(
        owner_serial
        for owner_serial in raw_lost
        if (
            owner_effects := tuple(
                row for row in source_inventory.effects
                if row.owner_serial == owner_serial
                and row.owner_serial in source_inventory.reachable_serials
            )
        )
        and all(has_accepted_disposition(row) for row in owner_effects)
    )
    return retained | authorized, raw_lost - authorized


def _task_15_vertical_inputs(factory):
    """Bind the complete call-local C closure inputs for one DIRECT fixture."""
    from d810.transforms.unflatten_authority.gates import GenericEffectfulGateFacts
    from d810.transforms.unflatten_authority.ids import projected_authority_id

    authority, plan, source, projected, lineage_facts, attempt = factory()
    source_owners = frozenset(
        row.owner_serial for row in source.effects
        if row.owner_serial in source.reachable_serials
    )
    projected_owners = frozenset(
        row.owner_serial for row in projected.effects
        if row.owner_serial in projected.reachable_serials
    )
    retained = source_owners & projected_owners
    raw_fact = bind.bind_raw_effect_gate_phase_fact(
        source_inventory=source, projected_inventory=projected,
        raw_gate_facts=GenericEffectfulGateFacts(
            not (source_owners - retained), source_owners, retained,
            source_owners - retained, "task-15-direct-raw",
        ),
    )
    effective_post, effective_lost = _task_15_expected_same_owner_effective_partition(
        proposal=plan.unflatten_proposal,
        source_inventory=source,
        projected_inventory=projected,
        raw_effect_gate_fact=raw_fact,
    )
    claims = plan.unflatten_proposal.claims
    patch_facts = tuple(sorted(lineage_facts, key=patch_step_fact_id))
    authority_value = projected_authority_id(
        attempt_id=attempt, proposal_id=authority.proposal_id,
        source_authority_id=authority.source_authority_id,
        plan_id=plan.plan_id, claims=claims, patch_step_facts=patch_facts,
        source_inventory=source, projected_inventory=projected,
        raw_effect_gate_fact=raw_fact,
    )
    values = {
        "authority_id": authority_value, "source_authority": authority,
        "plan": plan, "source_inventory": source,
        "projected_inventory": projected, "claims": claims,
        "patch_step_facts": patch_facts, "raw_effect_gate_fact": raw_fact,
        "legacy_effective_gate_facts": GenericEffectfulGateFacts(
            not effective_lost, source_owners, effective_post,
            effective_lost,
            "task-15-direct-effective",
        ),
        "attempt_id": attempt,
    }
    return values


