def _task_15_local_projected_inventory_with_observation_drift(
    inventory, *, mutation: str,
):
    """Rebuild the complete projected digest around one exact MOV drift."""
    claim = inventory.derived.local_alias_occurrences[0].claim
    projected = inventory.projected_inventory
    blocks = []
    found = 0
    for block in projected.blocks:
        observations = []
        for observation in block.instruction_observations:
            if (
                block.block_ref == claim.owner_subject.block_ref
                and observation.instruction_ea == claim.host_ea
                and observation.instruction_kind is InsnKind.MOV
            ):
                found += 1
                if mutation == "raw_opcode":
                    observation = replace(
                        observation, raw_opcode=observation.raw_opcode + 100,
                    )
                elif mutation == "open_expression":
                    observation = replace(
                        observation,
                        display_text=(
                            f"{claim.alias_token} = {claim.base_token} + foreign"
                        ),
                    )
                elif mutation == "prefix":
                    observation = replace(
                        observation,
                        display_text=f"foreign{claim.alias_token} = {claim.base_token}",
                    )
                elif mutation == "suffix":
                    observation = replace(
                        observation,
                        display_text=f"{claim.alias_token} = {claim.base_token}foreign",
                    )
                elif mutation == "identifier_case":
                    observation = replace(
                        observation,
                        display_text=(
                            f"{claim.alias_token.upper()} = "
                            f"{claim.base_token.upper()}"
                        ),
                    )
                elif mutation == "keyword_lower":
                    observation = replace(
                        observation,
                        display_text=(
                            f"{claim.alias_token} = dword ptr {claim.base_token}"
                        ),
                    )
                elif mutation == "keyword_upper":
                    observation = replace(
                        observation,
                        display_text=(
                            f"{claim.alias_token} = DWORD PTR {claim.base_token}"
                        ),
                    )
                elif mutation == "keyword_mixed":
                    observation = replace(
                        observation,
                        display_text=(
                            f"{claim.alias_token} = DwOrD PtR {claim.base_token}"
                        ),
                    )
                else:  # pragma: no cover - traceability guard
                    raise AssertionError(mutation)
            observations.append(observation)
        blocks.append(replace(block, instruction_observations=tuple(observations)))
    assert found == 1
    blocks = tuple(blocks)
    return replace(
        projected, blocks=blocks,
        inventory_digest=semantic_graph_inventory_digest(
            projected.phase, projected.graph_fingerprint, projected.generation,
            blocks, projected.subjects, projected.bindings, projected.effects,
            projected.terminals, projected.topology, projected.reachable_serials,
            projected.entry_serial, projected.source_subject_ids,
            projected.function_ea,
        ),
    )


def _task_15_publication_type_counts():
    """Count only accepted-closure publications; typed failures are excluded."""
    registries = (
        _private_route_registry(), bind._SITE_REGISTRY,
        bind._SITE_BINDING_REGISTRY,
    )
    publication_types = (
        model.DirectRouteRealization,
        model.LoweredConditionalRouteRealization,
        model.ClonedConditionalRouteRealization,
        model.ClonedSemanticInstructionOrigin,
        model.ClonedSemanticPrefix,
        model.TwoArmDirectBranchRouteRealization,
        model.BranchFallthroughHelperRouteRealization,
        model.ClonedRouteCorridorRealization,
        model.ProjectedRouteRealizationRow,
        model.ProjectedRouteRealization,
        model.ProjectedRouteRealizationAccepted,
        model.EffectSiteCoordinate,
        model.TerminalSiteCoordinate,
        model.ScalarizedInstructionCoordinate,
        model.ExactEffectBindingResult,
        model.LocalAliasScalarizationBindingResult,
        model.ProjectedEffectSiteResult,
        model.ProjectedTerminalSiteResult,
        model.ProjectedSemanticSitePhaseResult,
        model.ProjectedRouteSitePreservation,
    )
    return tuple(
        sum(
            1 for registry in registries for reference, _seal in registry.values()
            if type(reference()) is publication_type
        )
        for publication_type in publication_types
    )


def _task_15_observe_publication_events(callback):
    """Record durable accepted-publication attempts around one real call."""
    accepted_types = (
        model.DirectRouteRealization,
        model.LoweredConditionalRouteRealization,
        model.ClonedConditionalRouteRealization,
        model.ClonedSemanticInstructionOrigin,
        model.ClonedSemanticPrefix,
        model.TwoArmDirectBranchRouteRealization,
        model.BranchFallthroughHelperRouteRealization,
        model.ClonedRouteCorridorRealization,
        model.EffectSiteCoordinate,
        model.TerminalSiteCoordinate,
        model.ScalarizedInstructionCoordinate,
        model.ExactEffectBindingResult,
        model.LocalAliasScalarizationBindingResult,
        model.ProjectedEffectSiteResult,
        model.ProjectedTerminalSiteResult,
        model.ProjectedSemanticSitePhaseResult,
        model.ProjectedRouteSitePreservation,
        model.ProjectedRouteRealizationRow,
        model.ProjectedRouteRealization,
        model.ProjectedRouteRealizationAccepted,
    )
    ordinary = []
    deferred = []
    commits = []
    real_register = bind._register_registry_occurrence
    real_defer = bind._AtomicPublicationBatch.defer
    real_commit = bind._AtomicPublicationBatch.commit

    def register(value, seal, registry):
        ordinary.append(value)
        return real_register(value, seal, registry)

    def defer(batch, *, value, registry, seal):
        deferred.append(value)
        return real_defer(batch, value=value, registry=registry, seal=seal)

    def commit(batch):
        commits.append(tuple(
            reference() for _registry, _key, reference, _seal in batch._entries
        ))
        return real_commit(batch)

    with (
        patch.object(
            bind, "_register_registry_occurrence", side_effect=register,
        ),
        patch.object(
            bind._AtomicPublicationBatch, "defer", autospec=True,
            side_effect=defer,
        ),
        patch.object(
            bind._AtomicPublicationBatch, "commit", autospec=True,
            side_effect=commit,
        ),
    ):
        result = callback()
    return SimpleNamespace(
        result=result,
        ordinary=tuple(ordinary),
        deferred=tuple(deferred),
        commits=tuple(commits),
        accepted_types=accepted_types,
    )


def _task_15_canonical_helper_inverse_case():
    """Build a final-producer helper route and graph-backed helper mutation."""
    from d810.ir.expressions import ValueOpKind
    from d810.ir.flowgraph import BlockSnapshot, FlowGraph
    from d810.transforms.cfg_transaction import TransactionAttemptId
    from d810.transforms.edit_simulator import project_post_state
    from d810.transforms.graph_modification import RedirectBranch
    from tests.typed_patch_authority import compile_patch_plan

    source_seed, seed_evidence, witness, refs = exact_fixture(
        producer_inputs_only=True,
    )
    blocks = dict(source_seed.blocks)
    first, branch = blocks[1].insn_snapshots
    blocks[1] = replace(
        blocks[1], succs=(2, 3),
        insn_snapshots=(
            replace(
                first, kind=InsnKind.MOV,
                value_op_kind=ValueOpKind.MOVE,
                l=MopSnapshot(kind=OperandKind.NUMBER, size=4, value=7),
                d=MopSnapshot(
                    kind=OperandKind.STACK, size=4, stkoff=4,
                    stack_refs=(4,),
                ),
            ),
            replace(
                branch,
                d=MopSnapshot(kind=OperandKind.BLOCK, block_ref=3),
            ),
        ),
    )
    blocks[2] = replace(blocks[2], preds=(1,))
    blocks[3] = replace(blocks[3], preds=(1,))
    source_graph = FlowGraph(
        blocks, source_seed.entry_serial, source_seed.func_ea,
    )
    state = seed_evidence.route_proofs[0].state_write.state_variable
    fact = route_model.SemanticRouteFact(
        route_model.SemanticRouteFactKind.NATIVE_BOUND,
        1, 1, 0x2000, 7, 4, 0x2000, 0x5000, (1,), (),
        authority_id("task-15-canonical-helper-fact"),
    )
    context = route_model.CanonicalSemanticEvidenceProductionContext(
        seed_evidence.native_key, 1,
        authority_id("task-15-canonical-helper-group"), state,
        tuple(source_graph.blocks.values()),
        tuple((serial, ref.identity) for serial, ref in refs.items()),
        source_graph.entry_serial,
    )
    produced = route_model.build_canonical_semantic_evidence(
        (fact,), context,
    )
    assert produced.abstention is None and produced.evidence is not None
    evidence = produced.evidence
    proof = evidence.route_proofs[0]
    proposal = producer_api.build_proposal(
        plan_id=authority_id("task-15-canonical-helper-plan"),
        source=source_graph, block_refs_by_serial=refs,
        source_generation=1, canonical_route_evidence=evidence,
        selected_route_proof_ids=(proof.proof_id,),
        exact_state_effect_exclusions=(), dispatcher_entry_serial=1,
        dispatcher_member_serials=(0, 1, 2),
        authoritative_handler_serials=(4,),
        state_identity=state,
        use_def_witness=witness,
    )
    compiled = compile_patch_plan(
        [RedirectBranch(1, 2, 4)], source_graph,
        plan_id=proposal.plan_id, source_generation=1,
        block_refs_by_serial=refs,
    )
    plan = replace(
        compiled,
        source_coordinates=tuple(
            (ref, serial) for serial, ref in refs.items()
        ),
        unflatten_proposal=proposal,
    )
    materialization = route_model.CanonicalRouteMaterialization.capture(
        source_graph, generation=1,
        phase=route_model.CanonicalRouteAssessmentPhase.SOURCE,
    )
    source_inventory = transaction_api._build_semantic_graph_inventory(
        source_graph, proposal, plan, source=True,
        phase=model.UnflattenAuthorityPhase.PRODUCER_FORECAST,
        materialization=materialization,
    )
    authority = bind.bind_source_route_authority(
        proposal=proposal, source_inventory=source_inventory,
        source_materialization=materialization,
    )
    assert type(authority) is model.SourceBoundRouteAuthorityAccepted
    clean_projected_graph = project_post_state(source_graph, plan)
    clean_projected_inventory = transaction_api._build_semantic_graph_inventory(
        clean_projected_graph, proposal, plan, source=False,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        materialization=None, source_subjects=source_inventory.subjects,
    )
    helper_ref = plan.new_blocks[0].block_id
    helper_serial = clean_projected_inventory.serial_by_ref[helper_ref]
    helper = clean_projected_graph.blocks[helper_serial]
    goto = helper.insn_snapshots[0]
    injected_call = InsnSnapshot(
        77, goto.ea - 1, (), kind=InsnKind.CALL,
        is_call=True, raw_opcode=77,
    )
    changed_helper = replace(
        helper, insn_snapshots=(injected_call, goto),
        tail_opcode=goto.opcode, tail_kind=goto.kind,
        raw_tail_opcode=goto.raw_opcode,
    )
    mutated_projected_graph = FlowGraph(
        {
            **clean_projected_graph.blocks,
            helper_serial: changed_helper,
        },
        clean_projected_graph.entry_serial,
        clean_projected_graph.func_ea,
        metadata=clean_projected_graph.metadata,
    )
    mutated_projected_inventory = transaction_api._build_semantic_graph_inventory(
        mutated_projected_graph, proposal, plan, source=False,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        materialization=None, source_subjects=source_inventory.subjects,
    )
    assert (
        mutated_projected_inventory.graph_fingerprint
        != clean_projected_inventory.graph_fingerprint
    )
    injected_effect = next(
        row for row in mutated_projected_inventory.effects
        if row.owner_serial == helper_serial
        and row.instruction_ea == injected_call.ea
    )
    derived = transaction_api._derive_transaction_facts(source_inventory, plan)
    facts = derived.patch_step_facts
    attempt = TransactionAttemptId(
        plan.plan_id, authority_id("task-15-canonical-helper-session"), 1,
        authority_id("task-15-canonical-helper-attempt"),
    )
    claim_inventory = bind._bind_transaction_projected_claim_inventory(
        derived=derived, source_authority=authority.authority,
        attempt_id=attempt, projected_inventory=mutated_projected_inventory,
    )
    closure_inputs = _task_15_vertical_inputs_from_claim_inventory(
        claim_inventory,
    )
    return SimpleNamespace(
        source_graph=source_graph, clean_projected_graph=clean_projected_graph,
        mutated_projected_graph=mutated_projected_graph,
        proposal=proposal, source_authority=authority.authority, plan=plan,
        source_inventory=source_inventory,
        clean_projected_inventory=clean_projected_inventory,
        mutated_projected_inventory=mutated_projected_inventory,
        derived=derived, claim_inventory=claim_inventory,
        patch_step_facts=tuple(sorted(facts, key=patch_step_fact_id)),
        attempt_id=attempt, helper_ref=helper_ref,
        helper_anchor_ea=changed_helper.start_ea,
        injected_effect=injected_effect, closure_inputs=closure_inputs,
    )


def _assert_task_15_canonical_helper_inverse_rejection(values) -> None:
    """Pin public ATTEMPT and transaction-private semantic inverse seams."""
    import gc

    route_claim = next(
        claim for claim in values.derived.claims
        if type(claim) is model.EquivalentSemanticRouteClaim
    )
    proof = values.proposal.route_evidence.route_proofs[0]
    fact = values.derived.route_patch_step_facts[0]
    locator = route_claim.retired_route_subject.locator

    expected_relation = _task_15_independent_expected_publication(
        values.closure_inputs,
    )["relation"]
    internal_anchors = _mechanical_sorted_anchors((
        *_mechanical_branch_helper_anchors(None, expected_relation),
        model.AnchoredBlockRef(values.helper_ref, values.helper_anchor_ea),
    ))
    gc.collect()
    before = _task_15_publication_type_counts()
    with (
        patch.object(
            transaction_api, "_build_semantic_graph_inventory",
            side_effect=AssertionError("projected closure inventory replay"),
        ),
        patch.object(
            transaction_api, "_derive_transaction_facts",
            side_effect=AssertionError("projected closure fact replay"),
        ),
        patch.object(
            transaction_api, "_derive_patch_lineage_facts",
            side_effect=AssertionError("projected closure lineage replay"),
        ),
        patch.object(
            bind, "bind_source_route_authority",
            side_effect=AssertionError("projected closure source replay"),
        ),
        patch.object(
            route_model, "bind_canonical_semantic_evidence_result",
            side_effect=AssertionError("projected closure route replay"),
        ),
        patch.object(
            producer_api, "validate_exact_effect_claim_semantics",
            side_effect=AssertionError("projected closure producer exact replay"),
        ),
        patch.object(
            evaluate, "_classify_effect_site",
            side_effect=AssertionError("projected closure evaluator replay"),
        ),
    ):
        public_events = _task_15_observe_publication_events(lambda:
            bind.realize_projected_routes(
                authority_id=values.closure_inputs["authority_id"],
                source_authority=values.source_authority,
                plan=values.plan,
                source_inventory=values.source_inventory,
                projected_inventory=values.mutated_projected_inventory,
                claims=values.derived.claims,
                patch_step_facts=values.derived.patch_step_facts,
                raw_effect_gate_fact=values.closure_inputs["raw_effect_gate_fact"],
                legacy_effective_gate_facts=(
                    values.closure_inputs["legacy_effective_gate_facts"]
                ),
                attempt_id=values.attempt_id,
            )
        )
        internal_events = _task_15_observe_publication_events(lambda:
            bind._realize_projected_routes_from_claim_inventory(
                authority_id=values.closure_inputs["authority_id"],
                claim_inventory=values.claim_inventory,
                raw_effect_gate_fact=values.closure_inputs["raw_effect_gate_fact"],
                legacy_effective_gate_facts=(
                    values.closure_inputs["legacy_effective_gate_facts"]
                ),
            )
        )
    public_rejected = public_events.result
    assert type(public_rejected) is model.ProjectedRouteRealizationRejected
    bind.validate_projected_route_realization_result(public_rejected)
    assert len(public_rejected.failures) == 1
    public_failure = public_rejected.failures[0]
    assert public_failure.stage is model.RouteRealizationFailureStage.ATTEMPT_BINDING
    assert public_failure.scope is model.RouteRealizationFailureScope.EVIDENCE
    assert public_failure.proposal_id == authority_id(values.proposal)
    assert public_failure.evidence_id == values.proposal.route_evidence.atomic_group_id
    assert public_failure.claim_id is None
    assert public_failure.proof_id is None
    assert public_failure.route_subject_id is None
    assert public_failure.step_index is None
    assert public_failure.step_digest is None
    assert public_failure.anchored_refs == ()
    assert public_events.commits == ()
    assert not any(
        type(value) in public_events.accepted_types
        for value in public_events.deferred
    )
    assert not any(
        type(value) in public_events.accepted_types
        for value in public_events.ordinary
    )
    assert tuple(type(value) for value in public_events.ordinary) == (
        model.RouteRealizationFailure,
        model.ProjectedRouteRealizationRejected,
    )

    internal_rejected = internal_events.result
    assert type(internal_rejected) is model.ProjectedRouteRealizationRejected
    bind.validate_projected_route_realization_result(internal_rejected)
    assert len(internal_rejected.failures) == 1
    internal_failure = internal_rejected.failures[0]
    assert (
        internal_failure.stage
        is model.RouteRealizationFailureStage.EFFECT_TERMINAL_PRESERVATION
    )
    assert internal_failure.scope is model.RouteRealizationFailureScope.STEP
    assert internal_failure.claim_id == route_claim.claim_id
    assert internal_failure.proof_id == proof.proof_id
    assert (
        internal_failure.route_subject_id
        == route_claim.retired_route_subject.subject_id
    )
    assert internal_failure.step_index == fact.step_index
    assert internal_failure.step_digest == fact.step_digest
    assert internal_failure.anchored_refs == internal_anchors
    assert internal_events.commits == ()
    assert not any(
        type(value) in internal_events.accepted_types
        for value in internal_events.deferred
    )
    assert not any(
        type(value) in internal_events.accepted_types
        for value in internal_events.ordinary
    )
    assert tuple(type(value) for value in internal_events.ordinary) == (
        model.RouteRealizationFailure,
        model.ProjectedRouteRealizationRejected,
    )
    assert _task_15_publication_type_counts() == before

    cells, draft_kernel, _build = _private_projected_kernel_cells()
    structural, drafts, owner_index, route_publications = draft_kernel(
        source_authority=values.source_authority,
        plan=values.plan,
        source_inventory=values.source_inventory,
        projected_inventory=values.clean_projected_inventory,
        patch_step_facts=values.derived.route_patch_step_facts,
        attempt_id=values.attempt_id,
        _mint=cells["_route_mint"].cell_contents,
        _failure=cells["_route_failure"].cell_contents,
        _result=cells["_route_result"].cell_contents,
        _validate=cells["validate_route"].cell_contents,
    )
    assert structural is None
    assert len(drafts) == len(route_publications) == 1
    assert type(drafts[0].relation) is model.BranchFallthroughHelperRouteRealization
    site_draft = bind._draft_projected_site_closure(
        authority_id=values.closure_inputs["authority_id"],
        source_authority=values.source_authority,
        plan=values.plan,
        source_inventory=values.source_inventory,
        projected_inventory=values.mutated_projected_inventory,
        claims=values.derived.claims,
        patch_step_facts=values.derived.patch_step_facts,
        raw_effect_gate_fact=values.closure_inputs["raw_effect_gate_fact"],
        legacy_effective_gate_facts=(
            values.closure_inputs["legacy_effective_gate_facts"]
        ),
        attempt_id=values.attempt_id,
        drafts=drafts,
        owner_index=owner_index,
    )
    with pytest.raises(bind._ProjectedSiteDraftViolation) as raised:
        bind._validate_projected_site_closure_draft(
            site_draft,
            source_authority=values.source_authority,
            plan=values.plan,
            source_inventory=values.source_inventory,
            projected_inventory=values.mutated_projected_inventory,
            claims=values.derived.claims,
            patch_step_facts=values.derived.patch_step_facts,
            raw_effect_gate_fact=values.closure_inputs["raw_effect_gate_fact"],
            legacy_effective_gate_facts=(
                values.closure_inputs["legacy_effective_gate_facts"]
            ),
            attempt_id=values.attempt_id,
            drafts=drafts,
            owner_index=owner_index,
            route_publications=route_publications,
        )
    violation = raised.value
    assert violation.reason_code == "projected effect inverse is incomplete"
    assert violation.scope is model.RouteRealizationFailureScope.STEP
    assert violation.relation_draft is drafts[0]
    assert violation.projected_row is values.injected_effect
    translated = bind._translate_projected_site_draft_violation(violation)
    assert translated["stage"] is model.RouteRealizationFailureStage.EFFECT_TERMINAL_PRESERVATION
    assert translated["scope_override"] is model.RouteRealizationFailureScope.STEP
    assert translated["claim"] is route_claim
    assert translated["proof_override"] is proof
    assert translated["fact"] is fact
    coordinates = bind._route_failure_coordinates(values.proposal, **translated)
    private_anchors = internal_anchors
    assert coordinates == {
        "claim_id": route_claim.claim_id,
        "proof_id": proof.proof_id,
        "route_subject_id": route_claim.retired_route_subject.subject_id,
        "scope": model.RouteRealizationFailureScope.STEP,
        "proposal_id": authority_id(values.proposal),
        "evidence_id": values.proposal.route_evidence.atomic_group_id,
        "stage": model.RouteRealizationFailureStage.EFFECT_TERMINAL_PRESERVATION,
        "step_index": fact.step_index,
        "step_digest": fact.step_digest,
        "anchored_refs": private_anchors,
    }


def _task_15_independent_expected_publication(values):
    """Derive every approved family public ID from prior inputs."""
    from d810.transforms.unflatten_authority.ids import (
        derived_effect_gate_fact_id, exact_effect_binding_result_id,
        local_alias_binding_result_id, projected_effect_site_result_id,
        projected_route_realization_id, projected_route_realization_row_id,
        projected_route_site_preservation_id,
        projected_semantic_site_phase_result_id,
        projected_terminal_site_result_id,
    )

    def shell(cls, **fields):
        value = object.__new__(cls)
        for name in cls.__dataclass_fields__:
            object.__setattr__(value, name, fields[name])
        return value

    def identified(cls, identity_name, identity_factory, **fields):
        fields[identity_name] = "sha256:" + "0" * 64
        value = shell(cls, **fields)
        object.__setattr__(value, identity_name, identity_factory(value))
        return value

    def effect_coordinate(row):
        return shell(
            model.EffectSiteCoordinate,
            owner=model.AnchoredBlockRef(row.owner_ref, row.owner_anchor_ea),
            instruction_ordinal=row.instruction_ordinal,
            instruction_ea=row.instruction_ea, effect_kind=row.effect_kind,
            opcode=row.opcode, width=row.width,
        )

    def terminal_coordinate(row):
        return shell(
            model.TerminalSiteCoordinate,
            owner=model.AnchoredBlockRef(row.owner_ref, row.owner_anchor_ea),
            instruction_ordinal=row.instruction_ordinal,
            instruction_ea=row.instruction_ea,
            terminal_kind=row.terminal_kind,
        )

    def subject_id(inventory, row):
        for subject in inventory.subjects:
            locator = subject.locator
            if type(row) is model.InventoryEffectSite and (
                getattr(locator, "owner_ref", None) == row.owner_ref
                and getattr(locator, "instruction_ea", None) == row.instruction_ea
                and getattr(locator, "effect_kind", None) is row.effect_kind
            ):
                return subject.subject_id
            if type(row) is model.InventoryTerminalSite and (
                getattr(locator, "block_ref", None) == row.owner_ref
                and getattr(locator, "instruction_ea", None) == row.instruction_ea
                and getattr(locator, "terminal_kind", None) is row.terminal_kind
            ):
                return subject.subject_id
        raise AssertionError("canonical Task-15 site lacks its input subject")

    source = values["source_inventory"]
    projected = values["projected_inventory"]
    authority = values["source_authority"]
    attempt = values["attempt_id"]
    plan = values["plan"]
    raw = values["raw_effect_gate_fact"]
    route_claim = next(
        claim for claim in values["claims"]
        if type(claim) is model.EquivalentSemanticRouteClaim
    )
    exact_claims = tuple(
        claim for claim in values["claims"]
        if type(claim) is model.ExactInfeasibleEffectClaim
    )
    local_claims = tuple(
        claim for claim in values["claims"]
        if type(claim) is model.LocalAliasEffectScalarizationClaim
    )
    route_fact = next(
        fact for fact in values["patch_step_facts"]
        if fact.step_type in {
            "PatchRedirectGoto", "PatchLowerConditionalStateTransition",
            "PatchConditionalRedirect", "PatchRedirectBranch",
            "PatchEdgeSplitCorridor",
        }
    )
    step = plan.steps[route_fact.step_index]
    source_blocks = {row.block_ref: row for row in source.blocks}
    if route_fact.step_type == "PatchRedirectGoto":
        feeder = model.AnchoredBlockRef(
            step.from_serial, source_blocks[step.from_serial].anchor_ea,
        )
        old_target = model.AnchoredBlockRef(
            step.old_target, source_blocks[step.old_target].anchor_ea,
        )
        new_target = model.AnchoredBlockRef(
            step.new_target, source_blocks[step.new_target].anchor_ea,
        )
        relation = shell(
            model.DirectRouteRealization, feeder=feeder, old_target=old_target,
            new_target=new_target,
            relation_id=route_realization_id((
                "direct", feeder, old_target, new_target,
            )),
        )
        relation_subset_owners = {feeder, new_target}
        route_step_kind = PatchStepKind.REDIRECT_GOTO
        clone_owner_by_source = {}
    elif route_fact.step_type == "PatchLowerConditionalStateTransition":
        feeder = model.AnchoredBlockRef(
            step.source_serial, source_blocks[step.source_serial].anchor_ea,
        )
        proof_source = model.AnchoredBlockRef(
            step.old_dispatcher_serial,
            source_blocks[step.old_dispatcher_serial].anchor_ea,
        )
        arms = tuple(sorted((
            model.RealizedConditionalArm(
                SemanticEdgeRole.CONDITIONAL_FALLTHROUGH,
                model.AnchoredBlockRef(
                    step.false_target_serial,
                    source_blocks[step.false_target_serial].anchor_ea,
                ),
            ),
            model.RealizedConditionalArm(
                SemanticEdgeRole.CONDITIONAL_TAKEN,
                model.AnchoredBlockRef(
                    step.true_target_serial,
                    source_blocks[step.true_target_serial].anchor_ea,
                ),
            ),
        ), key=lambda arm: arm.role.value))
        relation = shell(
            model.LoweredConditionalRouteRealization,
            feeder=feeder, proof_source=proof_source,
            old_target=proof_source, arms=arms,
            relation_id=route_realization_id((
                "lowered_conditional", feeder, proof_source, proof_source,
                arms,
            )),
        )
        relation_subset_owners = {
            feeder, proof_source, *(arm.target for arm in arms),
        }
        route_step_kind = PatchStepKind.LOWER_CONDITIONAL
        clone_owner_by_source = {}
    elif route_fact.step_type == "PatchEdgeSplitCorridor":
        from d810.transforms.plan import PatchEdgeSplitCorridor
        from d810.transforms.unflatten_authority.proposal import (
            canonical_patch_step_descriptor,
        )

        assert type(step) is PatchEdgeSplitCorridor
        assert len(step.corridor_serials) == len(step.clone_block_ids) >= 1
        projected_blocks = {row.block_ref: row for row in projected.blocks}
        ref_by_serial = {
            serial: ref for ref, serial in source.serial_by_ref.items()
        }
        predecessor = model.AnchoredBlockRef(
            step.via_pred, source_blocks[step.via_pred].anchor_ea,
        )
        source_corridor = tuple(
            model.AnchoredBlockRef(ref, source_blocks[ref].anchor_ea)
            for ref in step.corridor_serials
        )
        cloned_corridor = tuple(
            model.AnchoredBlockRef(ref, projected_blocks[ref].anchor_ea)
            for ref in step.clone_block_ids
        )
        last_source = source_blocks[step.corridor_serials[-1]]
        terminal_continuation_ref = ref_by_serial[
            last_source.successor_serials[0]
        ]
        terminal_continuation = model.AnchoredBlockRef(
            terminal_continuation_ref,
            source_blocks[terminal_continuation_ref].anchor_ea,
        )
        descriptor_old_target = model.AnchoredBlockRef(
            step.old_target, source_blocks[step.old_target].anchor_ea,
        )
        semantic_target = model.AnchoredBlockRef(
            step.new_target, projected_blocks[step.new_target].anchor_ea,
        )
        creation_spec_digests = canonical_patch_step_descriptor(
            plan, route_fact.step_index,
        ).new_block_spec_digests
        semantic_prefixes = []
        for index, (source_owner, clone_owner) in enumerate(zip(
            source_corridor, cloned_corridor,
        )):
            source_block = source_blocks[source_owner.ref]
            clone_block = projected_blocks[clone_owner.ref]
            assert len(source_block.instruction_observations) == len(
                clone_block.instruction_observations
            )
            origins = []
            for ordinal, (source_observation, clone_observation) in enumerate(
                zip(
                    source_block.instruction_observations[:-1],
                    clone_block.instruction_observations[:-1],
                )
            ):
                assert source_observation == clone_observation
                digest = cloned_semantic_observation_digest(source_observation)
                preimage = (
                    "cloned_semantic_instruction_origin",
                    source_owner, clone_owner, ordinal, ordinal,
                    source_observation.instruction_ea, digest,
                )
                origins.append(shell(
                    model.ClonedSemanticInstructionOrigin,
                    source_owner=source_owner, clone_owner=clone_owner,
                    source_ordinal=ordinal, projected_ordinal=ordinal,
                    instruction_ea=source_observation.instruction_ea,
                    observation_digest=digest,
                    origin_id=cloned_semantic_instruction_origin_id(preimage),
                ))
            origins = tuple(origins)
            projected_successor = (
                cloned_corridor[index + 1]
                if index + 1 < len(cloned_corridor)
                else semantic_target
            )
            end = len(source_block.instruction_observations) - 1
            prefix_preimage = (
                "cloned_semantic_prefix", index, source_owner, clone_owner,
                0, end, origins, end,
                len(clone_block.instruction_observations) - 1,
                projected_successor, creation_spec_digests[index],
            )
            semantic_prefixes.append(shell(
                model.ClonedSemanticPrefix,
                ordinal=index, source_owner=source_owner,
                clone_owner=clone_owner, source_start_ordinal=0,
                source_end_ordinal_exclusive=end,
                instruction_origins=origins,
                source_trailing_goto_ordinal=end,
                projected_synthetic_goto_ordinal=(
                    len(clone_block.instruction_observations) - 1
                ),
                projected_successor=projected_successor,
                creation_spec_row=creation_spec_digests[index],
                prefix_id=cloned_semantic_prefix_id(prefix_preimage),
            ))
        semantic_prefixes = tuple(semantic_prefixes)
        relation = shell(
            model.ClonedRouteCorridorRealization,
            predecessor=predecessor, proof_source=source_corridor[0],
            descriptor_old_target=descriptor_old_target,
            terminal_continuation=terminal_continuation,
            source_corridor=source_corridor,
            cloned_corridor=cloned_corridor,
            semantic_target=semantic_target,
            semantic_prefixes=semantic_prefixes,
            creation_spec_digests=creation_spec_digests,
            relation_id=route_realization_id((
                "cloned_route_corridor", predecessor, source_corridor[0],
                descriptor_old_target, terminal_continuation,
                source_corridor, cloned_corridor, semantic_target,
                semantic_prefixes, creation_spec_digests,
            )),
        )
        relation_subset_owners = {
            predecessor, semantic_target, *source_corridor,
        }
        route_step_kind = PatchStepKind.HELPER_CORRIDOR
        clone_owner_by_source = dict(zip(
            step.corridor_serials, step.clone_block_ids,
        ))
    elif route_fact.step_type == "PatchRedirectBranch":
        from d810.transforms.unflatten_authority.proposal import (
            canonical_patch_step_descriptor,
        )

        feeder = model.AnchoredBlockRef(
            step.from_serial, source_blocks[step.from_serial].anchor_ea,
        )
        source_arm = model.AnchoredBlockRef(
            step.old_target, source_blocks[step.old_target].anchor_ea,
        )
        projected_arm = model.AnchoredBlockRef(
            step.new_target, source_blocks[step.new_target].anchor_ea,
        )
        source_successors = source_blocks[step.from_serial].successor_serials
        ref_by_serial = {
            serial: ref for ref, serial in source.serial_by_ref.items()
        }
        untouched_ref = ref_by_serial[next(
            serial for serial in source_successors
            if serial != source.serial_by_ref[step.old_target]
        )]
        untouched = model.AnchoredBlockRef(
            untouched_ref, source_blocks[untouched_ref].anchor_ea,
        )
        if step.fallthrough_helper_block_id is None:
            relation = shell(
                model.TwoArmDirectBranchRouteRealization,
                feeder=feeder, source_rewritten_arm=source_arm,
                projected_replacement_arm=projected_arm,
                untouched_arm=untouched,
                relation_id=route_realization_id((
                    "two_arm_direct_branch", feeder, source_arm,
                    projected_arm, untouched,
                )),
            )
        else:
            projected_blocks = {
                row.block_ref: row for row in projected.blocks
            }
            helper_owner = model.AnchoredBlockRef(
                step.fallthrough_helper_block_id,
                projected_blocks[
                    step.fallthrough_helper_block_id
                ].anchor_ea,
            )
            creation_spec_digests = canonical_patch_step_descriptor(
                plan, route_fact.step_index,
            ).new_block_spec_digests
            relation = shell(
                model.BranchFallthroughHelperRouteRealization,
                feeder=feeder, source_fallthrough=untouched,
                untouched_conditional_arm=untouched, helper=helper_owner,
                semantic_target=projected_arm,
                creation_spec_digests=creation_spec_digests,
                relation_id=route_realization_id((
                    "branch_fallthrough_helper", feeder, untouched,
                    untouched, helper_owner, projected_arm,
                    creation_spec_digests,
                )),
            )
        relation_subset_owners = {feeder, projected_arm, untouched}
        route_step_kind = PatchStepKind.REDIRECT_BRANCH
        clone_owner_by_source = {}
    else:
        from d810.transforms.plan import PatchConditionalRedirect
        from d810.transforms.unflatten_authority.proposal import (
            canonical_patch_step_descriptor,
        )

        assert type(step) is PatchConditionalRedirect
        projected_blocks = {row.block_ref: row for row in projected.blocks}
        feeder = model.AnchoredBlockRef(
            step.source_serial, source_blocks[step.source_serial].anchor_ea,
        )
        proof_source = model.AnchoredBlockRef(
            step.ref_block, source_blocks[step.ref_block].anchor_ea,
        )
        replacement_clone = model.AnchoredBlockRef(
            step.block_id, projected_blocks[step.block_id].anchor_ea,
        )
        fallthrough_helper = model.AnchoredBlockRef(
            step.fallthrough_block_id,
            projected_blocks[step.fallthrough_block_id].anchor_ea,
        )
        arms = tuple(sorted((
            model.RealizedConditionalArm(
                SemanticEdgeRole.CONDITIONAL_FALLTHROUGH,
                model.AnchoredBlockRef(
                    step.fallthrough_target,
                    source_blocks[step.fallthrough_target].anchor_ea,
                ),
            ),
            model.RealizedConditionalArm(
                SemanticEdgeRole.CONDITIONAL_TAKEN,
                model.AnchoredBlockRef(
                    step.conditional_target,
                    source_blocks[step.conditional_target].anchor_ea,
                ),
            ),
        ), key=lambda arm: arm.role.value))
        creation_spec_digests = canonical_patch_step_descriptor(
            plan, route_fact.step_index,
        ).new_block_spec_digests
        relation = shell(
            model.ClonedConditionalRouteRealization,
            feeder=feeder, proof_source=proof_source,
            old_target=proof_source, replacement_clone=replacement_clone,
            fallthrough_helper=fallthrough_helper, arms=arms,
            creation_spec_digests=creation_spec_digests,
            relation_id=route_realization_id((
                "cloned_conditional", feeder, proof_source, proof_source,
                replacement_clone, fallthrough_helper, arms,
                creation_spec_digests,
            )),
        )
        relation_subset_owners = {
            feeder, proof_source, *(arm.target for arm in arms),
        }
        route_step_kind = PatchStepKind.CONDITIONAL_REDIRECT
        clone_owner_by_source = {
            proof_source.ref: replacement_clone.ref,
        }

    exact_bindings = {}
    for claim in exact_claims:
        source_row = next(
            row for row in source.effects
            if row.owner_ref == claim.effect_subject.locator.owner_ref
            and row.instruction_ea == claim.discarded_effect_ea
            and row.effect_kind is claim.effect_subject.locator.effect_kind
        )
        binding = identified(
            model.ExactEffectBindingResult, "binding_result_id",
            exact_effect_binding_result_id,
            authority_id=values["authority_id"],
            source_authority_id=authority.source_authority_id,
            attempt_id=attempt,
            phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
            claim=claim, proof_id=claim.route_proof_ids[0],
            supporting_route_relation_id=relation.relation_id,
            source_subject_ids=tuple(sorted({
                claim.effect_subject.subject_id,
                claim.source_subject.subject_id,
                claim.predicate_subject.subject_id,
                claim.selected_target_subject.subject_id,
                claim.discarded_effect_subject.subject_id,
            })),
            source_site=effect_coordinate(source_row),
            source_inventory_digest=source.inventory_digest,
            projected_inventory_digest=projected.inventory_digest,
            source_fingerprint=source.graph_fingerprint,
            projected_fingerprint=projected.graph_fingerprint,
            source_generation=source.generation,
            projected_generation=projected.generation,
            raw_effect_gate_fact_id=raw.fact_id,
        )
        exact_bindings[(source_row.owner_ref, source_row.instruction_ea)] = binding

    local_bindings = {}
    for claim in local_claims:
        source_row = next(
            row for row in source.effects
            if row.owner_ref == claim.owner_subject.block_ref
            and row.instruction_ea == claim.host_ea
        )
        projected_block = next(
            block for block in projected.blocks
            if block.block_ref == claim.owner_subject.block_ref
        )
        observation = next(
            item for item in projected_block.instruction_observations
            if item.instruction_ea == claim.host_ea
            and item.instruction_kind is InsnKind.MOV
        )
        scalarized = shell(
            model.ScalarizedInstructionCoordinate,
            owner=model.AnchoredBlockRef(
                projected_block.block_ref, projected_block.anchor_ea,
            ),
            instruction_ordinal=observation.ordinal,
            instruction_ea=observation.instruction_ea,
            instruction_kind=InsnKind.MOV, opcode=observation.opcode,
            raw_opcode=observation.raw_opcode, width=observation.width,
            display_text_digest=authority_id((
                "scalarized-display-text", observation.display_text,
            )),
        )
        fact = next(
            fact for fact in values["patch_step_facts"]
            if fact.step_index == claim.step_index
        )
        binding = identified(
            model.LocalAliasScalarizationBindingResult, "binding_result_id",
            local_alias_binding_result_id,
            authority_id=values["authority_id"], attempt_id=attempt,
            phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
            claim=claim, source_subject_id=claim.owner_subject.subject_id,
            source_site=effect_coordinate(source_row),
            scalarized_site=scalarized, patch_step_fact=fact,
            patch_step_fact_id=patch_step_fact_id(fact),
            source_inventory_digest=source.inventory_digest,
            projected_inventory_digest=projected.inventory_digest,
            source_fingerprint=source.graph_fingerprint,
            projected_fingerprint=projected.graph_fingerprint,
            source_generation=source.generation,
            projected_generation=projected.generation,
        )
        local_bindings[(source_row.owner_ref, source_row.instruction_ea)] = binding

    effect_results = []
    for source_row in source.effects:
        if source_row.owner_serial not in source.reachable_serials:
            continue
        key = (source_row.owner_ref, source_row.instruction_ea)
        exact_binding = exact_bindings.get(key)
        local_binding = local_bindings.get(key)
        projected_owner = clone_owner_by_source.get(
            source_row.owner_ref, source_row.owner_ref,
        )
        projected_rows = tuple(
            row for row in projected.effects
            if row.owner_serial in projected.reachable_serials
            and row.owner_ref == projected_owner
            and row.instruction_ordinal == source_row.instruction_ordinal
            and row.instruction_ea == source_row.instruction_ea
            and row.effect_kind is source_row.effect_kind
            and row.opcode == source_row.opcode and row.width == source_row.width
        )
        projected_row = projected_rows[0] if len(projected_rows) == 1 else None
        if projected_row is not None:
            is_clone = source_row.owner_ref in clone_owner_by_source
            outcome = (
                model.ProjectedEffectSiteOutcome.RELATION_CLONED
                if is_clone else model.ProjectedEffectSiteOutcome.PRESERVED
            )
            projected_subject_id = subject_id(projected, projected_row)
            projected_site = effect_coordinate(projected_row)
            scalarized_site = None
            lineage = (
                model.ProjectedSiteLineageKind.RELATION_CLONE
                if is_clone else model.ProjectedSiteLineageKind.SAME_OWNER
            )
            relation_id = relation.relation_id if is_clone else None
            supporting_claim_id = supporting_binding_id = None
            latent = exact_binding.binding_result_id if exact_binding is not None else None
            patch_index = patch_digest = None
        elif local_binding is not None:
            outcome = model.ProjectedEffectSiteOutcome.LOCAL_ALIAS_SCALARIZED
            projected_subject_id = projected_site = None
            scalarized_site = local_binding.scalarized_site
            lineage = None
            supporting_claim_id = local_binding.claim.claim_id
            supporting_binding_id = local_binding.binding_result_id
            latent = None
            patch_index = local_binding.claim.step_index
            patch_digest = local_binding.claim.step_digest
            relation_id = None
        else:
            assert exact_binding is not None
            outcome = model.ProjectedEffectSiteOutcome.EXACT_INFEASIBLE
            projected_subject_id = projected_site = scalarized_site = lineage = None
            supporting_claim_id = exact_binding.claim.claim_id
            supporting_binding_id = exact_binding.binding_result_id
            latent = None
            patch_index = patch_digest = None
            relation_id = None
        source_subject = (
            exact_binding.claim.effect_subject.subject_id if exact_binding else
            subject_id(source, source_row) if local_binding else
            subject_id(source, source_row)
        )
        effect_results.append(identified(
            model.ProjectedEffectSiteResult, "result_id",
            projected_effect_site_result_id,
            authority_id=values["authority_id"], attempt_id=attempt,
            phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
            source_subject_id=source_subject,
            source_site=effect_coordinate(source_row), outcome=outcome,
            projected_subject_id=projected_subject_id,
            projected_site=projected_site, scalarized_site=scalarized_site,
            lineage_kind=lineage, relation_id=relation_id,
            supporting_claim_id=supporting_claim_id,
            supporting_binding_result_id=supporting_binding_id,
            latent_exact_binding_result_id=latent,
            patch_step_index=patch_index, patch_step_digest=patch_digest,
            raw_effect_gate_fact_id=raw.fact_id,
        ))
    effect_results = tuple(sorted(effect_results, key=lambda item: item.result_id))

    terminal_results = []
    for source_row in source.terminals:
        if source_row.owner_serial not in source.reachable_serials:
            continue
        projected_owner = clone_owner_by_source.get(
            source_row.owner_ref, source_row.owner_ref,
        )
        projected_row = next(
            row for row in projected.terminals
            if row.owner_serial in projected.reachable_serials
            and row.owner_ref == projected_owner
            and row.instruction_ea == source_row.instruction_ea
            and row.instruction_ordinal == source_row.instruction_ordinal
            and row.terminal_kind is source_row.terminal_kind
        )
        is_clone = source_row.owner_ref in clone_owner_by_source
        terminal_results.append(identified(
            model.ProjectedTerminalSiteResult, "result_id",
            projected_terminal_site_result_id,
            authority_id=values["authority_id"], attempt_id=attempt,
            phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
            source_subject_id=subject_id(source, source_row),
            source_site=terminal_coordinate(source_row),
            outcome=(
                model.ProjectedTerminalSiteOutcome.RELATION_CLONED
                if is_clone else model.ProjectedTerminalSiteOutcome.PRESERVED
            ),
            projected_subject_id=subject_id(projected, projected_row),
            projected_site=terminal_coordinate(projected_row),
            lineage_kind=(
                model.ProjectedSiteLineageKind.RELATION_CLONE
                if is_clone else model.ProjectedSiteLineageKind.SAME_OWNER
            ),
            relation_id=relation.relation_id if is_clone else None,
        ))
    terminal_results = tuple(sorted(
        terminal_results, key=lambda item: item.result_id,
    ))
    exact_values = tuple(sorted(
        exact_bindings.values(), key=lambda item: item.binding_result_id,
    ))
    local_values = tuple(sorted(
        local_bindings.values(), key=lambda item: item.binding_result_id,
    ))
    derived_id = derived_effect_gate_fact_id(
        raw.fact_id, tuple(item.result_id for item in effect_results),
    )
    phase = identified(
        model.ProjectedSemanticSitePhaseResult, "result_id",
        projected_semantic_site_phase_result_id,
        authority_id=values["authority_id"],
        source_authority_id=authority.source_authority_id,
        attempt_id=attempt,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        plan_id=plan.plan_id, source_inventory_digest=source.inventory_digest,
        projected_inventory_digest=projected.inventory_digest,
        source_fingerprint=source.graph_fingerprint,
        projected_fingerprint=projected.graph_fingerprint,
        source_generation=source.generation,
        projected_generation=projected.generation,
        relation_ids=(relation.relation_id,), raw_effect_gate_fact=raw,
        exact_effect_bindings=exact_values,
        local_alias_bindings=local_values,
        effect_results=effect_results, terminal_results=terminal_results,
        derived_effect_gate_fact_id=derived_id,
    )
    subset_effect_ids = tuple(
        item.result_id for item in effect_results
        if item.source_site.owner in relation_subset_owners
    )
    subset_terminal_ids = tuple(
        item.result_id for item in terminal_results
        if item.source_site.owner in relation_subset_owners
    )
    preservation = identified(
        model.ProjectedRouteSitePreservation, "preservation_id",
        projected_route_site_preservation_id,
        authority_id=values["authority_id"], attempt_id=attempt,
        relation_id=relation.relation_id,
        site_phase_result_id=phase.result_id,
        effect_result_ids=subset_effect_ids,
        terminal_result_ids=subset_terminal_ids,
    )
    row_id = projected_route_realization_row_id((
        route_claim.claim_id, route_claim.route_proof_ids[0],
        route_claim.retired_route_subject.subject_id, relation,
        route_fact.step_index, route_step_kind,
        route_fact.step_digest, source.graph_fingerprint,
        projected.graph_fingerprint, source.generation,
        projected.generation, preservation,
    ))
    row = shell(
        model.ProjectedRouteRealizationRow,
        claim_id=route_claim.claim_id,
        proof_id=route_claim.route_proof_ids[0],
        route_subject_id=route_claim.retired_route_subject.subject_id,
        relation=relation, site_preservation=preservation,
        plan_step_index=route_fact.step_index,
        plan_step_type=route_step_kind,
        plan_step_digest=route_fact.step_digest,
        source_fingerprint=source.graph_fingerprint,
        projected_fingerprint=projected.graph_fingerprint,
        source_generation=source.generation,
        projected_generation=projected.generation, row_id=row_id,
    )
    realization_id = projected_route_realization_id((
        authority.source_authority_id, attempt, plan.plan_id, (row,),
        projected.inventory_digest, projected.graph_fingerprint,
        projected.generation, phase,
    ))
    return {
        "relation": relation, "row": row, "phase": phase,
        "preservation": preservation, "effect_results": effect_results,
        "terminal_results": terminal_results,
        "exact_bindings": exact_values, "local_bindings": local_values,
        "realization_id": realization_id,
    }


def _task_15_independent_shared_publication(values):
    """Derive the two DIRECT rows and shared site closure from inputs."""
    from d810.transforms.unflatten_authority.ids import (
        derived_effect_gate_fact_id, projected_effect_site_result_id,
        projected_route_site_preservation_id,
        projected_semantic_site_phase_result_id,
        projected_terminal_site_result_id,
    )

    def shell(cls, **fields):
        value = object.__new__(cls)
        for name in cls.__dataclass_fields__:
            object.__setattr__(value, name, fields[name])
        return value

    def identified(cls, identity_name, identity_factory, **fields):
        fields[identity_name] = "sha256:" + "0" * 64
        value = shell(cls, **fields)
        object.__setattr__(value, identity_name, identity_factory(value))
        return value

    def subject_id(inventory, row):
        matches = []
        for subject in inventory.subjects:
            locator = subject.locator
            if type(row) is model.InventoryEffectSite and (
                getattr(locator, "owner_ref", None) == row.owner_ref
                and getattr(locator, "instruction_ea", None)
                == row.instruction_ea
                and getattr(locator, "effect_kind", None) is row.effect_kind
            ):
                matches.append(subject)
            if type(row) is model.InventoryTerminalSite and (
                getattr(locator, "block_ref", None) == row.owner_ref
                and getattr(locator, "instruction_ea", None)
                == row.instruction_ea
                and getattr(locator, "terminal_kind", None)
                is row.terminal_kind
            ):
                matches.append(subject)
        assert len(matches) == 1
        return matches[0].subject_id

    def effect_coordinate(row):
        return shell(
            model.EffectSiteCoordinate,
            owner=model.AnchoredBlockRef(
                row.owner_ref, row.owner_anchor_ea,
            ),
            instruction_ordinal=row.instruction_ordinal,
            instruction_ea=row.instruction_ea,
            effect_kind=row.effect_kind, opcode=row.opcode, width=row.width,
        )

    def terminal_coordinate(row):
        return shell(
            model.TerminalSiteCoordinate,
            owner=model.AnchoredBlockRef(
                row.owner_ref, row.owner_anchor_ea,
            ),
            instruction_ordinal=row.instruction_ordinal,
            instruction_ea=row.instruction_ea,
            terminal_kind=row.terminal_kind,
        )

    source = values["source_inventory"]
    projected = values["projected_inventory"]
    authority = values["source_authority"]
    plan = values["plan"]
    attempt = values["attempt_id"]
    raw = values["raw_effect_gate_fact"]
    claims = tuple(
        claim for claim in values["claims"]
        if type(claim) is model.EquivalentSemanticRouteClaim
    )
    proofs = authority.proposal.route_evidence.route_proofs
    facts = tuple(
        fact for fact in values["patch_step_facts"]
        if fact.step_type == "PatchRedirectGoto"
    )
    assert len(claims) == len(proofs) == len(plan.steps) == len(facts) == 2
    assert not tuple(
        claim for claim in values["claims"]
        if type(claim) in {
            model.ExactInfeasibleEffectClaim,
            model.LocalAliasEffectScalarizationClaim,
        }
    )
    source_blocks = {row.block_ref: row for row in source.blocks}
    relations_by_step = {}
    claim_by_step = {}
    proof_by_step = {}
    fact_by_step = {}
    for step_index, step in enumerate(plan.steps):
        fact = next(fact for fact in facts if fact.step_index == step_index)
        proof = next(
            proof for proof in proofs
            if proof.source_identity == step.from_serial.identity
        )
        claim = next(
            claim for claim in claims
            if claim.route_proof_ids == (proof.proof_id,)
        )
        assert fact.owner_ref == step.from_serial
        feeder = model.AnchoredBlockRef(
            step.from_serial, source_blocks[step.from_serial].anchor_ea,
        )
        old_target = model.AnchoredBlockRef(
            step.old_target, source_blocks[step.old_target].anchor_ea,
        )
        new_target = model.AnchoredBlockRef(
            step.new_target, source_blocks[step.new_target].anchor_ea,
        )
        relation = shell(
            model.DirectRouteRealization,
            feeder=feeder, old_target=old_target, new_target=new_target,
            relation_id=route_realization_id((
                "direct", feeder, old_target, new_target,
            )),
        )
        relations_by_step[step_index] = relation
        claim_by_step[step_index] = claim
        proof_by_step[step_index] = proof
        fact_by_step[step_index] = fact
    relations = tuple(relations_by_step.values())
    assert len({relation.relation_id for relation in relations}) == 2
    common_target = relations[0].new_target
    assert all(relation.new_target == common_target for relation in relations)

    source_effects = tuple(
        row for row in source.effects if row.owner_serial in source.reachable_serials
    )
    source_terminals = tuple(
        row for row in source.terminals
        if row.owner_serial in source.reachable_serials
    )
    assert len(source_effects) == len(source_terminals) == 1
    source_effect = source_effects[0]
    source_terminal = source_terminals[0]
    assert model.AnchoredBlockRef(
        source_effect.owner_ref, source_effect.owner_anchor_ea,
    ) == common_target
    assert model.AnchoredBlockRef(
        source_terminal.owner_ref, source_terminal.owner_anchor_ea,
    ) == common_target
    projected_effect = next(
        row for row in projected.effects
        if row.owner_serial in projected.reachable_serials
        and row.owner_ref == source_effect.owner_ref
        and row.owner_anchor_ea == source_effect.owner_anchor_ea
        and row.instruction_ordinal == source_effect.instruction_ordinal
        and row.instruction_ea == source_effect.instruction_ea
        and row.effect_kind is source_effect.effect_kind
        and row.opcode == source_effect.opcode
        and row.width == source_effect.width
    )
    projected_terminal = next(
        row for row in projected.terminals
        if row.owner_serial in projected.reachable_serials
        and row.owner_ref == source_terminal.owner_ref
        and row.owner_anchor_ea == source_terminal.owner_anchor_ea
        and row.instruction_ordinal == source_terminal.instruction_ordinal
        and row.instruction_ea == source_terminal.instruction_ea
        and row.terminal_kind is source_terminal.terminal_kind
    )
    effect = identified(
        model.ProjectedEffectSiteResult, "result_id",
        projected_effect_site_result_id,
        authority_id=values["authority_id"], attempt_id=attempt,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        source_subject_id=subject_id(source, source_effect),
        source_site=effect_coordinate(source_effect),
        outcome=model.ProjectedEffectSiteOutcome.PRESERVED,
        projected_subject_id=subject_id(projected, projected_effect),
        projected_site=effect_coordinate(projected_effect),
        scalarized_site=None,
        lineage_kind=model.ProjectedSiteLineageKind.SAME_OWNER,
        relation_id=None, supporting_claim_id=None,
        supporting_binding_result_id=None,
        latent_exact_binding_result_id=None,
        patch_step_index=None, patch_step_digest=None,
        raw_effect_gate_fact_id=raw.fact_id,
    )
    terminal = identified(
        model.ProjectedTerminalSiteResult, "result_id",
        projected_terminal_site_result_id,
        authority_id=values["authority_id"], attempt_id=attempt,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        source_subject_id=subject_id(source, source_terminal),
        source_site=terminal_coordinate(source_terminal),
        outcome=model.ProjectedTerminalSiteOutcome.PRESERVED,
        projected_subject_id=subject_id(projected, projected_terminal),
        projected_site=terminal_coordinate(projected_terminal),
        lineage_kind=model.ProjectedSiteLineageKind.SAME_OWNER,
        relation_id=None,
    )
    derived_id = derived_effect_gate_fact_id(raw.fact_id, (effect.result_id,))
    phase = identified(
        model.ProjectedSemanticSitePhaseResult, "result_id",
        projected_semantic_site_phase_result_id,
        authority_id=values["authority_id"],
        source_authority_id=authority.source_authority_id,
        attempt_id=attempt,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        plan_id=plan.plan_id, source_inventory_digest=source.inventory_digest,
        projected_inventory_digest=projected.inventory_digest,
        source_fingerprint=source.graph_fingerprint,
        projected_fingerprint=projected.graph_fingerprint,
        source_generation=source.generation,
        projected_generation=projected.generation,
        relation_ids=tuple(sorted(
            relation.relation_id for relation in relations
        )),
        raw_effect_gate_fact=raw, exact_effect_bindings=(),
        local_alias_bindings=(), effect_results=(effect,),
        terminal_results=(terminal,), derived_effect_gate_fact_id=derived_id,
    )
    rows = []
    preservations = []
    for step_index in range(2):
        relation = relations_by_step[step_index]
        claim = claim_by_step[step_index]
        proof = proof_by_step[step_index]
        fact = fact_by_step[step_index]
        preservation = identified(
            model.ProjectedRouteSitePreservation, "preservation_id",
            projected_route_site_preservation_id,
            authority_id=values["authority_id"], attempt_id=attempt,
            relation_id=relation.relation_id,
            site_phase_result_id=phase.result_id,
            effect_result_ids=(effect.result_id,),
            terminal_result_ids=(terminal.result_id,),
        )
        row_id = projected_route_realization_row_id((
            claim.claim_id, proof.proof_id,
            claim.retired_route_subject.subject_id, relation,
            fact.step_index, PatchStepKind.REDIRECT_GOTO, fact.step_digest,
            source.graph_fingerprint, projected.graph_fingerprint,
            source.generation, projected.generation, preservation,
        ))
        rows.append(shell(
            model.ProjectedRouteRealizationRow,
            claim_id=claim.claim_id, proof_id=proof.proof_id,
            route_subject_id=claim.retired_route_subject.subject_id,
            relation=relation, site_preservation=preservation,
            plan_step_index=fact.step_index,
            plan_step_type=PatchStepKind.REDIRECT_GOTO,
            plan_step_digest=fact.step_digest,
            source_fingerprint=source.graph_fingerprint,
            projected_fingerprint=projected.graph_fingerprint,
            source_generation=source.generation,
            projected_generation=projected.generation, row_id=row_id,
        ))
        preservations.append(preservation)
    rows = tuple(sorted(rows, key=lambda row: row.row_id))
    preservations = tuple(sorted(
        preservations, key=lambda item: item.preservation_id,
    ))
    realization_id = projected_route_realization_id((
        authority.source_authority_id, attempt, plan.plan_id, rows,
        projected.inventory_digest, projected.graph_fingerprint,
        projected.generation, phase,
    ))
    realization = shell(
        model.ProjectedRouteRealization,
        source_authority=authority, attempt_id=attempt, plan_id=plan.plan_id,
        rows=rows, site_phase_result=phase,
        projected_inventory_digest=projected.inventory_digest,
        projected_fingerprint=projected.graph_fingerprint,
        projected_generation=projected.generation,
        realization_id=realization_id,
    )
    accepted = shell(
        model.ProjectedRouteRealizationAccepted, realization=realization,
    )
    return {
        "claims": claim_by_step, "proofs": proof_by_step,
        "facts": fact_by_step, "relations": relations_by_step,
        "common_target": common_target, "effect": effect,
        "terminal": terminal, "phase": phase,
        "preservations": preservations, "rows": rows,
        "realization": realization, "accepted": accepted,
    }


def _assert_task_15_direct_publication(values, accepted, expected):
    """Check the exact DIRECT route ID preimages and public closure validators."""
    assert type(accepted) is model.ProjectedRouteRealizationAccepted
    realization = accepted.realization
    assert len(realization.rows) == 1
    row = realization.rows[0]
    relation = row.relation
    assert type(relation) is model.DirectRouteRealization
    assert relation == expected["relation"]
    assert row == expected["row"]
    assert realization.realization_id == expected["realization_id"]
    phase = realization.site_phase_result
    assert phase == expected["phase"]
    assert phase.exact_effect_bindings == expected["exact_bindings"]
    assert phase.local_alias_bindings == expected["local_bindings"]
    assert phase.effect_results == expected["effect_results"]
    assert phase.terminal_results == expected["terminal_results"]
    assert row.site_preservation == expected["preservation"]
    bind.validate_projected_site_phase_result(phase)
    bind.validate_projected_route_realization(realization)
    bind.validate_projected_route_realization_result(accepted)
    return phase


