@dataclass(frozen=True, slots=True)
class _MechanicalFamilyCase:
    family: str
    build: Callable[[], object]
    values_from_case: Callable[[object], dict[str, object]]
    assert_publication: Callable[..., object]
    relation_anchors: Callable[[object, object], tuple[model.AnchoredBlockRef, ...]]


@dataclass(frozen=True, slots=True)
class _MechanicalMutationSpec:
    row: str
    boundary: Literal["DRAFT", "GRAPH", "MODEL"]
    site_kind: Literal["effect", "terminal", "aggregate"]
    families: tuple[str, ...]
    mutate: Callable[..., object]
    expected_reason: str
    expected_scope: model.RouteRealizationFailureScope | None
    weakening_killed: str


@dataclass(frozen=True, slots=True)
class _MechanicalBaseline:
    family: _MechanicalFamilyCase
    case: object
    values: dict[str, object]
    expected: dict[str, object]
    accepted: model.ProjectedRouteRealizationAccepted
    draft: object
    drafter_kwargs: dict[str, object]
    validator_kwargs: dict[str, object]
    events: object
    publication_counts: tuple[int, ...]


@dataclass(frozen=True, slots=True)
class _MechanicalDraftTarget:
    site_kind: Literal["effect", "terminal"]
    disposition_index: int
    disposition: object
    source_row: object
    projected_row: object
    relation_draft: object
    claim: object
    proof: object
    patch_step_fact: model.PatchStepEvidencePayload
    owner_rows: tuple[object, ...]


@dataclass(frozen=True, slots=True)
class _MechanicalGraphMutationCase:
    family: _MechanicalFamilyCase
    mutate: Callable[[object], object]


def _mechanical_sorted_anchors(
    anchors: tuple[model.AnchoredBlockRef, ...],
) -> tuple[model.AnchoredBlockRef, ...]:
    return tuple(sorted(set(anchors), key=canonical_bytes))


def _mechanical_direct_anchors(_case, relation):
    assert type(relation) is model.DirectRouteRealization
    return _mechanical_sorted_anchors((
        relation.feeder, relation.old_target, relation.new_target,
    ))


def _mechanical_lowered_anchors(_case, relation):
    assert type(relation) is model.LoweredConditionalRouteRealization
    return _mechanical_sorted_anchors((
        relation.feeder, relation.proof_source, relation.old_target,
        *(arm.target for arm in relation.arms),
    ))


def _mechanical_cloned_conditional_anchors(_case, relation):
    assert type(relation) is model.ClonedConditionalRouteRealization
    return _mechanical_sorted_anchors((
        relation.feeder, relation.proof_source, relation.old_target,
        relation.replacement_clone, relation.fallthrough_helper,
        *(arm.target for arm in relation.arms),
    ))


def _mechanical_two_arm_anchors(_case, relation):
    assert type(relation) is model.TwoArmDirectBranchRouteRealization
    return _mechanical_sorted_anchors((
        relation.feeder, relation.source_rewritten_arm,
        relation.projected_replacement_arm, relation.untouched_arm,
    ))


def _mechanical_branch_helper_anchors(_case, relation):
    assert type(relation) is model.BranchFallthroughHelperRouteRealization
    return _mechanical_sorted_anchors((
        relation.feeder, relation.source_fallthrough,
        relation.untouched_conditional_arm, relation.helper,
        relation.semantic_target,
    ))


def _mechanical_corridor_anchors(_case, relation):
    assert type(relation) is model.ClonedRouteCorridorRealization
    return _mechanical_sorted_anchors((
        relation.predecessor, relation.proof_source,
        relation.descriptor_old_target, relation.terminal_continuation,
        *relation.source_corridor, *relation.cloned_corridor,
        relation.semantic_target,
        *(prefix.source_owner for prefix in relation.semantic_prefixes),
        *(prefix.clone_owner for prefix in relation.semantic_prefixes),
        *(prefix.projected_successor for prefix in relation.semantic_prefixes),
    ))


