def _capture_mechanical_baseline(family: _MechanicalFamilyCase) -> _MechanicalBaseline:
    import gc

    case = family.build()
    values = family.values_from_case(case)
    expected = _task_15_independent_expected_publication(values)
    drafted = []
    validated = []
    real_drafter = bind._draft_projected_site_closure
    real_validator = bind._validate_projected_site_closure_draft

    def capture_draft(**kwargs):
        draft = real_drafter(**kwargs)
        drafted.append((draft, kwargs))
        return draft

    def capture_validation(draft, **kwargs):
        validated.append((draft, kwargs))
        return real_validator(draft, **kwargs)

    with (
        patch.object(
            bind, "_draft_projected_site_closure", side_effect=capture_draft,
        ),
        patch.object(
            bind, "_validate_projected_site_closure_draft",
            side_effect=capture_validation,
        ),
        patch.object(
            transaction_api, "_build_semantic_graph_inventory",
            side_effect=AssertionError("mechanical baseline inventory replay"),
        ),
        patch.object(
            bind, "bind_source_route_authority",
            side_effect=AssertionError("mechanical baseline source replay"),
        ),
        patch.object(
            route_model, "bind_canonical_semantic_evidence_result",
            side_effect=AssertionError("mechanical baseline route replay"),
        ),
        patch.object(
            producer_api, "validate_exact_effect_claim_semantics",
            side_effect=AssertionError("mechanical baseline producer replay"),
        ),
        patch.object(
            evaluate, "_classify_effect_site",
            side_effect=AssertionError("mechanical baseline evaluator replay"),
        ),
    ):
        events = _task_15_observe_publication_events(
            lambda: bind.realize_projected_routes(**values),
        )

    assert len(drafted) == len(validated) == 1
    draft, drafter_kwargs = drafted[0]
    validated_draft, validator_kwargs = validated[0]
    assert validated_draft is draft
    for name in (
        "source_authority", "plan", "source_inventory",
        "projected_inventory", "claims", "patch_step_facts",
        "raw_effect_gate_fact", "legacy_effective_gate_facts",
        "attempt_id", "drafts", "owner_index",
    ):
        assert validator_kwargs[name] is drafter_kwargs[name]
    assert type(validator_kwargs["route_publications"]) is tuple
    assert validator_kwargs["route_publications"]
    assert len({id(value) for value, _identity in validator_kwargs[
        "route_publications"
    ]}) == len(validator_kwargs["route_publications"])
    accepted = events.result
    assert type(accepted) is model.ProjectedRouteRealizationAccepted
    family.assert_publication(values, accepted, expected)
    assert len(events.commits) == 1
    assert events.commits[0]
    assert all(
        type(value) in events.accepted_types
        for value in (*events.deferred, *events.commits[0], *events.ordinary)
    )
    assert not any(
        type(value) in {
            model.RouteRealizationFailure,
            model.ProjectedRouteRealizationRejected,
        }
        for value in events.ordinary
    )
    expected_relation = expected["relation"]
    assert family.relation_anchors(case, expected_relation)
    gc.collect()
    return _MechanicalBaseline(
        family=family, case=case, values=values, expected=expected,
        accepted=accepted, draft=draft, drafter_kwargs=drafter_kwargs,
        validator_kwargs=validator_kwargs, events=events,
        publication_counts=_task_15_publication_type_counts(),
    )


def _mechanical_draft_target(
    baseline: _MechanicalBaseline, site_kind: Literal["effect", "terminal"],
    *, terminal_kind: model.TerminalKind | None = None,
) -> _MechanicalDraftTarget:
    draft = baseline.draft
    dispositions = (
        draft.effect_dispositions
        if site_kind == "effect" else draft.terminal_dispositions
    )
    subset_name = (
        "effect_dispositions"
        if site_kind == "effect" else "terminal_dispositions"
    )
    candidates = tuple(
        (index, disposition)
        for index, disposition in enumerate(dispositions)
        if disposition.owner_mapping is not None
        and disposition.relation_draft is not None
        and (
            terminal_kind is None
            or disposition.projected_row.terminal_kind is terminal_kind
        )
        and any(
            any(disposition is item for item in getattr(subset, subset_name))
            for subset in draft.route_subsets
        )
    )
    assert candidates
    index, disposition = candidates[0]
    relation_draft = disposition.relation_draft
    claim = relation_draft.claim
    proof = relation_draft.proof
    assert any(
        relation_draft is item for item in baseline.drafter_kwargs["drafts"]
    )
    assert any(
        disposition.owner_mapping is item
        for item in baseline.drafter_kwargs["owner_index"].owner_rows
    )
    assert any(
        disposition.source_row is item
        for item in getattr(
            baseline.values["source_inventory"],
            "effects" if site_kind == "effect" else "terminals",
        )
    )
    assert any(
        disposition.projected_row is item
        for item in getattr(
            baseline.values["projected_inventory"],
            "effects" if site_kind == "effect" else "terminals",
        )
    )
    assert any(claim is item for item in baseline.values["claims"])
    assert any(
        proof is item
        for item in baseline.values[
            "source_authority"
        ].proposal.route_evidence.route_proofs
    )
    assert relation_draft.facts
    patch_step_fact = relation_draft.facts[0]
    assert any(
        patch_step_fact is fact
        for fact in baseline.values["patch_step_facts"]
    )
    return _MechanicalDraftTarget(
        site_kind=site_kind, disposition_index=index,
        disposition=disposition, source_row=disposition.source_row,
        projected_row=disposition.projected_row,
        relation_draft=relation_draft, claim=claim, proof=proof,
        patch_step_fact=patch_step_fact,
        owner_rows=tuple(baseline.drafter_kwargs["owner_index"].owner_rows),
    )


def _mechanical_stop_target(
    baseline: _MechanicalBaseline, site_kind: Literal["effect", "terminal"],
) -> _MechanicalDraftTarget:
    assert site_kind == "terminal"
    target = _mechanical_draft_target(
        baseline, site_kind, terminal_kind=model.TerminalKind.STOP,
    )
    assert target.source_row.terminal_kind is model.TerminalKind.STOP
    assert target.projected_row.terminal_kind is model.TerminalKind.STOP
    assert target.source_row.instruction_ordinal is None
    assert target.projected_row.instruction_ordinal is None
    with pytest.raises(ValueError, match="STOP terminals must be synthesized"):
        replace(target.projected_row, instruction_ordinal=0)
    return target


def _mechanical_clone_effect_target(
    baseline: _MechanicalBaseline,
) -> _MechanicalDraftTarget:
    candidates = tuple(
        (index, disposition)
        for index, disposition in enumerate(
            baseline.draft.effect_dispositions,
        )
        if disposition.owner_mapping is not None
        and disposition.owner_mapping.lineage
        is model.ProjectedSiteLineageKind.RELATION_CLONE
        and disposition.relation_draft is not None
    )
    assert candidates
    index, disposition = candidates[0]
    relation_draft = disposition.relation_draft
    assert type(relation_draft.relation) in {
        model.ClonedConditionalRouteRealization,
        model.ClonedRouteCorridorRealization,
    }
    return _MechanicalDraftTarget(
        site_kind="effect", disposition_index=index,
        disposition=disposition, source_row=disposition.source_row,
        projected_row=disposition.projected_row,
        relation_draft=relation_draft, claim=relation_draft.claim,
        proof=relation_draft.proof,
        patch_step_fact=relation_draft.facts[0],
        owner_rows=tuple(baseline.drafter_kwargs["owner_index"].owner_rows),
    )


def _mechanical_replace_disposition(draft, target, replacement):
    field = (
        "effect_dispositions"
        if target.site_kind == "effect" else "terminal_dispositions"
    )
    dispositions = getattr(draft, field)
    assert dispositions[target.disposition_index] is target.disposition
    return replace(
        draft,
        **{
            field: (
                *dispositions[:target.disposition_index], replacement,
                *dispositions[target.disposition_index + 1:],
            ),
        },
    )


def _mechanical_equal_value_clone(draft, target):
    cloned_row = replace(target.projected_row)
    assert cloned_row == target.projected_row
    assert cloned_row is not target.projected_row
    changed = _mechanical_replace_disposition(
        draft, target,
        replace(target.disposition, projected_row=cloned_row),
    )
    return changed, cloned_row


def _mutate_m01_omitted_source_site(draft, target, _projected_inventory):
    field = (
        "effect_dispositions"
        if target.site_kind == "effect" else "terminal_dispositions"
    )
    dispositions = getattr(draft, field)
    assert dispositions[target.disposition_index] is target.disposition
    return replace(draft, **{
        field: (
            *dispositions[:target.disposition_index],
            *dispositions[target.disposition_index + 1:],
        ),
    })


def _mutate_m02_duplicate_projected_site(
    draft, target, _projected_inventory,
):
    field = (
        "effect_dispositions"
        if target.site_kind == "effect" else "terminal_dispositions"
    )
    dispositions = getattr(draft, field)
    return replace(draft, **{field: (*dispositions, target.disposition)})


def _mutate_m05_foreign_clone_owner(draft, target, foreign_mapping):
    assert target.site_kind == "effect"
    assert foreign_mapping.lineage is model.ProjectedSiteLineageKind.RELATION_CLONE
    assert foreign_mapping is not target.disposition.owner_mapping
    return _mechanical_replace_disposition(
        draft, target,
        replace(target.disposition, owner_mapping=foreign_mapping),
    )


def _mutate_m22_conflicting_source_mapping(
    draft, target, _projected_inventory,
):
    canonical_mapping = target.disposition.owner_mapping
    assert canonical_mapping is not None
    alternatives = tuple(
        row for row in target.owner_rows
        if row is not canonical_mapping
        and row.projected_owner != canonical_mapping.projected_owner
    )
    assert alternatives
    foreign_mapping = sorted(
        alternatives, key=lambda row: canonical_bytes(row.projected_owner),
    )[0]
    assert any(foreign_mapping is row for row in target.owner_rows)
    conflicting = replace(
        target.disposition, owner_mapping=foreign_mapping,
    )
    field = (
        "effect_dispositions"
        if target.site_kind == "effect" else "terminal_dispositions"
    )
    dispositions = getattr(draft, field)
    return replace(draft, **{field: (*dispositions, conflicting)})


def _mutate_m06_ea_drift(draft, target, _projected_inventory):
    row = replace(
        target.projected_row,
        instruction_ea=target.projected_row.instruction_ea + 0x100000,
    )
    return _mechanical_replace_disposition(
        draft, target, replace(target.disposition, projected_row=row),
    )


def _mutate_m07_ordinal_drift(draft, target, _projected_inventory):
    assert type(target.projected_row.instruction_ordinal) is int
    row = replace(
        target.projected_row,
        instruction_ordinal=target.projected_row.instruction_ordinal + 97,
    )
    return _mechanical_replace_disposition(
        draft, target, replace(target.disposition, projected_row=row),
    )


def _mutate_m08_kind_drift(draft, target, _projected_inventory):
    if target.site_kind == "effect":
        replacements = {
            model.EffectSiteKind.CALL: model.EffectSiteKind.STORE,
            model.EffectSiteKind.STORE: model.EffectSiteKind.TRAP,
            model.EffectSiteKind.TRAP: model.EffectSiteKind.RETURN,
            model.EffectSiteKind.RETURN: model.EffectSiteKind.CALL,
        }
        row = replace(
            target.projected_row,
            effect_kind=replacements[target.projected_row.effect_kind],
        )
    else:
        replacements = {
            model.TerminalKind.RETURN: model.TerminalKind.TRAP,
            model.TerminalKind.TRAP: model.TerminalKind.NORETURN_CALL,
            model.TerminalKind.NORETURN_CALL: model.TerminalKind.RETURN,
            model.TerminalKind.STOP: model.TerminalKind.RETURN,
        }
        row = replace(
            target.projected_row,
            terminal_kind=replacements[target.projected_row.terminal_kind],
        )
    return _mechanical_replace_disposition(
        draft, target, replace(target.disposition, projected_row=row),
    )


def _mutate_m09_opcode_drift(draft, target, _projected_inventory):
    assert target.site_kind == "effect"
    row = replace(target.projected_row, opcode=target.projected_row.opcode + 101)
    return _mechanical_replace_disposition(
        draft, target, replace(target.disposition, projected_row=row),
    )


def _mutate_m11_width_drift(draft, target, _projected_inventory):
    assert target.site_kind == "effect"
    row = replace(target.projected_row, width=target.projected_row.width + 8)
    return _mechanical_replace_disposition(
        draft, target, replace(target.disposition, projected_row=row),
    )


def _mutate_m12_stop_ordinal_drift(draft, target, _projected_inventory):
    assert target.site_kind == "terminal"
    assert target.source_row.terminal_kind is model.TerminalKind.STOP
    assert target.projected_row.terminal_kind is model.TerminalKind.STOP
    assert target.source_row.instruction_ordinal is None
    assert target.projected_row.instruction_ordinal is None
    # InventoryTerminalSite correctly rejects this state at its public model
    # constructor.  M12 separately pins the private draft validator's
    # defense-in-depth without altering either sealed inventory occurrence.
    row = object.__new__(model.InventoryTerminalSite)
    for name in (
        "owner_serial", "owner_ref", "owner_anchor_ea", "instruction_ordinal",
        "instruction_ea", "terminal_kind",
    ):
        object.__setattr__(
            row, name,
            0 if name == "instruction_ordinal" else getattr(
                target.projected_row, name,
            ),
        )
    assert row not in _projected_inventory.terminals
    return _mechanical_replace_disposition(
        draft, target, replace(target.disposition, projected_row=row),
    )


def _mutate_m13_owner_drift(draft, target, projected_inventory):
    current = model.AnchoredBlockRef(
        target.projected_row.owner_ref,
        target.projected_row.owner_anchor_ea,
    )
    blocks = tuple(
        block for block in projected_inventory.blocks
        if block.serial in projected_inventory.reachable_serials
        if block.block_ref is not None
        and model.AnchoredBlockRef(block.block_ref, block.anchor_ea) != current
    )
    assert blocks
    foreign_block = sorted(
        blocks,
        key=lambda block: canonical_bytes(model.AnchoredBlockRef(
            block.block_ref, block.anchor_ea,
        )),
    )[0]
    assert any(foreign_block is block for block in projected_inventory.blocks)
    assert foreign_block.serial in projected_inventory.reachable_serials
    foreign = model.AnchoredBlockRef(
        foreign_block.block_ref, foreign_block.anchor_ea,
    )
    row = replace(
        target.projected_row, owner_ref=foreign.ref,
        owner_anchor_ea=foreign.anchor_ea,
    )
    return _mechanical_replace_disposition(
        draft, target, replace(target.disposition, projected_row=row),
    )


def _mechanical_draft_delta(before, after) -> tuple[str, ...]:
    assert type(before) is bind._ProjectedSiteClosureDraft
    assert type(after) is bind._ProjectedSiteClosureDraft
    changed_fields = tuple(
        name for name in type(before).__dataclass_fields__
        if getattr(before, name) is not getattr(after, name)
    )
    assert len(changed_fields) == 1
    field = changed_fields[0]
    if field == "route_subsets":
        assert len(before.route_subsets) == len(after.route_subsets)
        changed = tuple(
            index for index, (old, new) in enumerate(zip(
                before.route_subsets, after.route_subsets,
            ))
            if old is not new
        )
        assert len(changed) == 1
        index = changed[0]
        old = before.route_subsets[index]
        new = after.route_subsets[index]
        assert type(old) is type(new) is bind._RouteSiteSubsetDraft
        assert old.relation_draft is new.relation_draft
        tuple_changes = tuple(
            name for name in ("effect_dispositions", "terminal_dispositions")
            if getattr(old, name) is not getattr(new, name)
        )
        assert len(tuple_changes) == 1
        tuple_name = tuple_changes[0]
        old_rows = getattr(old, tuple_name)
        new_rows = getattr(new, tuple_name)
        assert len(old_rows) == len(new_rows) == 1
        assert old_rows[0] is not new_rows[0]
        assert old_rows[0].source_row is new_rows[0].source_row
        assert old_rows[0].projected_row is new_rows[0].projected_row
        assert old_rows[0].relation_draft is None
        assert new_rows[0].relation_draft is not old.relation_draft
        return (
            f"route_subsets[{index}].{tuple_name}[0].relation_draft",
        )
    assert field in {"effect_dispositions", "terminal_dispositions"}
    before_rows = getattr(before, field)
    after_rows = getattr(after, field)
    prefix = "effect_dispositions" if field == "effect_dispositions" else "terminal_dispositions"
    if len(after_rows) == len(before_rows) - 1:
        removed = tuple(
            index for index, item in enumerate(before_rows)
            if not any(item is candidate for candidate in after_rows)
        )
        assert len(removed) == 1
        index = removed[0]
        assert all(
            before is after
            for before, after in zip(
                (*before_rows[:index], *before_rows[index + 1:]),
                after_rows,
            )
        )
        return (f"{prefix}[source].omitted",)
    if len(after_rows) == len(before_rows) + 1:
        assert all(
            old is new for old, new in zip(before_rows, after_rows[:-1])
        )
        appended = after_rows[-1]
        if appended is before_rows[0] or any(
            appended is row for row in before_rows
        ):
            return (f"{prefix}[source].projected_occurrence multiplicity",)
        assert type(appended) is type(before_rows[0])
        matching_source = tuple(
            row for row in before_rows
            if appended.source_row is row.source_row
        )
        assert len(matching_source) == 1
        original = matching_source[0]
        assert appended.projected_row is original.projected_row
        assert appended.owner_mapping is not original.owner_mapping
        return (f"{prefix}[source].owner_mapping conflict",)
    assert len(before_rows) == len(after_rows)
    changed = tuple(
        index for index, (old, new) in enumerate(zip(before_rows, after_rows))
        if old is not new
    )
    assert len(changed) == 1
    index = changed[0]
    old = before_rows[index]
    new = after_rows[index]
    expected_type = (
        bind._ProjectedEffectDispositionDraft
        if field == "effect_dispositions"
        else bind._ProjectedTerminalDispositionDraft
    )
    assert type(old) is type(new) is expected_type
    disposition_changes = tuple(
        name for name in type(old).__dataclass_fields__
        if getattr(old, name) is not getattr(new, name)
    )
    if disposition_changes == ("owner_mapping",):
        assert old.owner_mapping is not new.owner_mapping
        assert old.projected_row is new.projected_row
        return (f"{prefix}[source].owner_mapping",)
    assert disposition_changes == ("projected_row",)
    old_row = old.projected_row
    new_row = new.projected_row
    assert type(old_row) is type(new_row)
    if type(old_row) is model.InventoryEffectSite:
        scalar_fields = (
            "owner_serial", "instruction_ordinal", "instruction_ea",
            "effect_kind", "opcode", "width",
        )
        kind_name = "effect_kind"
    else:
        assert type(old_row) is model.InventoryTerminalSite
        scalar_fields = (
            "owner_serial", "instruction_ordinal", "instruction_ea",
            "terminal_kind",
        )
        kind_name = "terminal_kind"
    owner_changed = (
        old_row.owner_ref != new_row.owner_ref
        or old_row.owner_anchor_ea != new_row.owner_anchor_ea
    )
    scalar_changes = tuple(
        name for name in scalar_fields
        if type(getattr(old_row, name)) is not type(getattr(new_row, name))
        or getattr(old_row, name) != getattr(new_row, name)
    )
    if owner_changed:
        assert scalar_changes == ()
        return (f"{prefix}[source].projected_row.owner",)
    assert old_row.owner_ref is new_row.owner_ref
    assert old_row.owner_anchor_ea == new_row.owner_anchor_ea
    assert len(scalar_changes) == 1
    leaf = scalar_changes[0]
    assert leaf in {
        "instruction_ordinal", "instruction_ea", kind_name, "opcode", "width",
    }
    return (f"{prefix}[source].projected_row.{leaf}",)


_ALL_MECHANICAL_FAMILIES = tuple(
    family.family for family in _MECHANICAL_FAMILY_CASES
)


def _validated_mechanical_specs(specs):
    keys = tuple(
        (spec.row, spec.boundary, spec.site_kind, spec.families)
        for spec in specs
    )
    if len(keys) != len(set(keys)):
        raise ValueError("mechanical mutation spec keys must be unique")
    functions_by_row = {}
    for spec in specs:
        previous = functions_by_row.setdefault(spec.row, spec.mutate)
        if previous is not spec.mutate:
            raise ValueError("one mechanical row must use one named mutator")
    if len(set(functions_by_row.values())) != len(functions_by_row):
        raise ValueError("mechanical mutation rows must not alias mutators")
    return tuple(specs)


