def _mechanical_expected_delta_path(spec):
    prefix = (
        "effect_dispositions"
        if spec.site_kind == "effect" else "terminal_dispositions"
    )
    leaves = {
        "M01": "omitted",
        "M02": "projected_occurrence multiplicity",
        "M06": "projected_row.instruction_ea",
        "M07": "projected_row.instruction_ordinal",
        "M08": (
            "projected_row.effect_kind"
            if spec.site_kind == "effect"
            else "projected_row.terminal_kind"
        ),
        "M09": "projected_row.opcode",
        "M11": "projected_row.width",
        "M12": "projected_row.instruction_ordinal",
        "M13": "projected_row.owner",
        "M22": "owner_mapping conflict",
    }
    return f"{prefix}[source].{leaves[spec.row]}"


def _mechanical_expected_failure_anchors(
    baseline, target, mutated_projected_row,
):
    anchors = list(baseline.family.relation_anchors(
        baseline.case, baseline.expected["relation"],
    ))
    for row in (target.source_row, mutated_projected_row):
        if row is not None:
            anchors.append(model.AnchoredBlockRef(
                row.owner_ref, row.owner_anchor_ea,
            ))
    return _mechanical_sorted_anchors(tuple(anchors))


def _assert_task_15_mechanical_negative(
    spec, family, *, target_factory=_mechanical_draft_target,
) -> None:
    import gc

    assert spec.boundary == "DRAFT"
    assert spec.weakening_killed
    baseline = _capture_mechanical_baseline(family)
    target = target_factory(baseline, spec.site_kind)
    detached = _clone_record(target.source_row)
    canonical_source_rows = getattr(
        baseline.values["source_inventory"],
        "effects" if spec.site_kind == "effect" else "terminals",
    )
    assert not any(detached is row for row in canonical_source_rows)

    if spec.row in {"M06", "M07", "M08", "M09", "M11", "M12", "M13"}:
        equal_clone_draft, equal_clone_row = _mechanical_equal_value_clone(
            baseline.draft, target,
        )
        with pytest.raises(bind._ProjectedSiteDraftViolation) as equal_raised:
            bind._validate_projected_site_closure_draft(
                equal_clone_draft, **baseline.validator_kwargs,
            )
        equal_violation = equal_raised.value
        equal_reason = (
            "projected effect occurrence differs"
            if spec.site_kind == "effect" else "terminal strictness differs"
        )
        assert equal_violation.reason_code == equal_reason
        assert equal_violation.reason_code != spec.expected_reason
        assert equal_violation.scope is spec.expected_scope
        assert equal_violation.relation_draft is target.relation_draft
        assert equal_violation.source_row is target.source_row
        assert equal_violation.projected_row is equal_clone_row

    mutated = spec.mutate(
        baseline.draft, target, baseline.values["projected_inventory"],
    )
    assert _mechanical_draft_delta(baseline.draft, mutated) == (
        _mechanical_expected_delta_path(spec),
    )
    mutated_dispositions = (
        mutated.effect_dispositions
        if spec.site_kind == "effect" else mutated.terminal_dispositions
    )
    mutated_disposition = (
        None if spec.row == "M01"
        else mutated_dispositions[-1]
        if spec.row in {"M02", "M22"}
        else mutated_dispositions[target.disposition_index]
    )
    mutated_projected_row = (
        None if mutated_disposition is None
        else mutated_disposition.projected_row
    )
    if spec.row == "M12":
        assert type(mutated_projected_row) is model.InventoryTerminalSite
        assert mutated_projected_row.instruction_ordinal == 0
        assert not any(
            mutated_projected_row is row
            for row in baseline.values["source_inventory"].terminals
        )
        assert not any(
            mutated_projected_row is row
            for row in baseline.values["projected_inventory"].terminals
        )
    if spec.row == "M13":
        alternate_blocks = tuple(
            block for block in baseline.values["projected_inventory"].blocks
            if block.serial
            in baseline.values["projected_inventory"].reachable_serials
            and block.block_ref == mutated_projected_row.owner_ref
            and block.anchor_ea == mutated_projected_row.owner_anchor_ea
        )
        assert len(alternate_blocks) == 1
        assert any(
            alternate_blocks[0] is block
            for block in baseline.values["projected_inventory"].blocks
        )
    gc.collect()
    before_direct = _task_15_publication_type_counts()
    with pytest.raises(bind._ProjectedSiteDraftViolation) as raised:
        bind._validate_projected_site_closure_draft(
            mutated, **baseline.validator_kwargs,
        )
    violation = raised.value
    assert violation.reason_code == spec.expected_reason
    assert violation.scope is spec.expected_scope
    assert violation.relation_draft is target.relation_draft
    assert violation.source_row is target.source_row
    assert violation.projected_row is mutated_projected_row
    assert target.relation_draft.claim is target.claim
    assert target.relation_draft.proof is target.proof
    assert any(
        target.patch_step_fact is fact
        for fact in target.relation_draft.facts
    )
    gc.collect()
    assert _task_15_publication_type_counts() == before_direct

    drafter_calls = []
    validator_calls = []
    real_drafter = bind._draft_projected_site_closure
    real_validator = bind._validate_projected_site_closure_draft

    def mutate_public(**kwargs):
        clean = real_drafter(**kwargs)
        public_baseline = replace(
            baseline, draft=clean, drafter_kwargs=kwargs,
        )
        public_target = target_factory(
            public_baseline, spec.site_kind,
        )
        changed = spec.mutate(
            clean, public_target, kwargs["projected_inventory"],
        )
        assert _mechanical_draft_delta(clean, changed) == (
            _mechanical_expected_delta_path(spec),
        )
        drafter_calls.append((clean, changed, public_target, kwargs))
        return changed

    def observe_validator(draft, **kwargs):
        validator_calls.append((draft, kwargs))
        return real_validator(draft, **kwargs)

    gc.collect()
    before_public = _task_15_publication_type_counts()
    with (
        patch.object(
            bind, "_draft_projected_site_closure", side_effect=mutate_public,
        ),
        patch.object(
            bind, "_validate_projected_site_closure_draft",
            side_effect=observe_validator,
        ),
        patch.object(
            transaction_api, "_build_semantic_graph_inventory",
            side_effect=AssertionError("mechanical negative inventory replay"),
        ),
        patch.object(
            bind, "bind_source_route_authority",
            side_effect=AssertionError("mechanical negative source replay"),
        ),
        patch.object(
            route_model, "bind_canonical_semantic_evidence_result",
            side_effect=AssertionError("mechanical negative route replay"),
        ),
        patch.object(
            producer_api, "validate_exact_effect_claim_semantics",
            side_effect=AssertionError("mechanical negative producer replay"),
        ),
        patch.object(
            evaluate, "_classify_effect_site",
            side_effect=AssertionError("mechanical negative evaluator replay"),
        ),
    ):
        events = _task_15_observe_publication_events(
            lambda: bind.realize_projected_routes(**baseline.values),
        )
    assert len(drafter_calls) == len(validator_calls) == 1
    _clean, changed, public_target, public_drafter_kwargs = drafter_calls[0]
    assert validator_calls[0][0] is changed
    for name in (
        "source_authority", "plan", "source_inventory",
        "projected_inventory", "claims", "patch_step_facts",
        "raw_effect_gate_fact", "legacy_effective_gate_facts",
        "attempt_id", "drafts", "owner_index",
    ):
        assert validator_calls[0][1][name] is public_drafter_kwargs[name]
    result = events.result
    assert type(result) is model.ProjectedRouteRealizationRejected
    assert len(result.failures) == 1
    failure = result.failures[0]
    assert failure.stage is model.RouteRealizationFailureStage.EFFECT_TERMINAL_PRESERVATION
    assert failure.scope is model.RouteRealizationFailureScope.STEP
    assert failure.claim_id == public_target.claim.claim_id
    assert failure.proof_id == public_target.proof.proof_id
    assert (
        failure.route_subject_id
        == public_target.claim.retired_route_subject.subject_id
    )
    assert failure.step_index == public_target.patch_step_fact.step_index
    assert failure.step_digest == public_target.patch_step_fact.step_digest
    public_mutated_rows = (
        changed.effect_dispositions
        if spec.site_kind == "effect" else changed.terminal_dispositions
    )
    public_projected_row = (
        None if spec.row == "M01"
        else public_mutated_rows[-1].projected_row
        if spec.row in {"M02", "M22"}
        else public_mutated_rows[public_target.disposition_index].projected_row
    )
    expected_failure_anchors = list(_mechanical_expected_failure_anchors(
        baseline, public_target, public_projected_row,
    ))
    if spec.row == "M22":
        public_appended = public_mutated_rows[-1]
        expected_failure_anchors.append(
            public_appended.owner_mapping.projected_owner,
        )
    expected_failure_anchors = _mechanical_sorted_anchors(
        tuple(expected_failure_anchors),
    )
    assert failure.anchored_refs == expected_failure_anchors
    source_owner = model.AnchoredBlockRef(
        public_target.source_row.owner_ref,
        public_target.source_row.owner_anchor_ea,
    )
    assert source_owner in failure.anchored_refs
    if public_projected_row is not None:
        projected_owner = model.AnchoredBlockRef(
            public_projected_row.owner_ref,
            public_projected_row.owner_anchor_ea,
        )
        canonical_projected_owner = model.AnchoredBlockRef(
            public_target.projected_row.owner_ref,
            public_target.projected_row.owner_anchor_ea,
        )
        assert projected_owner in failure.anchored_refs
        if spec.row == "M13":
            assert projected_owner != canonical_projected_owner
            assert canonical_projected_owner in failure.anchored_refs
        else:
            assert projected_owner == canonical_projected_owner
    assert events.commits == ()
    assert not any(
        type(value) in events.accepted_types
        for value in (*events.ordinary, *events.deferred)
    )
    assert tuple(type(value) for value in events.ordinary) == (
        model.RouteRealizationFailure,
        model.ProjectedRouteRealizationRejected,
    )
    gc.collect()
    assert _task_15_publication_type_counts() == before_public


