@pytest.mark.parametrize(
    ("row", "family_name", "mutate"),
    _MECHANICAL_BATCH_4_SUBJECT_CASES,
    ids=lambda value: value if isinstance(value, str) else value.__name__,
)
def test_task_15_mechanical_model_rejects_cloned_effect_subject_direction(
    row, family_name, mutate,
) -> None:
    """M14/M15 bind each cloned-effect subject to its own phase role."""
    family = next(
        item for item in _MECHANICAL_FAMILY_CASES
        if item.family == family_name
    )
    baseline = _capture_mechanical_baseline(family)
    phase = baseline.accepted.realization.site_phase_result
    original = next(
        result for result in phase.effect_results
        if result.outcome is model.ProjectedEffectSiteOutcome.RELATION_CLONED
    )
    assert original.source_subject_id != original.projected_subject_id
    candidate = mutate(original)
    changed = tuple(
        name for name in type(original).__dataclass_fields__
        if getattr(candidate, name) != getattr(original, name)
    )
    expected_role = (
        "projected_subject_id" if row == "M14" else "source_subject_id"
    )
    assert changed == (expected_role, "result_id")
    assert candidate.source_subject_id == candidate.projected_subject_id
    assert candidate.result_id == projected_effect_site_result_id(candidate)
    effect_results = tuple(sorted(
        (candidate if item is original else item for item in phase.effect_results),
        key=lambda item: item.result_id,
    ))
    detached_phase = _clone_record(phase, effect_results=effect_results)
    detached_phase = _clone_record(
        detached_phase,
        derived_effect_gate_fact_id=derived_effect_gate_fact_id(
            phase.raw_effect_gate_fact.fact_id,
            tuple(item.result_id for item in effect_results),
        ),
    )
    detached_phase = _clone_record(
        detached_phase,
        result_id=projected_semantic_site_phase_result_id(detached_phase),
    )
    before = _task_15_publication_type_counts()
    with pytest.raises(ValueError, match="cloned effect subjects must be distinct"):
        candidate.__post_init__()
    with pytest.raises(ValueError, match="cloned effect subjects must be distinct"):
        detached_phase.__post_init__()
    with pytest.raises((TypeError, ValueError)):
        bind.validate_projected_effect_site_result(candidate)
    with pytest.raises((TypeError, ValueError)):
        bind.validate_projected_site_phase_result(detached_phase)
    assert _task_15_publication_type_counts() == before


def _mutate_m17_foreign_authority_result(phase, foreign_result):
    """Substitute one real registered foreign-authority result occurrence."""
    original = next(
        item for item in phase.effect_results
        if item.source_site.effect_kind is foreign_result.source_site.effect_kind
    )
    results = tuple(sorted(
        (foreign_result if item is original else item for item in phase.effect_results),
        key=lambda item: item.result_id,
    ))
    candidate = _clone_record(phase, effect_results=results)
    candidate = _clone_record(
        candidate,
        derived_effect_gate_fact_id=derived_effect_gate_fact_id(
            phase.raw_effect_gate_fact.fact_id,
            tuple(item.result_id for item in results),
        ),
    )
    return _clone_record(
        candidate,
        result_id=projected_semantic_site_phase_result_id(candidate),
    ), original


def _assert_task_15_model_public_attempt_binding_rejection(
    events, source_authority,
) -> None:
    rejected = events.result
    assert type(rejected) is model.ProjectedRouteRealizationRejected
    assert len(rejected.failures) == 1
    failure = rejected.failures[0]
    assert failure.stage is model.RouteRealizationFailureStage.ATTEMPT_BINDING
    assert failure.scope is model.RouteRealizationFailureScope.EVIDENCE
    assert failure.proposal_id == source_authority.proposal_id
    assert (
        failure.evidence_id
        == source_authority.proposal.route_evidence.atomic_group_id
    )
    assert failure.claim_id is None
    assert failure.proof_id is None
    assert failure.route_subject_id is None
    assert failure.step_index is None
    assert failure.step_digest is None
    assert failure.anchored_refs == ()
    assert events.commits == ()
    assert tuple(type(value) for value in events.ordinary) == (
        model.RouteRealizationFailure,
        model.ProjectedRouteRealizationRejected,
    )
    assert not any(
        type(value) in events.accepted_types
        for value in (*events.ordinary, *events.deferred)
    )


