def test_task_15_mechanical_registered_phase_validator_visits_exact_children(
) -> None:
    """A real registered CC aggregate validates every exact child once."""
    family = next(
        item for item in _MECHANICAL_FAMILY_CASES if item.family == "CC"
    )
    baseline = _capture_mechanical_baseline(family)
    phase = baseline.accepted.realization.site_phase_result
    bind.validate_projected_site_phase_result(phase)
    real_effect_validator = bind.validate_projected_effect_site_result
    real_terminal_validator = bind.validate_projected_terminal_site_result
    visited_effects = []
    visited_terminals = []

    def validate_effect(value):
        real_effect_validator(value)
        visited_effects.append(value)

    def validate_terminal(value):
        real_terminal_validator(value)
        visited_terminals.append(value)

    before = _task_15_publication_type_counts()
    with (
        patch.object(
            bind, "validate_projected_effect_site_result",
            side_effect=validate_effect,
        ),
        patch.object(
            bind, "validate_projected_terminal_site_result",
            side_effect=validate_terminal,
        ),
    ):
        bind.validate_projected_site_phase_result(phase)

    assert tuple(visited_effects) == phase.effect_results
    assert tuple(visited_terminals) == phase.terminal_results
    assert all(
        visited is expected
        for visited, expected in zip(visited_effects, phase.effect_results)
    )
    assert all(
        visited is expected
        for visited, expected in zip(visited_terminals, phase.terminal_results)
    )
    assert len({id(value) for value in visited_effects}) == len(visited_effects)
    assert len({id(value) for value in visited_terminals}) == len(
        visited_terminals
    )
    assert _task_15_publication_type_counts() == before


def test_task_15_mechanical_model_batch4_applicability_is_exact() -> None:
    """Batch 4 has seven named mutations and exactly nine applications."""
    actual = {
        (row, family)
        for row, family, _mutate in _MECHANICAL_BATCH_4_SUBJECT_CASES
    }
    actual = {
        (row, family, "effect") for row, family in actual
    } | {
        (row, "D", "aggregate")
        for row, _family, _mutate, _field
        in _MECHANICAL_BATCH_4_FOREIGN_RESULT_CASES
    } | {
        (case.row, case.family, case.site_kind)
        for case in (*_MECHANICAL_M17_CASES, *_MECHANICAL_M19_CASES)
    }
    assert actual == {
        ("M14", "CC", "effect"),
        ("M14", "CR", "effect"),
        ("M15", "CC", "effect"),
        ("M15", "CR", "effect"),
        ("M17", "D", "aggregate"),
        ("M18", "D", "aggregate"),
        ("M19", "D", "aggregate"),
        ("M20", "D", "aggregate"),
        ("M21", "D", "aggregate"),
    }
    mutators = {
        *(
            mutate for _row, _family, mutate
            in _MECHANICAL_BATCH_4_SUBJECT_CASES
        ),
        *(
            mutate for _row, _family, mutate, _field
            in _MECHANICAL_BATCH_4_FOREIGN_RESULT_CASES
        ),
        *(
            case.mutate
            for case in (*_MECHANICAL_M17_CASES, *_MECHANICAL_M19_CASES)
        ),
    }
    assert len(mutators) == 7


def _mutate_m23_legacy_effective_gate_from_canonical_inputs(baseline):
    """Derive one unequal legacy partition without changing raw authority."""
    from d810.transforms.unflatten_authority.gates import GenericEffectfulGateFacts

    values = baseline.values
    raw = values["raw_effect_gate_fact"]
    source_serial_by_ref = {
        block.block_ref: block.serial
        for block in values["source_inventory"].blocks
        if block.block_ref is not None
    }

    def serials(owners):
        return frozenset(
            source_serial_by_ref[owner.ref]
            for owner in owners
            if owner.ref in source_serial_by_ref
        )

    pre = serials(raw.pre_effectful_source_owners)
    raw_retained = serials(raw.raw_retained_source_owners)
    raw_lost = serials(raw.raw_lost_source_owners)
    assert pre == raw_retained | raw_lost
    assert not raw_retained & raw_lost
    if raw_lost:
        mismatched_post = raw_retained
        mismatched_lost = raw_lost
    else:
        assert raw_retained
        misclassified_retained = frozenset((min(raw_retained),))
        mismatched_post = raw_retained - misclassified_retained
        mismatched_lost = misclassified_retained
    legacy = GenericEffectfulGateFacts(
        not mismatched_lost, pre, mismatched_post, mismatched_lost,
        values["legacy_effective_gate_facts"].reason,
    )
    return SimpleNamespace(
        legacy=legacy, pre=pre, raw_retained=raw_retained,
        raw_lost=raw_lost,
    )


_MECHANICAL_BATCH_5_M23_CASES = (
    next(item for item in _MECHANICAL_FAMILY_CASES if item.family == "D"),
    next(item for item in _MECHANICAL_FAMILY_CASES if item.family == "CR"),
)


@pytest.mark.parametrize(
    "family", _MECHANICAL_BATCH_5_M23_CASES,
    ids=lambda item: item.family,
)
def test_task_15_mechanical_m23_rejects_legacy_effective_gate_mismatch(
    family,
) -> None:
    """M23 rejects an unequal derived legacy view as aggregate evidence."""
    import gc

    baseline = _capture_mechanical_baseline(family)
    mismatch = _mutate_m23_legacy_effective_gate_from_canonical_inputs(
        baseline,
    )
    canonical_legacy = baseline.values["legacy_effective_gate_facts"]
    assert mismatch.legacy != canonical_legacy
    assert mismatch.legacy.pre_effectful_block_serials == mismatch.pre
    assert (
        mismatch.legacy.post_reachable_effectful_block_serials
        | mismatch.legacy.lost_block_serials
    ) == mismatch.pre
    assert not (
        mismatch.legacy.post_reachable_effectful_block_serials
        & mismatch.legacy.lost_block_serials
    )
    assert mismatch.legacy.passed == (not mismatch.legacy.lost_block_serials)
    if family.family == "D":
        assert mismatch.raw_lost == frozenset()
        assert mismatch.legacy.lost_block_serials <= mismatch.raw_retained
    else:
        relation = baseline.expected["relation"]
        assert type(relation) is model.ClonedRouteCorridorRealization
        source_serial_by_ref = baseline.values["source_inventory"].serial_by_ref
        expected_raw_lost = frozenset(
            source_serial_by_ref[owner.ref]
            for owner in relation.source_corridor
        )
        assert mismatch.raw_lost == expected_raw_lost
        assert mismatch.raw_lost
        assert canonical_legacy.lost_block_serials == frozenset()
        assert canonical_legacy.post_reachable_effectful_block_serials == mismatch.pre
        assert mismatch.legacy.post_reachable_effectful_block_serials == mismatch.raw_retained
        assert mismatch.legacy.lost_block_serials == mismatch.raw_lost

    direct_kwargs = dict(baseline.validator_kwargs)
    direct_kwargs["legacy_effective_gate_facts"] = mismatch.legacy
    gc.collect()
    before_direct = _task_15_publication_type_counts()
    with pytest.raises(bind._ProjectedSiteDraftViolation) as raised:
        bind._validate_projected_site_closure_draft(
            baseline.draft, **direct_kwargs,
        )
    violation = raised.value
    assert violation.reason_code == "legacy effective gate differs from derived view"
    assert violation.scope is model.RouteRealizationFailureScope.EVIDENCE
    assert violation.relation_draft is None
    assert violation.source_row is None
    assert violation.projected_row is None
    gc.collect()
    assert _task_15_publication_type_counts() == before_direct

    public_values = dict(baseline.values)
    public_values["legacy_effective_gate_facts"] = mismatch.legacy
    for name, value in baseline.values.items():
        if name != "legacy_effective_gate_facts":
            assert public_values[name] is value
    drafted = []
    validated = []
    real_drafter = bind._draft_projected_site_closure
    real_validator = bind._validate_projected_site_closure_draft

    def capture_draft(**kwargs):
        assert kwargs["legacy_effective_gate_facts"] is mismatch.legacy
        draft = real_drafter(**kwargs)
        drafted.append((draft, kwargs))
        return draft

    def capture_validation(draft, **kwargs):
        assert kwargs["legacy_effective_gate_facts"] is mismatch.legacy
        validated.append((draft, kwargs))
        return real_validator(draft, **kwargs)

    gc.collect()
    before_public = _task_15_publication_type_counts()
    with (
        patch.object(
            bind, "_draft_projected_site_closure", side_effect=capture_draft,
        ),
        patch.object(
            bind, "_validate_projected_site_closure_draft",
            side_effect=capture_validation,
        ),
        patch.object(
            transaction_api, "_build_semantic_graph_inventory",
            side_effect=AssertionError("M23 inventory replay"),
        ),
        patch.object(
            bind, "bind_source_route_authority",
            side_effect=AssertionError("M23 source replay"),
        ),
        patch.object(
            route_model, "bind_canonical_semantic_evidence_result",
            side_effect=AssertionError("M23 route replay"),
        ),
        patch.object(
            producer_api, "validate_exact_effect_claim_semantics",
            side_effect=AssertionError("M23 producer replay"),
        ),
        patch.object(
            evaluate, "_classify_effect_site",
            side_effect=AssertionError("M23 evaluator replay"),
        ),
    ):
        events = _task_15_observe_publication_events(
            lambda: bind.realize_projected_routes(**public_values),
        )
    assert len(drafted) == len(validated) == 1
    assert validated[0][0] is drafted[0][0]
    for name, value in public_values.items():
        if name in drafted[0][1]:
            assert drafted[0][1][name] is value
        if name in validated[0][1]:
            assert validated[0][1][name] is value
    rejected = events.result
    assert type(rejected) is model.ProjectedRouteRealizationRejected
    assert len(rejected.failures) == 1
    failure = rejected.failures[0]
    assert (
        failure.stage
        is model.RouteRealizationFailureStage.EFFECT_TERMINAL_PRESERVATION
    )
    assert failure.scope is model.RouteRealizationFailureScope.EVIDENCE
    assert failure.claim_id is None
    assert failure.proof_id is None
    assert failure.route_subject_id is None
    assert failure.step_index is None
    assert failure.step_digest is None
    assert failure.anchored_refs == ()
    assert events.commits == ()
    assert tuple(type(value) for value in events.ordinary) == (
        model.RouteRealizationFailure,
        model.ProjectedRouteRealizationRejected,
    )
    assert not any(
        type(value) in events.accepted_types
        for value in (*events.ordinary, *events.deferred)
    )
    gc.collect()
    assert _task_15_publication_type_counts() == before_public


@dataclass(frozen=True, slots=True)
class _MechanicalFinalRowContract:
    row: str
    families: tuple[str, ...]
    site_boundaries: tuple[tuple[str, str], ...]
    coverage_oracle: str
    weakening_killed: str


@dataclass(frozen=True, slots=True)
class _MechanicalFinalNaProof:
    combination: str
    reason: str


_MECHANICAL_FINAL_ROW_CONTRACTS = (
    _MechanicalFinalRowContract("M01", _ALL_MECHANICAL_FAMILIES, (("effect", "DRAFT"), ("terminal", "DRAFT")), "STEP", "removing exhaustive SOURCE partition validation"),
    _MechanicalFinalRowContract("M02", _ALL_MECHANICAL_FAMILIES, (("effect", "DRAFT"), ("terminal", "DRAFT")), "STEP", "changing projected consumption from exactly once to at least once"),
    _MechanicalFinalRowContract("M03", ("CC", "BH"), (("effect", "GRAPH"),), "STEP", "dropping inverse-only helper ownership or checking only helper topology/tail"),
    _MechanicalFinalRowContract("M04", ("CC", "CR"), (("effect", "GRAPH"),), "STEP", "truncating clone inverse validation at prefix end"),
    _MechanicalFinalRowContract("M05", ("CC", "CR"), (("effect", "DRAFT"),), "STEP", "replacing exact clone-owner occurrence with proximity or equality"),
    _MechanicalFinalRowContract("M06", _ALL_MECHANICAL_FAMILIES, (("effect", "DRAFT"), ("terminal", "DRAFT")), "STEP", "omitting EA from cross-phase coordinate equality"),
    _MechanicalFinalRowContract("M07", _ALL_MECHANICAL_FAMILIES, (("effect", "DRAFT"), ("terminal", "DRAFT")), "STEP", "omitting ordinal equality or normalizing ordinal by EA"),
    _MechanicalFinalRowContract("M08", _ALL_MECHANICAL_FAMILIES, (("effect", "DRAFT"), ("terminal", "DRAFT")), "STEP", "accepting an occurrence while ignoring semantic kind"),
    _MechanicalFinalRowContract("M09", _ALL_MECHANICAL_FAMILIES, (("effect", "DRAFT"),), "STEP", "omitting normalized opcode from effect equality"),
    _MechanicalFinalRowContract("M10", _ALL_MECHANICAL_FAMILIES, (("effect", "GRAPH"),), "STEP", "ignoring raw opcode or comparing only normalized opcode"),
    _MechanicalFinalRowContract("M11", _ALL_MECHANICAL_FAMILIES, (("effect", "DRAFT"),), "STEP", "omitting effect width from exact coordinate equality"),
    _MechanicalFinalRowContract("M12", _ALL_MECHANICAL_FAMILIES, (("terminal", "MODEL+DRAFT"),), "STEP", "treating synthesized STOP as instruction-backed or ignoring None ordinal"),
    _MechanicalFinalRowContract("M13", _ALL_MECHANICAL_FAMILIES, (("effect", "DRAFT"), ("terminal", "DRAFT")), "STEP", "joining site scalars without exact owner identity"),
    _MechanicalFinalRowContract("M14", ("CC", "CR"), (("effect", "MODEL"),), "MODEL", "treating source and projected subject IDs as interchangeable on clone lineage"),
    _MechanicalFinalRowContract("M15", ("CC", "CR"), (("effect", "MODEL"),), "MODEL", "failing to bind each subject ID to its own coordinate and phase role"),
    _MechanicalFinalRowContract("M16", ("D-SHARED",), (("effect", "DRAFT"), ("terminal", "DRAFT")), "STEP", "trusting any registered relation occurrence or matching by family only"),
    _MechanicalFinalRowContract("M17", ("D",), (("aggregate", "MODEL"),), "MODEL", "validating nested result IDs without exact authority occurrence"),
    _MechanicalFinalRowContract("M18", ("D",), (("aggregate", "MODEL"),), "MODEL", "accepting equality-shaped results from another attempt"),
    _MechanicalFinalRowContract("M19", ("D",), (("aggregate", "MODEL"),), "MODEL", "admitting observed rows into the projected-preflight result type"),
    _MechanicalFinalRowContract("M20", ("D",), (("aggregate", "MODEL"),), "MODEL", "omitting exact inventory envelope occurrence correlation"),
    _MechanicalFinalRowContract("M21", ("D",), (("aggregate", "MODEL"),), "MODEL", "trusting a content-shaped result from another generation"),
    _MechanicalFinalRowContract("M22", _ALL_MECHANICAL_FAMILIES, (("effect", "DRAFT"), ("terminal", "DRAFT")), "STEP", "using first-wins behavior for conflicting owner incidence"),
    _MechanicalFinalRowContract("M23", ("D", "CR"), (("aggregate", "DRAFT"),), "LEGACY_EVIDENCE", "trusting caller effective facts or omitting derived raw-lost authorization"),
)


_MECHANICAL_FINAL_NA_PROOFS = (
    _MechanicalFinalNaProof(
        "M03 helper injection on D/L/TA/CR",
        "Those closed relations declare no helper or inverse-only helper owner. CR clone bodies are covered by M04, not relabeled as helpers.",
    ),
    _MechanicalFinalNaProof(
        "M03 terminal on CC/BH",
        "Every terminal-producing helper instruction admitted by the inventory (TRAP, RETURN, or NORETURN CALL) also creates an effect occurrence. The exhaustive validator encounters that unconsumed effect first, so there is no one-coordinate helper-terminal mutation that independently reaches terminal inverse.",
    ),
    _MechanicalFinalNaProof(
        "M04 clone suffix on D/L/TA/BH",
        "Those relations have no relation-cloned semantic prefix. BH's helper is an inverse-only helper and belongs to M03.",
    ),
    _MechanicalFinalNaProof(
        "M04 terminal on CC/CR",
        "A terminal-producing suffix instruction also creates an effect and is rejected first as an unoriginated effect. Moving an existing terminal into the prefix changes valid source topology, not one projected suffix coordinate.",
    ),
    _MechanicalFinalNaProof(
        "M05 foreign clone owner on D/L/TA/BH",
        "No RELATION_CLONE owner mapping exists.",
    ),
    _MechanicalFinalNaProof(
        "M05 terminal on CC/CR",
        "The approved canonical valid topologies have no relation-cloned terminal disposition: CC's terminal is a same-owner arm and CR's terminal is same-owner N. A terminal cannot be moved into a copied prefix without changing topology and semantics.",
    ),
    _MechanicalFinalNaProof(
        "M09/M10/M11 terminal variants",
        "InventoryTerminalSite and TerminalSiteCoordinate have no opcode, raw-opcode, or width fields. Co-located effect rows carry those coordinates and are covered by effect variants.",
    ),
    _MechanicalFinalNaProof(
        "M12 effect variant",
        "STOP is a terminal kind, never an EffectSiteKind.",
    ),
    _MechanicalFinalNaProof(
        "M14/M15 D/L/TA/BH and all current terminal rows",
        "Same-owner preservation intentionally reuses the same subject ID in both phases, so either substitution is a no-op. Only CC/CR cloned effect rows have distinct source and projected subject IDs.",
    ),
    _MechanicalFinalNaProof(
        "M16 ordinary single-relation fixtures",
        "Another relation does not exist in an ordinary call. The dedicated two-relation control is mandatory; using a draft from another authority would turn this into M17.",
    ),
    _MechanicalFinalNaProof(
        "M17-M21 family/site multiplication",
        "These mutate aggregate result envelopes, not relation-family semantics. Repeating one nested foreign occurrence adds no coordinate coverage. D is the minimal same-owner representative.",
    ),
    _MechanicalFinalNaProof(
        "M23 site-kind multiplication",
        "The legacy DTO is one aggregate partition, not an effect or terminal row. D and CR cover its two distinct formulas.",
    ),
)


def _mechanical_final_actual_application_keys():
    keys = []
    for spec in (*_MECHANICAL_BATCH_1_SPECS, *_MECHANICAL_BATCH_2_DRAFT_SPECS):
        keys.extend(
            (spec.row, family, spec.site_kind, spec.boundary)
            for family in spec.families
        )
    keys.extend(
        (case.row, case.family, "effect", "GRAPH")
        for case in _MECHANICAL_BATCH_2_GRAPH_CASES
    )
    keys.extend(
        (case.row, case.family, case.site_kind, case.boundary)
        for case in _MECHANICAL_M05_CASES
    )
    keys.extend(
        (case.row, case.family, case.site_kind, case.boundary)
        for case in _MECHANICAL_M16_CASES
    )
    keys.extend(
        ("M10", case.family.family, "effect", "GRAPH")
        for case in _MECHANICAL_M10_GRAPH_CASES
    )
    keys.extend(
        ("M12", family.family, "terminal", "MODEL+DRAFT")
        for family in _MECHANICAL_STOP_CASES
    )
    keys.extend(
        (row, family, "effect", "MODEL")
        for row, family, _mutate in _MECHANICAL_BATCH_4_SUBJECT_CASES
    )
    keys.extend(
        (row, "D", "aggregate", "MODEL")
        for row, _family, _mutate, _field
        in _MECHANICAL_BATCH_4_FOREIGN_RESULT_CASES
    )
    keys.extend(
        (case.row, case.family, case.site_kind, case.boundary)
        for case in (*_MECHANICAL_M17_CASES, *_MECHANICAL_M19_CASES)
    )
    keys.extend(
        ("M23", family.family, "aggregate", "DRAFT")
        for family in _MECHANICAL_BATCH_5_M23_CASES
    )
    return tuple(keys)


def _mechanical_final_mutator_rows():
    rows = []
    for spec in (
        *_MECHANICAL_BATCH_1_SPECS,
        *_MECHANICAL_BATCH_2_DRAFT_SPECS,
        _MECHANICAL_M12_STOP_SPEC,
    ):
        rows.append((spec.row, spec.mutate))
    rows.extend((case.row, case.mutate) for case in _MECHANICAL_BATCH_2_GRAPH_CASES)
    rows.extend((case.row, case.mutate) for case in _MECHANICAL_M05_CASES)
    rows.extend((case.row, case.mutate) for case in _MECHANICAL_M16_CASES)
    rows.extend(("M10", case.mutate) for case in _MECHANICAL_M10_GRAPH_CASES)
    rows.extend(
        (row, mutate)
        for row, _family, mutate in _MECHANICAL_BATCH_4_SUBJECT_CASES
    )
    rows.extend(
        (row, mutate)
        for row, _family, mutate, _field
        in _MECHANICAL_BATCH_4_FOREIGN_RESULT_CASES
    )
    rows.extend(
        (case.row, case.mutate)
        for case in (*_MECHANICAL_M17_CASES, *_MECHANICAL_M19_CASES)
    )
    rows.append(("M23", _mutate_m23_legacy_effective_gate_from_canonical_inputs))
    return tuple(rows)


def test_task_15_mechanical_final_matrix_audit_is_closed_and_one_to_one() -> None:
    """M01-M23 have exact applications, N/A proofs, and owned mutators."""
    from collections import Counter

    expected_rows = tuple(f"M{index:02d}" for index in range(1, 24))
    assert tuple(contract.row for contract in _MECHANICAL_FINAL_ROW_CONTRACTS) == expected_rows
    assert all(contract.weakening_killed.strip() for contract in _MECHANICAL_FINAL_ROW_CONTRACTS)
    assert all(contract.coverage_oracle != "ATTEMPT_BINDING" for contract in _MECHANICAL_FINAL_ROW_CONTRACTS)
    assert all(
        spec.weakening_killed.strip()
        for spec in (
            *_MECHANICAL_BATCH_1_SPECS,
            *_MECHANICAL_BATCH_2_DRAFT_SPECS,
            _MECHANICAL_M12_STOP_SPEC,
        )
    )
    assert all(
        contract.coverage_oracle == "STEP"
        for contract in _MECHANICAL_FINAL_ROW_CONTRACTS
        if any(boundary in {"DRAFT", "GRAPH", "MODEL+DRAFT"} for _site, boundary in contract.site_boundaries)
        and contract.row != "M23"
        and contract.row not in {"M14", "M15"}
    )

    actual_keys = _mechanical_final_actual_application_keys()
    expected_keys = tuple(
        (contract.row, family, site, boundary)
        for contract in _MECHANICAL_FINAL_ROW_CONTRACTS
        for family in contract.families
        for site, boundary in contract.site_boundaries
    )
    assert len(actual_keys) == len(set(actual_keys))
    assert set(actual_keys) == set(expected_keys)
    assert len(actual_keys) == 127
    assert dict(Counter(row for row, _family, _site, _boundary in actual_keys)) == {
        "M01": 12,
        "M02": 12,
        "M03": 2,
        "M04": 2,
        "M05": 2,
        "M06": 12,
        "M07": 12,
        "M08": 12,
        "M09": 6,
        "M10": 6,
        "M11": 6,
        "M12": 6,
        "M13": 12,
        "M14": 2,
        "M15": 2,
        "M16": 2,
        "M17": 1,
        "M18": 1,
        "M19": 1,
        "M20": 1,
        "M21": 1,
        "M22": 12,
        "M23": 2,
    }

    mutator_rows = _mechanical_final_mutator_rows()
    rows_by_mutator = {}
    for row, mutate in mutator_rows:
        assert callable(mutate)
        assert type(mutate.__name__) is str and mutate.__name__.startswith("_")
        rows_by_mutator.setdefault(mutate, set()).add(row)
    assert len(rows_by_mutator) == 30
    assert all(len(rows) == 1 for rows in rows_by_mutator.values())
    assert {row for row, _mutate in mutator_rows} == set(expected_rows)

    expected_na_combinations = {
        "M03 helper injection on D/L/TA/CR",
        "M03 terminal on CC/BH",
        "M04 clone suffix on D/L/TA/BH",
        "M04 terminal on CC/CR",
        "M05 foreign clone owner on D/L/TA/BH",
        "M05 terminal on CC/CR",
        "M09/M10/M11 terminal variants",
        "M12 effect variant",
        "M14/M15 D/L/TA/BH and all current terminal rows",
        "M16 ordinary single-relation fixtures",
        "M17-M21 family/site multiplication",
        "M23 site-kind multiplication",
    }
    assert (
        len(_MECHANICAL_FINAL_NA_PROOFS)
        == len(expected_na_combinations)
        == 12
    )
    assert {proof.combination for proof in _MECHANICAL_FINAL_NA_PROOFS} == expected_na_combinations
    assert all(proof.reason.strip() for proof in _MECHANICAL_FINAL_NA_PROOFS)


