@pytest.mark.parametrize(
    "site_kind", ("effect", "terminal"), ids=("effect", "terminal"),
)
def test_task_15_mechanical_equal_value_clone_is_not_a_scalar_mutation(
    site_kind,
) -> None:
    """An equal detached occurrence reaches only the identity guard."""
    baseline = _capture_mechanical_baseline(_MECHANICAL_FAMILY_CASES[0])
    target = _mechanical_draft_target(baseline, site_kind)
    bind._validate_projected_site_closure_draft(
        baseline.draft, **baseline.validator_kwargs,
    )
    equal_clone_draft, equal_clone_row = _mechanical_equal_value_clone(
        baseline.draft, target,
    )
    with pytest.raises(bind._ProjectedSiteDraftViolation) as raised:
        bind._validate_projected_site_closure_draft(
            equal_clone_draft, **baseline.validator_kwargs,
        )
    violation = raised.value
    assert violation.reason_code == {
        "effect": "projected effect occurrence differs",
        "terminal": "terminal strictness differs",
    }[site_kind]
    assert violation.relation_draft is target.relation_draft
    assert violation.source_row is target.source_row
    assert violation.projected_row is equal_clone_row


