def test_task_15_direct_vertical_ordinary_preserves_call_store_and_terminal() -> None:
    """DIRECT ordinary closure publishes two preserved effects and one terminal."""
    values = _task_15_vertical_inputs(_task_15_direct_vertical_case)
    expected = _task_15_independent_expected_publication(values)
    accepted = bind.realize_projected_routes(**values)
    phase = _assert_task_15_direct_publication(values, accepted, expected)
    assert len(phase.effect_results) == 2
    assert {row.source_site.effect_kind for row in phase.effect_results} == {
        model.EffectSiteKind.CALL, model.EffectSiteKind.STORE,
    }
    assert all(
        row.outcome is model.ProjectedEffectSiteOutcome.PRESERVED
        and row.lineage_kind is model.ProjectedSiteLineageKind.SAME_OWNER
        and row.source_site == row.projected_site
        for row in phase.effect_results
    )
    assert len(phase.terminal_results) == 1
    terminal = phase.terminal_results[0]
    assert terminal.outcome is model.ProjectedTerminalSiteOutcome.PRESERVED
    assert terminal.lineage_kind is model.ProjectedSiteLineageKind.SAME_OWNER
    assert terminal.source_site == terminal.projected_site
    assert phase.exact_effect_bindings == ()
    assert phase.local_alias_bindings == ()
    assert accepted.realization.rows[0].site_preservation.site_phase_result_id == phase.result_id


@pytest.mark.parametrize("effect_kind", ("call", "store"))
def test_task_15_direct_vertical_exact_call_and_store_loss(effect_kind: str) -> None:
    """DIRECT exact closure authorizes only the proposal-owned lost effect."""
    values = _task_15_vertical_inputs(
        lambda: _task_15_exact_direct_case(effect_kind),
    )
    expected = _task_15_independent_expected_publication(values)
    with patch.object(
        producer_api, "validate_exact_effect_claim_semantics",
        side_effect=AssertionError("source exact replay"),
    ):
        accepted = bind.realize_projected_routes(**values)
    phase = _assert_task_15_direct_publication(values, accepted, expected)
    assert len(phase.effect_results) == 1
    effect = phase.effect_results[0]
    assert effect.outcome is model.ProjectedEffectSiteOutcome.EXACT_INFEASIBLE
    assert effect.projected_site is None
    assert len(phase.exact_effect_bindings) == 1
    binding = phase.exact_effect_bindings[0]
    claim = next(
        claim for claim in values["claims"]
        if type(claim) is model.ExactInfeasibleEffectClaim
    )
    assert binding.claim is claim
    assert effect.supporting_claim_id == claim.claim_id
    assert effect.supporting_binding_result_id == binding.binding_result_id
    # The discarded-arm GOTO is not a semantic terminal row and is not
    # replayed merely because it survives physically in an unreachable block.
    assert phase.terminal_results == ()


