def test_task_15_relation_owner_incidence_preserves_nested_conditional_arm_site_once() -> None:
    """A semantic arm target is an exact relation occurrence, not a tuple leaf."""
    values = _task_15_vertical_inputs(
        _task_15_lowered_conditional_vertical_case,
    )

    accepted = bind.realize_projected_routes(**values)

    assert type(accepted) is model.ProjectedRouteRealizationAccepted
    row = accepted.realization.rows[0]
    phase = accepted.realization.site_phase_result
    discarded_arm = next(
        arm.target for arm in row.relation.arms
        if arm.role is SemanticEdgeRole.CONDITIONAL_FALLTHROUGH
    )
    arm_effects = tuple(
        result for result in phase.effect_results
        if result.source_site.owner == discarded_arm
    )
    arm_terminals = tuple(
        result for result in phase.terminal_results
        if result.source_site.owner == discarded_arm
    )
    assert len(arm_effects) == 2
    assert len(arm_terminals) == 1
    assert row.site_preservation.effect_result_ids == tuple(sorted(
        result.result_id for result in arm_effects
    ))
    assert row.site_preservation.terminal_result_ids == tuple(sorted(
        result.result_id for result in arm_terminals
    ))


