def test_task_15_relation_owner_incidence_preserves_unrelated_same_owner_site() -> None:
    """An unchanged projected site outside every relation is consumed once."""
    values = _task_15_vertical_inputs(
        lambda: _task_15_lowered_conditional_vertical_case(
            unrelated_same_owner_site=True,
        ),
    )
    expected = _task_15_independent_expected_publication(values)

    accepted = bind.realize_projected_routes(**values)

    phase = _assert_task_15_lowered_publication(values, accepted, expected)
    unrelated_owner = next(
        model.AnchoredBlockRef(block.block_ref, block.anchor_ea)
        for block in values["source_inventory"].blocks
        if block.serial == 4
    )
    unrelated = tuple(
        result for result in phase.effect_results
        if result.source_site.owner == unrelated_owner
    )
    assert len(unrelated) == 1
    assert unrelated[0].outcome is model.ProjectedEffectSiteOutcome.PRESERVED
    assert unrelated[0].lineage_kind is model.ProjectedSiteLineageKind.SAME_OWNER
    assert unrelated[0].source_site == unrelated[0].projected_site
    assert unrelated[0].result_id not in set(
        accepted.realization.rows[0].site_preservation.effect_result_ids
    )


