def test_task_15_lowered_vertical_preserves_call_store_and_terminal_with_latent_exact_bindings() -> None:
    """RF-1 preserves exact CALL/STORE plus strict NORETURN on raw-retained L."""
    from d810.transforms.plan import PatchLowerConditionalStateTransition

    with (
        patch.object(
            producer_api, "build_proposal", wraps=producer_api.build_proposal,
        ) as producer_spy,
        patch.object(
            bind, "bind_source_route_authority",
            wraps=bind.bind_source_route_authority,
        ) as source_binder_spy,
        patch.object(
            transaction_api, "_build_semantic_graph_inventory",
            wraps=transaction_api._build_semantic_graph_inventory,
        ) as inventory_spy,
    ):
        fixture = _task_15_lowered_conditional_vertical_case()
    assert producer_spy.call_count == 1
    assert source_binder_spy.call_count == 1
    assert inventory_spy.call_count == 2
    assert tuple(
        call.kwargs["phase"] for call in inventory_spy.call_args_list
    ) == (
        model.UnflattenAuthorityPhase.PRODUCER_FORECAST,
        model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
    )
    values = _task_15_vertical_inputs(lambda: fixture)
    expected = _task_15_independent_expected_publication(values)
    step = values["plan"].steps[0]
    assert type(step) is PatchLowerConditionalStateTransition
    assert step.proof_id == next(
        proof.proof_id
        for proof in values["source_authority"].proposal.route_evidence.route_proofs
    )

    with (
        patch.object(
            bind, "_draft_projected_site_closure",
            wraps=bind._draft_projected_site_closure,
        ) as drafter_spy,
        patch.object(
            bind, "_validate_projected_site_closure_draft",
            wraps=bind._validate_projected_site_closure_draft,
        ) as validator_spy,
        patch.object(
            bind._AtomicPublicationBatch, "commit",
            autospec=True,
            side_effect=bind._AtomicPublicationBatch.commit,
        ) as commit_spy,
        patch.object(
            transaction_api, "_build_semantic_graph_inventory",
            side_effect=AssertionError("projected closure inventory replay"),
        ),
        patch.object(
            bind, "bind_source_route_authority",
            side_effect=AssertionError("projected closure source replay"),
        ),
        patch.object(
            route_model, "bind_canonical_semantic_evidence_result",
            side_effect=AssertionError("projected closure route replay"),
        ),
        patch.object(
            producer_api, "validate_exact_effect_claim_semantics",
            side_effect=AssertionError("projected closure producer exact replay"),
        ),
        patch.object(
            evaluate, "_classify_effect_site",
            side_effect=AssertionError("projected closure evaluator replay"),
        ),
    ):
        accepted = bind.realize_projected_routes(**values)

    assert drafter_spy.call_count == 1
    assert validator_spy.call_count == 1
    assert commit_spy.call_count == 1
    phase = _assert_task_15_lowered_publication(values, accepted, expected)
    relation = accepted.realization.rows[0].relation
    assert relation.feeder.ref == step.source_serial
    assert relation.proof_source.ref == step.old_dispatcher_serial
    assert relation.old_target == relation.proof_source
    assert {
        (arm.role, arm.target.ref) for arm in relation.arms
    } == {
        (SemanticEdgeRole.CONDITIONAL_FALLTHROUGH, step.false_target_serial),
        (SemanticEdgeRole.CONDITIONAL_TAKEN, step.true_target_serial),
    }
    discarded_owner = next(
        arm.target for arm in relation.arms
        if arm.role is SemanticEdgeRole.CONDITIONAL_FALLTHROUGH
    )
    raw = phase.raw_effect_gate_fact
    assert raw.pre_effectful_source_owners == (discarded_owner,)
    assert raw.raw_retained_source_owners == (discarded_owner,)
    assert raw.raw_lost_source_owners == ()
    assert len(phase.exact_effect_bindings) == 2
    bindings_by_site = {
        (binding.source_site.instruction_ea, binding.source_site.effect_kind): binding
        for binding in phase.exact_effect_bindings
    }
    assert set(bindings_by_site) == {
        (0x4000, model.EffectSiteKind.STORE),
        (0x4001, model.EffectSiteKind.CALL),
    }
    assert {
        binding.supporting_route_relation_id
        for binding in phase.exact_effect_bindings
    } == {relation.relation_id}
    assert len(phase.effect_results) == 2
    for result in phase.effect_results:
        binding = bindings_by_site[
            (result.source_site.instruction_ea, result.source_site.effect_kind)
        ]
        assert result.outcome is model.ProjectedEffectSiteOutcome.PRESERVED
        assert result.lineage_kind is model.ProjectedSiteLineageKind.SAME_OWNER
        assert result.source_site == result.projected_site
        assert result.supporting_claim_id is None
        assert result.supporting_binding_result_id is None
        assert result.latent_exact_binding_result_id == binding.binding_result_id
        assert result.relation_id is None
    assert len(phase.terminal_results) == 1
    terminal = phase.terminal_results[0]
    assert terminal.source_site.owner == discarded_owner
    assert terminal.source_site.instruction_ea == 0x4001
    assert terminal.source_site.terminal_kind is model.TerminalKind.NORETURN_CALL
    assert terminal.outcome is model.ProjectedTerminalSiteOutcome.PRESERVED
    assert terminal.lineage_kind is model.ProjectedSiteLineageKind.SAME_OWNER
    assert terminal.source_site == terminal.projected_site
    preservation = accepted.realization.rows[0].site_preservation
    assert preservation.effect_result_ids == tuple(sorted(
        result.result_id for result in phase.effect_results
    ))
    assert preservation.terminal_result_ids == (terminal.result_id,)


def test_task_15_lowered_vertical_exact_call_does_not_authorize_lost_noreturn_terminal() -> None:
    """Latent exact CALL authority cannot cover its missing terminal occurrence."""
    import gc

    values = _task_15_vertical_inputs(
        lambda: _task_15_lowered_conditional_vertical_case(
            remove_projected_noreturn_terminal=True,
        ),
    )
    assert {
        (row.instruction_ea, row.effect_kind)
        for row in values["projected_inventory"].effects
        if row.owner_serial in values["projected_inventory"].reachable_serials
    } == {
        (0x4000, model.EffectSiteKind.STORE),
        (0x4001, model.EffectSiteKind.CALL),
    }
    assert not any(
        row.terminal_kind is model.TerminalKind.NORETURN_CALL
        for row in values["projected_inventory"].terminals
        if row.owner_serial in values["projected_inventory"].reachable_serials
    )
    gc.collect()
    before = _task_15_publication_type_counts()

    events = _task_15_observe_publication_events(
        lambda: bind.realize_projected_routes(**values),
    )
    rejected = events.result

    assert type(rejected) is model.ProjectedRouteRealizationRejected
    assert len(rejected.failures) == 1
    failure = rejected.failures[0]
    route_claim = next(
        claim for claim in values["claims"]
        if type(claim) is model.EquivalentSemanticRouteClaim
    )
    proof = values["source_authority"].proposal.route_evidence.route_proofs[0]
    fact = values["patch_step_facts"][0]
    step = values["plan"].steps[0]
    source_blocks = {
        row.block_ref: row for row in values["source_inventory"].blocks
    }
    expected_anchors = _mechanical_sorted_anchors(tuple(
        model.AnchoredBlockRef(ref, source_blocks[ref].anchor_ea)
        for ref in (
            step.source_serial, step.old_dispatcher_serial,
            step.false_target_serial, step.true_target_serial,
        )
    ))
    assert failure.stage is model.RouteRealizationFailureStage.EFFECT_TERMINAL_PRESERVATION
    assert failure.scope is model.RouteRealizationFailureScope.STEP
    assert failure.claim_id == route_claim.claim_id
    assert failure.proof_id == proof.proof_id
    assert failure.step_index == fact.step_index
    assert failure.step_digest == fact.step_digest
    assert failure.anchored_refs == expected_anchors
    assert events.commits == ()
    assert not any(type(value) in events.accepted_types for value in events.deferred)
    assert not any(type(value) in events.accepted_types for value in events.ordinary)
    assert tuple(type(value) for value in events.ordinary) == (
        model.RouteRealizationFailure,
        model.ProjectedRouteRealizationRejected,
    )
    assert _task_15_publication_type_counts() == before


def test_task_15_cloned_conditional_vertical_maps_proof_prefix_to_exact_clone(
) -> None:
    """RF-2 maps the real proof prefix to one exact compiler clone."""
    from d810.transforms.plan import PatchConditionalRedirect

    produced = []
    bound = []
    real_producer = producer_api.build_proposal
    real_source_binder = bind.bind_source_route_authority

    def produce(*args, **kwargs):
        value = real_producer(*args, **kwargs)
        produced.append(value)
        return value

    def bind_source(*args, **kwargs):
        value = real_source_binder(*args, **kwargs)
        bound.append(value)
        return value

    with (
        patch.object(
            producer_api, "build_proposal", side_effect=produce,
        ) as producer_spy,
        patch.object(
            bind, "bind_source_route_authority", side_effect=bind_source,
        ) as source_binder_spy,
        patch.object(
            transaction_api, "_build_semantic_graph_inventory",
            wraps=transaction_api._build_semantic_graph_inventory,
        ) as inventory_spy,
    ):
        case = _task_15_cloned_conditional_vertical_case()
    assert producer_spy.call_count == len(produced) == 1
    assert produced[0] is case.proposal is case.plan.unflatten_proposal
    assert producer_spy.call_args.kwargs["source"] is case.source_graph
    assert source_binder_spy.call_count == len(bound) == 1
    assert bound[0].authority is case.source_authority
    assert inventory_spy.call_count == 2
    assert tuple(call.args[0] for call in inventory_spy.call_args_list) == (
        case.source_graph, case.projected_graph,
    )
    assert tuple(
        call.kwargs["phase"] for call in inventory_spy.call_args_list
    ) == (
        model.UnflattenAuthorityPhase.PRODUCER_FORECAST,
        model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
    )
    values = _task_15_cloned_conditional_vertical_inputs(case)
    expected = _task_15_independent_expected_publication(values)
    step = case.plan.steps[0]
    assert type(step) is PatchConditionalRedirect
    assert not any(
        type(claim) is model.ExactInfeasibleEffectClaim
        for claim in values["claims"]
    )
    helper_effects = tuple(
        row for row in case.projected_inventory.effects
        if row.owner_ref == step.fallthrough_block_id
    )
    helper_terminals = tuple(
        row for row in case.projected_inventory.terminals
        if row.owner_ref == step.fallthrough_block_id
    )
    assert helper_effects == helper_terminals == ()

    with (
        patch.object(
            bind, "_draft_projected_site_closure",
            wraps=bind._draft_projected_site_closure,
        ) as drafter_spy,
        patch.object(
            bind, "_validate_projected_site_closure_draft",
            wraps=bind._validate_projected_site_closure_draft,
        ) as validator_spy,
        patch.object(
            bind._AtomicPublicationBatch, "commit", autospec=True,
            side_effect=bind._AtomicPublicationBatch.commit,
        ) as commit_spy,
        patch.object(
            transaction_api, "_build_semantic_graph_inventory",
            side_effect=AssertionError("projected closure inventory replay"),
        ),
        patch.object(
            bind, "bind_source_route_authority",
            side_effect=AssertionError("projected closure source replay"),
        ),
        patch.object(
            route_model, "bind_canonical_semantic_evidence_result",
            side_effect=AssertionError("projected closure route replay"),
        ),
        patch.object(
            producer_api, "validate_exact_effect_claim_semantics",
            side_effect=AssertionError("projected closure producer exact replay"),
        ),
        patch.object(
            evaluate, "_classify_effect_site",
            side_effect=AssertionError("projected closure evaluator replay"),
        ),
    ):
        accepted = bind.realize_projected_routes(**values)

    assert drafter_spy.call_count == 1
    assert validator_spy.call_count == 1
    assert commit_spy.call_count == 1
    phase = _assert_task_15_cloned_conditional_publication(
        values, accepted, expected,
    )
    relation = accepted.realization.rows[0].relation
    assert relation.feeder.ref == step.source_serial
    assert relation.proof_source.ref == step.ref_block
    assert relation.old_target == relation.proof_source
    assert relation.replacement_clone.ref == step.block_id
    assert relation.fallthrough_helper.ref == step.fallthrough_block_id
    assert {
        (arm.role, arm.target.ref) for arm in relation.arms
    } == {
        (SemanticEdgeRole.CONDITIONAL_FALLTHROUGH, step.fallthrough_target),
        (SemanticEdgeRole.CONDITIONAL_TAKEN, step.conditional_target),
    }
    raw = phase.raw_effect_gate_fact
    assert raw.raw_lost_source_owners == (relation.proof_source,)
    assert relation.proof_source in raw.pre_effectful_source_owners
    assert relation.proof_source not in raw.raw_retained_source_owners
    clone_effects = tuple(
        result for result in phase.effect_results
        if result.source_site.owner == relation.proof_source
    )
    assert len(clone_effects) == 2
    assert {
        result.source_site.effect_kind for result in clone_effects
    } == {model.EffectSiteKind.STORE, model.EffectSiteKind.CALL}
    source_blocks = {
        row.block_ref: row for row in case.source_inventory.blocks
    }
    projected_blocks = {
        row.block_ref: row for row in case.projected_inventory.blocks
    }
    for result in clone_effects:
        assert result.outcome is model.ProjectedEffectSiteOutcome.RELATION_CLONED
        assert result.lineage_kind is model.ProjectedSiteLineageKind.RELATION_CLONE
        assert result.relation_id == relation.relation_id
        assert result.projected_site.owner == relation.replacement_clone
        assert (
            result.source_site.instruction_ordinal,
            result.source_site.instruction_ea,
            result.source_site.effect_kind,
            result.source_site.opcode,
            result.source_site.width,
        ) == (
            result.projected_site.instruction_ordinal,
            result.projected_site.instruction_ea,
            result.projected_site.effect_kind,
            result.projected_site.opcode,
            result.projected_site.width,
        )
        source_observation = source_blocks[
            relation.proof_source.ref
        ].instruction_observations[result.source_site.instruction_ordinal]
        projected_observation = projected_blocks[
            relation.replacement_clone.ref
        ].instruction_observations[result.projected_site.instruction_ordinal]
        assert (
            source_observation.instruction_kind,
            source_observation.opcode,
            source_observation.raw_opcode,
            source_observation.width,
        ) == (
            projected_observation.instruction_kind,
            projected_observation.opcode,
            projected_observation.raw_opcode,
            projected_observation.width,
        )
        assert result.supporting_claim_id is None
        assert result.supporting_binding_result_id is None
        assert result.latent_exact_binding_result_id is None
    same_owner_effects = tuple(
        result for result in phase.effect_results
        if result.source_site.owner != relation.proof_source
    )
    assert {
        result.source_site.owner for result in same_owner_effects
    } == {
        relation.feeder, *(arm.target for arm in relation.arms),
    }
    assert all(
        result.outcome is model.ProjectedEffectSiteOutcome.PRESERVED
        and result.lineage_kind is model.ProjectedSiteLineageKind.SAME_OWNER
        and result.source_site == result.projected_site
        and result.relation_id is None
        for result in same_owner_effects
    )
    assert len(phase.terminal_results) == 1
    terminal = phase.terminal_results[0]
    assert terminal.source_site.owner in {arm.target for arm in relation.arms}
    assert terminal.outcome is model.ProjectedTerminalSiteOutcome.PRESERVED
    assert terminal.lineage_kind is model.ProjectedSiteLineageKind.SAME_OWNER
    assert terminal.source_site == terminal.projected_site
    assert terminal.relation_id is None
    preservation = accepted.realization.rows[0].site_preservation
    exact_incidence_owners = {
        relation.feeder, relation.proof_source,
        *(arm.target for arm in relation.arms),
    }
    assert preservation.effect_result_ids == tuple(sorted(
        result.result_id for result in phase.effect_results
        if result.source_site.owner in exact_incidence_owners
    ))
    assert preservation.terminal_result_ids == tuple(sorted(
        result.result_id for result in phase.terminal_results
        if result.source_site.owner in exact_incidence_owners
    ))
    assert phase.exact_effect_bindings == ()
    assert phase.local_alias_bindings == ()


