    occurrences = tuple(
        (row.relation_id, row.source_owner, row.projected_owner, row.lineage)
        for row in owner_index.relation_owner_occurrences
    )
    assert len(occurrences) == 3
    assert set(occurrences) == {
        (relation.relation_id, relation.feeder, relation.feeder, same),
        (
            relation.relation_id, relation.untouched_conditional_arm,
            relation.untouched_conditional_arm, same,
        ),
        (
            relation.relation_id, relation.semantic_target,
            relation.semantic_target, same,
        ),
    }
    assert sum(
        row.source_owner == relation.source_fallthrough
        for row in owner_index.relation_owner_occurrences
    ) == 1
    owner_rows = tuple(
        (row.source_owner, row.projected_owner, row.lineage)
        for row in owner_index.owner_rows
    )
    assert len(owner_rows) == 3
    assert set(owner_rows) == {
        (relation.feeder, relation.feeder, same),
        (
            relation.untouched_conditional_arm,
            relation.untouched_conditional_arm, same,
        ),
        (relation.semantic_target, relation.semantic_target, same),
    }
    assert owner_index.inverse_only_projected_owners == (relation.helper,)
    assert {
        (result.source_site.owner, result.source_site.effect_kind)
        for result in phase.effect_results
    } == {
        (relation.feeder, model.EffectSiteKind.STORE),
        (relation.untouched_conditional_arm, model.EffectSiteKind.CALL),
        (relation.semantic_target, model.EffectSiteKind.STORE),
    }
    assert all(
        result.outcome is model.ProjectedEffectSiteOutcome.PRESERVED
        and result.lineage_kind is same
        and result.source_site == result.projected_site
        and result.relation_id is None
        and result.supporting_claim_id is None
        and result.supporting_binding_result_id is None
        for result in phase.effect_results
    )
    assert len(phase.terminal_results) == 1
    terminal = phase.terminal_results[0]
    assert terminal.source_site.owner == relation.untouched_conditional_arm
    assert terminal.source_site.terminal_kind is model.TerminalKind.NORETURN_CALL
    assert terminal.outcome is model.ProjectedTerminalSiteOutcome.PRESERVED
    assert terminal.lineage_kind is same
    assert terminal.source_site == terminal.projected_site
    subset = accepted.realization.rows[0].site_preservation
    assert subset.effect_result_ids == tuple(sorted(
        result.result_id for result in phase.effect_results
    ))
    assert subset.terminal_result_ids == (terminal.result_id,)
    assert not any(
        result.source_site.owner == relation.helper
        for result in (*phase.effect_results, *phase.terminal_results)
    )


