@pytest.mark.parametrize("coordinate", ("from_serial", "old_target", "new_target"))
def test_task_15_selected_arm_step_coordinate_drift_rejects_end_to_end(
    coordinate: str,
) -> None:
    """A closed but mis-correlated RedirectGoto fails at its typed STEP gate."""
    from d810.transforms.unflatten_authority.ids import projected_authority_id

    values = _task_15_vertical_inputs(lambda: _task_15_exact_direct_case("call"))
    plan = values["plan"]
    step = plan.steps[0]
    replacement = {
        "from_serial": step.old_target,
        "old_target": step.new_target,
        "new_target": step.old_target,
    }[coordinate]
    mutated_plan = replace(
        plan, steps=(replace(step, **{coordinate: replacement}),),
    )
    facts = transaction_api._derive_patch_lineage_facts(
        values["source_inventory"], mutated_plan,
    )
    values.update(plan=mutated_plan, patch_step_facts=facts)
    values["authority_id"] = projected_authority_id(
        attempt_id=values["attempt_id"],
        proposal_id=values["source_authority"].proposal_id,
        source_authority_id=values["source_authority"].source_authority_id,
        plan_id=mutated_plan.plan_id, claims=values["claims"],
        patch_step_facts=facts,
        source_inventory=values["source_inventory"],
        projected_inventory=values["projected_inventory"],
        raw_effect_gate_fact=values["raw_effect_gate_fact"],
    )
    before = _task_15_publication_type_counts()
    rejected = bind.realize_projected_routes(**values)
    assert type(rejected) is model.ProjectedRouteRealizationRejected
    failure = rejected.failures[0]
    assert failure.stage is model.RouteRealizationFailureStage.PLAN_STEP_CORRELATION
    assert failure.scope is model.RouteRealizationFailureScope.STEP
    assert failure.step_index == facts[0].step_index
    assert failure.step_digest == facts[0].step_digest
    route_claim = next(
        claim for claim in values["claims"]
        if type(claim) is model.EquivalentSemanticRouteClaim
    )
    assert failure.claim_id == route_claim.claim_id
    proof = values["plan"].unflatten_proposal.route_evidence.route_proofs[0]
    assert failure.proof_id == proof.proof_id
    locator = route_claim.retired_route_subject.locator
    assert failure.anchored_refs == tuple(sorted((
        model.AnchoredBlockRef(locator.source_ref, locator.source_anchor_ea),
        *tuple(
            model.AnchoredBlockRef(ref, anchor)
            for ref, anchor in zip(
                locator.destination_refs, locator.destination_anchor_eas,
            )
        ),
    ), key=canonical_bytes))
    assert _task_15_publication_type_counts() == before


