@pytest.mark.parametrize("mutation", ("equal_clone", "duplicate", "foreign", "mixed"))
def test_task_15_direct_vertical_rejects_non_owned_exact_claim_bundles(
    mutation: str,
) -> None:
    """The public typed boundary admits only the exact proposal claim tuple."""
    values = _task_15_vertical_inputs(lambda: _task_15_exact_direct_case("call_store"))
    exact = tuple(
        claim for claim in values["claims"]
        if type(claim) is model.ExactInfeasibleEffectClaim
    )
    assert len(exact) == 2
    foreign_values = _task_15_vertical_inputs(
        lambda: _task_15_exact_direct_case("store"),
    )
    foreign = next(
        claim for claim in foreign_values["claims"]
        if type(claim) is model.ExactInfeasibleEffectClaim
    )
    if mutation == "equal_clone":
        replacement = _clone_record(exact[0])
        claims = tuple(replacement if claim is exact[0] else claim for claim in values["claims"])
    elif mutation == "duplicate":
        claims = tuple(sorted((*values["claims"], exact[0]), key=lambda claim: claim.claim_id))
    elif mutation == "foreign":
        claims = tuple(foreign if claim is exact[0] else claim for claim in values["claims"])
    else:
        claims = tuple(sorted((*values["claims"], foreign), key=lambda claim: claim.claim_id))
    before_sites = len(bind._SITE_REGISTRY)
    before_bindings = len(bind._SITE_BINDING_REGISTRY)
    rejected = bind.realize_projected_routes(**{**values, "claims": claims})
    assert type(rejected) is model.ProjectedRouteRealizationRejected
    assert rejected.failures[0].stage is model.RouteRealizationFailureStage.ATTEMPT_BINDING
    assert len(bind._SITE_REGISTRY) == before_sites
    assert len(bind._SITE_BINDING_REGISTRY) == before_bindings


def test_task_15_direct_vertical_transaction_local_store_scalarizes_to_mov() -> None:
    """DIRECT local closure consumes one real transaction-derived STORE claim."""
    derive_transaction = transaction_api._derive_transaction_facts
    derive_lineage = transaction_api._derive_patch_lineage_facts
    with patch.object(
        transaction_api, "_derive_transaction_facts", wraps=derive_transaction,
    ) as transaction_spy, patch.object(
        transaction_api, "_derive_patch_lineage_facts", wraps=derive_lineage,
    ) as lineage_spy:
        authority, plan, source, projected, _lineage, attempt, derived = (
            _task_15_direct_vertical_case(
                local_alias=True, derive_transaction=True,
            )
        )
    assert transaction_spy.call_count == 1
    assert lineage_spy.call_count == 1
    assert derived is not None
    route_occurrences = {id(item) for item in derived.route_patch_step_facts}
    local_occurrences = {id(item) for item in derived.local_patch_step_facts}
    assert route_occurrences.isdisjoint(local_occurrences)
    assert route_occurrences | local_occurrences == {
        id(item) for item in derived.patch_step_facts
    }
    assert derived.patch_step_facts == tuple(sorted(
        derived.patch_step_facts, key=patch_step_fact_id,
    ))
    inventory = bind._bind_transaction_projected_claim_inventory(
        derived=derived, source_authority=authority, attempt_id=attempt,
        projected_inventory=projected,
    )
    values = _task_15_vertical_inputs_from_claim_inventory(inventory)
    expected = _task_15_independent_expected_publication(values)
    with patch.object(
        transaction_api, "_derive_transaction_facts",
        side_effect=AssertionError("transaction fact replay"),
    ), patch.object(
        transaction_api, "_derive_patch_lineage_facts",
        side_effect=AssertionError("lineage fact replay"),
    ), patch.object(
        transaction_api, "_derive_local_alias_transaction_facts",
        side_effect=AssertionError("local fact replay"),
    ):
        accepted = bind._realize_projected_routes_from_claim_inventory(
            authority_id=values["authority_id"],
            claim_inventory=values["claim_inventory"],
            raw_effect_gate_fact=values["raw_effect_gate_fact"],
            legacy_effective_gate_facts=values["legacy_effective_gate_facts"],
        )
    phase = _assert_task_15_direct_publication(values, accepted, expected)
    assert len(phase.local_alias_bindings) == 1
    binding = phase.local_alias_bindings[0]
    assert binding.claim is derived.local_alias_occurrences[0].claim
    assert binding.patch_step_fact is derived.local_alias_occurrences[0].patch_step_fact
    effect = next(
        row for row in phase.effect_results
        if row.source_site.effect_kind is model.EffectSiteKind.STORE
    )
    assert effect.outcome is model.ProjectedEffectSiteOutcome.LOCAL_ALIAS_SCALARIZED
    source_store_subject = next(
        subject for subject in source.subjects
        if subject.kind is model.SemanticSubjectKind.EFFECT
        and type(subject.locator) is model.EffectSubjectLocator
        and subject.locator.instruction_ea == effect.source_site.instruction_ea
        and subject.locator.effect_kind is model.EffectSiteKind.STORE
    )
    assert effect.source_subject_id == source_store_subject.subject_id
    assert effect.source_subject_id != binding.claim.owner_subject.subject_id
    assert effect.scalarized_site == binding.scalarized_site
    assert effect.scalarized_site.instruction_kind is InsnKind.MOV
    assert effect.supporting_claim_id == binding.claim.claim_id
    assert effect.supporting_binding_result_id == binding.binding_result_id
    assert any(
        row.source_site.effect_kind is model.EffectSiteKind.CALL
        and row.outcome is model.ProjectedEffectSiteOutcome.PRESERVED
        for row in phase.effect_results
    )
    assert len(phase.terminal_results) == 1
    assert phase.terminal_results[0].outcome is model.ProjectedTerminalSiteOutcome.PRESERVED


