@pytest.mark.parametrize(
    "mutation",
    ("derived", "source_authority", "attempt", "source_inventory", "projected_inventory"),
)
def test_task_15_transaction_projected_claim_inventory_rejects_equal_clones(
    mutation: str,
) -> None:
    """Every lifecycle coordinate is bound by exact occurrence, not equality."""
    authority, plan, source, projected, _lineage, attempt = (
        _task_15_direct_vertical_case(local_alias=True)
    )
