def _compiler_split_case(*, corridor_length: int = 1, corridor: bool = False,
                         partition: bool = False, extra_prefix_origin: bool = False):
    """Build a compiler-finalized split/trampoline or clone corridor case."""
    from d810.ir.flowgraph import FlowGraph, InsnKind, MopSnapshot, OperandKind, ValueOpKind
    from d810.transforms.edit_simulator import project_post_state
    from d810.transforms.graph_modification import EdgeRedirectViaPredSplit
    from d810.transforms.plan import PatchEdgeSplitCorridor, PatchEdgeSplitTrampoline
    from d810.transforms.cfg_transaction import TransactionAttemptId
    from tests.typed_patch_authority import compile_patch_plan

    if corridor_length not in (1, 2):
        raise ValueError("compiler split fixture supports one or two corridor blocks")
    source, base, _exclusion, refs = exact_fixture()
    updated_catalog = None
    if extra_prefix_origin:
        old_ref = refs[1]
        new_identity = StableBlockIdentity.from_instruction_eas(
            (0x1FFF, 0x2000, 0x2001),
            native_key=old_ref.identity.native_key,
        )
        new_ref = NativeBlockRef(new_identity)
        refs = {**refs, 1: new_ref}
        catalog = tuple(
            model.SourceBlockIdentityWitness(
                new_ref if block.block_ref == old_ref else block.block_ref,
                block.anchor_ea,
                (0x1FFF, 0x2000, 0x2001)
                if block.block_ref == old_ref else block.native_instruction_eas,
            )
            for block in base.source_identity_catalog.blocks
        )
        updated_catalog = replace(
            base.source_identity_catalog, blocks=catalog,
        )
    blocks = dict(source.blocks)
    first = blocks[1].insn_snapshots[0]
    blocks[1] = replace(
        blocks[1],
        insn_snapshots=(
            replace(
                first, kind=InsnKind.MOV, value_op_kind=ValueOpKind.MOVE,
                l=MopSnapshot(kind=OperandKind.NUMBER, size=4, value=7),
                d=MopSnapshot(kind=OperandKind.STACK, size=4, stkoff=4, stack_refs=(4,)),
            ), blocks[1].insn_snapshots[1],
        ),
    )
    if extra_prefix_origin:
        extra = replace(
            first, ea=0x1FFF, value_op_kind=ValueOpKind.MOVE,
            l=MopSnapshot(kind=OperandKind.NUMBER, size=4, value=6),
            d=MopSnapshot(kind=OperandKind.STACK, size=4, stkoff=8),
        )
        blocks[1] = replace(
            blocks[1], insn_snapshots=(extra, *blocks[1].insn_snapshots),
        )
    if partition:
        # The partition prover accepts the real carrier shape used by the
        # semantic-route producer: owner writes the constant to a register,
        # then the shared feeder materializes that carrier into the state slot.
        owner_first = blocks[0].insn_snapshots[0]
        blocks[0] = replace(
            blocks[0],
            insn_snapshots=(replace(
                owner_first,
                d=MopSnapshot(kind=OperandKind.REGISTER, size=4, reg=16),
            ), blocks[0].insn_snapshots[1]),
        )
        feeder_first = blocks[1].insn_snapshots[0]
        blocks[1] = replace(
            blocks[1],
            insn_snapshots=(replace(
                feeder_first,
                l=MopSnapshot(kind=OperandKind.REGISTER, size=4, reg=16),
            ), blocks[1].insn_snapshots[1]),
        )
        blocks[1] = _one_way_goto(blocks[1], 2, preds=(0,))
        branch = replace(
            blocks[1].insn_snapshots[0], ea=0x3000,
            kind=InsnKind.COND_JUMP,
            value_op_kind=None,
            control_transfer_kind=ControlTransferKind.CONDITIONAL_BRANCH,
            branch_predicate=__import__("d810.ir.flowgraph", fromlist=["PredicateKind"]).PredicateKind.EQ,
            is_conditional_jump=True,
            l=MopSnapshot(kind=OperandKind.STACK, size=4, stkoff=4, stack_refs=(4,)),
            r=MopSnapshot(kind=OperandKind.NUMBER, size=4, value=7),
            d=MopSnapshot(kind=OperandKind.BLOCK, block_ref=4),
        )
        blocks[2] = replace(
            blocks[2], succs=(4, 3), preds=(1,), kind=BlockKind.TWO_WAY,
            tail_kind=InsnKind.COND_JUMP, insn_snapshots=(branch,),
        )
        # This fixture exercises carrier partition/corridor realization, not
        # effect exclusion.  Keep the structurally unselected arm as ordinary
        # plumbing into the same semantic target; a reachable CALL/terminal
        # on that arm would require its own exact effect-loss claim.
        blocks[3] = _one_way_goto(blocks[3], 4, preds=(2,))
        blocks[4] = replace(blocks[4], preds=(2, 3))
        source_corridor = (1,)
        old_target = 2
        clone_until = 1
    else:
        blocks[1] = _one_way_goto(blocks[1], 2, preds=(0,))
    if corridor_length == 1 and not partition:
        blocks[2] = replace(blocks[2], preds=(1,))
        blocks[3] = replace(blocks[3], preds=())
        source_corridor = (1,)
        old_target = 2
        clone_until = 1
    elif not partition:
        blocks[2] = _one_way_goto(blocks[2], 3, preds=(1,))
        # Keep the two-block corridor fixture focused on route realization.
        # The relation's ``terminal_continuation`` is the structural
        # continuation after the cloned prefix, not an implicit allowance to
        # retire a reachable no-return CALL.  Make that continuation ordinary
        # plumbing into the semantic target so effect/terminal loss remains
        # covered only by its own typed claim in dedicated fixtures.
        blocks[3] = _one_way_goto(blocks[3], 4, preds=(2,))
        source_corridor = (1, 2)
        old_target = 2
        clone_until = 2
    if not partition:
        blocks[4] = replace(
            blocks[4], preds=((3,) if corridor_length == 2 else ()),
        )
    source = FlowGraph(blocks, source.entry_serial, source.func_ea)

    state = base.route_evidence.route_proofs[0].state_write.state_variable
    dag = route_model.DecisionDagRouteWitness(
        state, 7, 2, 0x3000, (2,), (0x3000,),
        ((2, RouteComparison(2, "jz", 7, 4, 3)),), (),
    )
    partition_witness = route_model.StatePartitionGroupWitness(
        authority_id("3b3-partition-group"), 1, 0x2000, state,
        (route_model.StatePartitionMemberWitness(0, 1, state, 7),),
    )
    fact = route_model.SemanticRouteFact(
        route_model.SemanticRouteFactKind.STATE_PARTITION if partition else route_model.SemanticRouteFactKind.NATIVE_BOUND,
        0, 1, 0x2000, 7, 4, 0x1000, 0x5000, (0, 1), ((0, 1),),
        authority_id("3b3-split-fact"),
        partition_witness=(partition_witness if partition else None),
        decision_dag_witness=(dag if partition else None),
    )
    context = route_model.CanonicalSemanticEvidenceProductionContext(
        base.route_evidence.native_key, 1, authority_id("3b3-split-group"), state,
        tuple(source.blocks.values()),
        tuple((serial, ref.identity) for serial, ref in refs.items()),
        source.entry_serial,
    )
    produced = route_model.build_canonical_semantic_evidence((fact,), context)
    assert produced.abstention is None and produced.evidence is not None
    evidence = produced.evidence
    proof = evidence.route_proofs[0]
    claims = producer_api.build_equivalent_route_claims(
        source=source, source_catalog=(updated_catalog or base.source_identity_catalog),
        route_evidence=evidence, selected_proof_ids=(proof.proof_id,),
    )
    proposal = replace(
        base, route_evidence=evidence, claims=claims,
        source_identity_catalog=(updated_catalog or base.source_identity_catalog),
        plan_inputs=replace(
            base.plan_inputs, shape=model.UnflattenPlanShape.PARTIAL_REWRITE,
            dispatcher_entry_ref=refs[1],
            dispatcher_member_refs=tuple(refs[serial] for serial in (0, 1, 2)),
        ),
    )
    modification = EdgeRedirectViaPredSplit(
        1, old_target, 4, 0,
        clone_until=(clone_until if corridor else None),
    )
    if partition:
        from d810.backends.hexrays.evidence.condition_chain_analysis import build_condition_chain_walker_provider
        from d810.capabilities.providers import register_condition_chain_walkers
        register_condition_chain_walkers(build_condition_chain_walker_provider())
    compiled = compile_patch_plan(
        [modification], source, plan_id=proposal.plan_id,
        source_generation=1, block_refs_by_serial=refs,
    )
    plan = replace(
        compiled,
        source_coordinates=tuple((ref, serial) for serial, ref in refs.items()),
        unflatten_proposal=proposal,
    )
    materialization = route_model.CanonicalRouteMaterialization.capture(
        source, generation=1, phase=route_model.CanonicalRouteAssessmentPhase.SOURCE,
    )
    source_inventory = transaction_api._build_semantic_graph_inventory(
        source, proposal, plan, source=True,
        phase=model.UnflattenAuthorityPhase.PRODUCER_FORECAST,
        materialization=materialization,
    )
    authority = bind.bind_source_route_authority(
        proposal=proposal, source_inventory=source_inventory,
        source_materialization=materialization,
    )
    assert type(authority) is model.SourceBoundRouteAuthorityAccepted
    projected = project_post_state(source, plan)
    projected_inventory = transaction_api._build_semantic_graph_inventory(
        projected, proposal, plan, source=False,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        materialization=None, source_subjects=source_inventory.subjects,
    )
    facts = transaction_api._derive_patch_lineage_facts(source_inventory, plan)
    attempt = TransactionAttemptId(
        plan.plan_id, authority_id("3b3-split-session"), 1,
        authority_id("3b3-split-attempt"),
    )
    expected = model.ClonedRouteCorridorRealization if corridor else None
    assert type(plan.steps[0]) is (
        PatchEdgeSplitCorridor if corridor else PatchEdgeSplitTrampoline
    )
    return authority.authority, plan, source_inventory, projected_inventory, facts, attempt, expected


def _compiler_empty_split_unsupported_case(*, proof_kind):
    """Compile P->S->O with an empty S and SOURCE-bind a real bootstrap/terminal proof."""
    from d810.analyses.control_flow.semantic_route_evidence import (
        CanonicalSemanticEvidenceProductionContext,
        DecisionDagRouteWitness,
        SemanticBootstrapRouteWitness,
        SemanticRouteFact,
        SemanticRouteFactKind,
    )
    from d810.analyses.control_flow.terminal_return_carrier_evidence import (
        TerminalReturnCarrierEvidence,
        TerminalReturnCarrierSource,
        TerminalReturnCarrierSourceKind,
    )
    from d810.ir.flowgraph import FlowGraph, InsnSnapshot, PredicateKind, ValueOpKind
    from d810.ir.instructions import InstructionEffectKind, InstructionEffectSite
    from d810.ir.storage_identity import StorageIdentity, StorageIdentityKind
    from d810.transforms.edit_simulator import project_post_state
    from d810.transforms.graph_modification import EdgeRedirectViaPredSplit
    from tests.typed_patch_authority import compile_patch_plan

    source, base, _exclusion, refs = exact_fixture()
    blocks = dict(source.blocks)
    # Entry 0 -> P1 -> empty S2 -> dispatcher O3.  The split rewrites P1's
    # edge to S2; S2 itself contains no semantic MOV/work, only a GOTO.
    p_tail = replace(
        blocks[1].insn_snapshots[-1], ea=0x2001, kind=InsnKind.GOTO,
        l=MopSnapshot(kind=OperandKind.BLOCK, block_ref=2), r=None, d=None,
        control_transfer_kind=None, is_conditional_jump=False,
        is_unconditional_jump=True,
    )
    blocks[1] = replace(
        blocks[1], succs=(2,), preds=(0,), kind=BlockKind.ONE_WAY,
        tail_kind=InsnKind.GOTO,
        insn_snapshots=(
                replace(
                    blocks[1].insn_snapshots[0], kind=InsnKind.STORE,
                    value_op_kind=ValueOpKind.STORE,
                    l=MopSnapshot(kind=OperandKind.NUMBER, size=4, value=7),
                    d=MopSnapshot(
                        kind=OperandKind.ADDRESS, size=8, stack_refs=(4,),
                        sub_l=MopSnapshot(kind=OperandKind.STACK, size=4, stkoff=4, stack_refs=(4,)),
                    ),
                ),
            p_tail,
        ),
    )
    blocks[2] = _one_way_goto(blocks[2], 3, preds=(1,))
    dispatcher_tail = replace(
        source.blocks[1].insn_snapshots[-1],
        ea=0x4000, kind=InsnKind.COND_JUMP,
        l=MopSnapshot(kind=OperandKind.STACK, size=4, stkoff=4, stack_refs=(4,)),
        r=MopSnapshot(kind=OperandKind.NUMBER, size=4, value=7),
        d=MopSnapshot(kind=OperandKind.BLOCK, block_ref=4),
        control_transfer_kind=ControlTransferKind.CONDITIONAL_BRANCH,
        branch_predicate=PredicateKind.EQ, is_conditional_jump=True,
        is_unconditional_jump=False,
    )
    blocks[3] = replace(
        blocks[3], succs=(4, 5), preds=(2,), kind=BlockKind.TWO_WAY,
        tail_kind=InsnKind.COND_JUMP, insn_snapshots=(dispatcher_tail,),
    )
    blocks[4] = replace(blocks[4], preds=(3,))
    blocks[5] = replace(
        blocks[4], serial=5, start_ea=0x6000, preds=(3,),
        insn_snapshots=(replace(blocks[4].insn_snapshots[0], ea=0x6000),),
    )
    refs = dict(refs)
    refs[5] = NativeBlockRef(StableBlockIdentity.from_instruction_eas(
        (0x6000,), native_key=refs[4].identity.native_key,
    ))
    state = StorageIdentity(StorageIdentityKind.STACK, 4)
    if proof_kind is route_model.SemanticRouteProofKind.BOOTSTRAP:
        dag = DecisionDagRouteWitness(
            state, 7, 3, 0x4000, (3,), (0x4000,),
            ((3, RouteComparison(3, "jz", 7, 4, 5)),), (),
        )
        witness = SemanticBootstrapRouteWitness(
            0, 1, 0x2000, 2, 3, state, 7, 4,
            (1, 2, 3), (0x2000, 0x3000, 0x4000),
            (InstructionEffectSite(0x2000, InstructionEffectKind.STORE, 0x2000),), dag,
        )
        fact = SemanticRouteFact(
            SemanticRouteFactKind.BOOTSTRAP, 2, 1, 0x2000, 7,
            4, 0x3000, 0x5000, (1, 2), ((1, 2),),
            authority_id("3b3-empty-s-bootstrap"),
            decision_dag_witness=dag, bootstrap_witness=witness,
        )
    elif proof_kind is route_model.SemanticRouteProofKind.TERMINAL_RETURN:
        first = blocks[1].insn_snapshots[0]
        state_write = replace(
            first, kind=InsnKind.MOV, value_op_kind=ValueOpKind.MOVE,
            l=MopSnapshot(kind=OperandKind.NUMBER, size=4, value=7),
            d=MopSnapshot(kind=OperandKind.REGISTER, size=4, reg=16),
        )
        carrier = replace(state_write, ea=0x2001)
        goto = replace(
            blocks[1].insn_snapshots[-1], ea=0x2002, kind=InsnKind.GOTO,
            l=MopSnapshot(kind=OperandKind.BLOCK, block_ref=2), r=None, d=None,
            control_transfer_kind=None, is_conditional_jump=False,
            is_unconditional_jump=True,
        )
        blocks[1] = replace(blocks[1], insn_snapshots=(state_write, carrier, goto), succs=(2,), kind=BlockKind.ONE_WAY, tail_kind=InsnKind.GOTO)
        refs = dict(refs)
        refs[1] = NativeBlockRef(StableBlockIdentity.from_instruction_eas(
            (0x2000, 0x2001, 0x2002), native_key=refs[1].identity.native_key,
        ))
        blocks[3] = replace(
            blocks[3], succs=(), preds=(2,), kind=BlockKind.ZERO_WAY,
            tail_kind=InsnKind.RET,
            insn_snapshots=(InsnSnapshot(opcode=0, ea=0x4000, operands=(), kind=InsnKind.RET, raw_opcode=0),),
        )
        blocks[4] = replace(blocks[4], preds=())
        blocks[5] = replace(blocks[5], preds=())
        source = FlowGraph(blocks, source.entry_serial, source.func_ea)
        source_catalog = producer_api.build_source_identity_catalog(
            source, refs, native_key=refs[1].identity.native_key, source_generation=1,
        )
        terminal_carrier = TerminalReturnCarrierEvidence(
            request=__import__(
                "d810.analyses.control_flow.materialized_indirect_transfer",
                fromlist=["TerminalReturnCarrierRequest"],
                ).TerminalReturnCarrierRequest(0x2000, 0x4000, 16, 7),
            capture_identity=refs[1].identity, terminal_identity=refs[3].identity,
            state_write_ea=0x2000, carrier_ea=0x2001, terminal_return_ea=0x4000,
            operation=ValueOpKind.MOVE,
            source=TerminalReturnCarrierSource(TerminalReturnCarrierSourceKind.CONSTANT, width=4, constant=7),
            return_width=4, corridor_instruction_eas=(0x2000, 0x2001),
        )
        proof = route_model.SemanticRouteProof(
            proof_id="terminal-return:3b3-empty-s", atomic_group_id="3b3-empty-s-terminal",
            proof_kind=proof_kind, shape=route_model.SemanticRouteShape.DIRECT,
                source_identity=refs[2].identity, source_anchor_ea=0x3000,
                delivery_region=NativeEaInterval(0x3000, 0x3001),
            destinations=(route_model.SemanticRouteDestination(
                    SemanticEdgeRole.DIRECT, 7, refs[3].identity, 0x4000, terminal=True,
            ),),
            state_write=route_model.SemanticStateWriteProof(
                refs[1].identity, 0x2000, StorageIdentity(StorageIdentityKind.REGISTER, 16),
                4, 7, (0x2000, 0x2001), None, (),
            ), terminal_return_carrier=terminal_carrier,
        )
        evidence = canonical_semantic_evidence_from_proofs(
            native_key=refs[1].identity.native_key, generation=1, proofs=(proof,),
        )
    else:
        raise ValueError(f"unsupported empty split proof kind: {proof_kind}")
    if proof_kind is route_model.SemanticRouteProofKind.BOOTSTRAP:
        source = FlowGraph(blocks, source.entry_serial, source.func_ea)
        source_catalog = producer_api.build_source_identity_catalog(
            source, refs, native_key=refs[1].identity.native_key, source_generation=1,
        )
        context = CanonicalSemanticEvidenceProductionContext(
            refs[0].identity.native_key, 1, authority_id("3b3-empty-s-group"), state,
            tuple(source.blocks.values()), tuple((serial, ref.identity) for serial, ref in refs.items()),
            source.entry_serial,
        )
        produced = route_model.build_canonical_semantic_evidence((fact,), context)
        assert produced.abstention is None and produced.evidence is not None
        evidence = produced.evidence
    route_proof = evidence.route_proofs[0]
    claims = producer_api.build_equivalent_route_claims(
        source=source, source_catalog=source_catalog, route_evidence=evidence,
        selected_proof_ids=(route_proof.proof_id,),
    )
    proposal = replace(
        base, source_identity_catalog=source_catalog, route_evidence=evidence, claims=claims,
        plan_inputs=replace(
            base.plan_inputs, shape=model.UnflattenPlanShape.PARTIAL_REWRITE,
            dispatcher_entry_ref=refs[3],
            dispatcher_member_refs=tuple(refs[serial] for serial in (0, 1, 2, 3, 4, 5)),
        ),
    )
    compiled = compile_patch_plan(
        [EdgeRedirectViaPredSplit(2, 3, 4, 1)], source,
        plan_id=proposal.plan_id, source_generation=1, block_refs_by_serial=refs,
    )
    plan = replace(
        compiled, source_coordinates=tuple((ref, serial) for serial, ref in refs.items()),
        unflatten_proposal=proposal,
    )
    materialization = route_model.CanonicalRouteMaterialization.capture(
        source, generation=1, phase=route_model.CanonicalRouteAssessmentPhase.SOURCE,
    )
    source_inventory = transaction_api._build_semantic_graph_inventory(
        source, proposal, plan, source=True,
        phase=model.UnflattenAuthorityPhase.PRODUCER_FORECAST, materialization=materialization,
    )
    bound = bind.bind_source_route_authority(
        proposal=proposal, source_inventory=source_inventory, source_materialization=materialization,
    )
    assert type(bound) is model.SourceBoundRouteAuthorityAccepted
    projected = project_post_state(source, plan)
    projected_inventory = transaction_api._build_semantic_graph_inventory(
        projected, proposal, plan, source=False,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT, materialization=None,
        source_subjects=source_inventory.subjects,
    )
    facts = transaction_api._derive_patch_lineage_facts(source_inventory, plan)
    from d810.transforms.cfg_transaction import TransactionAttemptId
    attempt = TransactionAttemptId(
        plan.plan_id, authority_id("3b3-empty-s-session"), 1, authority_id("3b3-empty-s-attempt"),
    )
    assert type(plan.steps[0]).__name__ == "PatchEdgeSplitTrampoline"
    return bound.authority, plan, source_inventory, projected_inventory, facts, attempt


def _physical_split_x_canonical_replay_case(proof_kind):
    """Replay real proof evidence against the semantic-empty split S topology."""
    from d810.ir.flowgraph import BlockSnapshot, FlowGraph, InsnSnapshot
    from tests.unit.analyses.control_flow.test_semantic_route_evidence import (
        _composite_partition_evidence,
    )

    if proof_kind is route_model.SemanticRouteProofKind.STATE_ASSIGNMENT:
        authority, _plan, _source, _projected, _facts, _attempt, _ = _compiler_split_case()
        _source, _base, _exclusion, _refs = exact_fixture()
        blocks = dict(_source.blocks)
        blocks[1] = _one_way_goto(blocks[1], 2, preds=(0,))
        blocks[2] = replace(blocks[2], preds=(1,))
        blocks[3] = replace(blocks[3], preds=())
        bad_graph = FlowGraph(blocks, _source.entry_serial, _source.func_ea)
        return (
            authority.proposal.route_evidence,
            bad_graph,
            route_model.CanonicalRouteBindingStage.STATE_WRITE,
        )

    if proof_kind in {
        route_model.SemanticRouteProofKind.STATE_DAG,
        route_model.SemanticRouteProofKind.STATE_CHOICE,
    }:
        if proof_kind is route_model.SemanticRouteProofKind.STATE_DAG:
            authority, _plan, _source, _projected, _facts, _attempt = _compiler_direct_branch_case(
                proof_kind=route_model.SemanticRouteFactKind.DECISION_DAG,
            )
            expected_stage = route_model.CanonicalRouteBindingStage.STATE_DAG
        else:
            authority, _plan, _source, _projected, _facts, _attempt = _compiler_choice_branch_case()
            expected_stage = route_model.CanonicalRouteBindingStage.CONDITIONAL_ROUTE
        source, _base, _exclusion, _refs = exact_fixture()
        blocks = dict(source.blocks)
        blocks[1] = _one_way_goto(blocks[1], 2, preds=(0,))
        blocks[2] = replace(blocks[2], preds=(1,))
        blocks[3] = replace(blocks[3], preds=())
        return authority.proposal.route_evidence, FlowGraph(
            blocks, source.entry_serial, source.func_ea,
        ), expected_stage

    if proof_kind is route_model.SemanticRouteProofKind.STATE_TRANSFORM:
        evidence, graph, _ = _branch_x_canonical_replay_case(proof_kind)
        source_block = graph.blocks[285]
        empty = tuple(
            replace(snapshot, kind=InsnKind.NOP, value_op_kind=None, l=None, r=None, d=None)
            for snapshot in source_block.insn_snapshots[:-1]
        ) + (source_block.insn_snapshots[-1],)
        source_block = replace(
            source_block, succs=(446,), preds=(999,), kind=BlockKind.ONE_WAY,
            tail_kind=InsnKind.GOTO, insn_snapshots=empty,
        )
        predecessor = BlockSnapshot(
            serial=999, block_type=0, succs=(285,), preds=(), flags=0,
            start_ea=0x70000000, insn_snapshots=(),
        )
        return evidence, type(graph)(
            {**graph.blocks, 999: predecessor, 285: source_block},
            graph.entry_serial, graph.func_ea,
        ), route_model.CanonicalRouteBindingStage.STATE_TRANSFORM

    if proof_kind is route_model.SemanticRouteProofKind.STATE_CARRIER:
        evidence, graph, _ = _branch_x_canonical_replay_case(proof_kind)
        source_block = _one_way_goto(graph.blocks[2], 3, preds=(1,))
        predecessor = BlockSnapshot(
            serial=1, block_type=0, succs=(2,), preds=(), flags=0,
            start_ea=0x1100, insn_snapshots=(),
        )
        blocks = {**graph.blocks, 1: predecessor, 2: source_block}
        blocks[5] = replace(blocks[5], preds=(3,))
        return evidence, type(graph)(blocks, graph.entry_serial, graph.func_ea), route_model.CanonicalRouteBindingStage.STATE_CARRIER

    if proof_kind is route_model.SemanticRouteProofKind.STATE_PARTITION:
        graph, evidence = _composite_partition_evidence()
        from d810.backends.hexrays.evidence.condition_chain_analysis import build_condition_chain_walker_provider
        from d810.capabilities.providers import register_condition_chain_walkers
        register_condition_chain_walkers(build_condition_chain_walker_provider())
        source_block = _one_way_goto(graph.blocks[2], 5, preds=(1,))
        blocks = {**graph.blocks, 2: source_block}
        return evidence, type(graph)(blocks, graph.entry_serial, graph.func_ea), route_model.CanonicalRouteBindingStage.STATE_PARTITION

    raise ValueError(f"unsupported physical split X proof kind: {proof_kind}")


def _compile_corridor_from_canonical_evidence(
    *, source, evidence, from_serial: int, old_target: int, new_target: int,
    predecessor_serial: int, clone_until: int, state_identity, tag: str,
):
    """Compile one real corridor plan around already-produced canonical evidence."""
    from d810.ir.block_identity import stable_block_identity_from_snapshot
    from d810.transforms.cfg_transaction import NativeBlockRef, TransactionAttemptId
    from d810.transforms.edit_simulator import project_post_state
    from d810.transforms.graph_modification import EdgeRedirectViaPredSplit
    from tests.typed_patch_authority import compile_patch_plan

    # Canonical source normalization belongs in each producer fixture, before
    # proof/evidence construction.  Mutating here would invalidate the
    # producer's stable identities and hide ordering bugs in transform proofs.
    refs = {
        serial: NativeBlockRef(stable_block_identity_from_snapshot(
            block, native_key=evidence.native_key,
        ))
        for serial, block in source.blocks.items()
    }
    source_catalog = producer_api.build_source_identity_catalog(
        source, refs, native_key=evidence.native_key,
        source_generation=evidence.generation,
    )
    proof = evidence.route_proofs[0]
    claims = producer_api.build_equivalent_route_claims(
        source=source, source_catalog=source_catalog,
        route_evidence=evidence, selected_proof_ids=(proof.proof_id,),
    )
    witness = model.UseDefFragmentWitness(
        authority_id(f"{tag}-fragment"), state_identity, (refs[from_serial],),
        authority_id(f"{tag}-redirect"), True, True, 0, (),
    )
    proposal = producer_api.build_proposal(
        plan_id=authority_id(f"{tag}-plan"), source=source,
        block_refs_by_serial=refs, source_generation=evidence.generation,
        canonical_route_evidence=evidence,
        selected_route_proof_ids=(proof.proof_id,),
        exact_state_effect_exclusions=(), dispatcher_entry_serial=from_serial,
        dispatcher_member_serials=tuple(source.blocks),
        authoritative_handler_serials=(), state_identity=state_identity,
        use_def_witness=witness,
    )
    compiled = compile_patch_plan(
        [EdgeRedirectViaPredSplit(
            from_serial, old_target, new_target, predecessor_serial,
            clone_until=clone_until,
        )], source, plan_id=proposal.plan_id,
        source_generation=evidence.generation, block_refs_by_serial=refs,
    )
    plan = replace(
        compiled,
        source_coordinates=tuple((ref, serial) for serial, ref in refs.items()),
        unflatten_proposal=proposal,
    )
    materialization = route_model.CanonicalRouteMaterialization.capture(
        source, generation=evidence.generation,
        phase=route_model.CanonicalRouteAssessmentPhase.SOURCE,
    )
    source_inventory = transaction_api._build_semantic_graph_inventory(
        source, proposal, plan, source=True,
        phase=model.UnflattenAuthorityPhase.PRODUCER_FORECAST,
        materialization=materialization,
    )
    bound = bind.bind_source_route_authority(
        proposal=proposal, source_inventory=source_inventory,
        source_materialization=materialization,
    )
    assert type(bound) is model.SourceBoundRouteAuthorityAccepted
    projected = project_post_state(source, plan)
    projected_inventory = transaction_api._build_semantic_graph_inventory(
        projected, proposal, plan, source=False,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        materialization=None, source_subjects=source_inventory.subjects,
    )
    facts = transaction_api._derive_patch_lineage_facts(source_inventory, plan)
    attempt = TransactionAttemptId(
        plan.plan_id, authority_id(f"{tag}-session"),
        evidence.generation, authority_id(f"{tag}-attempt"),
    )
    from d810.transforms.plan import PatchEdgeSplitCorridor
    assert type(plan.steps[0]) is PatchEdgeSplitCorridor
    return bound.authority, plan, source_inventory, projected_inventory, facts, attempt


def _normalize_corridor_source(graph):
    """Make the portable producer snapshot complete before proving evidence."""
    blocks = {}
    for serial, block in graph.blocks.items():
        snapshots = tuple(
            replace(snapshot, raw_opcode=0 if snapshot.raw_opcode is None else snapshot.raw_opcode)
            for snapshot in block.insn_snapshots
        )
        if not snapshots:
            blocks[serial] = block
            continue
        blocks[serial] = replace(
            block,
            start_ea=(block.start_ea if block.native_start_ea is not None else snapshots[0].ea),
            insn_snapshots=snapshots,
            tail_opcode=(block.tail_opcode if block.tail_opcode is not None else snapshots[-1].opcode),
            tail_kind=(block.tail_kind if block.tail_kind is not None else snapshots[-1].kind),
            raw_tail_opcode=(block.raw_tail_opcode if block.raw_tail_opcode is not None else snapshots[-1].raw_opcode),
        )
    return type(graph)(blocks, graph.entry_serial, graph.func_ea)


def _compiler_exact_dag_or_bootstrap_corridor_case(*, proof_kind):
    """Build Sol's one-way Q0/D corridor before producing canonical evidence."""
    from d810.analyses.control_flow.semantic_route_evidence import (
        CanonicalSemanticEvidenceProductionContext,
        DecisionDagRouteWitness,
        SemanticBootstrapRouteWitness,
        SemanticRouteFact,
        SemanticRouteFactKind,
        build_canonical_semantic_evidence,
    )
    from d810.ir.block_identity import stable_block_identity_from_snapshot
    from d810.ir.flowgraph import BlockSnapshot, FlowGraph, InsnKind, InsnSnapshot
    from d810.ir.storage_identity import StorageIdentity, StorageIdentityKind
    from tests.unit.analyses.control_flow.test_semantic_route_evidence import NATIVE_KEY

    source, _base, _exclusion, _old_refs = exact_fixture()
    state = StorageIdentity(StorageIdentityKind.STACK, 4)
    old = dict(source.blocks)
    def retarget(block, serial, start_ea):
        return replace(
            block, serial=serial, start_ea=start_ea,
            insn_snapshots=tuple(
                replace(insn, ea=start_ea + index)
                for index, insn in enumerate(block.insn_snapshots)
            ),
        )
    # D=1 is a real conditional comparison; N=2/O=3 are its two semantic arms.
    dispatcher = replace(retarget(old[1], 1, 0x4000), preds=(0,), succs=(2, 3))
    destination = replace(retarget(old[2], 2, 0x5000), preds=(1,))
    other = replace(retarget(old[3], 3, 0x6000), preds=(1,))
    entry = BlockSnapshot(
        5, 0, (0,), (), 0, 0x2000,
        (InsnSnapshot(0, 0x2000, (), l=MopSnapshot(kind=OperandKind.BLOCK, block_ref=0),
                      kind=InsnKind.GOTO, raw_opcode=0),),
        tail_opcode=0, kind=BlockKind.ONE_WAY, tail_kind=InsnKind.GOTO,
        raw_tail_opcode=0,
    )
    if proof_kind is route_model.SemanticRouteProofKind.STATE_DAG:
        q0 = replace(retarget(old[0], 0, 0x3000), preds=(5,), succs=(1,))
        blocks = {5: entry, 0: q0, 1: dispatcher, 2: destination, 3: other}
        corridor = (0,)
        fact = SemanticRouteFact(
            SemanticRouteFactKind.DECISION_DAG, 0, 0, 0x3000, 7, 2,
            0x3000, 0x5000, (0,), (), authority_id("3b3-corridor-dag"),
            decision_dag_witness=DecisionDagRouteWitness(
                state, 7, 1, 0x4000, (1,), (0x4000,),
                ((1, RouteComparison(1, "jz", 7, 2, 3)),), (),
            ),
        )
        from_serial, old_target, via_pred, clone_until = 0, 1, 5, 0
        tag = "corridor-state-dag"
    elif proof_kind is route_model.SemanticRouteProofKind.BOOTSTRAP:
        p = replace(retarget(old[0], 0, 0x3000), preds=(5,), succs=(6,))
        q0 = BlockSnapshot(
            6, 0, (1,), (0,), 0, 0x3800,
            (InsnSnapshot(0, 0x3800, (), l=MopSnapshot(kind=OperandKind.BLOCK, block_ref=1),
                          kind=InsnKind.GOTO, raw_opcode=0),),
            tail_opcode=0, kind=BlockKind.ONE_WAY, tail_kind=InsnKind.GOTO,
            raw_tail_opcode=0,
        )
        dispatcher = replace(dispatcher, preds=(6,))
        blocks = {5: entry, 0: p, 6: q0, 1: dispatcher, 2: destination, 3: other}
        dag = DecisionDagRouteWitness(
            state, 7, 1, 0x4000, (1,), (0x4000,),
            ((1, RouteComparison(1, "jz", 7, 2, 3)),), (),
        )
        witness = SemanticBootstrapRouteWitness(
            5, 0, 0x3000, 6, 1, state, 7, 4,
            (0, 6, 1), (0x3000, 0x3800, 0x4000), (), dag,
        )
        fact = SemanticRouteFact(
            SemanticRouteFactKind.BOOTSTRAP, 6, 0, 0x3000, 7, 2,
            0x3800, 0x5000, (0, 6), ((0, 6),), authority_id("3b3-corridor-bootstrap"),
            decision_dag_witness=dag, bootstrap_witness=witness,
        )
        from_serial, old_target, via_pred, clone_until = 6, 1, 0, 6
        tag = "corridor-bootstrap"
    else:
        raise ValueError(proof_kind)
    source = _normalize_corridor_source(FlowGraph(blocks, 5, source.func_ea))
    identities = {
        serial: stable_block_identity_from_snapshot(block, native_key=NATIVE_KEY)
        for serial, block in source.blocks.items()
    }
    produced = build_canonical_semantic_evidence(
        (fact,), CanonicalSemanticEvidenceProductionContext(
            NATIVE_KEY, 1, authority_id(f"{tag}-group"), state,
            tuple(source.blocks.values()), tuple(identities.items()), source.entry_serial,
        ),
    )
    assert produced.abstention is None and produced.evidence is not None
    return _compile_corridor_from_canonical_evidence(
        source=source, evidence=produced.evidence,
        from_serial=from_serial, old_target=old_target, new_target=2,
        predecessor_serial=via_pred, clone_until=clone_until,
        state_identity=state, tag=tag,
    )


