def _compiler_corridor_unsupported_case(*, proof_kind):
    """Build a compiler-produced corridor with a real SOURCE proof of each U kind."""
    from d810.ir.flowgraph import BlockSnapshot, FlowGraph, InsnKind, InsnSnapshot
    from d810.ir.storage_identity import StorageIdentity, StorageIdentityKind

    if proof_kind in {
        route_model.SemanticRouteProofKind.STATE_DAG,
        route_model.SemanticRouteProofKind.BOOTSTRAP,
    }:
        return _compiler_exact_dag_or_bootstrap_corridor_case(proof_kind=proof_kind)

    if proof_kind is route_model.SemanticRouteProofKind.STATE_TRANSFORM:
        from d810.analyses.control_flow.semantic_route_evidence import (
            CanonicalSemanticEvidenceProductionContext, SemanticRouteFact,
            SemanticRouteFactKind, build_canonical_semantic_evidence,
        )
        from d810.analyses.control_flow.state_carrier import prove_exact_u32_state_transform_feeder
        from d810.ir.storage_identity import StorageIdentity, StorageIdentityKind
        from tests.unit.analyses.control_flow.test_semantic_route_evidence import NATIVE_KEY
        from tests.unit.preanalysis.flow.test_minimal_state_recovery import _captured_nested_state_transform_fixture
        graph, dag, _transition, _dispatcher = _captured_nested_state_transform_fixture()
        predecessor = BlockSnapshot(
            serial=999, block_type=0, succs=(285,), preds=(), flags=0,
            start_ea=0x70000000,
            insn_snapshots=(InsnSnapshot(0, 0x70000000, (), kind=InsnKind.NOP, raw_opcode=0),),
        )
        source_block = replace(graph.blocks[285], preds=(999,))
        source = type(graph)(
            {**graph.blocks, 285: source_block, 999: predecessor},
            graph.entry_serial, graph.func_ea,
        )
        source = type(source)(
            {
                **source.blocks,
                200: replace(
                    source.blocks[200],
                    insn_snapshots=(InsnSnapshot(0, 37064, (), kind=InsnKind.NOP, raw_opcode=0),),
                    tail_opcode=0, tail_kind=InsnKind.NOP, raw_tail_opcode=0,
                ),
            },
            source.entry_serial, source.func_ea,
        )
        source = _normalize_corridor_source(source)
        witness = prove_exact_u32_state_transform_feeder(
            source, 285, 446, state_var_stkoff=0x64, state_var_reg=None,
            required_comparison_serials=frozenset({4, *dag.nodes}),
            expected_state=0x28F25B96,
        )
        assert witness is not None
        from d810.ir.block_identity import stable_block_identity_from_snapshot
        identities = {
            serial: stable_block_identity_from_snapshot(block, native_key=NATIVE_KEY)
            for serial, block in source.blocks.items()
        }
        fact = route_model.SemanticRouteFact(
            SemanticRouteFactKind.STATE_TRANSFORM, 285, 285, witness.source_ea,
            witness.state, 118, witness.source_ea, 0x180016680, (285,), (),
            transform_witness=witness,
        )
        produced = build_canonical_semantic_evidence(
            (fact,), CanonicalSemanticEvidenceProductionContext(
                NATIVE_KEY, 0, "canonical-semantic:corridor-transform",
                StorageIdentity(StorageIdentityKind.STACK, 0x64),
                tuple(source.blocks.values()), tuple(identities.items()),
            ),
        )
        assert produced.evidence is not None
        evidence = produced.evidence
        return _compile_corridor_from_canonical_evidence(
            source=source, evidence=evidence, from_serial=285, old_target=446,
            new_target=4, predecessor_serial=999, clone_until=446,
            state_identity=StorageIdentity(StorageIdentityKind.STACK, 0x64),
            tag="corridor-state-transform",
        )

    if proof_kind is route_model.SemanticRouteProofKind.STATE_CARRIER:
        from d810.analyses.control_flow.semantic_route_evidence import (
            CanonicalSemanticEvidenceProductionContext, SemanticRouteFact,
            SemanticRouteFactKind, build_canonical_semantic_evidence,
        )
        from d810.ir.storage_identity import StorageIdentity, StorageIdentityKind
        from d810.ir.varnode import Space, Varnode
        from tests.unit.analyses.control_flow.test_semantic_route_evidence import NATIVE_KEY
        from d810.analyses.control_flow.state_carrier import ExactCarrierStateWrite
        wide_constant = MopSnapshot(kind=OperandKind.NUMBER, size=4, value=7)
        wide_carrier = MopSnapshot(kind=OperandKind.REGISTER, size=4, reg=16)
        narrow_carrier = MopSnapshot(kind=OperandKind.REGISTER, size=4, reg=16)
        state_mop = MopSnapshot(kind=OperandKind.STACK, size=4, stkoff=0x40, stack_refs=(0x40,))
        source = FlowGraph(
            blocks={
                1: BlockSnapshot(1, 0, (2,), (), 0, 0x1100, (InsnSnapshot(0, 0x1100, (), kind=InsnKind.NOP, raw_opcode=0),)),
                2: BlockSnapshot(2, 1, (3,), (1,), 0, 0x1200, (InsnSnapshot(0, 0x1200, (), l=wide_constant, d=wide_carrier, kind=InsnKind.MOV, value_op_kind=__import__("d810.ir.expressions", fromlist=["ValueOpKind"]).ValueOpKind.MOVE, raw_opcode=0),)),
                3: BlockSnapshot(3, 1, (4,), (2,), 0, 0x1300, (InsnSnapshot(0, 0x1300, (), l=narrow_carrier, d=state_mop, kind=InsnKind.MOV, value_op_kind=__import__("d810.ir.expressions", fromlist=["ValueOpKind"]).ValueOpKind.MOVE, raw_opcode=0),)),
                4: BlockSnapshot(4, 1, (5, 6), (3,), 0, 0x1400, (InsnSnapshot(0, 0x1400, (), l=state_mop, r=MopSnapshot(kind=OperandKind.NUMBER, size=4, value=7), d=MopSnapshot(kind=OperandKind.BLOCK, block_ref=5), kind=InsnKind.COND_JUMP, control_transfer_kind=ControlTransferKind.CONDITIONAL_BRANCH, branch_predicate=__import__("d810.ir.flowgraph", fromlist=["PredicateKind"]).PredicateKind.EQ, is_conditional_jump=True, raw_opcode=0),), tail_opcode=0, kind=BlockKind.TWO_WAY, tail_kind=InsnKind.COND_JUMP, raw_tail_opcode=0),
                5: BlockSnapshot(5, 0, (), (4,), 0, 0x1500, (InsnSnapshot(0, 0x1500, (), kind=InsnKind.NOP, raw_opcode=0),)),
                6: BlockSnapshot(6, 0, (), (4,), 0, 0x1600, (InsnSnapshot(0, 0x1600, (), kind=InsnKind.NOP, raw_opcode=0),)),
            }, entry_serial=1, func_ea=0x1000,
        )
        source = _normalize_corridor_source(source)
        storage = StorageIdentity(StorageIdentityKind.STACK, 0x40)
        fact = SemanticRouteFact(
            SemanticRouteFactKind.STATE_CARRIER, 2, 2, 0x1200, 7, 5,
            0x1200, 0x1500, (2,), (),
            carrier_witness=ExactCarrierStateWrite(
                state=7, source_serial=2, feeder_serial=3,
                comparison_entry_serial=4,
                carrier=Varnode(Space.REGISTER, 16, 4), state_identity=storage,
            ),
        )
        from d810.ir.block_identity import stable_block_identity_from_snapshot
        identities = {
            serial: stable_block_identity_from_snapshot(block, native_key=NATIVE_KEY)
            for serial, block in source.blocks.items()
        }
        produced = build_canonical_semantic_evidence(
            (fact,), CanonicalSemanticEvidenceProductionContext(
                NATIVE_KEY, 0, "canonical-semantic:corridor-carrier", storage,
                tuple(source.blocks.values()), tuple(identities.items()),
            ),
        )
        assert produced.evidence is not None
        evidence = produced.evidence
        return _compile_corridor_from_canonical_evidence(
            source=source, evidence=evidence, from_serial=2, old_target=3,
            new_target=5, predecessor_serial=1, clone_until=3,
            state_identity=StorageIdentity(StorageIdentityKind.STACK, 0x40),
            tag="corridor-state-carrier",
        )

    if proof_kind is route_model.SemanticRouteProofKind.TERMINAL_RETURN:
        return _compiler_exact_terminal_corridor_case()

    raise ValueError(f"unsupported corridor U proof kind: {proof_kind}")


def _corridor_x_canonical_replay_case():
    """Replay a real STATE_CHOICE proof against a one-way Q0 source block."""
    from d810.ir.flowgraph import FlowGraph

    _authority, _plan, _source, _projected, _facts, _attempt = (
        _compiler_choice_branch_case()
    )
    source, _base, _exclusion, _refs = exact_fixture()
    blocks = dict(source.blocks)
    blocks[1] = _one_way_goto(blocks[1], 2, preds=(0,))
    blocks[2] = replace(blocks[2], preds=(1,))
    blocks[3] = replace(blocks[3], preds=())
    graph = FlowGraph(blocks, source.entry_serial, source.func_ea)
    evidence = _authority.proposal.route_evidence
    result = route_model.bind_canonical_semantic_evidence_result(graph, evidence)
    assert result.bound_evidence is None
    return evidence, graph, result.failures[0].stage


