def _compiler_terminal_branch_case(*, helper: bool = False):
    """Build a portable terminal-return carrier on the real branch compiler path."""
    from d810.analyses.control_flow.materialized_indirect_transfer import TerminalReturnCarrierRequest
    from d810.analyses.control_flow.terminal_return_carrier_evidence import (
        TerminalReturnCarrierEvidence,
        TerminalReturnCarrierSource,
        TerminalReturnCarrierSourceKind,
    )
    from d810.ir.flowgraph import FlowGraph, InsnSnapshot, ValueOpKind
    from d810.ir.storage_identity import StorageIdentity, StorageIdentityKind
    from d810.transforms.edit_simulator import project_post_state
    from d810.transforms.graph_modification import RedirectBranch
    from tests.typed_patch_authority import compile_patch_plan

    source, base, _exclusion, refs = exact_fixture()
    target_serial = 4 if helper else 3
    target_ea = 0x5000 if helper else 0x4000
    blocks = dict(source.blocks)
    first = blocks[1].insn_snapshots[0]
    state_write_snapshot = replace(
        first,
        kind=InsnKind.MOV,
        value_op_kind=__import__("d810.ir.expressions", fromlist=["ValueOpKind"]).ValueOpKind.MOVE,
        l=MopSnapshot(kind=OperandKind.NUMBER, size=4, value=7),
        d=MopSnapshot(kind=OperandKind.REGISTER, size=4, reg=16),
    )
    carrier = replace(
        state_write_snapshot,
        ea=0x2001,
    )
    branch = replace(
        blocks[1].insn_snapshots[1],
        ea=0x2002,
        d=MopSnapshot(kind=OperandKind.BLOCK, block_ref=target_serial),
    )
    blocks[1] = replace(
        blocks[1],
        succs=(2, target_serial),
        insn_snapshots=(state_write_snapshot, carrier, branch),
    )
    blocks[2] = replace(blocks[2], preds=(1,))
    blocks[3] = replace(blocks[3], preds=(() if helper else (1,)))
    blocks[4] = replace(blocks[4], preds=((1,) if helper else ()))
    terminal = replace(
        blocks[target_serial],
        kind=BlockKind.ZERO_WAY,
        tail_kind=InsnKind.RET,
        insn_snapshots=(InsnSnapshot(opcode=0, ea=target_ea, operands=(), kind=InsnKind.RET, raw_opcode=0),),
    )
    blocks[target_serial] = terminal
    source = FlowGraph(blocks, source.entry_serial, source.func_ea)
    refs = dict(refs)
    refs[1] = NativeBlockRef(StableBlockIdentity.from_instruction_eas(
        (0x2000, 0x2001, 0x2002), native_key=refs[1].identity.native_key,
    ))
    source_catalog = producer_api.build_source_identity_catalog(
        source, refs, native_key=refs[1].identity.native_key, source_generation=1,
    )
    state = StorageIdentity(StorageIdentityKind.REGISTER, 16)
    request = TerminalReturnCarrierRequest(
        source_handler_ea=0x2000,
        terminal_target_ea=target_ea,
        state_var_reg=16,
        state_constant=7,
    )
    terminal_carrier = TerminalReturnCarrierEvidence(
        request=request,
        capture_identity=refs[1].identity,
        terminal_identity=refs[target_serial].identity,
        state_write_ea=0x2000,
        carrier_ea=0x2001,
        terminal_return_ea=target_ea,
        operation=__import__("d810.ir.expressions", fromlist=["ValueOpKind"]).ValueOpKind.MOVE,
        source=TerminalReturnCarrierSource(
            TerminalReturnCarrierSourceKind.CONSTANT,
            width=4,
            constant=7,
        ),
        return_width=4,
        corridor_instruction_eas=(0x2000, 0x2001),
    )
    proof = route_model.SemanticRouteProof(
        proof_id="terminal-return:3b3-branch",
        atomic_group_id="terminal-return:3b3-branch-group",
        proof_kind=route_model.SemanticRouteProofKind.TERMINAL_RETURN,
        shape=route_model.SemanticRouteShape.DIRECT,
        source_identity=refs[1].identity,
        source_anchor_ea=0x2000,
        delivery_region=NativeEaInterval(0x2000, 0x2001),
        destinations=(route_model.SemanticRouteDestination(
            role=SemanticEdgeRole.DIRECT,
            state_constant=7,
            target_identity=refs[target_serial].identity,
            target_anchor_ea=target_ea,
            terminal=True,
        ),),
        state_write=route_model.SemanticStateWriteProof(
            identity=refs[1].identity,
            instruction_ea=0x2000,
            state_variable=state,
            width=4,
            state_constant=7,
            corridor_instruction_eas=(0x2000,),
            authority_transfer_ea=None,
            preserved_call_instruction_eas=(),
        ),
        terminal_return_carrier=terminal_carrier,
    )
    evidence = canonical_semantic_evidence_from_proofs(
        native_key=refs[1].identity.native_key,
        generation=1,
        proofs=(proof,),
    )
    route_proof = evidence.route_proofs[0]
    claims = producer_api.build_equivalent_route_claims(
        source=source,
        source_catalog=source_catalog,
        route_evidence=evidence,
        selected_proof_ids=(route_proof.proof_id,),
    )
    proposal = replace(
        base,
        source_identity_catalog=source_catalog,
        route_evidence=evidence,
        claims=claims,
        plan_inputs=replace(
            base.plan_inputs,
            shape=model.UnflattenPlanShape.PARTIAL_REWRITE,
            dispatcher_entry_ref=refs[1],
            dispatcher_member_refs=(refs[0], refs[1], refs[2], refs[4]),
        ),
    )
    compiled = compile_patch_plan(
        [RedirectBranch(1, 2, target_serial)],
        source,
        plan_id=proposal.plan_id,
        source_generation=1,
        block_refs_by_serial=refs,
    )
    plan = replace(
        compiled,
        source_coordinates=tuple((ref, serial) for serial, ref in refs.items()),
        unflatten_proposal=proposal,
    )
    materialization = route_model.CanonicalRouteMaterialization.capture(
        source, generation=1, phase=route_model.CanonicalRouteAssessmentPhase.SOURCE,
    )
    source_inventory = transaction_api._build_semantic_graph_inventory(
        source, proposal, plan, source=True,
        phase=model.UnflattenAuthorityPhase.PRODUCER_FORECAST,
        materialization=materialization,
    )
    bound = bind.bind_source_route_authority(
        proposal=proposal,
        source_inventory=source_inventory,
        source_materialization=materialization,
    )
    assert type(bound) is model.SourceBoundRouteAuthorityAccepted
    projected = project_post_state(source, plan)
    projected_inventory = transaction_api._build_semantic_graph_inventory(
        projected, proposal, plan, source=False,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        materialization=None,
        source_subjects=source_inventory.subjects,
    )
    facts = transaction_api._derive_patch_lineage_facts(source_inventory, plan)
    from d810.transforms.cfg_transaction import TransactionAttemptId
    attempt = TransactionAttemptId(
        plan.plan_id,
        authority_id("3b3-terminal-session"),
        1,
        authority_id("3b3-terminal-attempt"),
    )
    return bound.authority, plan, source_inventory, projected_inventory, facts, attempt


def _compiler_choice_branch_case(*, helper: bool = False):
    """Compile a genuine conditional STATE_CHOICE branch in both orientations."""
    from d810.ir.flowgraph import FlowGraph
    from d810.transforms.edit_simulator import project_post_state
    from d810.transforms.graph_modification import RedirectBranch
    from tests.typed_patch_authority import compile_patch_plan

    source, base, _exclusion, refs = exact_fixture()
    choice = base.route_evidence.route_proofs[0]
    target_serial = 4
    blocks = dict(source.blocks)
    blocks[1] = replace(
        blocks[1],
        succs=((2, 3) if helper else (3, 2)),
    )
    blocks[3] = replace(blocks[3], preds=(1,))
    blocks[4] = replace(blocks[4], preds=())
    source = FlowGraph(blocks, source.entry_serial, source.func_ea)
    proof = route_model.SemanticRouteProof(
        proof_id="state-choice:3b3-branch",
        atomic_group_id="state-choice:3b3-branch-group",
        proof_kind=route_model.SemanticRouteProofKind.STATE_CHOICE,
        shape=route_model.SemanticRouteShape.CONDITIONAL,
        source_identity=refs[1].identity,
        source_anchor_ea=0x2000,
        destinations=(
            route_model.SemanticRouteDestination(
                SemanticEdgeRole.CONDITIONAL_TAKEN,
                7,
                refs[2].identity,
                0x3000,
            ),
            route_model.SemanticRouteDestination(
                SemanticEdgeRole.CONDITIONAL_FALLTHROUGH,
                8,
                refs[3].identity,
                0x4000,
            ),
        ),
        state_write=choice.state_write,
        predicate=choice.predicate,
        carriers=choice.carriers,
    )
    evidence = canonical_semantic_evidence_from_proofs(
        native_key=refs[1].identity.native_key,
        generation=1,
        proofs=(proof,),
    )
    route_proof = evidence.route_proofs[0]
    claims = producer_api.build_equivalent_route_claims(
        source=source,
        source_catalog=base.source_identity_catalog,
        route_evidence=evidence,
        selected_proof_ids=(route_proof.proof_id,),
    )
    proposal = replace(
        base,
        route_evidence=evidence,
        claims=claims,
        plan_inputs=replace(
            base.plan_inputs,
            shape=model.UnflattenPlanShape.PARTIAL_REWRITE,
            dispatcher_member_refs=(refs[0], refs[1], refs[2], refs[4]),
        ),
    )
    compiled = compile_patch_plan(
        [RedirectBranch(1, 2, target_serial)],
        source,
        plan_id=proposal.plan_id,
        source_generation=1,
        block_refs_by_serial=refs,
    )
    plan = replace(
        compiled,
        source_coordinates=tuple((ref, serial) for serial, ref in refs.items()),
        unflatten_proposal=proposal,
    )
    materialization = route_model.CanonicalRouteMaterialization.capture(
        source, generation=1, phase=route_model.CanonicalRouteAssessmentPhase.SOURCE,
    )
    source_inventory = transaction_api._build_semantic_graph_inventory(
        source, proposal, plan, source=True,
        phase=model.UnflattenAuthorityPhase.PRODUCER_FORECAST,
        materialization=materialization,
    )
    bound = bind.bind_source_route_authority(
        proposal=proposal,
        source_inventory=source_inventory,
        source_materialization=materialization,
    )
    assert type(bound) is model.SourceBoundRouteAuthorityAccepted
    projected = project_post_state(source, plan)
    projected_inventory = transaction_api._build_semantic_graph_inventory(
        projected, proposal, plan, source=False,
        phase=model.UnflattenAuthorityPhase.PROJECTED_PREFLIGHT,
        materialization=None,
        source_subjects=source_inventory.subjects,
    )
    facts = transaction_api._derive_patch_lineage_facts(source_inventory, plan)
    from d810.transforms.cfg_transaction import TransactionAttemptId
    attempt = TransactionAttemptId(
        plan.plan_id,
        authority_id("3b3-choice-session"),
        1,
        authority_id("3b3-choice-attempt"),
    )
    return bound.authority, plan, source_inventory, projected_inventory, facts, attempt


def _branch_x_canonical_replay_case(proof_kind):
    """Produce real non-choice evidence, then replay it against TWO_WAY F."""
    from d810.analyses.control_flow.semantic_route_evidence import (
        CanonicalSemanticEvidenceProductionContext,
        SemanticRouteFact,
        SemanticRouteFactKind,
        build_canonical_semantic_evidence,
    )
    from d810.ir.storage_identity import StorageIdentity, StorageIdentityKind

    if proof_kind is route_model.SemanticRouteProofKind.STATE_TRANSFORM:
        from tests.unit.preanalysis.flow.test_minimal_state_recovery import (
            _captured_nested_state_transform_fixture,
        )
        from d810.analyses.control_flow.state_carrier import (
            prove_exact_u32_state_transform_feeder,
        )
        from tests.unit.analyses.control_flow.test_semantic_route_evidence import (
            NATIVE_KEY,
        )
        graph, dag, _transition, _dispatcher = _captured_nested_state_transform_fixture()
        witness = prove_exact_u32_state_transform_feeder(
            graph,
            285,
            446,
            state_var_stkoff=0x64,
            state_var_reg=None,
            required_comparison_serials=frozenset({4, *dag.nodes}),
            expected_state=0x28F25B96,
        )
        assert witness is not None
        identities = {
            serial: __import__(
                "d810.ir.block_identity", fromlist=["stable_block_identity_from_snapshot"]
            ).stable_block_identity_from_snapshot(block, native_key=NATIVE_KEY)
            for serial, block in graph.blocks.items()
        }
        assert all(identity is not None for identity in identities.values())
        fact = SemanticRouteFact(
            SemanticRouteFactKind.STATE_TRANSFORM,
            285, 285, witness.source_ea, witness.state, 118,
            witness.source_ea, 0x180016680, (285,), (),
            transform_witness=witness,
        )
        production = build_canonical_semantic_evidence(
            (fact,),
            CanonicalSemanticEvidenceProductionContext(
                NATIVE_KEY, 0, "canonical-semantic:branch-transform-x",
                StorageIdentity(StorageIdentityKind.STACK, 0x64),
                tuple(graph.blocks.values()), tuple(identities.items()),
            ),
        )
        assert production.evidence is not None
        proof = production.evidence.route_proofs[0]
        source_block = graph.blocks[285]
        bad_source = replace(
            source_block,
            succs=(446, 4),
            kind=BlockKind.TWO_WAY,
        )
        bad_graph = type(graph)(
            {**graph.blocks, 285: bad_source}, graph.entry_serial, graph.func_ea,
        )
        return production.evidence, bad_graph, route_model.CanonicalRouteBindingStage.STATE_TRANSFORM

    if proof_kind is route_model.SemanticRouteProofKind.STATE_CARRIER:
        from d810.ir.flowgraph import BlockSnapshot, FlowGraph, InsnSnapshot, ValueOpKind
        from d810.ir.varnode import Varnode
        from d810.ir.varnode import Space
        from tests.unit.analyses.control_flow.test_semantic_route_evidence import NATIVE_KEY

        wide_constant = MopSnapshot(kind=OperandKind.NUMBER, size=8, value=7)
        wide_carrier = MopSnapshot(kind=OperandKind.REGISTER, size=8, reg=16)
        narrow_carrier = MopSnapshot(kind=OperandKind.REGISTER, size=4, reg=16)
        state = MopSnapshot(kind=OperandKind.STACK, size=4, stkoff=0x40, stack_refs=(0x40,))
        graph = FlowGraph(
            blocks={
                2: BlockSnapshot(2, 1, (3,), (), 0, 0x1200, (InsnSnapshot(0, 0x1200, (), l=wide_constant, d=wide_carrier, kind=InsnKind.MOV, value_op_kind=__import__("d810.ir.expressions", fromlist=["ValueOpKind"]).ValueOpKind.MOVE, raw_opcode=0),)),
                3: BlockSnapshot(3, 1, (4,), (2,), 0, 0x1300, (InsnSnapshot(0, 0x1300, (), l=narrow_carrier, d=state, kind=InsnKind.MOV, value_op_kind=__import__("d810.ir.expressions", fromlist=["ValueOpKind"]).ValueOpKind.MOVE, raw_opcode=0),)),
                4: BlockSnapshot(4, 0, (), (3,), 0, 0x1400, ()),
                5: BlockSnapshot(5, 0, (), (), 0, 0x1500, ()),
            },
            entry_serial=2,
            func_ea=0x1000,
        )
        from d810.ir.block_identity import stable_block_identity_from_snapshot
        identities = {
            serial: stable_block_identity_from_snapshot(block, native_key=NATIVE_KEY)
            for serial, block in graph.blocks.items()
        }
        assert all(identity is not None for identity in identities.values())
        storage = StorageIdentity(StorageIdentityKind.STACK, 0x40)
        fact = SemanticRouteFact(
            SemanticRouteFactKind.STATE_CARRIER,
            2, 2, 0x1200, 7, 5, 0x1200, 0x1500, (2,), (),
            carrier_witness=__import__(
                "d810.analyses.control_flow.state_carrier",
                fromlist=["ExactCarrierStateWrite"],
            ).ExactCarrierStateWrite(
                state=7, source_serial=2, feeder_serial=3,
                comparison_entry_serial=4,
                carrier=Varnode(Space.REGISTER, 16, 8),
                state_identity=storage,
            ),
        )
        production = build_canonical_semantic_evidence(
            (fact,),
            CanonicalSemanticEvidenceProductionContext(
                NATIVE_KEY, 0, "canonical-semantic:branch-carrier-x", storage,
                tuple(graph.blocks.values()), tuple(identities.items()),
            ),
        )
        assert production.evidence is not None
        bad_graph = FlowGraph(
            {**graph.blocks, 2: replace(graph.blocks[2], succs=(3, 5), kind=BlockKind.TWO_WAY), 5: replace(graph.blocks[5], preds=(2, 3))},
            graph.entry_serial,
            graph.func_ea,
        )
        return production.evidence, bad_graph, route_model.CanonicalRouteBindingStage.STATE_CARRIER

    if proof_kind is route_model.SemanticRouteProofKind.STATE_PARTITION:
        from tests.unit.analyses.control_flow.test_semantic_route_evidence import (
            _composite_partition_evidence,
        )
        from d810.backends.hexrays.evidence.condition_chain_analysis import (
            build_condition_chain_walker_provider,
        )
        from d810.capabilities.providers import register_condition_chain_walkers
        register_condition_chain_walkers(build_condition_chain_walker_provider())
        graph, evidence = _composite_partition_evidence()
        proof = evidence.route_proofs[0]
        source_serial = next(
            serial for serial, block in graph.blocks.items()
            if block.start_ea == proof.source_anchor_ea
        )
        source_block = graph.blocks[source_serial]
        target = source_block.succs[0]
        alternate = next(
            serial for serial in graph.blocks
            if serial not in {source_serial, target} and serial != graph.entry_serial
        )
        bad_graph = type(graph)(
            {
                **graph.blocks,
                source_serial: replace(
                    source_block,
                    succs=(target, alternate),
                    kind=BlockKind.TWO_WAY,
                ),
            },
            graph.entry_serial,
            graph.func_ea,
        )
        return evidence, bad_graph, route_model.CanonicalRouteBindingStage.STATE_PARTITION

    raise AssertionError(f"unsupported branch X proof fixture: {proof_kind}")

# ---------------------------------------------------------------------------
# Slice 3B4-C executable RED matrix
# ---------------------------------------------------------------------------

def _c_complete_kwargs(factory):
    """Return one real route fixture with every C-bound input populated."""
    from d810.transforms.unflatten_authority.gates import GenericEffectfulGateFacts
    from d810.transforms.unflatten_authority.ids import patch_step_fact_id, projected_authority_id

    values = _slice_c_route_kwargs(factory)
    values["patch_step_facts"] = tuple(sorted(values["patch_step_facts"], key=patch_step_fact_id))
    values["claims"] = values["source_authority"].proposal.claims
    # Re-bind the raw partition from the reachable source rows.  Some
    # two-proof fixtures deliberately retain an unreachable CALL block; using
    # every inventory effect here would make the fixture itself stale rather
    # than exercising the route contract.
    raw = bind.bind_raw_effect_gate_phase_fact(
        source_inventory=values["source_inventory"],
        projected_inventory=values["projected_inventory"],
        raw_gate_facts=GenericEffectfulGateFacts(
            True,
            frozenset(
                row.owner_serial for row in values["source_inventory"].effects
                if row.owner_serial in values["source_inventory"].reachable_serials
            ),
            frozenset(
                row.owner_serial for row in values["source_inventory"].effects
                if row.owner_serial in values["source_inventory"].reachable_serials
            ),
            frozenset(),
            "slice-3b4-c-red-rebound",
        ),
    )
    values["raw_effect_gate_fact"] = raw
    values["authority_id"] = projected_authority_id(
        attempt_id=values["attempt_id"],
        proposal_id=values["source_authority"].proposal_id,
        source_authority_id=values["source_authority"].source_authority_id,
        plan_id=values["plan"].plan_id,
        claims=values["claims"],
        patch_step_facts=values["patch_step_facts"],
        source_inventory=values["source_inventory"],
        projected_inventory=values["projected_inventory"],
        raw_effect_gate_fact=raw,
    )
    owners = frozenset(row.owner_serial for row in values["projected_inventory"].effects)
    values["legacy_effective_gate_facts"] = GenericEffectfulGateFacts(
        True, owners, owners, frozenset(), "slice-3b4-c-red-shadow",
    )
    return values


def _c_exact_leaf_transaction_inputs():
    """Build one proposal-owned exact claim with its real structural cells."""
    fixture = lambda: _lower_conditional_case(include_exact_claim=True)
