def test_task_15_mechanical_shared_relation_cites_one_effect_and_terminal_result() -> None:
    """Two exact proof/step rows share one complete atomic site closure."""
    values = _c_complete_kwargs(_task_15_two_relation_shared_site_vertical_case)
    expected = _task_15_independent_shared_publication(values)
    drafted = []
    validated = []
    real_drafter = bind._draft_projected_site_closure
    real_validator = bind._validate_projected_site_closure_draft

    def capture_draft(**kwargs):
        draft = real_drafter(**kwargs)
        drafted.append((draft, kwargs))
        return draft

    def capture_validation(draft, **kwargs):
        validated.append((draft, kwargs))
        return real_validator(draft, **kwargs)

    with (
        patch.object(
            bind, "_draft_projected_site_closure",
            side_effect=capture_draft,
        ),
        patch.object(
            bind, "_validate_projected_site_closure_draft",
            side_effect=capture_validation,
        ),
        patch.object(
            transaction_api, "_build_semantic_graph_inventory",
            side_effect=AssertionError("shared-site inventory replay"),
        ),
        patch.object(
            bind, "bind_source_route_authority",
            side_effect=AssertionError("shared-site source replay"),
        ),
        patch.object(
            route_model, "bind_canonical_semantic_evidence_result",
            side_effect=AssertionError("shared-site route replay"),
        ),
        patch.object(
            producer_api, "validate_exact_effect_claim_semantics",
            side_effect=AssertionError("shared-site producer replay"),
        ),
        patch.object(
            evaluate, "_classify_effect_site",
            side_effect=AssertionError("shared-site evaluator replay"),
        ),
    ):
        events = _task_15_observe_publication_events(
            lambda: realize_projected_routes_for_test(**values),
        )

    assert len(drafted) == len(validated) == 1
    draft, drafter_kwargs = drafted[0]
    validated_draft, validator_kwargs = validated[0]
    assert validated_draft is draft
    for name in (
        "source_authority", "plan", "source_inventory",
        "projected_inventory", "claims", "patch_step_facts",
        "raw_effect_gate_fact", "legacy_effective_gate_facts",
        "attempt_id", "drafts", "owner_index",
    ):
        assert validator_kwargs[name] is drafter_kwargs[name]

    proposal = values["source_authority"].proposal
    proofs = proposal.route_evidence.route_proofs
    claims = tuple(
        claim for claim in values["claims"]
        if type(claim) is model.EquivalentSemanticRouteClaim
    )
    facts = tuple(
        fact for fact in values["patch_step_facts"]
        if fact.step_type == "PatchRedirectGoto"
    )
    assert len(proofs) == len(claims) == len(values["plan"].steps) == 2
    assert len(facts) == 2
    assert len({proof.proof_id for proof in proofs}) == 2
    assert len({claim.claim_id for claim in claims}) == 2
    assert len({fact.step_index for fact in facts}) == 2
    assert len({fact.step_digest for fact in facts}) == 2
    assert len(draft.route_subsets) == 2
    for subset in draft.route_subsets:
        relation_draft = subset.relation_draft
        assert relation_draft.facts
        step_index = relation_draft.facts[0].step_index
        assert relation_draft.claim is expected["claims"][step_index]
        assert relation_draft.proof is expected["proofs"][step_index]
        assert relation_draft.facts[0] is expected["facts"][step_index]
        assert relation_draft.relation == expected["relations"][step_index]
        assert relation_draft.relation.new_target == expected["common_target"]
        assert len(subset.effect_dispositions) == 1
        assert len(subset.terminal_dispositions) == 1
    assert (
        draft.route_subsets[0].effect_dispositions[0]
        is draft.route_subsets[1].effect_dispositions[0]
    )
    assert (
        draft.route_subsets[0].terminal_dispositions[0]
        is draft.route_subsets[1].terminal_dispositions[0]
    )

    result = events.result
    assert type(result) is model.ProjectedRouteRealizationAccepted
    assert result == expected["accepted"]
    realization = result.realization
    assert realization == expected["realization"]
    assert realization.realization_id == expected["realization"].realization_id
    assert realization.rows == expected["rows"]
    assert len({row.row_id for row in realization.rows}) == 2
    assert len({row.relation.relation_id for row in realization.rows}) == 2
    phase = realization.site_phase_result
    assert phase == expected["phase"]
    assert phase.effect_results == (expected["effect"],)
    assert phase.terminal_results == (expected["terminal"],)
    for row in realization.rows:
        assert row.site_preservation.effect_result_ids == (
            expected["effect"].result_id,
        )
        assert row.site_preservation.terminal_result_ids == (
            expected["terminal"].result_id,
        )
        step_index = row.plan_step_index
        assert row.claim_id == expected["claims"][step_index].claim_id
        assert row.proof_id == expected["proofs"][step_index].proof_id
        assert row.plan_step_digest == expected["facts"][step_index].step_digest
        assert row.relation == expected["relations"][step_index]
    assert tuple(sorted(
        (row.site_preservation for row in realization.rows),
        key=lambda item: item.preservation_id,
    )) == expected["preservations"]
    bind.validate_projected_site_phase_result(phase)
    bind.validate_projected_route_realization(realization)
    bind.validate_projected_route_realization_result(result)

    assert events.ordinary == ()
    assert len(events.commits) == 1
    assert len(events.deferred) == len(events.commits[0])
    assert all(
        deferred is committed
        for deferred, committed in zip(events.deferred, events.commits[0])
    )
    assert all(type(value) in events.accepted_types for value in events.deferred)
    assert not any(
        type(value) in {
            model.RouteRealizationFailure,
            model.ProjectedRouteRealizationRejected,
        }
        for value in events.deferred
    )


