@pytest.mark.parametrize("model_attribute", ("absent", "foreign"))
def test_3b4_c_13_5_local_binding_uses_no_mutable_model_id_callback(
    monkeypatch: pytest.MonkeyPatch, model_attribute: str,
) -> None:
    """The owning model resolves its canonical ID without a public callback seam."""
    authority, _plan, _source, projected, _lineage, attempt, derived = (
        _task_15_direct_vertical_case(local_alias=True, derive_transaction=True)
    )
    callback_calls = []
    if model_attribute == "absent":
        monkeypatch.delattr(model, "patch_step_fact_id", raising=False)
    else:
        def foreign_callback(value):
            callback_calls.append(value)
            return patch_step_fact_id(value)

        monkeypatch.setattr(model, "patch_step_fact_id", foreign_callback, raising=False)
    inventory = bind._bind_transaction_projected_claim_inventory(
        derived=derived, source_authority=authority, attempt_id=attempt,
        projected_inventory=projected,
    )
    values = _task_15_vertical_inputs_from_claim_inventory(inventory)
    result = bind._realize_projected_routes_from_claim_inventory(
        authority_id=values["authority_id"], claim_inventory=values["claim_inventory"],
        raw_effect_gate_fact=values["raw_effect_gate_fact"],
        legacy_effective_gate_facts=values["legacy_effective_gate_facts"],
    )
    assert type(result) is model.ProjectedRouteRealizationAccepted
    assert callback_calls == []


