    orphan = _clone_record(phase, **({"exact_effect_bindings": (binding,)} if binding_kind == "exact" else {"local_alias_bindings": (binding,)}))
    with pytest.raises((TypeError, ValueError)):
        bind.validate_projected_site_phase_result(orphan)
    duplicate = _clone_record(phase, **({"exact_effect_bindings": (binding, binding)} if binding_kind == "exact" else {"local_alias_bindings": (binding, binding)}))
    with pytest.raises((TypeError, ValueError)):
        bind.validate_projected_site_phase_result(duplicate)
    equal_nested = _clone_record(binding)
    nested = _clone_record(phase, **({"exact_effect_bindings": (equal_nested,)} if binding_kind == "exact" else {"local_alias_bindings": (equal_nested,)}))
    with pytest.raises((TypeError, ValueError)):
        bind.validate_projected_site_phase_result(nested)


