def test_13_1_16_every_site_record_rejects_public_lifecycle_operations() -> None:
    import copy
    import pickle

    result = realize_projected_routes_for_test(**_c_complete_kwargs(_compiler_redirect_goto_case))
    assert type(result) is model.ProjectedRouteRealizationAccepted
    records = (
        result.realization.site_phase_result,
        result.realization.site_phase_result.effect_results[0],
        result.realization.site_phase_result.terminal_results[0],
        result.realization.rows[0].site_preservation,
    )
    for record in records:
        for operation in (copy.copy, copy.deepcopy, pickle.dumps):
            with pytest.raises((TypeError, ValueError)):
                operation(record)
        with pytest.raises((TypeError, ValueError)):
            replace(record)


